SKU_RE = re.compile(
    r"(?<![A-Za-z0-9])("
    r"(?:[A-Za-z]{1,6}[A-Za-z0-9]{0,12}(?:[-_](?:[A-Za-z0-9]{1,24}(?:\([A-Za-z0-9]{1,24}\))?|[\u4e00-\u9fff]{1,8}))+)"
    r"|(?:[A-Za-z]{1,6}\d{2,12}[A-Za-z0-9\u4e00-\u9fff]{0,12})"
    r")(?=$|[\s，。,；;：:）)\]】>\"'？?])"
)
COMPOSITE_RECOMMENDATION_HINTS = (
    "推荐",
    "建议",
    "适合",
    "最适合",
    "更适合",
    "哪款",
    "哪个",
    "选什么",
    "帮我选",
    "帮我挑",
)
COMPOSITE_FACT_RECOMMENDATION_MARKERS = (
    "顺便",
    "再推荐",
    "再帮我推荐",
    "另外推荐",
    "然后推荐",
    "也推荐",
    "推荐一个",
    "推荐一款",
    "推荐一下",
)

