def _split_composite_customer_question(question: str) -> dict[str, str] | None:
    text = str(question or "").strip()
    if not text:
        return None
    fact_terms = ("酒精炉", "清洗", "保养", "比较", "对比", "区别", "材质", "容量", "重量", "认证", "卖点", "支持", "能不能", "能否")
    reverse = _split_reverse_composite_customer_question(text, fact_terms)
    if reverse:
        return reverse
    marker_pos: tuple[str, int] | None = None
    for marker in COMPOSITE_FACT_RECOMMENDATION_MARKERS:
        index = text.find(marker)
        if index > 0:
            marker_pos = (marker, index)
            break
    if marker_pos:
        _, index = marker_pos
    else:
        selection_match = re.search(
            r"(?:哪个|哪一个|哪款|哪一款)(?:产品)?更适合\s*(?:[1-9]\d?|[一二两三四五六七八九十])\s*(?:个)?人",
            text,
        )
        explicit_skus = list(dict.fromkeys(item.upper() for item in SKU_RE.findall(text)))
        if not selection_match or len(explicit_skus) < 2 or not any(term in text[:selection_match.start()] for term in ("比较", "对比")):
            return None
        index = selection_match.start()
    fact_part = text[:index].strip("。！？!? ，,；; ")
    recommendation_part = text[index:].strip("。！？!? ，,；; ")
    if not fact_part or not recommendation_part:
        return None
    if not any(term in recommendation_part for term in COMPOSITE_RECOMMENDATION_HINTS):
        return None
    if not any(term in fact_part for term in fact_terms):
        return None
    if any(term in fact_part for term in COMPOSITE_RECOMMENDATION_HINTS) and not any(term in fact_part for term in fact_terms):
        return None
    return {"fact_part": fact_part, "recommendation_part": recommendation_part, "order": "fact_first"}


def _split_reverse_composite_customer_question(text: str, fact_terms: tuple[str, ...]) -> dict[str, str] | None:
    if not any(term in text for term in COMPOSITE_RECOMMENDATION_HINTS):
        return None
    connectors = ("并说明", "同时问", "同时", "并且", "另外", "还要", "顺便", "最后")
    marker: tuple[str, int] | None = None
    for connector in connectors:
        index = text.find(connector)
        if index > 0:
            marker = (connector, index)
            break
    if not marker:
        return None
    connector, index = marker
    before = text[:index].strip("。！？!? ，,；;：: ")
    after = text[index + len(connector):].strip("。！？!? ，,；;：: ")
    if connector == "同时问" and "，" in after:
        head, tail = after.split("，", 1)
        if any(term in head for term in COMPOSITE_RECOMMENDATION_HINTS):
            before = f"{before}，{head}".strip("。！？!? ，,；;：: ")
            after = tail.strip("。！？!? ，,；;：: ")
    if not before or not after:
        return None
    if not any(term in before for term in COMPOSITE_RECOMMENDATION_HINTS):
        return None
    if not any(term in after for term in fact_terms):
        return None
    if not SKU_RE.search(after):
        return None
    return {"recommendation_part": before, "fact_part": after, "order": "recommendation_first"}


def _normalize_composite_recommendation_part(recommendation_part: str) -> str:
    text = str(recommendation_part or "").strip("。！？!? ，,；; ")
    if not text:
        return text
    for prefix in ("顺便", "再帮我", "再", "另外", "然后", "也", ""):
        candidate = text
        if prefix and not text.startswith(prefix):
            continue
        if prefix:
            candidate = text[len(prefix):].strip("。！？!? ，,；; ")
        for starter in ("推荐一个", "推荐一款"):
            if not candidate.startswith(starter):
                continue
            target = candidate[len(starter):].strip("。！？!? ，,；; ")
            if target.startswith(("更适合", "最适合", "适合")):
                return f"推荐{target}"
            if target:
                return f"推荐适合{target}"
    return text


def _merge_composite_answers(fact_answer: str, recommendation_answer: str) -> str:
    fact_answer = str(fact_answer or "").strip()
    recommendation_answer = str(recommendation_answer or "").strip()
    if fact_answer and recommendation_answer:
        return f"{fact_answer}\n\n{recommendation_answer}"
    return fact_answer or recommendation_answer


def _merge_supplemental_product_qa_into_field_answer(
    agent_result: dict,
    *,
    supplemental: dict | None,
    supplemental_query: str,
) -> dict:
    """Attach a second semantic product-QA intent after formal-field repair.

    Both the primary result and the optional QA result have already passed
    their own entity/evidence contracts.  This function never chooses a
    product or derives a fact from wording: it only preserves a same-SKU QA
    answer, or makes the independently requested QA part safely missing.
    """
    result_skus = [
        str(sku or "").strip().upper()
        for sku in (agent_result.get("result_skus") or [])
        if str(sku or "").strip()
    ]
    query = str(supplemental_query or "").strip()
    if not query or len(result_skus) != 1:
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if supplemental and supplemental.get("result_skus") == result_skus:
        extra = str(supplemental.get("answer") or "").strip()
        if extra:
            agent_result["answer"] = str(agent_result.get("answer") or "").strip() + "\n" + extra
            metadata["supplemental_product_qa"] = supplemental.get("answer_metadata") or {}
            agent_result["answer_metadata"] = metadata
            return agent_result
    agent_result["answer"] = (
        str(agent_result.get("answer") or "").strip()
        + f"\n关于“{query}”：当前同 SKU 资料未找到可直接确认的依据，无法确认。"
    )
    metadata["supplemental_product_qa"] = {
        "contract_field_type": "product_qa",
        "evidence_status": "missing",
        "evidence_skus": [],
        "requested_query": query,
        "resolved_sku": result_skus[0],
    }
    agent_result["answer_metadata"] = metadata
    return agent_result


async def _try_same_sku_structured_best_effort_answer(
    db: Session,
    *,
    question: str,
    safe_missing: dict,
    semantic_preplan: dict | None,
) -> dict | None:
    """Answer an open product question from directly relevant structured facts.

    DeepSeek decides relevance and wording. Deterministic code only supplies
    customer-visible fields for the already sealed SKU and validates that the
    resulting answer cites those exact facts.
    """
    if str((semantic_preplan or {}).get("evidence_kind") or "") != "product_qa":
        return None
    sku = str(safe_missing.get("sku") or "").strip().upper()
    if not sku:
        sealed_skus = {
            str(item or "").strip().upper()
            for item in (safe_missing.get("result_skus") or [])
            if str(item or "").strip()
        }
        sealed_skus.update(
            str(row.get("sku") or "").strip().upper()
            for row in (safe_missing.get("results") or [])
            if isinstance(row, dict) and str(row.get("sku") or "").strip()
        )
        if len(sealed_skus) == 1:
            sku = next(iter(sealed_skus))
    if not sku:
        return None
    product, specs, business, content = _phase1_product_bundle_by_ref(db, sku)
    if product is None or str(product.sku or "").strip().upper() != sku:
        return None
    excluded_fields = {
        "sku", "barcode", "product_name_cn", "product_name_en",
        "content_title", "content_description", "bullet_points",
        "search_keywords", "manual", "inventory", "price",
    }
    raw_items: list[dict[str, Any]] = []
    for field in sorted(customer_field_contract.FORMAL_DETAIL_FIELDS):
        if field in excluded_fields or not customer_field_contract.is_supported_detail_field(field):
            continue
        value, source = _structured_product_field_evidence(
            field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
        )
        if not value or not source:
            continue
        raw_items.append({
            "evidence_id": customer_evidence_bundle.stable_customer_evidence_id(
                namespace="structured",
                sku=sku,
                value=f"{field}|{value}",
            ),
            "sku": sku,
            "source_type": "structured_field",
            "source": str(source),
            "field": field,
            "value": str(value)[:800],
            "visibility": customer_evidence_bundle.CUSTOMER_VISIBLE,
        })
    bundle = customer_evidence_bundle.build_customer_evidence_bundle(
        sku=sku,
        product_name=product.product_name_cn or product.product_name_en or sku,
        evidence_items=raw_items,
    )
    if not bundle.items:
        return None
    candidates = [
        {
            "evidence_id": item.evidence_id,
            "field": item.field,
            "field_label": customer_field_contract.product_detail_field_label(item.field) or item.field,
            "value": item.value,
        }
        for item in bundle.items
    ]
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string,evidence_ids:string[],evidence_quotes:string[]}. "
                        "Answer the complete customer question only when one or more supplied same-product "
                        "structured facts directly support it. You may combine multiple directly relevant "
                        "facts for a bounded suitability judgement, but never infer safety, durability, "
                        "compatibility, performance, ease of use, or a guarantee from merely adjacent facts. "
                        "Use NO_EVIDENCE when the facts are only related rather than sufficient. "
                        "Use only supplied facts, keep uncertainty explicit, and copy one to three literal "
                        "evidence quotes of at most 60 characters."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {"question": question, "same_sku": sku, "candidates": candidates},
                        ensure_ascii=False,
                    ),
                },
            ],
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 360),
            purpose="same_sku_structured_best_effort_answer",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return None
    payload = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    answer = str(payload.get("answer") or "").strip()
    evidence_ids = payload.get("evidence_ids")
    if not answer or answer == "NO_EVIDENCE" or not isinstance(evidence_ids, list) or not evidence_ids:
        return None
    selected_id_set = {str(item or "").strip() for item in evidence_ids if str(item or "").strip()}
    selected_items = [item for item in bundle.items if item.evidence_id in selected_id_set]
    if len(selected_items) != len(selected_id_set):
        return None
    evidence_content = "\n".join(item.value for item in selected_items)
    if (
        not _same_sku_rag_answer_has_selected_quotes(payload, evidence_content)
        or not await _same_sku_rag_answer_is_grounded_after_quote_validation(
            db, question, answer, payload, evidence_content
        )
    ):
        return None
    result = dict(safe_missing)
    result.update({
        "answer": answer,
        "confidence": "high",
        "uncertainty": "resolved",
        "evidence": [
            {
                "evidence_id": item.evidence_id,
                "sku": sku,
                "field_label": customer_field_contract.product_detail_field_label(item.field) or item.field,
                "value": item.value,
                "source_type": "structured_field",
                "source_layer": "structured",
                "matched_by": "semantic_same_sku_structured_evidence",
            }
            for item in selected_items
        ],
        "sources": [{"type": "product_field", "label": "同 SKU 商品资料", "sku": sku}],
        "answer_metadata": {
            "contract_field_type": "product_qa",
            "evidence_status": "matched",
            "evidence_sku": sku,
            "evidence_skus": [sku],
            "evidence_bundle_skus": [sku],
            "evidence_ids": [item.evidence_id for item in selected_items],
            "evidence_source": "same_sku_structured_best_effort",
        },
        "skip_polish": False,
    })
    result.setdefault("debug", {})["agent_mode"] = "sealed_same_sku_structured_best_effort"
    return result


async def _save_agent_result_and_return(
    db: Session,
    *,
    user_id: str,
    question: str,
    conversation_id: str | None,
    agent_result: dict,
    request_start: float,
    branch: str,
    semantic_preplan: dict | None = None,
) -> dict:
    stage_start = perf_counter()
    original_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    persisted_plan = original_debug.get("plan") if isinstance(original_debug.get("plan"), dict) else {}
    effective_semantic_preplan = semantic_preplan or persisted_plan.get("semantic_preplan") or {}
    if str(original_debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing":
        recovered = await _try_same_sku_structured_best_effort_answer(
            db,
            question=question,
            safe_missing=agent_result,
            semantic_preplan=effective_semantic_preplan,
        )
        if recovered is not None:
            agent_result = recovered
            original_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        else:
            rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
            if rows:
                row = rows[0]
                sku = str(row.get("sku") or "").strip().upper()
                name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
                agent_result["answer"] = (
                    f"{name}（{sku}）：当前同 SKU 资料中暂未找到可直接确认这个问题的产品问答内容。"
                )
            agent_result["skip_polish"] = True
    supplemental_query = str((effective_semantic_preplan or {}).get("supplemental_qa_evidence_query") or "").strip()
    if not ((agent_result.get("debug") or {}).get("timing")) or not ((agent_result.get("answer_metadata") or {}).get("timing")):
        existing_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        existing_plan = existing_debug.get("plan") if isinstance(existing_debug.get("plan"), dict) else {}
        agent_result = _attach_phase1_plan_and_timing(
            agent_result,
            existing_plan,
            _phase1_timing(request_start=request_start),
        )
    agent_result = _ensure_debug_plan_raw_question(agent_result, question)
    agent_result = _finalize_answer(agent_result)
    agent_result = _attach_semantic_preplan_debug(
        agent_result,
        semantic_preplan,
        final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
    )
    # Explicit single-product field answers must not be completed with unrelated QA or selling points.
    agent_result = _enforce_field_evidence_policy(db, question, agent_result)
    field_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if (
        str(field_metadata.get("contract_field_type") or "").strip() == "accessories"
        and field_metadata.get("field_evidence_missing") is True
        and len(agent_result.get("result_skus") or []) == 1
    ):
        accessory_preplan = dict(effective_semantic_preplan or {})
        accessory_preplan.update({
            "route_family": "product_bound_qa",
            "route_hint": "product_detail",
            "question_type": "field",
            "subject_text": str(agent_result.get("result_skus")[0]),
            "canonical_fields": [],
            "field_type": "",
            "field_hint": None,
            "evidence_required": True,
            "evidence_kind": "product_qa",
            "qa_evidence_query": question,
            "fallback_reason": "",
        })
        accessory_qa_result = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan={"semantic_preplan": accessory_preplan},
        )
        if accessory_qa_result and accessory_qa_result.get("result_skus") == agent_result.get("result_skus"):
            accessory_qa_result.setdefault("answer_metadata", {}).update({
                "contract_field_type": "accessories",
                "evidence_field": "accessories",
                "field_evidence_match": True,
                "field_evidence_missing": False,
                "evidence_status": "matched",
            })
            agent_result = accessory_qa_result
    compound_queries = [
        str(item or "").strip()
        for item in ((effective_semantic_preplan or {}).get("qa_evidence_queries") or [])
        if str(item or "").strip()
    ]
    semantic_subject = customer_agent_service.normalize_search_text(
        str((effective_semantic_preplan or {}).get("subject_text") or "")
    ).lower()
    if (
        semantic_subject
        and len(compound_queries) > 1
        and all(semantic_subject in customer_agent_service.normalize_search_text(query).lower() for query in compound_queries)
    ):
        # Repeated subject-bearing rewrites are an overview decomposition, not
        # independently answerable product facts.
        compound_queries = []
    compound_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if (
        compound_queries
        and len(agent_result.get("result_skus") or []) == 1
        and str(compound_metadata.get("contract_field_type") or "").strip() == "product_qa"
    ):
        # The final save boundary is the last place before a safe-missing
        # response becomes user-visible. Re-run only the already semantic,
        # independently scoped queries under the same resolved SKU; never
        # reinterpret the question here.
        child_answers: list[dict] = []
        missing_child_queries: list[str] = []
        answered_child_requests: list[tuple[str, str]] = []
        child_evidence_ids: set[str] = set()
        for query in compound_queries:
            child_preplan = dict(effective_semantic_preplan)
            child_preplan.update({
                "qa_evidence_query": query,
                "qa_evidence_queries": [],
                "compound": False,
                "strict_compound_child_qa": True,
            })
            child_question = " ".join(item for item in (str(child_preplan.get("subject_text") or "").strip(), query) if item) or question
            child_result = await _try_product_qa_shortcut_with_semantic_selection(
                db, child_question, phase1_plan={"semantic_preplan": child_preplan},
            )
            if _is_sealed_product_qa_safe_missing(child_result):
                child_result = None
            if not child_result:
                child_result = await _try_sealed_same_sku_knowledge_answer(
                    db, child_question, {"semantic_preplan": child_preplan},
                )
            if child_result:
                child_meta = child_result.get("answer_metadata") if isinstance(child_result.get("answer_metadata"), dict) else {}
                child_evidence_id = str(child_meta.get("evidence_source") or "").strip()
                # A strict child selector must not reuse the sibling QA row.
                # Treat a duplicate evidence id as uncovered instead of
                # repeating an answer for a different sub-question.
                if child_evidence_id and child_evidence_id in child_evidence_ids:
                    missing_child_queries.append(query)
                else:
                    if child_evidence_id:
                        child_evidence_ids.add(child_evidence_id)
                    child_answers.append(child_result)
                    answered_child_requests.append((
                        query,
                        child_evidence_id
                        or str(child_meta.get("source") or "same_sku_child_evidence"),
                    ))
            else:
                missing_child_queries.append(query)
        if child_answers:
            if _is_sealed_product_qa_safe_missing(agent_result):
                agent_result = child_answers.pop(0)
            base_answer = str(agent_result.get("answer") or "").strip()
            extra_answers = []
            seen_answer_texts = {base_answer} if base_answer else set()
            for index, item in enumerate(child_answers):
                extra = str(item.get("answer") or "").strip()
                if extra and extra in seen_answer_texts:
                    if index + 1 < len(compound_queries):
                        missing_child_queries.append(compound_queries[index + 1])
                    continue
                if extra and extra not in base_answer and base_answer not in extra:
                    extra_answers.append(extra)
                    seen_answer_texts.add(extra)
            extra_answers.extend(
                f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。"
                for query in missing_child_queries
                if query
            )
            if extra_answers:
                agent_result["answer"] = "\n".join([base_answer, *extra_answers])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = missing_child_queries
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=answered_child_requests,
                    unsupported_requests=missing_child_queries,
                ).to_dict()
            )
        elif len(compound_queries) > 1:
            # The parent answer may still be valid for the first child, but a
            # failed narrow retrieval must not make later semantic children
            # disappear from the customer-visible response.
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_queries[1:]
            parent_evidence_id = str(
                compound_metadata.get("evidence_source")
                or compound_metadata.get("source")
                or "same_sku_parent_evidence"
            )
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=[(compound_queries[0], parent_evidence_id)],
                    unsupported_requests=compound_queries[1:],
                ).to_dict()
            )
    if supplemental_query and len(agent_result.get("result_skus") or []) == 1:
        supplemental, supplemental_query = await _resolve_sealed_supplemental_product_evidence(
            db,
            question=question,
            semantic_preplan=effective_semantic_preplan,
            base_plan={"semantic_preplan": effective_semantic_preplan},
        )
        agent_result = _merge_supplemental_product_qa_into_field_answer(
            agent_result,
            supplemental=supplemental,
            supplemental_query=supplemental_query,
        )
    agent_result = _ensure_debug_plan_raw_question(agent_result, question)
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    skip_polish = bool(agent_result.get("skip_polish"))
    if _should_skip_polish_for_agent_result(agent_result):
        skip_polish = True
    if answer_metadata.get("evidence_insufficient") is True or answer_metadata.get("answer_policy") == "insufficient_evidence":
        skip_polish = True
    if not skip_polish:
        agent_result["answer"] = await _polish_customer_answer(db, question, agent_result)
    # Preserve independently scoped child questions after customer polishing.
    # The polish model may shorten a safe-missing clause, but it must not erase
    # a requested sub-question that lacked same-SKU evidence.
    coverage_contract = customer_answer_coverage_contract.AnswerCoverageContract.from_dict(
        answer_metadata.get("answer_coverage_contract")
    )
    if coverage_contract is not None:
        agent_result = _apply_answer_coverage_contract(agent_result)
    else:
        missing_child_queries = [
            str(item or "").strip()
            for item in (answer_metadata.get("compound_missing_child_queries") or [])
            if str(item or "").strip()
        ]
        if missing_child_queries:
            answer_text = str(agent_result.get("answer") or "").strip()
            missing_lines = [f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in missing_child_queries]
            additions = [line for line in missing_lines if line not in answer_text]
            if additions:
                agent_result["answer"] = "\n".join([item for item in (answer_text, *additions) if item])
            compound_query_list = []
        else:
            compound_query_list = [
                str(item or "").strip()
                for item in (answer_metadata.get("compound_product_qa_queries") or [])
                if str(item or "").strip()
            ]
        # If a compound turn produced only one answer, do not silently drop
        # later independently requested children.  The child query itself is
        # the semantic source; absent an explicit answer for it, fail closed.
        answer_text = str(agent_result.get("answer") or "").strip()
        if len(compound_query_list) > 1:
            uncovered_queries = _uncovered_compound_queries_for_output(
                answer_text,
                compound_query_list,
                answer_metadata,
            )
            additions = [
                f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。"
                for query in uncovered_queries
            ]
            if additions:
                agent_result["answer"] = "\n".join([item for item in (answer_text, *additions) if item])
    agent_result = _shape_answer_for_output(agent_result)
    final_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    if str(final_debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing":
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        if rows:
            row = rows[0]
            sku = str(row.get("sku") or "").strip().upper()
            name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
            agent_result["answer"] = (
                f"{name}（{sku}）：当前同 SKU 资料中暂未找到可直接确认这个问题的产品问答内容。"
            )
        agent_result["skip_polish"] = True
    result_rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    saved_plan = ((agent_result.get("debug") or {}).get("plan") or {})
    comparison_recommendation = bool(
        agent_result.get("answer_type") == "recommendation"
        and isinstance(saved_plan, dict)
        and (
            saved_plan.get("must_compare_both_products")
            or str(saved_plan.get("primary_intent") or "") == "product_compare_recommendation"
        )
    )
    if comparison_recommendation and result_rows:
        top_sku = str(result_rows[0].get("sku") or "").strip().upper()
        lower_skus = {
            str(row.get("sku") or "").strip().upper()
            for row in result_rows[1:]
            if str(row.get("sku") or "").strip()
        }
        lines = str(agent_result.get("answer") or "").splitlines()
        top_line_index = next(
            (
                index
                for index, line in enumerate(lines)
                if top_sku in line.upper() and not any(sku in line.upper() for sku in lower_skus)
            ),
            None,
        )
        if top_line_index is not None:
            agent_result["answer"] = "\n".join(lines[top_line_index:]).strip()
    agent_result["skip_polish"] = skip_polish
    agent_result = customer_final_answer_arbiter.arbitrate_final_answer(agent_result)
    agent_result = _attach_agent_quality(agent_result, question)
    conversation = _get_or_create_conversation(db, user_id, question, agent_result.get("sku"), conversation_id)
    db.add(CustomerServiceMessage(
        conversation_id=conversation.id,
        role="user",
        content=question,
        sku=agent_result.get("sku"),
    ))
    assistant_turn_index = _assistant_turn_index(db, conversation.id)
    sources_with_context = _sources_with_result_context(
        agent_result,
        turn_index=assistant_turn_index,
        user_question=question,
        inherited_recommendation_context=_latest_recommendation_context_for_sources(db, conversation.id),
        inherited_candidate_context=_latest_candidate_context_for_sources(db, conversation.id),
    )
    assistant_message = CustomerServiceMessage(
        conversation_id=conversation.id,
        role="assistant",
        content=agent_result["answer"],
        sku=agent_result.get("sku"),
        sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
    )
    db.add(assistant_message)
    _touch_conversation(conversation, agent_result.get("sku"))
    conversation_id_value = conversation.id
    message_id_value = assistant_message.id
    db.commit()
    customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch=branch, skip_polish=bool(agent_result.get("skip_polish")))
    customer_perf_service.log_stage(
        "ask_customer_service.total",
        request_start,
        branch=branch,
        intent=agent_result.get("intent"),
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode"),
    )
    customer_perf_service.summarize_request(
        final_answer=agent_result.get("answer"),
        intent=agent_result.get("intent"),
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode"),
    )
    release_session_connection(db)
    agent_result = _attach_semantic_preplan_debug(
        agent_result,
        semantic_preplan,
        final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
    )
    public_intent = _public_intent_name(agent_result.get("intent"), agent_result.get("answer_type"))
    return {
        "conversation_id": conversation_id_value,
        "message_id": message_id_value,
        "intent": public_intent,
        "answer_type": agent_result.get("answer_type"),
        "confidence": agent_result.get("confidence"),
        "uncertainty": agent_result.get("uncertainty"),
        "needs_clarification": agent_result.get("needs_clarification", False),
        "anomalies": agent_result.get("anomalies") or [],
        "suggested_followups": agent_result.get("suggested_followups") or [],
        "followups": agent_result.get("followups") or agent_result.get("suggested_followups") or [],
        "warnings": agent_result.get("warnings") or [],
        "evidence": agent_result.get("evidence") or [],
        "agent_quality": agent_result.get("agent_quality") or {},
        "answer_metadata": agent_result.get("answer_metadata") or {},
        "debug": agent_result.get("debug") or {},
        "sku": agent_result.get("sku"),
        "answer": agent_result["answer"],
        "sources": sources_with_context,
        "actions": agent_result.get("actions") or [],
        "results": agent_result.get("results") or [],
        "steps": agent_result.get("steps") or [],
        "result_skus": agent_result.get("result_skus") if "result_skus" in agent_result else [
            str(item.get("sku") or "").strip().upper()
            for item in (agent_result.get("results") or [])
            if isinstance(item, dict) and str(item.get("sku") or "").strip()
        ],
        "candidate_skus": agent_result.get("candidate_skus") if "candidate_skus" in agent_result else [
            str(item.get("sku") or "").strip().upper()
            for item in (agent_result.get("results") or [])
            if isinstance(item, dict) and str(item.get("sku") or "").strip()
        ],
        "agent_mode": (agent_result.get("debug") or {}).get("agent_mode"),
    }


def _phase1_timing(
    *,
    request_start: float,
    planner_duration_ms: float = 0,
    retrieval_duration_ms: float = 0,
    executor_duration_ms: float = 0,
    composer_duration_ms: float = 0,
    guard_duration_ms: float = 0,
    llm_duration_ms: float = 0,
    llm_call_count: int = 0,
) -> dict:
    return customer_agent_planner_service.merge_timing(
        None,
        {
            "total_duration_ms": round((perf_counter() - request_start) * 1000, 2),
            "planner_duration_ms": planner_duration_ms,
            "retrieval_duration_ms": retrieval_duration_ms,
            "executor_duration_ms": executor_duration_ms,
            "llm_duration_ms": llm_duration_ms,
            "llm_call_count": llm_call_count,
            "composer_duration_ms": composer_duration_ms,
            "guard_duration_ms": guard_duration_ms,
        },
    )


def _attach_phase1_plan_and_timing(agent_result: dict, plan: dict, timing: dict) -> dict:
    if not isinstance(agent_result, dict):
        return agent_result
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    existing_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    merged_timing = customer_agent_planner_service.merge_timing(debug.get("timing"), timing)
    answer_metadata["timing"] = customer_agent_planner_service.merge_timing(answer_metadata.get("timing"), merged_timing)
    debug["timing"] = merged_timing
    # ``_db`` is a runtime-only dependency for the phase executors.  It must
    # never escape into the debug payload: HTTP debug responses are JSON and
    # a SQLAlchemy Session is neither customer evidence nor serializable.
    original_plan = {
        key: value
        for key, value in (plan.items() if isinstance(plan, dict) else [])
        if key != "_db"
    }
    debug["plan"] = {**original_plan, **existing_plan} if existing_plan else original_plan
    if isinstance(plan, dict) and isinstance(plan.get("semantic_preplan"), dict):
        already_attached = bool((debug.get("semantic_preplan") or {}).get("called")) if isinstance(debug.get("semantic_preplan"), dict) else False
        preplan_debug = dict(plan["semantic_preplan"])
        if not preplan_debug.get("accepted_or_overridden"):
            final_route = str(agent_result.get("answer_type") or agent_result.get("intent") or "").strip()
            route_hint = str(preplan_debug.get("route_hint") or "").strip()
            accepted = bool(route_hint and final_route in _semantic_preplan_equivalent_routes(route_hint, final_route))
            preplan_debug["accepted_or_overridden"] = "accepted" if accepted else "overridden"
            if not accepted:
                preplan_debug["override_reason"] = preplan_debug.get("fallback_reason") or "deterministic_guard_final_route"
        plan["semantic_preplan"] = preplan_debug
        debug["semantic_preplan"] = preplan_debug
        if not already_attached and preplan_debug.get("called"):
            delta = int(preplan_debug.get("llm_call_count_delta") or preplan_debug.get("llm_call_count") or 0)
            if delta:
                debug["timing"]["llm_call_count"] = int(debug["timing"].get("llm_call_count") or 0) + delta
                answer_metadata["timing"]["llm_call_count"] = int(answer_metadata["timing"].get("llm_call_count") or 0) + delta
    agent_result["answer_metadata"] = answer_metadata
    agent_result["debug"] = debug
    return agent_result


def _ensure_debug_plan_raw_question(agent_result: dict, question: str) -> dict:
    """Keep the public audit trace complete without changing an effective plan."""
    if not isinstance(agent_result, dict):
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    raw_question = str(question or "").strip()
    if raw_question and not str(plan.get("raw_question") or "").strip():
        plan["raw_question"] = raw_question
    debug["plan"] = plan
    agent_result["debug"] = debug
    return agent_result


def _semantic_preplan_equivalent_routes(route_hint: str, final_route: str) -> set[str]:
    route = str(route_hint or "").strip()
    final = str(final_route or "").strip()
    equivalents = {
        "comparison": {"comparison", "recommendation"},
        "query_products": {"query_products", "product_query"},
        "usage_care": {"knowledge_base_answer", "product_usage_care"},
        "unknown_field": {"product_detail", "knowledge_base_answer"},
        "product_detail": {"product_detail"},
    }
    return equivalents.get(route) or {route, final}


def _attach_semantic_preplan_debug(agent_result: dict | None, semantic_preplan: dict | None, *, final_route: str) -> dict | None:
    if not isinstance(agent_result, dict) or not isinstance(semantic_preplan, dict) or not semantic_preplan.get("called"):
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    already_attached = bool((debug.get("semantic_preplan") or {}).get("called")) if isinstance(debug.get("semantic_preplan"), dict) else False
    final = str(final_route or agent_result.get("answer_type") or agent_result.get("intent") or "").strip()
    route_hint = str(semantic_preplan.get("route_hint") or "").strip()
    accepted = bool(route_hint and final in _semantic_preplan_equivalent_routes(route_hint, final))
    preplan_debug = dict(semantic_preplan)
    preplan_debug["accepted_or_overridden"] = "accepted" if accepted else "overridden"
    if not accepted:
        preplan_debug["override_reason"] = preplan_debug.get("fallback_reason") or "deterministic_guard_final_route"
    debug["semantic_preplan"] = preplan_debug
    if not already_attached:
        for container in (debug, answer_metadata):
            timing = container.get("timing") if isinstance(container.get("timing"), dict) else None
            if timing:
                timing["llm_call_count"] = int(timing.get("llm_call_count") or 0) + int(semantic_preplan.get("llm_call_count_delta") or semantic_preplan.get("llm_call_count") or 0)
                timing["llm_duration_ms"] = timing.get("llm_duration_ms") or 0
        trace = debug.get("trace") if isinstance(debug.get("trace"), dict) else None
        if trace is not None:
            trace["llm_call_count"] = int(trace.get("llm_call_count") or 0) + int(semantic_preplan.get("llm_call_count_delta") or semantic_preplan.get("llm_call_count") or 0)
    agent_result["debug"] = debug
    agent_result["answer_metadata"] = answer_metadata
    return agent_result


def _has_explicit_sku_text(question: str) -> bool:
    return bool(SKU_RE.search(str(question or "")))


def _is_clear_explicit_sku_field_question_for_preplan(question: str, phase1_plan: dict | None) -> bool:
    text = str(question or "")
    if not _has_explicit_sku_text(text):
        return False
    if any(term in text for term in ("使用限制", "注意事项", "禁忌", "怎么清洗", "怎么用")):
        return False
    if isinstance(phase1_plan, dict) and phase1_plan.get("primary_intent") == "product_field":
        return True
    clear_terms = (
        "容量",
        "材质",
        "材料",
        "重量",
        "尺寸",
        "规格",
        "酒精炉",
        "明火",
        "热源",
        "冷水",
        "热水",
        "烧水",
        "补水",
    )
    return any(term in text for term in clear_terms)


def _is_sku_usage_restriction_ambiguous_for_preplan(question: str) -> bool:
    text = str(question or "")
    return _has_explicit_sku_text(text) and any(term in text for term in ("使用限制", "注意事项", "禁忌"))


def _is_complex_filter_ambiguous_for_preplan(question: str) -> bool:
    text = str(question or "")
    if not any(term in text for term in ("有哪些", "哪几", "适合", "更偏", "推荐")):
        return False
    coffee_filter = any(term in text for term in ("咖啡器具", "咖啡", "手冲")) and any(term in text for term in ("手冲", "咖啡器具"))
    water_filter = any(term in text for term in ("水具", "水杯", "水壶")) and any(term in text for term in ("冷水", "补水", "随身"))
    return bool(coffee_filter or water_filter)


def _looks_like_contents_accessories_contract_question(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    return bool(
        customer_agent_service.looks_like_contents_accessories_question(text)
        or customer_agent_intent_service._looks_like_contents_grounding_question(text)
    )


def _has_non_usage_care_field_contract(question: str) -> bool:
    """Keep non-usage product fields out of the usage/care fast path."""
    field_contract = customer_field_contract.detect_field_contract(question)
    # Any formal field must reach the central entity arbitration before a
    # scope guard or usage/care shortcut can decide the result.  Accessories
    # retains its additional generic-query exclusion below.
    if field_contract and field_contract.field_type != "accessories":
        return True
    if not field_contract or field_contract.field_type != "accessories":
        return _looks_like_contents_accessories_contract_question(question)

    # An explicit SKU is a sealed product-identity signal even when subject
    # span extraction also retains a shorter SKU-shaped search candidate.
    # Contents/accessories must therefore enter entity arbitration rather than
    # degrading into a generic catalogue query.
    if _has_explicit_sku_text(question):
        return True

    # Accessories only become product-bound when FieldContract left a concrete
    # subject. Category discovery and recommendation language keeps its
    # established query-products path even though it mentions accessories.
    selection = customer_field_contract.select_entity_subject_for_routing(raw_question=question)
    subject = str(selection.entity_subject or "").strip()
    if not subject or subject.startswith(("哪些", "有哪些", "什么", "推荐", "适合")):
        return False
    if _is_generic_contents_subject(subject):
        return False
    if any(term in str(question or "") for term in ("更偏", "推荐", "适合", "用于", "收纳")):
        return False
    return not _is_generic_category_phrase(subject) and not _is_generic_modifier_prefixed_product_scope(subject)


def _should_call_semantic_preplan(
    question: str,
    phase1_plan: dict | None,
    *,
    conversation_id: str | None,
    has_named_product: bool = False,
) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if _detect_resolved_entity_unknown_fact_label(text):
        return True
    if _looks_like_contents_accessories_contract_question(text):
        return True
    if _is_sku_usage_restriction_ambiguous_for_preplan(text):
        return True
    if customer_agent_service._extract_skus(text):
        # An explicit SKU seals only the product subject.  It must not let a
        # legacy field parser or a usage/care shortcut decide what the user is
        # asking before the constrained semantic planner has emitted its
        # allowlisted field signal.
        return True
    if has_named_product:
        if (
            "?" not in text
            and "？" not in text
            and any(term in text for term in ("再看", "改看", "看看", "看一下"))
        ):
            # Existing offline navigation remains available when the semantic
            # provider is unavailable. New declarative forms still reach the
            # semantic navigation contract below.
            return False
        # A catalogue identity answers only "which product".  The semantic
        # preplan must still decide "what is being asked" before lexical
        # recommendation/usage helpers can interpret words such as "适合" or
        # tokens embedded in the product name.
        return True
    if isinstance(phase1_plan, dict) and phase1_plan.get("primary_intent") == "recommendation":
        # The deterministic planner may recognize that this is a candidate
        # request, but it is not allowed to infer the customer's actual
        # subject, constraints, or priority.  Always obtain the constrained
        # semantic plan before a legacy recommendation executor can run.
        return True
    if (
        isinstance(phase1_plan, dict)
        and phase1_plan.get("primary_intent") == "query_products"
        and "?" not in text
        and "？" not in text
        and not any(term in text for term in ("再看", "改看", "看看", "看一下"))
    ):
        # A terse declarative turn outside the established offline navigation
        # grammar can be a product-navigation request. Its meaning belongs to
        # semantic planning; deterministic code only verifies a later exact
        # entity contract before any anchor is stored.
        return True
    if (
        isinstance(phase1_plan, dict)
        and phase1_plan.get("primary_intent") == "catalog_count"
        and _looks_like_semantic_catalog_query(text)
        and not has_named_product
    ):
        # Count-like wording can conceal a recommendation or a multi-constraint
        # catalogue request.  Let the semantic preplan decide the user's full
        # intent before the old count route discards that meaning; the later
        # deterministic layer still verifies the actual catalogue evidence.
        return True
    if conversation_id and _asks_for_alternative_recommendation(text):
        return True
    if _phase1_is_griddle_vs_cookware_scenario(text):
        return True
    if _is_complex_filter_ambiguous_for_preplan(text):
        return True
    if (
        isinstance(phase1_plan, dict)
        and not str(phase1_plan.get("primary_intent") or "").strip()
        and str(phase1_plan.get("confidence") or "").strip().lower() in {"", "low"}
    ):
        # A low-confidence legacy plan has not understood the request.  It
        # therefore cannot authorize a downstream QA or structured-query
        # shortcut: let the semantic preplan classify the whole utterance
        # first, then keep deterministic code to contracts and evidence only.
        return True
    # For every ordinary, unbound customer turn, semantic planning owns the
    # full sentence meaning before a legacy parser can turn a single noun into
    # a field route. Punctuation is not a semantic boundary: declarative
    # requests are common in chat. The later contracts still retain entity,
    # field-allowlist, and same-SKU evidence authority.
    return True


async def _maybe_run_semantic_preplan(
    db: Session,
    question: str,
    phase1_plan: dict | None,
    *,
    conversation_id: str | None,
) -> dict | None:
    # Entity recognition remains deterministic.  It only decides whether a
    # product subject is present; semantic planning alone classifies the field.
    # This prevents a named product fact containing catalogue vocabulary from
    # being skipped before it can form the formal field contract.
    has_named_product = bool(_products_named_in_question(db, question))
    if not _should_call_semantic_preplan(
        question,
        phase1_plan,
        conversation_id=conversation_id,
        has_named_product=has_named_product,
    ):
        return None
    recommendation_context = _latest_recommendation_context_for_sources(db, conversation_id) if conversation_id else {}
    prior_customer_preference_texts: list[str] = []
    if isinstance(recommendation_context, dict) and isinstance(
        recommendation_context.get("effective_recommendation_contract")
        or recommendation_context.get("recommendation_request_contract"),
        dict,
    ):
        prior_question = str(recommendation_context.get("user_question") or "").strip()
        if prior_question:
            prior_customer_preference_texts.append(prior_question)
    active_anchor_sku = str(
        (recommendation_context or {}).get("active_single_product_anchor") or ""
    ).strip().upper()
    active_anchor = {}
    if active_anchor_sku:
        product = db.query(Product).filter(Product.sku == active_anchor_sku).first()
        if product is not None:
            active_anchor = {
                "sku": active_anchor_sku,
                "product_name": str(product.product_name_cn or product.product_name_en or "").strip(),
            }
    # This is identity provenance only, never a route decision: the semantic
    # planner still decides whether the complete turn requests a product fact.
    # Passing a boolean avoids leaking a SKU, catalogue value, or answer into
    # the semantic prompt while allowing it to distinguish a named-product
    # question from genuinely unscoped general guidance.
    current_turn_products = _products_named_in_question(db, question)
    unique_current_turn_catalog_product_name = bool(
        customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            current_turn_products,
        )
    )
    unique_current_turn_catalog_product_mention = (
        customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            current_turn_products,
        )
        if unique_current_turn_catalog_product_name
        else ""
    )
    return await customer_agent_planner_service.plan_customer_question_semantic(
        db,
        question,
        phase1_plan,
        context={
            "conversation_id": conversation_id,
            "has_recommendation_context": bool(prior_customer_preference_texts),
            "prior_customer_preference_texts": prior_customer_preference_texts,
            "active_product_anchor": active_anchor,
            "has_unique_current_turn_catalog_product_name": unique_current_turn_catalog_product_name,
            # This text is already a literal span of the customer turn, not
            # a SKU or database fact. It lets the semantic model distinguish
            # a catalog name that happens to resemble a generic category.
            "unique_current_turn_catalog_product_mention": unique_current_turn_catalog_product_mention,
        },
    )


def _semantic_preplan_route_family(preplan: dict | None) -> str:
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return ""
    family = str(preplan.get("route_family") or "").strip()
    if family:
        return family
    route_hint = str(preplan.get("route_hint") or "").strip()
    subtype = str(preplan.get("subtype") or "").strip()
    question_type = str(preplan.get("question_type") or "").strip()
    if subtype == "structured_query" or (route_hint == "query_products" and question_type in {"filter", "count"}):
        return "structured_query" if subtype == "structured_query" else "generic_query"
    if route_hint == "recommendation" or subtype == "recommendation":
        return "recommendation"
    if route_hint == "unknown_field" or subtype in {"unknown_realtime", "commercial_realtime"}:
        return "unknown_realtime"
    if question_type == "contents_accessories" or subtype in {"contents_accessories", "composition"}:
        return "contents_accessories"
    if route_hint in {"product_detail", "usage_care", "knowledge_base_answer"}:
        return "product_bound_qa"
    if route_hint == "clarification" or subtype == "no_match":
        return "clarification"
    return ""


def _apply_semantic_single_field_route_precedence(
    phase1_plan: dict | None,
    semantic_preplan: dict | None,
) -> None:
    """Remove parser-only collection state after a sealed singular field plan.

    The semantic planner owns the whole-turn meaning.  A legacy parser can
    still expose a short SKU prefix as a second participant (for example a
    compact token embedded in a longer SKU); that diagnostic extraction must
    never turn a high-confidence, one-product field request into comparison
    work.  This helper changes no field, entity, SKU, or evidence: Phase 2
    will independently validate the semantic subject into its contract.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else None
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    fields = [
        str(field or "").strip()
        for field in (preplan.get("canonical_fields") or [])
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ]
    if not (
        plan is not None
        and preplan.get("called")
        and _semantic_preplan_confident(preplan, minimum=0.9)
        and _semantic_preplan_route_family(preplan) == "product_bound_qa"
        and len(fields) == 1
    ):
        return
    plan["primary_intent"] = "product_detail"
    plan["answer_type"] = "product_detail"
    plan["product_refs"] = []
    plan["must_compare_both_products"] = False
    plan["must_make_choice"] = False
    plan["tasks"] = []


def _semantic_preplan_entity_scope(preplan: dict | None) -> str:
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return ""
    scope = str(preplan.get("entity_scope") or "").strip()
    aliases = {
        "resolved_single": "resolved_product",
        "unique_product_name": "resolved_product",
        "ambiguous_product_name": "ambiguous_product",
        "unresolved_product_like": "unresolved_product",
    }
    return aliases.get(scope, scope)


def _semantic_preplan_confident(preplan: dict | None, *, minimum: float = 0.5) -> bool:
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return False
    label = str(preplan.get("confidence_label") or "").strip()
    if label == "high":
        return True
    if label == "medium":
        return minimum <= 0.65
    try:
        confidence = float(preplan.get("confidence") or 0)
    except (TypeError, ValueError):
        confidence = 0.0
    if confidence >= minimum:
        return True
    # A fail-closed semantic parser clears its public confidence, but the
    # catalogue adapter may safely consume the independently retained route
    # confidence only to select an exact value from the live DB closed set.
    if (
        str(preplan.get("semantic_route_family_hint") or "") == "structured_query"
        and str(preplan.get("fallback_reason") or "") in {
            "incomplete_structured_query_scope",
            "catalogue_value_requires_structured_query",
            "unbound_catalogue_browse_requires_structured_query",
        }
    ):
        try:
            return float(preplan.get("semantic_confidence_hint") or 0) >= minimum
        except (TypeError, ValueError):
            return False
    return False


def _semantic_catalog_aggregate_contract(preplan: dict | None, phase1_plan: dict | None) -> bool:
    """Keep a semantic category aggregate on its database-count contract.

    ``category`` is a formally supported product field, but a high-confidence
    structured catalogue aggregate has no single product entity to resolve.
    The deterministic planner has already classified the turn as a count; this
    helper only prevents the generic detail-field guard from erasing that
    aggregate contract.  It does not infer a category from wording or grant
    a product identity.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    value = preplan if isinstance(preplan, dict) else {}
    count_like_question = any(token in str(value.get("raw_question") or "") for token in ("多少", "几款", "几种", "几个"))
    return bool(
        (plan.get("primary_intent") == "catalog_count" or count_like_question)
        and value.get("called")
        and str(value.get("route_family") or "").strip() == "structured_query"
        and str(value.get("route_hint") or "").strip() == "query_products"
        and str(value.get("field_type") or "").strip() == "category"
        and str(value.get("question_type") or "").strip() == "filter"
        and _semantic_preplan_confident(value, minimum=0.9)
    )


def _semantic_pairwise_contract_candidate(preplan: dict | None) -> bool:
    """Whether a semantic plan requires sealed handling of multiple named products.

    A user can request a choice between two named products using either the
    ``comparison`` or ``recommendation`` route family.  The latter is still a
    pairwise decision, not permission for the legacy recommendation renderer
    to invent a preference.  Semantic planning owns that distinction; this
    helper only decides whether every supplied participant must be sealed.
    """
    value = preplan if isinstance(preplan, dict) else {}
    route_family = str(value.get("route_family") or "").strip()
    if route_family == "comparison":
        return True
    # A request to choose from the catalogue is a recommendation, not a
    # pairwise comparison.  But once semantic planning has supplied two or
    # more named product spans, a catalogue-wide recommendation must never
    # replace them.  ``decision_requested`` is useful answer-shaping context,
    # not a safe prerequisite for preserving those identities: model output
    # can omit that boolean while still understanding a natural “怎么选” ask.
    participants = [str(item).strip() for item in (value.get("entities") or []) if str(item or "").strip()]
    return route_family == "recommendation" and len(participants) >= 2


def _semantic_structured_comparison_overview_contract(preplan: dict | None) -> bool:
    """Recognize an intentional fieldless semantic comparison overview.

    The semantic plan, not a legacy field alias in words such as "features",
    decides whether a named comparison asks for one field or for a bounded
    overview of recorded differences.
    """
    value = preplan if isinstance(preplan, dict) else {}
    return bool(
        str(value.get("route_family") or "").strip() == "comparison"
        and str(value.get("subtype") or "").strip() == "comparison_overview"
        and str(value.get("evidence_kind") or "").strip() == "structured_field"
        and not list(value.get("canonical_fields") or [])
        and not str(value.get("field_type") or value.get("field_hint") or "").strip()
        and not bool(value.get("decision_requested"))
    )


def _should_execute_semantic_catalog_recommendation(preplan: dict | None) -> bool:
    """Allow the catalogue executor only for an unbound semantic recommendation.

    Named multi-product requests are sealed comparison work, even when the
    semantic route label is ``recommendation``.  This guard is intentionally
    based on the structured semantic plan, rather than lexical heuristics.
    """
    if not isinstance(preplan, dict) or _semantic_pairwise_contract_candidate(preplan):
        return False
    return (
        str(preplan.get("route_family") or "") == "recommendation"
        and not preplan.get("fallback_reason")
        and not preplan.get("ambiguity")
        # A grounded medium-confidence recommendation still belongs to the
        # semantic contract.  Confidence controls whether the model may claim
        # certainty about wording; it must not reopen the legacy lexical
        # ``query_products`` router.  The shared verifier below either proves
        # every candidate from same-SKU evidence or returns a safe
        # clarification, so accepting the semantic route at the medium floor
        # does not relax the evidence boundary.
        and _semantic_preplan_confident(preplan, minimum=0.65)
        and isinstance(preplan.get("recommendation_constraints"), dict)
        and bool(preplan.get("recommendation_constraints"))
    )


def _apply_pairwise_recommendation_field_adapter(preplan: dict | None) -> None:
    """Adapt grounded recommendation constraints into one formal comparison FieldContract.

    This consumes only structured DeepSeek output that has already passed the
    recommendation grounding pass.  It maps schema dimensions, never lexical
    wording or product names, and only when the semantic plan has named a
    pair of products for sealed comparison.
    """
    if not isinstance(preplan, dict) or not _semantic_pairwise_contract_candidate(preplan):
        return
    if preplan.get("recommendation_constraint_grounding") != "validated_semantic_grounding":
        return
    constraints = dict(preplan.get("recommendation_constraints") or {})
    if not isinstance(constraints, dict):
        return
    mapping = (
        ("people", "people"),
        ("heat_sources", "heat_source"),
        ("scenarios", "usage_scene"),
        ("weight_preference", "weight"),
    )
    fields = [field for constraint, field in mapping if constraints.get(constraint)]
    if not fields:
        return
    preplan["canonical_fields"] = fields
    preplan["field_type"] = fields[0] if len(fields) == 1 else ""
    preplan["field_hint"] = preplan["field_type"]
    preplan["semantic_adapter_source"] = "validated_pairwise_recommendation_constraints"


def _apply_structured_named_field_entity_adapter(
    db: Session,
    question: str,
    preplan: dict | None,
) -> bool:
    """Adapt a named product field that the semantic model wrapped as a filter.

    DeepSeek occasionally retains a ``structured_query`` route shell for a
    named product attribute.  This adapter does not reinterpret customer
    wording, choose an SKU, or consume evidence.  It accepts only the model's
    high-confidence allowlisted field, then asks the ordinary
    EntityResolutionContract whether the model-supplied subject names one or
    more catalogue products.  A unique identity can proceed to the normal
    field provider; an ambiguous identity remains a clarification with the
    same formal field contract.  Generic catalogue filters stay untouched.
    """
    value = preplan if isinstance(preplan, dict) else {}
    if not (
        value.get("called")
        and not value.get("fallback_reason")
        and not value.get("ambiguity")
        and _semantic_preplan_confident(value, minimum=0.9)
        and str(value.get("route_family") or "").strip() == "structured_query"
        and str(value.get("route_hint") or "").strip() == "query_products"
        and str(value.get("question_type") or "").strip() == "filter"
        and str(value.get("subtype") or "").strip() == "structured_query"
    ):
        return False
    fields = list(dict.fromkeys(
        customer_field_contract.semantic_preplan_field_type(item)
        for item in (value.get("canonical_fields") or [])
        if customer_field_contract.semantic_preplan_field_type(item) in customer_field_contract.FORMAL_DETAIL_FIELDS
    ))
    field_type = customer_field_contract.semantic_preplan_field_type(value.get("field_type"))
    field_hint = customer_field_contract.semantic_preplan_field_type(value.get("field_hint"))
    if len(fields) != 1 or fields[0] != field_type or field_hint != field_type:
        return False
    # A category-only catalogue request with no current-turn entity has no
    # product field to adapt.  Preserve that semantic structured-query route.
    # Conversely, do not let this catalogue-scope escape consume an explicit
    # SKU or a product identity already resolved from the current question:
    # those cases must first form the ordinary FieldContract and
    # EntityResolutionContract.
    if (
        field_type == "category"
        and not (value.get("entities") or [])
        and not (value.get("structured_query_constraints") or [])
        and not customer_agent_service._extract_skus(question)
        and not _products_named_in_question(db, question)
    ):
        return False
    subject = str(value.get("subject_text") or "").strip()
    if not subject:
        return False
    products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        entity_text_override=subject,
        field_type_override=field_type,
    )
    if entity_contract.status not in {"resolved", "ambiguous"} or not entity_contract.candidate_skus:
        return False
    value["route_family"] = "product_bound_qa"
    value["route_hint"] = "product_detail"
    value["question_type"] = "field"
    value["subtype"] = "known_detail"
    value["evidence_required"] = True
    value["entities"] = [subject]
    value["entity_scope"] = (
        "resolved_product" if entity_contract.status == "resolved" else "ambiguous_product"
    )
    value["semantic_original_route_family"] = "structured_query"
    value["semantic_adapter_source"] = "validated_structured_named_field_entity_contract"
    return True


def _semantic_comparison_entity_contracts(
    question: str,
    semantic_preplan: dict | None,
    products: list[Product],
    *,
    context_anchor_sku: str | None = None,
) -> list[customer_entity_resolution_contract.EntityResolutionContract]:
    """Validate semantic comparison participants without accepting an LLM SKU decision."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if (
        not _semantic_pairwise_contract_candidate(preplan)
        or not _semantic_preplan_confident(preplan, minimum=0.9)
        or bool(preplan.get("ambiguity"))
    ):
        return []
    normalized_question = customer_agent_service.normalize_search_text(question)
    canonical_anchor_sku = str(context_anchor_sku or "").strip().upper()
    anchor_product = next(
        (
            product
            for product in products
            if str(product.sku or "").strip().upper() == canonical_anchor_sku
        ),
        None,
    )
    allow_context_anchor = bool(
        anchor_product is not None
        and str(preplan.get("context_usage") or "").strip() == "entity_anchor"
    )
    participants: list[str] = []
    context_anchor_participants: set[str] = set()
    for raw_participant in preplan.get("entities") or []:
        participant = str(raw_participant or "").strip()
        normalized_participant = customer_agent_service.normalize_search_text(participant)
        if not normalized_participant or participant in participants:
            return []
        if normalized_participant not in normalized_question:
            anchor_identity_values = {
                customer_agent_service.normalize_search_text(value)
                for value in (
                    canonical_anchor_sku,
                    getattr(anchor_product, "product_name_cn", "") if anchor_product else "",
                    getattr(anchor_product, "product_name_en", "") if anchor_product else "",
                )
                if str(value or "").strip()
            }
            if not allow_context_anchor or normalized_participant not in anchor_identity_values:
                return []
            context_anchor_participants.add(participant)
        participants.append(participant)
    if len(participants) < 2:
        return []
    # Entity sealing proves identity only.  For a single formal comparison
    # criterion, preserve that already-validated field on every contract so
    # downstream evidence can be audited against the same canonical request.
    # Multiple criteria intentionally stay unbound here: a missing value must
    # produce a same-SKU evidence gap, never make a uniquely named product
    # disappear or let identity arbitration choose among criteria.
    canonical_fields = [
        customer_field_contract.semantic_preplan_field_type(item)
        for item in (preplan.get("canonical_fields") or [])
    ]
    canonical_fields = list(dict.fromkeys(field for field in canonical_fields if field))
    field_type = canonical_fields[0] if len(canonical_fields) == 1 else None
    contracts: list[customer_entity_resolution_contract.EntityResolutionContract] = []
    resolved_skus: set[str] = set()
    for participant in participants:
        if participant in context_anchor_participants and anchor_product is not None:
            normalized_participant = customer_agent_service.normalize_search_text(participant)
            matched_by = (
                "sku_exact"
                if normalized_participant
                == customer_agent_service.normalize_search_text(canonical_anchor_sku)
                else "canonical_name_exact"
            )
            contract = customer_entity_resolution_contract.EntityResolutionContract(
                entity_text=participant,
                normalized_entity_text=normalized_participant,
                status="resolved",
                resolved_sku=canonical_anchor_sku,
                resolver_candidate_skus=[canonical_anchor_sku],
                diagnostic_candidate_skus=[],
                candidate_skus=[canonical_anchor_sku],
                matched_by=matched_by,
                confidence="high",
                is_unique=True,
                matched_span=None,
                field_type=field_type,
                status_reason="trusted_context_anchor_exact",
            )
        else:
            contract = customer_entity_resolution_contract.build_entity_resolution_contract(
                question,
                products,
                entity_text_override=participant,
                field_type_override=field_type,
                participant_local_identity=True,
            )
        decision = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
        if not decision.allowed or not decision.resolved_sku or decision.resolved_sku in resolved_skus:
            return []
        resolved_skus.add(decision.resolved_sku)
        contracts.append(contract)
    return contracts


def _apply_semantic_comparison_plan(
    question: str,
    phase1_plan: dict[str, Any],
    semantic_preplan: dict | None,
    products: list[Product],
    *,
    context_anchor_sku: str | None = None,
) -> list[customer_entity_resolution_contract.EntityResolutionContract]:
    """Adapt one validated semantic comparison into sealed multi-entity execution."""
    contracts = _semantic_comparison_entity_contracts(
        question,
        semantic_preplan,
        products,
        context_anchor_sku=context_anchor_sku,
    )
    if not contracts:
        return []
    resolved_skus = [str(contract.resolved_sku or "").strip().upper() for contract in contracts]
    if len(resolved_skus) < 2 or any(not sku for sku in resolved_skus):
        return []
    phase1_plan.update(
        {
            "primary_intent": "comparison",
            "answer_type": "comparison",
            "product_refs": resolved_skus,
            "must_compare_both_products": True,
            "must_make_choice": bool((semantic_preplan or {}).get("decision_requested")),
            "semantic_comparison_entity_contracts": [contract.to_dict() for contract in contracts],
        }
    )
    return contracts


def _semantic_comparison_fail_closed_result(semantic_preplan: dict | None) -> dict | None:
    """Keep an unsealed semantic comparison out of legacy free-form execution."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if not preplan.get("called") or not _semantic_pairwise_contract_candidate(preplan):
        return None
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "我理解你想比较多个商品，但还不能把每个比较对象唯一锁定。请补充各商品的 SKU 或完整商品名，我会按同一字段和各自资料继续比较。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_comparison_unsealed_clarification",
            "evidence_status": "entity_unsealed",
        },
        "debug": {
            "agent_mode": "semantic_comparison_unsealed_clarification",
            "semantic_comparison_entities": list(preplan.get("entities") or []),
        },
        "skip_polish": True,
    }


def _semantic_pairwise_missing_criterion_result(
    rows: list[dict[str, Any]],
    entity_contracts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Clarify a sealed pairwise purchase decision that lacks a criterion.

    The semantic plan has already established that the user wants one of two
    named products, but has not supplied a product field or suitability
    criterion.  Choosing from broad row text here would recreate the legacy
    rule-based comparator.  Keep both identities auditable and ask for the
    customer's actual priority instead.
    """
    candidate_skus = [
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    ]
    labels = [
        f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{sku}）"
        for row, sku in zip(rows, candidate_skus)
    ]
    products_text = "、".join(label for label in labels if label) or "这两款商品"
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": (
            f"我已锁定你在比较的{products_text}，但还不知道你最在意的选择依据。"
            "请告诉我更看重容量、重量、使用场景或预算中的哪一项，我会只按各自同 SKU 的已标注资料帮你比较。"
        ),
        "results": [],
        "result_skus": [],
        "candidate_skus": candidate_skus,
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_pairwise_missing_criterion_clarification",
            "evidence_status": "criterion_missing",
            "final_choice_sku": None,
        },
        "debug": {
            "agent_mode": "semantic_pairwise_missing_criterion_clarification",
            "entity_resolution_contracts": entity_contracts,
        },
        "skip_polish": True,
    }


def _semantic_pairwise_realtime_fields_result(
    rows: list[dict[str, Any]],
    entity_contracts: list[dict[str, Any]],
    field_types: list[str],
) -> dict[str, Any]:
    """Preserve a sealed realtime comparison instead of choosing on unrelated data."""
    canonical_fields = list(dict.fromkeys(
        str(field or "").strip()
        for field in field_types
        if str(field or "").strip()
    ))
    candidate_skus = [
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    ]
    labels = [
        f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{sku}）"
        for row, sku in zip(rows, candidate_skus)
    ]
    products_text = "、".join(label for label in labels if label) or "这两款商品"
    if canonical_fields == ["price"]:
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护这两款的实时价格，"
            "因此不能判断哪款更便宜。请以同一平台、同一时间的实际售价和优惠为准。"
        )
    elif canonical_fields == ["inventory"]:
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护这两款的实时库存，"
            "因此不能判断哪款现货更充足。请以平台或店铺页面为准。"
        )
    else:
        field_labels = [
            customer_field_contract.product_detail_field_label(field) or field
            for field in canonical_fields
        ]
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护可核验的"
            f"{'、'.join(field_labels)}，因此不能据此指定其中一款。"
        )
    return {
        "intent": "compare_products",
        "answer_type": "comparison",
        "answer": answer,
        "results": rows,
        "result_skus": candidate_skus,
        "candidate_skus": candidate_skus,
        "sources": [],
        "answer_metadata": {
            "source": "semantic_pairwise_realtime_field_boundary",
            "contract_field_types": canonical_fields,
            "evidence_status": "realtime_source_unavailable",
            "final_choice_sku": None,
        },
        "debug": {
            "agent_mode": "semantic_pairwise_realtime_field_boundary",
            "field_contract": {
                "field_type": canonical_fields[0] if len(canonical_fields) == 1 else "",
                "canonical_fields": canonical_fields,
                "source": "validated_semantic_preplan",
            },
            "entity_resolution_contracts": entity_contracts,
        },
        "skip_polish": True,
    }


def _invalid_semantic_pairwise_preplan_clarification_result(
    question: str,
    phase1_plan: dict[str, Any] | None,
    semantic_preplan: dict[str, Any] | None,
    products: list[Product],
) -> dict | None:
    """Fail closed when semantic comparison meaning is invalid before legacy prose can answer."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if (
        not preplan.get("called")
        or not str(preplan.get("fallback_reason") or "").strip()
        or str(plan.get("primary_intent") or "") not in {"comparison", "product_compare_recommendation"}
        or len(products) < 2
    ):
        return None
    contracts: list[customer_entity_resolution_contract.EntityResolutionContract] = []
    seen_skus: set[str] = set()
    for product in products[:8]:
        entity_text = str(product.product_name_cn or product.product_name_en or product.sku or "").strip()
        if not entity_text:
            return None
        contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            entity_text_override=entity_text,
            field_type_override=None,
        )
        decision = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
        sku = str(decision.resolved_sku or "").strip().upper()
        if not decision.allowed or not sku or sku in seen_skus:
            return None
        seen_skus.add(sku)
        contracts.append(contract)
    rows = [
        {
            "sku": str(product.sku or "").strip().upper(),
            "product_name_cn": str(product.product_name_cn or product.product_name_en or product.sku or "").strip(),
        }
        for product in products[:len(contracts)]
    ]
    result = _semantic_pairwise_missing_criterion_result(rows, [contract.to_dict() for contract in contracts])
    result["answer_metadata"]["source"] = "semantic_pairwise_invalid_preplan_clarification"
    result["answer_metadata"]["semantic_fallback_reason"] = str(preplan.get("fallback_reason") or "")
    result["debug"]["agent_mode"] = "semantic_pairwise_invalid_preplan_clarification"
    return result


def _semantic_product_navigation_contract_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    """Seal an LLM-identified product-navigation turn before storing an anchor."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    # A semantic product_bound_qa with no requested field or evidence is a
    # conservative representation of navigation, not permission for legacy
    # generic retrieval.  The catalogue still seals the subject below.
    if str(preplan.get("route_family") or "") not in {"product_navigation", "product_bound_qa"}:
        return None
    if not _semantic_preplan_confident(preplan, minimum=0.9):
        return None
    if preplan.get("ambiguity") or preplan.get("evidence_required"):
        return None
    if preplan.get("canonical_fields") or preplan.get("field_type"):
        return None
    subject = str(preplan.get("subject_text") or "").strip()
    normalized_subject = customer_agent_service.normalize_search_text(subject)
    normalized_question = customer_agent_service.normalize_search_text(question)
    if not normalized_subject or normalized_subject not in normalized_question:
        return None
    products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        entity_text_override=subject,
    )
    decision = customer_entity_resolution_contract.can_resolve_single_product(entity_contract, products)
    if not decision.allowed or not decision.resolved_sku:
        return None
    product = next(
        (item for item in products if str(item.sku or "").strip().upper() == decision.resolved_sku),
        None,
    )
    if product is None:
        return None
    sku = str(product.sku or "").strip().upper()
    name = str(product.product_name_cn or product.product_name_en or sku).strip()
    return {
        "answer": f"已切换到{name}（{sku}）。你可以继续问它的材质、尺寸、重量、配件或使用方式。",
        "intent": "product_detail",
        "answer_type": "product_detail",
        "confidence": "high",
        "uncertainty": "confirmed",
        "needs_clarification": False,
        "sources": [{"type": "product", "label": "语义导航实体合同", "sku": sku}],
        "actions": [],
        "results": [{"sku": sku, "product_name_cn": product.product_name_cn, "category": product.category}],
        "result_skus": [sku],
        "candidate_skus": [sku],
        "steps": [{"type": "entity_navigation_contract", "label": "建立当前商品上下文", "detail": f"语义主体经实体合同解析为 {sku}", "ok": True}],
        "warnings": [],
        "evidence": [],
        "answer_metadata": {
            "source": "semantic_product_navigation_contract",
            "evidence_status": "sealed_navigation_identity",
            "evidence_sku": sku,
            "evidence_skus": [sku],
        },
        "debug": {
            "agent_mode": "semantic_product_navigation_contract",
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "sku": sku,
        "skip_polish": True,
    }


def _product_row_from_model(product: Product, specs: ProductSpecs | None = None, business: ProductBusiness | None = None, content: ProductContent | None = None) -> dict:
    return {
        "sku": product.sku,
        "barcode": product.barcode,
        "product_name_cn": product.product_name_cn,
        "product_name_en": product.product_name_en,
        "brand": product.brand,
        "series": product.series,
        "category": product.category,
        "sub_category": product.sub_category,
        "product_level": product.product_level,
        "launch_date": str(product.launch_date) if product.launch_date else "",
        "lifecycle_status": product.lifecycle_status,
        "capacity": getattr(specs, "capacity", "") if specs else "",
        "size_info": getattr(specs, "size_info", "") if specs else "",
        "heat_source": getattr(specs, "heat_source", "") if specs else "",
        "body_material": getattr(specs, "body_material", "") if specs else "",
        "color": getattr(specs, "color", "") if specs else "",
        "usage_instruction": getattr(specs, "usage_instruction", "") if specs else "",
        "gross_weight_g": getattr(specs, "gross_weight_g", 0) if specs else 0,
        "features": getattr(specs, "technical_advantages", "") if specs else "",
        "usage_scenarios": getattr(business, "usage_scenarios", "") if business else "",
        "target_audience": getattr(business, "target_audience", "") if business else "",
        "positioning": getattr(business, "positioning", "") if business else "",
        "top_selling_points": getattr(business, "top_selling_points", "") if business else "",
        "price_positioning": getattr(business, "price_positioning", "") if business else "",
        # These customer-facing content columns are not independently used as
        # catalogue predicates.  They let the value-scope executor prove that
        # a customer-provided multilingual collection name occurs on the same
        # product row as one formal catalogue value.
        "title_en": getattr(content, "title_en", "") if content else "",
        "website_title": getattr(content, "website_title", "") if content else "",
        "amazon_title": getattr(content, "amazon_title", "") if content else "",
        "long_description_en": getattr(content, "long_description_en", "") if content else "",
        "long_description_cn": getattr(content, "long_description_cn", "") if content else "",
    }


def _phase1_product_bundle_by_ref(db: Session, product_ref: str) -> tuple[Product | None, ProductSpecs | None, ProductBusiness | None, ProductContent | None]:
    ref = str(product_ref or "").strip()
    if not ref:
        return None, None, None, None
    exact_sku_value = _resolve_exact_sku_variant(db, ref) or ref.upper()
    exact_sku = db.query(Product).filter(Product.sku == exact_sku_value).first()
    if exact_sku:
        specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == exact_sku.id).first()
        business = db.query(ProductBusiness).filter(ProductBusiness.product_id == exact_sku.id).first()
        content = db.query(ProductContent).filter(ProductContent.product_id == exact_sku.id).first()
        return exact_sku, specs, business, content
    product = (
        db.query(Product)
        .filter(
            (Product.product_name_cn == ref)
            | (Product.product_name_cn.contains(ref))
            | (Product.product_name_en.contains(ref))
            | (Product.sku == ref.upper())
        )
        .order_by(Product.sku.asc())
        .first()
    )
    if not product:
        return None, None, None, None
    specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == product.id).first()
    business = db.query(ProductBusiness).filter(ProductBusiness.product_id == product.id).first()
    content = db.query(ProductContent).filter(ProductContent.product_id == product.id).first()
    return product, specs, business, content


def _field_display_value(requested_field: str, value: Any) -> str:
    """Remove a duplicated leading label without rewriting evidence content."""
    display = str(value or "").strip().rstrip("。.!！?？：:")
    label = str(requested_field or "").strip()
    if not display or not label:
        return display
    return re.sub(
        rf"^{re.escape(label)}(?:包括|有|是)?\s*[：:]\s*",
        "",
        display,
        count=1,
    ).strip()


def _phase1_product_field_result(db: Session, plan: dict) -> dict | None:
    product_ref = str(plan.get("product_ref") or "").strip()
    explicit_sku = str(plan.get("sku") or "").strip().upper()
    requested_field = str(plan.get("requested_field") or "").strip()
    raw_question = str(plan.get("raw_question") or "").strip()
    field_contract = customer_field_contract.detect_field_contract(raw_question)
    explicit_field_override = str(plan.get("field_type_override") or "").strip()
    # The question's deterministic FieldContract is authoritative over a
    # compatibility planner label.  Otherwise a broad legacy label such as
    # dimensions can turn a formal specification request into a different
    # safe-missing answer.
    canonical_field = (
        explicit_field_override
        if customer_field_contract.is_supported_detail_field(explicit_field_override)
        else field_contract.field_type if field_contract else
        customer_field_contract.field_type_from_detail_label(requested_field)
    )
    canonical_label = customer_field_contract.product_detail_field_label(canonical_field)
    if canonical_label:
        requested_field = canonical_label
        plan["requested_field"] = requested_field
    if requested_field == "适用场景":
        canonical_field = "usage_scene"
    resolved_ref = (
        _resolve_exact_sku_variant(db, explicit_sku or product_ref or raw_question)
        or explicit_sku
        or _resolve_sku(db, raw_question or product_ref, product_ref or None)
        or _resolve_sku(db, product_ref, None)
        or product_ref
    )
    if resolved_ref:
        plan["product_ref"] = resolved_ref
        plan["sku"] = resolved_ref
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_ref)
    identity_source = str(plan.get("product_identity_source") or "").strip() or None
    sealed_entity_contract = None
    initial_identity_decision = (
        customer_entity_resolution_contract.can_trust_bound_product_identity(
            product=product,
            sku=resolved_ref,
            identity_source=identity_source,
        )
        if product
        else None
    )
    # A weak planner reference may be repaired by a direct canonical name in
    # the question. Once a trusted upstream identity contract has sealed a
    # SKU, however, this evidence provider must consume that SKU and must not
    # independently re-resolve the raw question to another product.
    if (
        canonical_field
        and raw_question
        and not bool(initial_identity_decision and initial_identity_decision.allowed)
    ):
        # The legacy field executor may receive only a weak planner reference.
        # Repair it through the same sealed EntityResolutionContract used by
        # Phase 2, never by a first fuzzy database row.  This also permits a
        # field-specific safe-missing answer for an exact named product whose
        # requested column has no valid value.
        all_products = db.query(Product).order_by(Product.sku.asc()).all()
        question_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            raw_question,
            all_products,
            field_type_override=canonical_field,
        )
        resolution = customer_entity_resolution_contract.can_resolve_single_product(
            question_contract,
            all_products,
        )
        if resolution.allowed and resolution.resolved_sku:
            sealed_entity_contract = question_contract
            product, specs, business, content = _phase1_product_bundle_by_ref(db, resolution.resolved_sku)
            resolved_ref = resolution.resolved_sku
            plan["product_ref"] = resolved_ref
            plan["sku"] = resolved_ref
            plan["entity_resolution_contract"] = question_contract.to_dict()
    if product:
        identity_decision = customer_entity_resolution_contract.can_trust_bound_product_identity(
            product=product,
            sku=resolved_ref,
            entity_contract=sealed_entity_contract,
            identity_source=identity_source,
        )
        if not identity_decision.allowed:
            return {
                "intent": "clarify",
                "answer_type": "clarification",
                "answer": f"我还不能把“{product_ref}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名。",
                "results": [],
                "result_skus": [],
                "candidate_skus": [],
                "needs_clarification": True,
                "answer_metadata": {"source": "entity_strength_gate_clarification"},
                "debug": {
                    "agent_mode": "entity_strength_gate_clarification",
                    "bound_product_identity_decision": identity_decision.to_dict(),
                },
                "skip_polish": True,
            }
    if not product:
        return {
            "intent": "product_detail",
            "answer_type": "product_detail",
            "answer": f"当前资料中暂未标注{resolved_ref}的{requested_field}。",
            "results": [],
            "result_skus": [],
            "answer_metadata": {"answer_policy": "field_only_missing"},
            "debug": {"agent_mode": "planner_product_field"},
            "skip_polish": True,
        }
    # Structured product fields are authoritative.  Same-SKU QA remains a
    # field-compatible fallback below when the validated database provider is
    # empty; an exact wording match alone must not replace a formal field.
    value = ""
    evidence_source = None
    evidence_scope = "subject"
    dimension_evidence = None
    dimension_subtype = (
        customer_field_contract.requested_dimension_subtype(raw_question)
        if canonical_field == "dimensions"
        else None
    )
    cleaning_subtype = (
        customer_field_contract.requested_cleaning_subtype(raw_question)
        if canonical_field == "cleaning"
        else None
    )
    usage_instruction_subtype = (
        customer_field_contract.requested_usage_instruction_subtype(raw_question)
        if canonical_field == "usage_instruction"
        else None
    )
    content_subtype = _content_field_evidence_subtype(raw_question, canonical_field)
    if canonical_field == "accessories":
        accessories_qa = _best_product_qa_match(
            db,
            product,
            raw_question or requested_field,
            requested_field_type="accessories",
        )
        value = str(getattr(accessories_qa, "answer", "") or "").strip()
        evidence_source = f"product_qa:{accessories_qa.id}" if accessories_qa and value else None
    elif requested_field == "SKU":
        value = str(product.sku or "").strip().upper()
        evidence_source = "product.sku"
    elif requested_field == "尺寸":
        dimension_evidence = customer_field_contract.select_dimension_evidence(
            getattr(specs, "size_info", "") if specs else "",
            requested_scope=customer_field_contract.requested_evidence_scope(raw_question, "dimensions"),
            requested_subtype=customer_field_contract.requested_dimension_subtype(raw_question),
        )
        value = dimension_evidence.value if dimension_evidence else ""
        evidence_source = "specs.size_info" if dimension_evidence else None
        evidence_scope = dimension_evidence.scope if dimension_evidence else customer_field_contract.requested_evidence_scope(raw_question, "dimensions")
        if value in {"", "[]", "/"}:
            value = ""
    elif requested_field == "容量":
        value = _capacity_field_evidence(getattr(specs, "capacity", "") if specs else "")
        evidence_source = "specs.capacity" if value else None
    elif requested_field == "重量":
        weight = getattr(specs, "gross_weight_g", None)
        # Keep this older phase-one path on the same validated formatter as
        # the central structured-evidence provider.  A database float such as
        # 150.0 is a gram value, not a customer-facing precision claim.
        value = _weight_field_evidence(weight, capacity=getattr(specs, "capacity", "") if specs else "")
        evidence_source = "specs.gross_weight_g" if value else None
    elif requested_field == "材质":
        value = str(getattr(specs, "body_material", "") or "").strip()
        evidence_source = "specs.body_material" if value else None
        if value in {"", "[]", "/"}:
            value = ""
    elif requested_field == "颜色":
        value = _color_field_evidence(getattr(specs, "color", "") if specs else "")
        evidence_source = "specs.color" if value else None
    elif canonical_field == "usage_scene":
        value = _compound_display_value(getattr(business, "usage_scenarios", "") if business else "")
        evidence_source = "business.usage_scenarios" if value else None
    # Structured product fields are authoritative. A same-SKU QA entry that
    # passes the canonical field policy is only a fallback when the structured
    # provider is missing or fails its semantic validation.
    if not value and canonical_field in {"usage_instruction", "cleaning", "care"}:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    if not value and canonical_field and canonical_field not in {
        "dimensions",
        "people",
        "dishwasher",
        "heat_source",
        "accessories",
    }:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    if not value and canonical_field:
        qa_evidence = _best_product_qa_match(
            db,
            product,
            raw_question or requested_field,
            requested_field_type=canonical_field,
            # The FieldContract already fixed the customer field and the
            # EntityResolutionContract already fixed this SKU.  Restrict the
            # fallback to request-side QA text (question/tags), so natural
            # wording such as a platform-purchase question can use a
            # field-compatible same-SKU QA without answer-body keyword drift.
            semantic_query=raw_question or requested_field,
        )
        qa_value = str(getattr(qa_evidence, "answer", "") or "").strip()
        if canonical_field == "dimensions" and qa_value and dimension_subtype:
            qa_subtype = customer_field_contract.requested_dimension_subtype(
                " ".join((
                    str(getattr(qa_evidence, "question", "") or ""),
                    str(getattr(qa_evidence, "tags", "") or ""),
                ))
            )
            if qa_subtype != dimension_subtype:
                qa_value = ""
        if canonical_field in {"usage_instruction", "cleaning", "care"} and qa_value:
            if not _usage_instruction_matches_product(product, qa_value):
                qa_value = ""
            elif canonical_field == "cleaning" and cleaning_subtype == "machine_wash":
                qa_value = _machine_wash_specific_evidence(qa_value)
            elif canonical_field == "usage_instruction" and usage_instruction_subtype == "liquid_temperature_capability":
                qa_value = _liquid_temperature_capability_evidence(qa_value)
        if qa_value:
            value = qa_value
            evidence_source = f"product_qa:{qa_evidence.id}"
            evidence_scope = "subject"
    if not value and canonical_field and canonical_field not in {
        "dimensions",
        "people",
        "dishwasher",
        "heat_source",
        "accessories",
    }:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    row = _product_row_from_model(product, specs, business, content)
    evidence_value = value
    capacity_conflict = (
        _capacity_evidence_conflict(product.product_name_cn, value)
        if requested_field == "容量" and value
        else None
    )
    color_conflict = (
        _color_evidence_conflict(product.product_name_cn, value)
        if requested_field == "颜色" and value
        else None
    )
    # Product-detail callers may provide either the display label ("热源")
    # or the canonical FieldContract type ("heat_source").  Evidence routing
    # must follow the contract, not the incidental display representation;
    # otherwise a sealed EntityResolutionContract skips its own same-SKU
    # structured heat-source evidence and falsely reports it as missing.
    if canonical_field == "heat_source":
        if not str(row.get("heat_source") or "").strip():
            merged_detail = product_service.get_product_detail(db, product.sku)
            merged_specs = merged_detail.get("specs") if isinstance(merged_detail, dict) else {}
            merged_heat_source = str((merged_specs or {}).get("heat_source") or "").strip()
            if merged_heat_source:
                row["heat_source"] = merged_heat_source
        if str(row.get("heat_source") or "").strip():
            evidence_source = "specs.heat_source"
        heat_source_evidence: dict[str, Any] = {}
        answer, evidence_status = _phase1_heat_source_capability_answer(
            db,
            row,
            raw_question or requested_field,
            evidence_metadata=heat_source_evidence,
        )
        evidence_value = str(heat_source_evidence.get("evidence_value") or "").strip()
        evidence_source = heat_source_evidence.get("evidence_source") or evidence_source
        evidence_scope = heat_source_evidence.get("evidence_scope") or evidence_scope
    elif requested_field == "适用人数":
        people_evidence: dict[str, Any] = {}
        answer = _phase1_people_capacity_answer(row, evidence_metadata=people_evidence)
        evidence_value = str(people_evidence.get("evidence_value") or "").strip()
        evidence_source = people_evidence.get("evidence_source")
        evidence_scope = people_evidence.get("evidence_scope") or evidence_scope
        evidence_status = "structured" if evidence_value else "missing"
    elif requested_field == "洗碗机适配":
        instruction = str(getattr(specs, "usage_instruction", "") or "").strip()
        dishwasher_evidence = (
            value
            if value and str(evidence_source or "").startswith("product_qa:")
            else _dishwasher_specific_evidence(instruction)
        )
        if dishwasher_evidence:
            evidence_value = dishwasher_evidence
            evidence_source = evidence_source or "specs.usage_instruction"
            answer = f"{product.product_name_cn}（{product.sku}）的洗碗机适配资料：{dishwasher_evidence}。"
            evidence_status = "structured"
        else:
            evidence_value = ""
            evidence_source = None
            answer = f"{product.product_name_cn}（{product.sku}）当前资料未标注，未明确说明是否可放入洗碗机。"
            evidence_status = "missing"
    elif capacity_conflict:
        name_capacity, structured_capacity = capacity_conflict
        answer = (
            f"{product.product_name_cn}（{product.sku}）的容量资料存在冲突："
            f"商品名称标注{name_capacity}，规格字段记录{structured_capacity}；"
            "当前无法确认准确容量，请以官方页面或人工核实结果为准。"
        )
        evidence_value = ""
        evidence_source = None
        evidence_status = "conflict"
    elif color_conflict:
        name_color, structured_color = color_conflict
        answer = (
            f"{product.product_name_cn}（{product.sku}）的颜色资料存在冲突："
            f"商品名称标注{name_color}，规格字段记录{structured_color}；"
            "当前无法确认准确颜色，请以官方页面或人工核实结果为准。"
        )
        evidence_value = ""
        evidence_source = None
        evidence_status = "conflict"
    elif value:
        if requested_field == "尺寸" and dimension_evidence is not None:
            display_value = dimension_evidence.value.replace("*", "×")
            display_unit = f" {dimension_evidence.unit}" if dimension_evidence.unit else ""
            if dimension_evidence.is_generic_fallback and dimension_subtype not in {"expanded", "storage", "package"}:
                answer = (
                    f"当前资料未单独维护{product.product_name_cn}（{product.sku}）的产品本体尺寸；"
                    f"仅记录了{dimension_evidence.label}：{display_value}{display_unit}。"
                )
            else:
                answer = (
                    f"{product.product_name_cn}（{product.sku}）的{dimension_evidence.label or requested_field}："
                    f"{display_value}{display_unit}。"
                )
        else:
            display_value = _field_display_value(requested_field, value)
            if requested_field == "核心卖点":
                display_value = re.sub(
                    rf"^(?:{re.escape(str(product.product_name_cn or '').strip())}的)?核心卖点(?:包括|有|是)?[：:]\s*",
                    "",
                    display_value,
                ).strip()
            answer = f"{product.product_name_cn}（{product.sku}）的{requested_field}：{display_value}。"
        evidence_status = "structured"
    else:
        dimension_missing_label = {
            "expanded": "展开尺寸",
            "storage": "收纳尺寸",
            "package": "包装尺寸",
        }.get(dimension_subtype, requested_field)
        if canonical_field == "cleaning" and cleaning_subtype == "machine_wash":
            answer = f"当前资料未明确标注{product.product_name_cn}（{product.sku}）是否可以用洗衣机机洗。"
        elif canonical_field == "usage_instruction" and usage_instruction_subtype == "liquid_temperature_capability":
            answer = f"{product.product_name_cn}（{product.sku}）：当前资料未直接标明是否可以装热水、冷水或开水。"
        elif canonical_field == "accessories":
            answer = (
                f"{product.product_name_cn}（{product.sku}）：当前资料未标注套装包含内容、"
                "包装清单或具体配件，无法确认具体清单。"
            )
        else:
            answer = (
                f"\u5f53\u524d\u8d44\u6599\u4e2d\u6682\u672a\u627e\u5230"
                f"{product.product_name_cn}\uff08{product.sku}\uff09\u7684{dimension_missing_label}\u3002"
            )
        evidence_status = "missing"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "sku": product.sku,
        "answer": answer,
        "results": [row],
        "result_skus": [product.sku],
        "candidate_skus": [product.sku],
        "answer_metadata": {
            "answer_policy": "field_only",
            "requested_field": canonical_field or requested_field,
            "requested_field_label": requested_field,
            "evidence_status": evidence_status,
            "evidence_field": canonical_field if evidence_value else None,
            "evidence_source": evidence_source,
            "evidence_value": evidence_value,
            "evidence_scope": evidence_scope if evidence_value else None,
            "evidence_sku": product.sku if evidence_value else None,
            "evidence_label": dimension_evidence.label if dimension_evidence else None,
            "evidence_unit": dimension_evidence.unit if dimension_evidence else None,
            "evidence_subtype": dimension_evidence.subtype if dimension_evidence else dimension_subtype or cleaning_subtype,
            "dimension_generic_fallback": dimension_evidence.is_generic_fallback if dimension_evidence else False,
            "field_evidence_match": bool(canonical_field and evidence_value),
            "field_evidence_missing": bool(canonical_field and not evidence_value),
        },
        "debug": {
            "agent_mode": "planner_product_compatibility" if requested_field == "heat_source" else "planner_product_field",
            "plan": {
                "primary_intent": "product_field",
                "product_ref": product.sku,
                "requested_field": requested_field,
                "raw_question": raw_question or requested_field,
            },
            "raw_results": [row],
            "candidate_skus": [product.sku],
        },
        "skip_polish": True,
    }


def _phase1_alcohol_stove_compatibility_answer(
    db: Session,
    row: dict,
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    category = str(row.get("category") or "").strip()
    heat_source = _heat_source_field_evidence(row.get("heat_source"))
    normalized_heat_source = "" if heat_source in {"", "/", "[]"} else heat_source
    if not normalized_heat_source and not any(term in category for term in ("锅", "炉", "壶", "酒具", "咖啡")):
        return f"{name}（{sku}）不是炉具或炊具，当前资料也未标注适用酒精炉；不建议按酒精炉适配产品理解。", "not_applicable"
    def _capability_evidence_status(value: str) -> str | None:
        text_value = str(value or "").strip().lower()
        if not text_value:
            return None
        if re.search(r"(?:未(?:标注|显示|找到)|没有|暂无).{0,20}(?:支持|适用|可用).{0,8}(酒精炉|alcohol stove)", text_value):
            return "not_listed"
        if re.search(r"(不支持|不适合|不建议|不能|不可).{0,8}(酒精炉|alcohol stove)", text_value):
            return "unsupported"
        if any(term in text_value for term in ("液体酒精", "工业酒精", "alcohol fuel")):
            return "supported"
        verdict = customer_agent_intent_service._alcohol_stove_support_verdict(text_value)
        if verdict is True:
            return "supported"
        if verdict is False:
            return "unsupported"
        return None

    evidence_status = _capability_evidence_status(normalized_heat_source)
    evidence = ""
    if normalized_heat_source and evidence_metadata is not None:
        evidence_metadata.update({
            "evidence_value": normalized_heat_source,
            "evidence_source": "specs.heat_source",
            "evidence_scope": "subject",
            "evidence_sku": sku,
        })
    if evidence_status is None and sku:
        evidence = str(customer_agent_intent_service._best_same_sku_evidence_text(
            db,
            sku=sku,
            supporting=None,
            term_groups=[("酒精炉", "alcohol stove")],
        ) or "").strip()
        evidence_status = _capability_evidence_status(evidence)
        if evidence and evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": evidence,
                "evidence_source": "product_qa",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
    if evidence_status == "supported":
        source_text = evidence or normalized_heat_source
        return f"{name}（{sku}）当前资料显示支持酒精炉；适用热源/同 SKU 证据为：{source_text}。", "supported"
    if evidence_status == "unsupported":
        return f"{name}（{sku}）当前资料显示不支持酒精炉；相关证据为：{evidence or normalized_heat_source}。", "unsupported"
    if normalized_heat_source or evidence_status == "not_listed":
        return f"{name}（{sku}）当前资料显示适用热源为：{normalized_heat_source}；当前资料未显示支持酒精炉。", "not_listed"
    return f"当前资料里没有找到{name}（{sku}）是否支持酒精炉的明确说明。", "missing"


def _same_sku_usage_instruction_heat_source_boundary(
    usage_instruction: Any,
    *,
    asked_capability: str,
    asks_direct_heating: bool,
) -> str:
    """Return an explicit negative heat-source boundary from same-SKU instructions.

    ``usage_instruction`` is not a general heat-source provider.  It is used
    here only when one complete source sentence directly negates the specific
    heat source or direct-heating operation in the customer's question.
    """
    text = str(usage_instruction or "").strip()
    if not text or text in {"[]", "/", "暂无", "未标注"}:
        return ""
    capability_terms = {
        "卡式炉": ("卡式炉",),
        "燃气炉": ("燃气炉", "气炉", "卡式炉"),
        "气炉": ("气炉", "燃气炉", "卡式炉"),
        "明火直烧": ("明火直烧", "明火"),
        "明火": ("明火", "明火直烧"),
        "分体炉": ("分体炉",),
        "一体炉": ("一体炉",),
    }.get(asked_capability, ())
    negative_markers = ("不可", "不能", "不建议", "严禁", "禁止")
    for sentence in re.split(r"(?<=[。！？!?；;])\s*", text):
        for clause in re.split(r"(?<=[，,])\s*", sentence):
            candidate = re.sub(r"\s+", " ", clause).strip()
            if not candidate or not any(marker in candidate for marker in negative_markers):
                continue
            directly_names_capability = bool(capability_terms and any(term in candidate for term in capability_terms))
            directly_names_operation = asks_direct_heating and any(
                term in candidate for term in ("直接加热", "直接置于", "直接放", "明火上加热")
            )
            if directly_names_capability or directly_names_operation:
                return candidate.rstrip("。；; ")
    return ""


def _phase1_heat_source_capability_answer(
    db: Session,
    row: dict,
    question: str,
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    text = str(question or "").strip()
    identity_free_text = text
    for identity in (
        row.get("product_name_cn"),
        row.get("product_name_en"),
        row.get("sku"),
    ):
        identity_text = str(identity or "").strip()
        if identity_text:
            identity_free_text = re.sub(re.escape(identity_text), "", identity_free_text, flags=re.IGNORECASE)
    if any(term in identity_free_text for term in ("酒精炉", "酒精")):
        return _phase1_alcohol_stove_compatibility_answer(db, row, evidence_metadata=evidence_metadata)

    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    prefix = f"{name}（{sku}）" if name else sku
    heat_source = _heat_source_field_evidence(row.get("heat_source"))
    normalized_heat_source = "" if heat_source in {"", "/", "[]", "暂无", "未标注"} else heat_source
    asks_direct_heating = any(term in identity_free_text for term in (
        "直接加热", "明火加热", "上火加热", "直接放", "直接置于",
    ))
    asks_heat_source = any(term in identity_free_text for term in ("热源", "燃料", "适用什么热源", "适用热源"))
    capability_aliases = {
        "卡式炉": ("卡式炉",),
        "燃气炉": ("燃气炉", "气炉", "卡式炉"),
        "气炉": ("气炉", "燃气炉", "卡式炉"),
        "明火直烧": ("明火直烧", "明火"),
        "明火": ("明火", "明火直烧"),
        "分体炉": ("分体炉",),
        "一体炉": ("一体炉",),
    }
    asked_capability = next((label for label in capability_aliases if label in identity_free_text), "")

    if normalized_heat_source:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": normalized_heat_source,
                "evidence_source": "specs.heat_source",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
        if asks_direct_heating:
            return f"{prefix}：可以按直接加热理解，当前资料显示适用热源为{normalized_heat_source}。", "supported"
        if asked_capability:
            aliases = capability_aliases.get(asked_capability, ())
            if any(alias and alias in normalized_heat_source for alias in aliases):
                return f"{prefix}：支持{asked_capability}，当前资料显示适用热源为{normalized_heat_source}。", "supported"
            return f"{prefix}：当前资料未显示支持{asked_capability}，当前资料显示适用热源为{normalized_heat_source}。", "not_listed"
        if "燃料" in text:
            return f"{prefix}：当前资料显示适用燃料/气源为{normalized_heat_source}。", "structured"
        if asks_heat_source:
            return f"{prefix}：当前资料显示适用热源为{normalized_heat_source}。", "structured"
        return f"{prefix}：当前资料显示适用热源为{normalized_heat_source}。", "structured"

    instruction_boundary = _same_sku_usage_instruction_heat_source_boundary(
        row.get("usage_instruction"),
        asked_capability=asked_capability,
        asks_direct_heating=asks_direct_heating,
    )
    if instruction_boundary:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": instruction_boundary,
                "evidence_source": "specs.usage_instruction",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
        return f"{prefix}：{instruction_boundary}。", "unsupported"

    if asks_direct_heating:
        return f"{prefix}：当前资料未标注适用热源；是否可以直接加热，不能仅凭现有资料确认。", "missing"
    if asked_capability:
        return f"{prefix}：当前资料未标注适用热源；是否支持{asked_capability}，不能仅凭现有资料确认。", "missing"
    return f"{prefix}：当前资料未标注适用热源，不能仅凭现有资料确认。", "missing"


def _result_has_positive_capability_evidence(result: dict[str, Any], question: str) -> bool:
    text = str(question or "").strip()
    if not isinstance(result, dict) or not text:
        return False
    rows = [row for row in (result.get("results") or []) if isinstance(row, dict)]
    if not rows:
        return False
    asks_alcohol = any(term in text for term in ("酒精炉", "酒精"))
    asks_heat_source = any(term in text for term in ("热源", "燃料", "明火", "卡式炉", "燃气炉"))
    asks_waterware_capability = any(term in text for term in ("直接加热", "烧水", "装热水", "喝热水", "冷水", "热水", "补水"))
    for row in rows:
        field_values = row.get("field_values") if isinstance(row.get("field_values"), dict) else {}
        evidence_values = [
            str(row.get("heat_source") or "").strip(),
            str(field_values.get("热源") or "").strip(),
            str(field_values.get("适用热源") or "").strip(),
            str(field_values.get("燃料") or "").strip(),
            str(field_values.get("是否支持酒精炉") or "").strip(),
        ]
        combined = " ".join(value for value in evidence_values if value)
        if asks_alcohol and customer_agent_intent_service._alcohol_stove_support_verdict(combined) is True:
            return True
        if asks_heat_source and combined:
            return True
        if asks_waterware_capability and any(term in combined for term in ("热水", "烧水", "补水", "冷水", "保温")):
            return True
    return False


def _phase1_pan_category_terms(category_ref: str) -> tuple[str, ...]:
    ref = str(category_ref or "").strip().lower()
    if ref == "煎盘":
        return ("煎盘", "煎烤盘", "griddle", "grill pan", "fry pan", "pan plate")
    if ref == "烤盘":
        return ("烤盘", "煎烤盘", "griddle", "grill pan", "pan plate")
    if ref == "煎烤盘":
        return ("煎盘", "烤盘", "煎烤盘", "griddle", "grill pan")
    return ("煎盘", "烤盘", "煎烤盘", "griddle", "grill pan", "fry pan", "pan plate")


def _phase1_is_pan_category_row(row: dict, category_ref: str) -> bool:
    category = str(row.get("category") or "").strip().lower()
    name = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "product_name_en")).lower()
    if any(term in category for term in ("炉具", "茶具", "水壶")):
        return False
    if "不含" in name and any(term in name for term in ("煎盘", "烤盘", "griddle", "grill pan")):
        return False
    haystack = " ".join(
        str(row.get(key) or "")
        for key in ("product_name_cn", "product_name_en", "category")
    ).lower()
    return any(term in haystack for term in _phase1_pan_category_terms(category_ref))


def _phase1_category_compatibility_result(db: Session, plan: dict) -> dict:
    category_ref = str(plan.get("category_ref") or "").strip() or "煎盘/烤盘"
    rows = [row for row in _phase1_catalog_rows(db, "产品") if _phase1_is_pan_category_row(row, category_ref)]
    skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
    if rows:
        lines = [f"你问的是{category_ref}这个品类。当前资料中的对应产品及酒精炉兼容性如下："]
        for row in rows:
            answer, _ = _phase1_alcohol_stove_compatibility_answer(db, row)
            lines.append(f"- {answer}")
        answer = "\n".join(lines)
    else:
        answer = f"你问的是{category_ref}这个品类。当前资料里没有找到对应产品，无法确认是否支持酒精炉；请提供具体产品名或 SKU。"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": rows,
        "result_skus": skus,
        "candidate_skus": skus,
        "answer_metadata": {
            "answer_policy": "category_compatibility",
            "requested_field": "heat_source",
            "category_ref": category_ref,
        },
        "debug": {
            "agent_mode": "planner_category_compatibility",
            "raw_results": rows,
            "candidate_skus": skus,
        },
        "skip_polish": True,
    }


def _phase1_catalog_rows(db: Session, product_ref: str) -> list[dict]:
    ref = str(product_ref or "").strip()
    category_scope_config = {
        "配件": {
            "categories": {"配件"},
            "sub_categories": ("收纳包具", "餐厨配件", "附件"),
            "fallback_terms": ("配件", "附件"),
        },
        "炉具": {
            "categories": {"炉具"},
            "sub_categories": ("炉具", "炉子", "酒精炉", "气炉", "卡式炉"),
            "fallback_terms": ("炉具", "炉子", "酒精炉", "卡式炉", "气炉"),
        },
        "餐具": {
            "categories": {"餐具"},
            "sub_categories": ("餐具",),
            "fallback_terms": ("餐具",),
        },
        "水具": {
            "categories": {"水具", "水壶"},
            "sub_categories": ("水具", "水壶", "水杯", "杯具"),
            "fallback_terms": ("水具", "水壶", "水杯", "杯具"),
        },
        "桌椅": {
            "categories": {"桌椅"},
            "sub_categories": ("桌椅",),
            "fallback_terms": ("桌椅",),
        },
        "咖啡器具": {
            "categories": {"咖啡器具"},
            "sub_categories": ("咖啡器具",),
            "fallback_terms": ("咖啡器具",),
        },
        "茶具": {
            "categories": {"茶具"},
            "sub_categories": ("茶具",),
            "fallback_terms": ("茶具",),
        },
        "天幕/地垫/帐篷": {
            "categories": {"天幕", "地垫", "帐篷", "天幕/地垫/帐篷", "天幕、地垫、帐篷"},
            "sub_categories": ("天幕", "地垫", "帐篷"),
            "fallback_terms": ("天幕", "地垫", "帐篷"),
        },
    }

    def _matches_category_scope(row: dict, scope: dict[str, Any]) -> bool:
        category = str(row.get("category") or "").strip()
        sub_category = str(row.get("sub_category") or "").strip()
        if category in (scope.get("categories") or set()):
            return True
        if sub_category and any(term in sub_category for term in (scope.get("sub_categories") or ())):
            return True
        if category or sub_category:
            return False
        name_text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "product_name_en"))
        return any(term and term in name_text for term in (scope.get("fallback_terms") or ()))

    query = (
        db.query(Product, ProductSpecs, ProductBusiness, ProductContent)
        .outerjoin(ProductSpecs, ProductSpecs.product_id == Product.id)
        .outerjoin(ProductBusiness, ProductBusiness.product_id == Product.id)
        .outerjoin(ProductContent, ProductContent.product_id == Product.id)
    )
    rows: list[dict] = []
    for product, specs, business, content in query.all():
        row = _product_row_from_model(product, specs, business, content)
        haystack = " ".join(str(row.get(key) or "") for key in (
            "product_name_cn",
            "product_name_en",
            "category",
            "capacity",
            "features",
            "usage_scenarios",
            "positioning",
            "long_description_cn",
        ))
        if ref == "产品":
            matched = True
        elif ref == "水壶":
            category_text = " ".join(str(row.get(key) or "") for key in ("category", "sub_category", "product_name_cn", "product_name_en"))
            matched = "水壶" in category_text
        elif ref == "锅具":
            # The catalogue label "锅具" includes product-family records that
            # are actually griddles or accessory components.  Count only
            # standalone pots and cookware sets, using the same canonical
            # candidate boundary as recommendation and structured filtering.
            matched = (
                customer_structured_query_contract.resolve_material_subject_scope(row, "\u9505\u5177")["eligible"]
                and _is_service_pot_or_cookware_set_candidate(row)
            )
        elif ref == "烤盘":
            category = str(row.get("category") or "").strip()
            griddle_text = " ".join(
                str(row.get(key) or "")
                for key in ("product_name_cn", "product_name_en", "sub_category", "features")
            )
            matched = category != "炉具" and any(term in griddle_text for term in ("烤盘", "煎盘", "煎烤盘"))
        elif ref in category_scope_config:
            matched = _matches_category_scope(row, category_scope_config[ref])
        elif ref == "套锅":
            matched = "套锅" in haystack or "锅" in str(row.get("category") or "") and "套" in haystack
        else:
            matched = bool(ref and ref in haystack)
        if matched:
            rows.append(row)
    return rows


def _database_category_scope_ref(rows: list[dict], semantic_subject: str) -> str:
    """Resolve a semantic category subject to an existing DB category label.

    This is a bounded catalogue-identity adapter, not a field-intent router:
    the semantic preplan has already chosen ``structured_query/category``.
    We only accept a subject that maps to a real category value (including a
    segment of a stored composite category) so product-name recall cannot
    broaden a category count.
    """
    subject = customer_agent_service.normalize_search_text(semantic_subject)
    if not subject:
        return ""
    normalized_categories = {
        customer_agent_service.normalize_search_text(str(row.get("category") or "")): str(row.get("category") or "").strip()
        for row in rows
        if str(row.get("category") or "").strip()
    }
    if subject in normalized_categories:
        return normalized_categories[subject]
    # A one-character head noun is a common customer shorthand for a stored
    # category label (锅 -> 锅具, 炉 -> 炉具).  Match only an actual category
    # label, never a product name or selling-point field.
    if len(subject) == 1:
        matches = [
            label for normalized, label in normalized_categories.items()
            if normalized.startswith(subject) and normalized.endswith("具")
        ]
        if len(matches) == 1:
            return matches[0]
    composite_matches = [
        label for normalized, label in normalized_categories.items()
        if subject and subject in normalized and any(separator in normalized for separator in ("/", "、", "，", ","))
    ]
    return composite_matches[0] if len(composite_matches) == 1 else ""


def _phase1_catalog_count_rows(db: Session, product_ref: str, question: str) -> tuple[list[dict], str | None]:
    """Return the authoritative category-membership population for count questions.

    Product discovery can deliberately use a narrower functional domain (for
    example, excluding a standalone griddle from cookware recommendations).
    A customer asking how many products are in a catalogue category needs the
    database category membership instead, including a product assigned to a
    composite category.  Keep that distinction at the aggregate boundary.
    """
    ref = str(product_ref or "").strip()
    text = str(question or "")
    is_count = any(token in text for token in ("多少", "几款", "几种", "几个"))
    if ref != "锅具" or not is_count:
        return _phase1_catalog_rows(db, ref), None

    rows = _phase1_catalog_rows(db, "产品")
    category_rows = [row for row in rows if "锅具" in str(row.get("category") or "")]
    pure_count = sum(str(row.get("category") or "").strip() == "锅具" for row in category_rows)
    composite_count = len(category_rows) - pure_count
    scope_note = f"其中类目为“锅具”{pure_count} 款"
    if composite_count:
        scope_note += f"，复合类目中包含“锅具”{composite_count} 款"
    return category_rows, scope_note


def _phase1_catalog_count_result(db: Session, plan: dict) -> dict:
    product_ref = str(plan.get("product_ref") or "").strip() or "产品"
    rows, scope_note = _phase1_catalog_count_rows(db, product_ref, str(plan.get("raw_question") or ""))
    display_ref = _phase1_catalog_display_label(product_ref)
    skus = [str(row.get("sku") or "") for row in rows if row.get("sku")]
    display_rows = _phase1_rank_catalog_display_rows(product_ref, rows)[:10]
    display_skus = [str(row.get("sku") or "") for row in display_rows if row.get("sku")]
    samples = "、".join(
        f"{row.get('sku')} {row.get('product_name_cn')}".strip()
        for row in display_rows
        if row.get("sku")
    )
    scope_label = f"【{display_ref}】" if product_ref != "产品" else "【产品】"
    if not rows:
        answer = f"当前产品库里暂未维护明确的{scope_label}类产品。"
        if product_ref != "产品":
            answer += " 如果你愿意，我可以改按相近类目或具体用途继续帮你找。"
    else:
        if samples and len(rows) > len(display_rows):
            suffix = f"先列前 {len(display_rows)} 款：{samples}。"
        elif samples:
            suffix = f"分别是：{samples}。"
        else:
            suffix = ""
        if product_ref == "配件" and samples:
            suffix = f"先按更像明确配件的小件/附件口径列前 {len(display_rows)} 款：{samples}。"
        elif product_ref == "水具" and samples:
            suffix = f"先按通用饮水/补水口径列前 {len(display_rows)} 款：{samples}。"
        answer = f"当前匹配到{scope_label}类产品共有 {len(rows)} 款。{suffix}"
        if scope_note:
            answer += f" 统计口径：{scope_note}。"
        if product_ref != "产品":
            answer += " 如果你想继续缩小范围，我可以再按用途、人数、容量、重量或收纳继续筛。"
    return {
        "intent": "query_products",
        "answer_type": "product_query" if product_ref == "天幕/地垫/帐篷" else "query_products",
        "answer": answer,
        "results": display_rows,
        "result_skus": display_skus,
        "candidate_skus": display_skus,
        "answer_metadata": {
            "source": "product_catalog_structured_query",
            "catalog_count": len(rows),
            "display_count": len(display_rows),
            "product_ref": product_ref,
        },
        "debug": {"agent_mode": "structured_catalog_count"},
        "skip_polish": True,
    }


def _phase1_catalog_display_label(product_ref: str) -> str:
    ref = str(product_ref or "").strip()
    if ref == "all_products":
        return "全部产品"
    if ref == "天幕/地垫/帐篷":
        return "天幕、地垫、帐篷"
    return ref


def _phase1_rank_catalog_display_rows(product_ref: str, rows: list[dict]) -> list[dict]:
    ref = str(product_ref or "").strip()
    if ref not in {"配件", "水具"}:
        return list(rows or [])

    def _score(row: dict) -> tuple[int, str]:
        text = " ".join(
            str(row.get(key) or "").strip()
            for key in ("product_name_cn", "product_name_en", "category", "sub_category", "features", "usage_scenarios", "positioning")
        )
        score = 0
        if ref == "配件":
            if any(term in text for term in ("配件", "附件", "替换件", "维修件", "炉芯", "防风板", "提手", "手夹", "刀板", "收纳件", "小配件")):
                score += 10
            if any(term in text for term in ("锅具配件", "餐厨配件", "炉具配件", "替换配件", "备用配件")):
                score += 5
            if any(term in text for term in ("收纳包", "折叠箱", "保温包", "围裙", "堆堆车", "炊雪盘", "水袋", "雪拉碗", "喷枪")):
                score -= 8
        elif ref == "水具":
            if any(term in text for term in ("水具", "水壶", "水杯", "杯", "饮水", "补水", "便携水具", "保温壶", "冷水壶")):
                score += 8
            if any(term in text for term in ("便携", "随身", "公园野餐", "徒步补水", "户外补水", "饮水")):
                score += 4
            if any(term in text for term in ("咖啡", "手冲", "细口壶", "煮茶")):
                score -= 6
            if any(term in text for term in ("烧水", "加热", "套装礼盒", "礼盒")):
                score -= 3
        sku = str(row.get("sku") or "")
        return (-score, sku)

    return sorted(list(rows or []), key=_score)


def _semantic_catalog_product_ref(question: str) -> str:
    text = str(question or "").strip()
    if any(term in text for term in ("咖啡器具", "手冲", "手冲壶")):
        return "咖啡器具"
    if "茶具" in text:
        return "茶具"
    if any(term in text for term in ("烤盘", "煎盘")):
        return "烤盘"
    if "水壶" in text:
        return "水壶"
    if "水具" in text:
        return "水具"
    if any(term in text for term in ("炉具", "炉子", "卡式炉", "分体炉", "一体炉", "气炉", "stove", "burner")):
        return "炉具"
    if any(term in text for term in ("锅具", "套锅", "单锅", "锅")):
        return "锅具"
    if "配件" in text:
        return "配件"
    if "餐具" in text:
        return "餐具"
    if "桌椅" in text:
        return "桌椅"
    if any(term in text for term in ("天幕", "地垫", "帐篷")):
        return "天幕/地垫/帐篷"
    return "产品"


_STRUCTURED_TARGET_CATEGORY_ALIASES = (
    ("咖啡器具", "咖啡器具"),
    ("烤盘", "烤盘"),
    ("煎盘", "烤盘"),
    ("水壶", "水壶"),
    ("水具", "水具"),
    ("锅具", "锅具"),
    ("炉具", "炉具"),
    ("炉子", "炉具"),
    ("配件", "配件"),
    ("餐具", "餐具"),
    ("桌椅", "桌椅"),
)


def _structured_target_category_from_question(question: str) -> str:
    text = str(question or "").strip()
    if not text:
        return ""
    aliases = "|".join(re.escape(alias) for alias, _ in _STRUCTURED_TARGET_CATEGORY_ALIASES)
    for pattern in (
        rf"(?:哪些|哪一些|有哪些)\s*({aliases})",
        rf"的\s*({aliases})\s*[？?。！!，,；;]*$",
    ):
        match = re.search(pattern, text)
        if match is not None:
            alias = match.group(1)
            return next(category for candidate, category in _STRUCTURED_TARGET_CATEGORY_ALIASES if candidate == alias)
    return ""


def _looks_like_semantic_catalog_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    generic_category_listing = bool(re.match(
        r"^\s*(?:有)?\s*(?:哪些|多少款|多少个|多少种|多少|几款|几种)\s*"
        r"(?:锅具|套锅|单锅|锅|炉具|炉子|炉|水具|水壶|配件|附件|餐具|桌椅|咖啡器具|咖啡|茶具|烤盘|煎盘|天幕|地垫|帐篷)"
        r"(?:产品|商品)?\s*[？?！!]?$",
        text,
    ))
    # A formal field predicate (shipping, price, material, etc.) outweighs a
    # coincidental count token such as "多少" inside a product question.
    if customer_field_contract.detect_field_contract(text) is not None and not generic_category_listing:
        return False
    count_or_list_terms = ("多少款", "多少个", "多少种", "多少", "几款", "几种", "有哪些", "列出")
    scope_terms = ("锅具", "套锅", "单锅", "锅", "炉具", "炉子", "炉", "水具", "水壶", "配件", "餐具", "桌椅", "咖啡器具", "咖啡", "茶具", "烤盘", "煎盘", "天幕", "地垫", "帐篷")
    if any(term in text for term in ("适合", "更偏", "能配", "搭配", "随身补水", "冷水", "热水", "手冲", "泡茶")):
        return False
    return any(term in text for term in count_or_list_terms) and any(term in text for term in scope_terms)


def _has_resolved_entity_contents_accessories_question(db: Session, question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if not customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return False
    if _resolve_sku(db, text, None):
        return True
    return bool(_products_named_in_question(db, text))


def _structured_query_row_text(row: dict[str, Any]) -> str:
    return " ".join(
        str(row.get(key) or "").strip()
        for key in (
            "sku",
            "product_name_cn",
            "product_name_en",
            "category",
            "sub_category",
            "capacity",
            "body_material",
            "material",
            "heat_source",
            "applicable_heat_source",
            "target_audience",
            "gross_weight_g",
            "specification",
            "size",
            "features",
            "usage_scenarios",
            "positioning",
            "long_description_cn",
        )
    )


def _structured_row_matches_category_value(row: dict[str, Any], value: str) -> bool:
    text = _structured_query_row_text(row)
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "水杯":
        has_cup_signal = any(token in text for token in ("水杯", "杯", "杯子", "随行杯", "保温杯", "钛杯", "马克杯"))
        has_kettle_signal = any(token in text for token in ("水壶", "茶壶", "烧水壶", "细口壶", "冷水壶", "保温壶"))
        return has_cup_signal and not has_kettle_signal
    if normalized == "水具":
        return any(token in text for token in ("水具", "水壶", "杯", "杯子", "水杯", "壶"))
    if normalized == "水壶":
        has_kettle_signal = any(token in text for token in ("水壶", "茶壶", "烧水壶", "细口壶", "冷水壶", "保温壶"))
        has_cup_signal = any(token in text for token in ("水杯", "杯", "杯子", "随行杯", "保温杯", "钛杯", "马克杯"))
        return has_kettle_signal and not has_cup_signal
    if normalized == "锅具":
        return "锅" in text
    if normalized == "炉具":
        return "炉" in text
    if normalized == "配件":
        return "配件" in text
    if normalized == "咖啡器具":
        return "咖啡" in text
    return normalized in text


def _structured_row_matches_material_value(row: dict[str, Any], value: str) -> bool:
    contract = customer_structured_query_contract.StructuredQueryContract(
        subject_category="all_products",
        field="material",
        operator="contains",
        value=str(value or "").strip(),
        status="resolved",
    )
    return customer_structured_query_contract.match_material_condition(contract=contract, row=row)["matched"]


def _structured_row_matches_heat_value(row: dict[str, Any], value: str) -> bool:
    text = " ".join(
        str(row.get(key) or "").strip()
        for key in ("heat_source", "applicable_heat_source", "features", "long_description_cn")
    )
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "明火直烧":
        return "明火" in text
    if normalized == "明火":
        return any(token in text for token in ("明火", "直接加热", "烧水"))
    if normalized == "卡式炉":
        return "卡式炉" in text or "卡式气罐" in text
    if normalized == "酒精炉":
        return "酒精炉" in text or "酒精" in text
    return normalized in text


def _structured_row_matches_usage_value(row: dict[str, Any], value: str) -> bool:
    text = " ".join(
        str(row.get(key) or "").strip()
        for key in ("usage_scenarios", "features", "positioning", "long_description_cn", "target_audience")
    )
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "徒步":
        return any(token in text for token in ("徒步", "轻量", "便携"))
    if normalized == "咖啡":
        return any(token in text for token in ("咖啡", "手冲", "滤杯", "分享壶", "细口壶"))
    if "徒步" in normalized:
        return any(token in text for token in ("徒步", "轻量", "便携"))
    if "新手" in normalized:
        return any(token in text for token in ("新手", "入门", "基础", "性价比"))
    return normalized in text


def _structured_product_query_result(
    *,
    question: str,
    product_ref: str,
    rows: list[dict[str, Any]],
    source: str,
    reason_label: str,
    answer_type: str = "product_query",
    metadata_source: str | None = None,
    membership_field: str | None = None,
) -> dict | None:
    display_rows = rows[:10]
    if not display_rows:
        return None
    result_skus = [str(row.get("sku") or "").strip().upper() for row in display_rows if str(row.get("sku") or "").strip()]
    sample_text = "、".join(
        f"{row.get('sku')} {row.get('product_name_cn')}".strip()
        for row in display_rows
        if row.get("sku")
    )
    answer = (
        f"当前按{reason_label}在【{product_ref}】里筛到 {len(rows)} 款候选。"
        f"{'先列前 %d 款：%s。' % (len(display_rows), sample_text) if sample_text else ''}"
        "如果你要继续缩小范围，我可以再按容量、重量、材质或人数继续筛。"
    )
    membership_evidence = []
    if membership_field:
        membership_label = customer_field_contract.product_detail_field_label(membership_field) or membership_field
        for row in display_rows:
            sku = str(row.get("sku") or "").strip().upper()
            value = row.get(membership_field)
            if sku and value is not None and str(value).strip():
                membership_evidence.append({
                    "type": "catalogue_membership",
                    "sku": sku,
                    "field": membership_field,
                    "field_label": membership_label,
                    "value": value,
                    "source_type": "product_db",
                    "source_label": "product_db",
                    "evidence_text": f"{membership_label} {value}",
                })
    return {
        "intent": "query_products",
        "answer_type": answer_type,
        "answer": answer,
        "results": display_rows,
        "result_skus": result_skus,
        "candidate_skus": result_skus,
        "evidence": membership_evidence,
        "answer_metadata": {
            "source": metadata_source or source,
            "product_ref": product_ref,
            "matched_count": len(rows),
            "membership_evidence_field": membership_field or "",
        },
        "debug": {"agent_mode": source, "raw_results": display_rows, "candidate_skus": result_skus},
        "skip_polish": True,
    }


def _detect_unknown_product_fact_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    for label, terms in _STRUCTURED_UNKNOWN_FACT_TERMS.items():
        if any(term in text for term in terms):
            return label
    return None


def _detect_resolved_entity_unknown_fact_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_contract = customer_field_contract.detect_field_contract(text)
    if field_contract and field_contract.field_type == "shipping":
        return "发货时效"
    if field_contract:
        contract_label = customer_field_contract.product_detail_field_label(field_contract.field_type)
        if contract_label in _RESOLVED_ENTITY_UNKNOWN_FACT_TERMS:
            return contract_label
    for label, terms in _RESOLVED_ENTITY_UNKNOWN_FACT_TERMS.items():
        if any(term in text for term in terms):
            return label
    return None


def _resolved_entity_unknown_field_guard_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    label = _detect_resolved_entity_unknown_fact_label(text)
    if label in _RESOLVED_ENTITY_REALTIME_COMMERCIAL_LABELS:
        return label
    if customer_agent_intent_service._looks_like_usage_care_question(text):
        return None
    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return None
    if customer_agent_intent_service._is_compare_question(text):
        return None
    if _looks_like_recommendation_request(text):
        return None
    return label


def _resolved_entity_realtime_commercial_field_guard_label(question: str) -> str | None:
    label = _resolved_entity_unknown_field_guard_label(question)
    if label in _RESOLVED_ENTITY_REALTIME_COMMERCIAL_LABELS:
        return label
    return None


def _semantic_preplan_unknown_realtime_subtype(preplan: dict | None, question: str) -> str:
    subtype = str((preplan or {}).get("subtype") or "").strip()
    if subtype in _SEMANTIC_UNKNOWN_REALTIME_SUBTYPES:
        return subtype
    route_hint = str((preplan or {}).get("route_hint") or "").strip()
    question_type = str((preplan or {}).get("question_type") or "").strip()
    label = _resolved_entity_realtime_commercial_field_guard_label(question) or _detect_unknown_product_fact_label(question)
    if label and (route_hint == "unknown_field" or question_type == "unknown_field" or (preplan or {}).get("unknown_field")):
        return "commercial_realtime"
    return ""


def _resolved_entity_unknown_fact_answer(prefix: str, label: str) -> str:
    special = {
        "库存": f"{prefix}\n当前资料未标注库存，也不能仅凭现有资料确认实时库存；请以平台或店铺页面为准，或联系人工客服确认。",
        "在售状态": f"{prefix}\n当前资料未维护可确认的实时在售状态或库存，不能仅凭静态产品资料判断；请以平台或店铺页面为准，或联系人工客服确认。",
        "销量": f"{prefix}\n当前资料未标注销量，也不能仅凭现有资料判断实时销量；请以平台或店铺页面为准。",
        "评价": f"{prefix}\n当前资料未标注评价或好评率，也不能仅凭现有资料确认实时评价信息；请以平台或店铺页面为准。",
        "价格": f"{prefix}\n当前资料未标注实时价格，也不能仅凭现有资料确认当前售价；请以平台或店铺页面为准。",
        "保修": f"{prefix}\n当前资料未标注保修信息，也无法仅凭现有资料确认具体质保政策；请以平台或店铺页面或人工客服说明为准。",
        "认证": f"{prefix}\n当前资料未标注对应认证或检测信息，不能仅凭现有资料确认。",
        "官方说明书": f"{prefix}\n当前资料未维护官方说明书信息，如需确认建议联系人工客服。",
        "售后电话": f"{prefix}\n当前资料未维护正式售后电话号码，无法提供可核验的联系电话；请通过购买平台的官方客服入口确认。",
        "安装视频": f"{prefix}\n当前资料未维护安装视频信息，如需确认建议联系人工客服。",
        "优惠活动": f"{prefix}\n当前资料未标注该商品的优惠、活动、券、会员价或到手价信息，也无法确认实时促销；请以平台或店铺页面为准。",
        # ``shipping`` is one safely-unsupported commercial field, but it
        # covers several customer meanings (carrier, dispatch/delivery timing,
        # postage, and delivery promises).  Do not fabricate an ETA premise
        # for a carrier question merely because both meanings share this
        # formal contract.  The semantic plan determines the field; this copy
        # is only the evidence-safe boundary when no matching same-SKU QA or
        # structured source exists.
        "发货时效": f"{prefix}\n当前资料未标注该商品的承运快递、发货或配送时效、运费及配送承诺等具体安排，无法确认；请以平台或店铺页面为准。",
        "赠品": f"{prefix}\n当前资料未标注该商品是否附赠赠品，也无法确认实时活动赠品；请以平台或店铺页面为准。",
        "包邮": f"{prefix}\n当前资料未标注该商品的包邮或运费规则，也无法确认实时包邮活动；请以平台或店铺页面为准。",
        "售后": f"{prefix}\n当前资料未标注该商品的售后政策或服务细则，也无法确认实时售后安排；请以平台或店铺页面或人工客服说明为准。",
    }
    # Non-realtime unsupported fields (for example a manufacturer model
    # number) must keep their own field boundary.  Do not borrow the generic
    # realtime-commercial disclaimer merely because this function also serves
    # price, inventory and delivery guards above.
    return special.get(label) or f"{prefix}\n当前资料未标注{label}信息，无法确认。"


def _build_resolved_product_unknown_field_result(
    db: Session,
    product: Product,
    *,
    label: str,
    source: str,
    resolution_decision: customer_entity_resolution_contract.SingleProductResolutionDecision,
) -> dict:
    row = _product_row_from_model(product)
    name = str(product.product_name_cn or product.product_name_en or product.sku or "").strip()
    sku = str(product.sku or "").strip().upper()
    if not resolution_decision.allowed or resolution_decision.resolved_sku != sku:
        raise ValueError("resolved unknown-field answer requires an allowed exact entity decision")
    prefix = f"{name}（{sku}）" if name else sku
    manual_document = None
    if label == "官方说明书":
        manual_document = (
            db.query(KnowledgeDocument)
            .filter(
                KnowledgeDocument.sku == sku,
                KnowledgeDocument.source_type == "manual",
                KnowledgeDocument.is_active.is_(True),
            )
            .order_by(KnowledgeDocument.updated_at.desc())
            .first()
        )
    manual_value = ""
    if manual_document is not None:
        manual_value = str(manual_document.file_name or manual_document.title or "").strip()
    if manual_value:
        answer = f"{prefix}\n当前资料已维护官方说明书：{manual_value}。"
    else:
        answer = _resolved_entity_unknown_fact_answer(prefix, label)
    evidence_field = "manual" if manual_value else None
    evidence_source = "knowledge_documents.manual" if manual_value else None
    evidence_value = manual_value
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        sku,
        [product],
        resolver_candidates=[product],
        entity_text_override=sku,
        field_type_override=customer_field_contract.field_type_from_detail_label(label),
    )
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [row],
        "result_skus": [sku],
        "candidate_skus": [sku],
        "sku": sku,
        "answer_metadata": {
            "source": source,
            "requested_field": label,
            "contract_field_type": customer_field_contract.field_type_from_detail_label(label),
            "evidence_status": "structured" if evidence_value else "missing",
            "evidence_field": evidence_field,
            "evidence_source": evidence_source,
            "evidence_value": evidence_value,
            "evidence_sku": sku if evidence_value else None,
            "evidence_scope": "subject" if evidence_value else None,
            "field_evidence_match": bool(evidence_value),
            "field_evidence_missing": not bool(evidence_value),
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "debug": {
            "agent_mode": source,
            "entity_resolution_contract": entity_contract.to_dict(),
            "single_product_resolution_decision": resolution_decision.to_dict(),
            "plan": {"primary_intent": "product_field", "product_ref": sku, "requested_field": label},
            "raw_results": [row],
            "candidate_skus": [sku],
        },
        "skip_polish": True,
    }


def _clarification_compatible_products(question: str, products: list[Product]) -> list[Product]:
    explicit_colors = [term for term in customer_agent_service.PRODUCT_COLOR_TERMS if term in str(question or "")]
    if not explicit_colors:
        return list(products)
    return [
        product
        for product in products
        if any(color in str(product.product_name_cn or product.product_name_en or "") for color in explicit_colors)
    ]


def _build_ambiguous_named_product_unknown_field_result(
    products: list[Product],
    *,
    label: str,
    question: str = "",
) -> dict:
    display_products = _clarification_compatible_products(question, products)[:5]
    rows = [_product_row_from_model(product) for product in display_products]
    options = "；".join(
        f"{str(product.product_name_cn or product.product_name_en or product.sku).strip()}（{str(product.sku or '').strip().upper()}）"
        for product in display_products
    )
    answer = (
        f"匹配到多个相关商品：{options}。请先指定 SKU 或具体款式；"
        f"另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        if options
        else f"没有找到与当前显式条件一致的明确商品。请提供 SKU 或更完整型号，再确认{label}信息。"
    )
    resolver_candidate_skus = [str(product.sku or "").strip().upper() for product in products[:5] if str(product.sku or "").strip()]
    clarification_candidate_skus = [str(product.sku or "").strip().upper() for product in display_products if str(product.sku or "").strip()]
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": resolver_candidate_skus,
        "clarification_candidate_skus": clarification_candidate_skus,
        "sku": None,
        "needs_clarification": True,
        "suggested_followups": ["请直接提供 SKU 或完整产品名。"],
        "followups": ["请直接提供 SKU 或完整产品名。"],
        "answer_metadata": {"source": "named_product_unknown_field_clarification", "requested_field": label, "evidence_status": "ambiguous_product"},
        "debug": {
            "agent_mode": "named_product_unknown_field_clarification",
            "plan": {"primary_intent": "clarify", "requested_field": label},
            "raw_results": rows,
            "candidate_skus": resolver_candidate_skus,
            "clarification_candidate_skus": clarification_candidate_skus,
        },
        "skip_polish": True,
    }


def _content_field_evidence_subtype(question: str, canonical_field: str | None) -> str | None:
    """Choose a content column only after the FieldContract has fixed its type."""
    text = str(question or "").casefold()
    field = str(canonical_field or "").strip()
    if field == "content_title":
        if "amazon" in text:
            return "content_title_amazon"
        if "官网" in text or "网站" in text:
            return "content_title_website"
        return "content_title_en" if "英文" in text or "english" in text else "content_title_cn"
    if field == "content_description":
        listing = "刊登" in text or "listing" in text
        english = "英文" in text or "english" in text
        if listing:
            return "content_description_listing_en" if english else "content_description_listing_cn"
        return "content_description_en" if english else "content_description_cn"
    return None


def _structured_product_field_evidence(
    canonical_field: str | None,
    *,
    db: Session,
    product: Product,
    specs: ProductSpecs | None,
    business: ProductBusiness | None,
    content: ProductContent | None,
    requested_subtype: str | None = None,
) -> tuple[str, str | None]:
    """Read the first non-empty value allowed by the canonical evidence policy."""
    policy = customer_field_contract.field_evidence_policy(canonical_field)
    if policy is None:
        return "", None
    if canonical_field == "specification":
        value = _specification_field_evidence(product=product, specs=specs)
        return (value, "specification.summary") if value else ("", None)
    if canonical_field in {"content_title", "content_description"}:
        if content is None:
            return "", None
        subtype = str(requested_subtype or "").strip()
        field_map = {
            "content_title_cn": "title_cn",
            "content_title_en": "title_en",
            "content_title_website": "website_title",
            "content_title_amazon": "amazon_title",
            "content_description_cn": "long_description_cn",
            "content_description_en": "long_description_en",
            "content_description_listing_cn": "listing_cn",
            "content_description_listing_en": "listing_en",
        }
        attribute = field_map.get(subtype)
        if not attribute:
            attribute = "title_cn" if canonical_field == "content_title" else "long_description_cn"
        value = _compound_display_value(getattr(content, attribute, ""))
        return (value, f"content.{attribute}") if _is_valid_structured_field_value(canonical_field, value) else ("", None)
    layers = {
        "product": product,
        "specs": specs,
        "business": business,
        "content": content,
    }
    for field_path in policy.structured_fields:
        if field_path.startswith("associations."):
            association = field_path.partition(".")[2]
            if association == "channels":
                values = [
                    str(row.channel_name or "").strip()
                    for row in (
                        db.query(ListingChannel)
                        .join(ProductListingChannel, ProductListingChannel.channel_id == ListingChannel.id)
                        .filter(ProductListingChannel.product_id == product.id)
                        .order_by(ListingChannel.channel_name.asc())
                        .all()
                    )
                ]
                source = "product_listing_channels->listing_channels"
            elif association == "regions":
                values = [
                    str(row.region_name or "").strip()
                    for row in (
                        db.query(SalesRegion)
                        .join(ProductSalesRegion, ProductSalesRegion.region_id == SalesRegion.id)
                        .filter(ProductSalesRegion.product_id == product.id)
                        .order_by(SalesRegion.region_name.asc())
                        .all()
                    )
                ]
                source = "product_sales_regions->sales_regions"
            elif association == "certifications":
                values = [
                    _certification_association_evidence(row)
                    for row in (
                        db.query(Certification)
                        .join(ProductCertification, ProductCertification.certification_id == Certification.id)
                        .filter(ProductCertification.product_id == product.id)
                        .order_by(Certification.certification_name.asc())
                        .all()
                    )
                ]
                source = "product_certifications->certifications"
            else:
                values, source = [], ""
            values = [item for item in values if _is_valid_structured_field_value(canonical_field, item)]
            if values:
                return "、".join(values), source
            continue
        layer_name, separator, attribute = str(field_path or "").partition(".")
        source = layers.get(layer_name)
        if not separator or source is None or not attribute:
            continue
        raw_value = getattr(source, attribute, None)
        value = (
            _weight_field_evidence(
                raw_value,
                capacity=getattr(specs, "capacity", "") if specs is not None else "",
            )
            if canonical_field == "weight" and field_path in {"specs.gross_weight_g", "specs.net_weight_g"}
            else
            _capacity_field_evidence(raw_value)
            if canonical_field == "capacity" and field_path == "specs.capacity"
            else _people_count_field_evidence(raw_value)
            if canonical_field == "people" and field_path in {"business.target_audience", "business.top_selling_points"}
            else _color_field_evidence(raw_value)
            if canonical_field == "color" and field_path == "specs.color"
            else _heat_source_field_evidence(raw_value)
            if canonical_field == "heat_source" and field_path == "specs.heat_source"
            else _selling_point_heat_source_evidence(raw_value)
            if canonical_field == "heat_source" and field_path == "business.top_selling_points"
            else _dishwasher_specific_evidence(raw_value)
            if canonical_field == "dishwasher"
            else _compound_display_value(raw_value)
        )
        if not _is_valid_structured_field_value(canonical_field, value):
            continue
        if field_path == "specs.usage_instruction" and canonical_field in {
            "usage_instruction",
            "cleaning",
            "care",
        }:
            if not _usage_instruction_matches_product(product, raw_value):
                continue
            value = (
                _machine_wash_specific_evidence(value)
                if canonical_field == "cleaning" and requested_subtype == "machine_wash"
                else _liquid_temperature_capability_evidence(value)
                if canonical_field == "usage_instruction" and requested_subtype == "liquid_temperature_capability"
                else _usage_instruction_field_evidence(value, canonical_field)
            )
            if not value:
                continue
        return value, field_path
    return "", None


def _weight_field_evidence(value: Any, *, capacity: Any = None) -> str:
    """Render a valid gram-column value without guessing an inconsistent unit."""
    try:
        grams = float(value)
    except (TypeError, ValueError):
        return ""
    if grams <= 0:
        return ""
    capacity_text = _capacity_field_evidence(capacity)
    capacity_liters = [
        float(match.group(1))
        for match in re.finditer(r"(\d+(?:\.\d+)?)\s*(?:L|l|升)", capacity_text)
    ]
    # ``gross_weight_g`` is explicitly a grams column.  A sub-five-gram value
    # alongside a 10L-or-larger capacity is an incompatible source-unit shape;
    # do not guess that the number means kilograms.  Fail closed until the
    # source data is corrected.
    if grams < 5 and any(liters >= 10 for liters in capacity_liters):
        return ""
    display = f"{grams:g}"
    return f"{display}g"


def _specification_field_evidence(
    *,
    product: Product,
    specs: ProductSpecs | None,
) -> str:
    """Build a field-scoped specification summary from validated SKU columns."""
    if specs is None:
        return ""
    parts: list[str] = []
    dimension = customer_field_contract.select_dimension_evidence(
        getattr(specs, "size_info", ""),
        requested_scope="subject",
    )
    if dimension and dimension.value:
        unit = f" {dimension.unit}" if dimension.unit else ""
        parts.append(f"尺寸：{dimension.value.replace('*', '×')}{unit}")
    def _without_own_label(value: Any, label: str) -> str:
        return re.sub(rf"^\s*{re.escape(label)}\s*[：:]\s*", "", str(value or "").strip())

    capacity = _without_own_label(_capacity_field_evidence(getattr(specs, "capacity", "")), "容量")
    if _is_valid_structured_field_value("capacity", capacity):
        parts.append(f"容量：{capacity}")
    weight = getattr(specs, "gross_weight_g", None)
    weight_display = _weight_field_evidence(weight, capacity=getattr(specs, "capacity", ""))
    if weight_display:
        parts.append(f"重量：{weight_display}")
    material = _without_own_label(_compound_display_value(getattr(specs, "body_material", "")), "材质")
    if _is_valid_structured_field_value("material", material):
        parts.append(f"材质：{material}")
    color = _without_own_label(_color_field_evidence(getattr(specs, "color", "")), "颜色")
    if _is_valid_structured_field_value("color", color):
        parts.append(f"颜色：{color}")
    power = _without_own_label(_compound_display_value(getattr(specs, "power", "")), "功率")
    if _is_valid_structured_field_value("power", power):
        parts.append(f"功率：{power}")
    return "；".join(parts)


def _certification_association_evidence(certification: Certification) -> str:
    """Preserve the dictionary explanation for a certification or standard label."""
    name = str(getattr(certification, "certification_name", "") or "").strip()
    description = str(getattr(certification, "description", "") or "").strip()
    if not description or description == name or description in name:
        return name
    return f"{name}（{description}）" if name else ""


def _is_valid_structured_field_value(canonical_field: str | None, value: Any) -> bool:
    """Reject placeholders before they become customer evidence."""
    text = _compound_display_value(value).strip()
    if not text or text.lower() in {"[]", "/", "null", "none", "n/a", "na", "unknown", "未分类", "未知", "暂无"}:
        return False
    if canonical_field == "barcode":
        return bool(re.fullmatch(r"\d{8,14}", text.replace(" ", "")))
    if canonical_field == "people":
        return bool(_people_count_field_evidence(text))
    return True


def _people_count_field_evidence(value: Any) -> str:
    """Return only an explicit serving headcount, never capacity or audience prose."""
    text = _compound_display_value(value).strip()
    match = re.search(
        r"(?:(?:\d+\s*[-~至]\s*\d+)|(?:\d+)|[一二两三四五六七八九十]+)\s*(?:个)?人",
        text,
    )
    return match.group(0) if match else ""


def _build_structured_query_contract_result(
    db: Session,
    contract: customer_structured_query_contract.StructuredQueryContract,
) -> dict:
    rows, evaluations = _evaluate_structured_query_contract_rows(db, contract)
    matched_skus = [item["sku"] for item in evaluations if item["matched"] and item["sku"]]
    by_sku = {str(row.get("sku") or "").strip().upper(): row for row in rows}
    filtered_rows = [by_sku[sku] for sku in matched_skus if sku in by_sku]
    display_rows = filtered_rows[:10]
    display_skus = [str(row.get("sku") or "").strip().upper() for row in display_rows if str(row.get("sku") or "").strip()]
    evidence = [item for item in evaluations if item["sku"] in set(display_skus)]
    evidence_guard = customer_structured_query_contract.validate_structured_evidence(
        contract=contract,
        filtered_rows=display_rows,
        evidence_rows=evidence,
    )
    evidence = evidence_guard["accepted_evidence"]
    subject_display = _phase1_catalog_display_label(str(contract.subject_category or ""))
    condition_summary = customer_structured_query_contract.format_structured_condition_summary(contract)
    if display_rows:
        samples = "、".join(
            f"{row.get('sku')} {row.get('product_name_cn')}".strip()
            for row in display_rows
        )
        if len(filtered_rows) > len(display_rows):
            answer = f"共找到 {len(filtered_rows)} 款符合“{condition_summary}”条件的【{subject_display}】商品，以下先展示前 {len(display_rows)} 款：{samples}。"
        else:
            answer = f"当前在【{subject_display}】中筛到 {len(filtered_rows)} 款符合“{condition_summary}”条件的商品：{samples}。"
    else:
        answer = (
            "当前结构化商品库未找到符合条件的商品。"
            f"查询类目：【{subject_display}】；筛选条件：{condition_summary}。"
        )
    contract_data = contract.to_dict()
    runtime_plan = {
        "product_ref": contract.subject_category,
        "requested_field": customer_field_contract.product_detail_field_label(contract.field) or contract.field,
    }
    return {
        "intent": "query_products",
        "answer_type": "product_query",
        "answer": answer,
        "results": display_rows,
        "result_skus": display_skus,
        "candidate_skus": display_skus,
        "answer_metadata": {
            "source": "structured_category_field_filter_query",
            "contract_source": "structured_query_contract",
            "product_ref": contract.subject_category,
            "matched_count": len(filtered_rows),
            "total_match_count": len(filtered_rows),
            "returned_count": len(display_rows),
            "is_truncated": len(filtered_rows) > len(display_rows),
            "condition_summary": condition_summary,
            "structured_query_contract": contract_data,
            "structured_match_evidence": evidence,
            "structured_rejected_evidence": evidence_guard["rejected_evidence"],
        },
        "debug": {
            "agent_mode": "structured_query_contract",
            "plan": runtime_plan,
            "structured_query_contract": contract_data,
            "structured_match_evidence": evidence,
            "raw_results": display_rows,
            "candidate_skus": display_skus,
        },
        "skip_polish": True,
    }


def _evaluate_structured_query_contract_rows(
    db: Session,
    contract: customer_structured_query_contract.StructuredQueryContract,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Evaluate structured filters across the canonical catalog candidate scope."""
    rows = _phase1_catalog_rows(db, "产品")
    evaluations = [customer_structured_query_contract.evaluate_structured_row(row, contract) for row in rows]
    return rows, evaluations


def _build_category_field_general_result(
    db: Session,
    contract: customer_structured_query_contract.StructuredQueryContract,
) -> dict:
    rows = _phase1_catalog_rows(db, "产品")
    aggregation = customer_structured_query_contract.aggregate_category_field_rows(rows, contract)
    field_label = {
        "heat_source": "适用炉具",
    }.get(str(contract.field or "")) or customer_field_contract.product_detail_field_label(contract.field) or "字段"
    subject_display = _phase1_catalog_display_label(str(contract.subject_category or ""))
    aggregated_values = list(aggregation["aggregated_values"])
    if aggregated_values and contract.field == "heat_source":
        groups = aggregation["value_groups"]
        appliances = "、".join(groups["appliance"])
        answer = (
            f"当前已标注的商品资料中，【{subject_display}】的适用炉具主要有：{appliances}。"
            if appliances
            else f"当前已标注的商品资料中，【{subject_display}】没有明确的适用炉具信息。"
        )
        additional_parts = []
        if groups["fuel_source"]:
            additional_parts.append(f"燃料或气源：{'、'.join(groups['fuel_source'])}")
        if groups["heating_method"]:
            additional_parts.append(f"其他加热方式：{'、'.join(groups['heating_method'])}")
        if groups["other"]:
            additional_parts.append(f"其他已标注信息：{'、'.join(groups['other'])}")
        if additional_parts:
            answer += f"另外，部分资料还标注了{'；'.join(additional_parts)}。"
    elif aggregated_values:
        displayed_values = aggregated_values[:12]
        values_text = "、".join(displayed_values)
        remainder = f"（共 {len(aggregated_values)} 种已标注值）" if len(aggregated_values) > len(displayed_values) else ""
        answer = f"当前已标注的商品资料中，【{subject_display}】的{field_label}主要有：{values_text}{remainder}。"
    else:
        answer = f"当前已标注的商品资料中没有找到明确的{field_label}信息。"
    contract_data = contract.to_dict()
    search_top1_promotion_blocked = bool(
        contract.status == "generic"
        and contract.subject_category
        and contract.field
        and contract.operator is None
        and contract.value is None
    )
    return {
        "intent": "query_products",
        "answer_type": "product_query",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {
            "source": "category_field_general",
            "subject_category": contract.subject_category,
            "field": contract.field,
            "structured_query_contract": contract_data,
            **aggregation,
        },
        "debug": {
            "agent_mode": "category_field_general",
            "structured_query_contract": contract_data,
            "candidate_skus": [],
            "aggregated_values": aggregated_values,
            "supporting_skus": aggregation["supporting_skus"],
            "binding_provenance": "none" if search_top1_promotion_blocked else None,
            "allow_search_top1_promotion": not search_top1_promotion_blocked,
            "search_top1_promotion_blocked": search_top1_promotion_blocked,
            "blocked_promotion_source": "category_field_general" if search_top1_promotion_blocked else None,
        },
        "skip_polish": True,
    }


def _build_generic_ambiguous_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    products: list[Product] | None = None,
    subject_override: str | None = None,
) -> dict:
    resolver_products = list(products or [])[:5]
    display_products = _clarification_compatible_products(question, resolver_products)
    rows = [_product_row_from_model(product) for product in display_products]
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or "这款商品"
    if rows:
        options = "；".join(
            f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{str(row.get('sku') or '').strip().upper()}）"
            for row in rows
            if str(row.get("sku") or "").strip()
        )
        answer = (
            f"“{subject}”这个叫法可能对应多个相关商品：{options}。"
            f"请先指定 SKU 或更完整的款式名；另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        )
    else:
        answer = (
            f"“{subject}”这个叫法可能对应多个相关商品。"
            f"请先提供 SKU 或更完整的商品名；另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        )
    candidate_skus = [str(product.sku or "").strip().upper() for product in resolver_products if str(product.sku or "").strip()]
    clarification_candidate_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": candidate_skus,
        "clarification_candidate_skus": clarification_candidate_skus,
        "sku": None,
        "needs_clarification": True,
        "suggested_followups": ["请直接提供 SKU 或完整产品名。"],
        "followups": ["请直接提供 SKU 或完整产品名。"],
        "answer_metadata": {"source": "named_product_unknown_field_clarification", "requested_field": label, "evidence_status": "ambiguous_product"},
        "debug": {
            "agent_mode": "named_product_unknown_field_clarification",
            "plan": {"primary_intent": "clarify", "requested_field": label},
            "raw_results": rows,
            "candidate_skus": candidate_skus,
            "clarification_candidate_skus": clarification_candidate_skus,
        },
        "skip_polish": True,
    }


def _enforce_field_evidence_policy(db: Session, question: str, agent_result: dict) -> dict:
    """Replace unsafe explicit-field answers with the deterministic same-SKU field result.

    This is deliberately narrow: only one explicit field, a single result SKU, and an
    exact canonical-name/SKU product mention can enter the guard. It cannot select a
    product for category, recommendation, comparison, or fuzzy entity requests.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    navigation_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if navigation_metadata.get("source") == "semantic_product_navigation_contract":
        # This turn intentionally established only a sealed identity anchor.
        # Tokens in the product name must not be retrofitted into an
        # unrequested field answer by the evidence-repair layer.
        return agent_result
    # Reuse the formal field decision already attached by the central route.
    # Re-parsing only the raw wording here can turn an incidental lexical word
    # (such as ``brand`` in a price-tier question) into a different field and
    # overwrite a correct Phase-2 answer.  Semantic classification remains
    # allowlisted and is still incapable of supplying identity or evidence.
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    attached_field_request = (
        debug.get("field_contract")
        if isinstance(debug.get("field_contract"), dict)
        else debug_plan.get("field_contract")
        if isinstance(debug_plan.get("field_contract"), dict)
        else None
    )
    # A generic QA contract is already sealed by exact entity resolution and
    # same-SKU QA evidence. Do not reinterpret it through an unrelated
    # semantic formal field during evidence-repair formatting.
    if str((attached_field_request or {}).get("field_type") or "").strip() == "product_qa":
        # A sealed semantic QA request may legitimately have no matching
        # same-SKU QA.  Its safe-missing response is still owned by the QA
        # contract; reparsing lexical fragments here must not relabel it as
        # an unrelated formal field (for example return policy -> heat source).
        return agent_result
    sealed_multi_fields = [
        str(field or "").strip()
        for field in (attached_field_request or {}).get("canonical_fields") or []
        if str(field or "").strip()
    ]
    sealed_evidence_skus = {
        str(sku or "").strip().upper()
        for sku in navigation_metadata.get("evidence_skus") or []
        if str(sku or "").strip()
    }
    result_skus = {
        str(sku or "").strip().upper()
        for sku in agent_result.get("result_skus") or []
        if str(sku or "").strip()
    }
    if (
        len(sealed_multi_fields) > 1
        and str((attached_field_request or {}).get("source") or "") == "validated_semantic_preplan"
        and len(result_skus) == 1
    ):
        # A resolved compound contract remains valid even when every requested
        # field is missing.  Requiring an evidence SKU here used to collapse
        # an all-missing answer to the first field during repair, silently
        # dropping the remaining customer request.
        return agent_result
    trusted_attached_field_sources = {
        "validated_semantic_preplan",
        "deterministic_full_predicate",
        "deterministic_alias",
    }
    attached_formal_field_type = (
        str(attached_field_request.get("field_type") or "").strip()
        if isinstance(attached_field_request, dict)
        and attached_field_request.get("source") in trusted_attached_field_sources
        and customer_field_contract.is_supported_detail_field(attached_field_request.get("field_type"))
        else None
    )
    semantic_preplan = debug.get("semantic_preplan") if isinstance(debug.get("semantic_preplan"), dict) else None
    formal_field_request = customer_field_contract.resolve_requested_field_contract(
        question,
        {"semantic_preplan": semantic_preplan} if semantic_preplan else None,
    )
    formal_field_type = (
        formal_field_request.get("field_type")
        if formal_field_request.get("source") == "validated_semantic_preplan"
        else None
    )
    field_contract = (
        customer_field_contract.field_contract_for_type(attached_formal_field_type or formal_field_type)
        if attached_formal_field_type or formal_field_type
        else customer_field_contract.detect_field_contract(question)
    )
    detected_field_types = customer_field_contract.detect_field_types(question)
    # A validated attached contract has already adjudicated the user's field.
    # Product names and parenthetical descriptors may contain another field
    # word (for example “赠品”), which must not exempt a mismatched QA answer
    # from same-field evidence enforcement.  Without that formal attachment,
    # preserve the existing fail-closed multi-field behavior.
    if not field_contract or (
        not attached_formal_field_type
        and not formal_field_type
        and len(detected_field_types) != 1
    ):
        return agent_result
    if str(agent_result.get("answer_type") or "") != "product_detail":
        return agent_result
    plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    tasks = [task for task in (plan.get("tasks") or []) if isinstance(task, dict)]
    if (
        plan.get("routing_conflict")
        or plan.get("must_compare_both_products")
        or plan.get("must_make_choice")
        or len(tasks) > 1
    ):
        return agent_result
    result_skus = [str(sku or "").strip().upper() for sku in (agent_result.get("result_skus") or []) if str(sku or "").strip()]
    if len(result_skus) != 1:
        return agent_result
    product = _explicit_product_from_question(db, question)
    if not product or str(product.sku or "").strip().upper() != result_skus[0]:
        return agent_result
    requested_label = customer_field_contract.product_detail_field_label(field_contract.field_type)
    if not requested_label:
        return agent_result
    # Material components (body, lid, handle) have independent evidence scopes.
    # A generic material replacement would collapse them to body material and
    # can therefore invent a lid/handle fact from an otherwise valid response.
    if (
        field_contract.field_type == "material"
        and customer_field_contract.material_component_detail_requests(question)
    ):
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    # Shipping is safely unsupported as a structured database field, but an
    # explicit same-SKU ProductQa record is an allowed evidence source under
    # the shipping FieldEvidencePolicy.  Preserve that sealed result instead
    # of rebuilding it as a generic real-time shipping safe-missing answer.
    # The metadata is created only after the QA helper has sealed both the
    # EntityResolutionContract and the field-compatible QA evidence.
    has_same_sku_shipping_qa_evidence = bool(
        field_contract.field_type == "shipping"
        and metadata.get("contract_field_type") == "shipping"
        and metadata.get("field_evidence_match") is True
        and str(metadata.get("evidence_field") or "") == "product_qa"
        and str(metadata.get("evidence_sku") or "").strip().upper() == result_skus[0]
        and str(metadata.get("evidence_source") or "").startswith("product_qa:")
    )
    if has_same_sku_shipping_qa_evidence:
        return agent_result
    # Warranty has no customer-facing structured column, but a sealed same-SKU
    # QA/RAG record may state the limited static fact that official warranty is
    # available. Preserve only that evidence-bound result; missing duration or
    # terms remain absent rather than becoming an invented policy.
    has_same_sku_warranty_evidence = bool(
        field_contract.field_type == "warranty"
        and metadata.get("contract_field_type") == "warranty"
        and metadata.get("field_evidence_match") is True
        and str(metadata.get("evidence_field") or "") == "warranty"
        and result_skus[0] in {
            str(metadata.get("evidence_sku") or "").strip().upper(),
            *(
                str(sku or "").strip().upper()
                for sku in metadata.get("evidence_skus") or []
            ),
        }
    )
    if has_same_sku_warranty_evidence:
        return agent_result
    if not customer_field_contract.is_supported_detail_field(field_contract.field_type):
        # Safely unsupported fields are never repaired from a different
        # structured field. Rebuild their answer through the exact-entity safe
        # boundary so a product-name token cannot replace (for example) a gift
        # request with heat-source evidence.
        entity_debug = debug.get("entity_resolution_contract") if isinstance(debug.get("entity_resolution_contract"), dict) else {}
        resolution_decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
            allowed=True,
            resolved_sku=result_skus[0],
            resolved_product_id=str(product.id),
            reason="field_evidence_guard_exact_identity",
            match_level=str(entity_debug.get("matched_by") or "canonical_name_exact"),
        )
        route_source = str(debug.get("agent_mode") or metadata.get("source") or "resolved_entity_unknown_field_fallback")
        if route_source not in {"resolved_entity_detail_contract", "resolved_entity_unknown_field_fallback"}:
            route_source = "resolved_entity_unknown_field_fallback"
        replacement = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=requested_label,
            source=route_source,
            resolution_decision=resolution_decision,
        )
        replacement_debug = replacement.get("debug") if isinstance(replacement.get("debug"), dict) else {}
        replacement_debug["field_contract"] = dict(attached_field_request or formal_field_request)
        if entity_debug:
            replacement_debug["entity_resolution_contract"] = dict(entity_debug)
        if isinstance(semantic_preplan, dict):
            replacement_debug["semantic_preplan"] = dict(semantic_preplan)
        replacement_debug["binding_provenance"] = "resolved_entity_contract"
        replacement_debug["field_evidence_guard_applied"] = True
        replacement["debug"] = replacement_debug
        return replacement
    evidence_field = str(metadata.get("evidence_field") or "").strip()
    evidence_sku = str(metadata.get("evidence_sku") or "").strip().upper()
    if evidence_field == field_contract.field_type and evidence_sku == result_skus[0]:
        return agent_result
    replacement = _phase1_product_field_result(db, {
        "primary_intent": "product_field",
        "answer_type": "product_detail",
        "product_ref": result_skus[0],
        "sku": result_skus[0],
        "requested_field": requested_label,
        "field_type_override": field_contract.field_type,
        "field_only": True,
        "product_identity_source": "field_evidence_repair",
        "raw_question": question,
    })
    if not replacement:
        return agent_result
    replacement_metadata = replacement.get("answer_metadata") if isinstance(replacement.get("answer_metadata"), dict) else {}
    if not evidence_field:
        evidence_value = str(replacement_metadata.get("evidence_value") or "").strip()
        normalized_answer = re.sub(r"[\s，,。；;：:（）()]", "", str(agent_result.get("answer") or ""))
        normalized_evidence = re.sub(r"[\s，,。；;：:（）()]", "", evidence_value)
        # A compound answer can legitimately combine the requested structured
        # field with another same-SKU QA/KB-supported intent. Preserve it when
        # the structured evidence is already visible in the answer; attach the
        # formal evidence metadata instead of collapsing the second intent.
        if normalized_evidence and normalized_evidence in normalized_answer:
            metadata.update({
                key: replacement_metadata.get(key)
                for key in (
                    "evidence_status",
                    "evidence_field",
                    "evidence_source",
                    "evidence_value",
                    "evidence_scope",
                    "evidence_sku",
                    "evidence_label",
                    "evidence_unit",
                    "evidence_subtype",
                    "field_evidence_match",
                    "field_evidence_missing",
                )
            })
            metadata["field_evidence_metadata_repaired"] = True
            agent_result["answer_metadata"] = metadata
            debug["field_evidence_guard_applied"] = True
            agent_result["debug"] = debug
            return agent_result
        requested_label = customer_field_contract.product_detail_field_label(field_contract.field_type) or ""
        safe_missing_markers = ("暂未", "未找到", "未维护", "未标注", "无法确认", "没有")
        if (
            replacement_metadata.get("field_evidence_missing") is True
            and requested_label
            and requested_label in str(agent_result.get("answer") or "")
            and any(marker in str(agent_result.get("answer") or "") for marker in safe_missing_markers)
        ):
            metadata.update({
                key: replacement_metadata.get(key)
                for key in (
                    "evidence_status",
                    "evidence_field",
                    "evidence_source",
                    "evidence_value",
                    "evidence_scope",
                    "evidence_sku",
                    "evidence_label",
                    "evidence_unit",
                    "evidence_subtype",
                    "field_evidence_match",
                    "field_evidence_missing",
                )
            })
            metadata["field_evidence_metadata_repaired"] = True
            agent_result["answer_metadata"] = metadata
            debug["field_evidence_guard_applied"] = True
            agent_result["debug"] = debug
            return agent_result
    replacement_debug = replacement.get("debug") if isinstance(replacement.get("debug"), dict) else {}
    replacement_debug["field_evidence_guard_applied"] = True
    # Evidence repair may change formatter provenance, never the already
    # sealed identity or formal field decision that caused the repair.
    if isinstance(attached_field_request, dict):
        replacement_debug["field_contract"] = dict(attached_field_request)
        replacement_plan = replacement_debug.get("plan") if isinstance(replacement_debug.get("plan"), dict) else {}
        replacement_plan["field_contract"] = dict(attached_field_request)
        if isinstance(debug_plan, dict):
            for key in ("primary_intent", "requested_field", "requested_fields", "product_ref"):
                if key in debug_plan:
                    replacement_plan[key] = debug_plan[key]
        replacement_debug["plan"] = replacement_plan
    if isinstance(debug.get("entity_resolution_contract"), dict):
        replacement_debug["entity_resolution_contract"] = dict(debug["entity_resolution_contract"])
    if isinstance(semantic_preplan, dict):
        replacement_debug["semantic_preplan"] = dict(semantic_preplan)
    replacement_debug["agent_mode"] = str(debug.get("agent_mode") or "resolved_entity_detail_contract")
    replacement["debug"] = replacement_debug
    replacement_metadata["qa_shortcut_rejected_reason"] = (
        "field_evidence_missing"
        if not evidence_field
        else "field_evidence_mismatch"
    )
    replacement_metadata["contract_field_type"] = field_contract.field_type
    if isinstance(metadata.get("timing"), dict):
        replacement_metadata["timing"] = dict(metadata["timing"])
    replacement["answer_metadata"] = replacement_metadata
    return replacement


def _build_unresolved_product_like_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict | None:
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question)
    if not subject:
        return None
    if not _looks_like_product_like_scope_subject(subject):
        return None
    if _is_generic_contents_subject(subject):
        return None
    product_like_suffixes = ("壶", "水壶", "锅", "套锅", "炉", "炉具", "烤盘", "盘", "杯", "茶具", "咖啡壶", " kettle")
    normalized_subject = customer_agent_service.normalize_search_text(subject).strip()
    if (
        not any(normalized_subject.endswith(suffix.strip()) for suffix in product_like_suffixes if suffix.strip())
        and not _looks_like_product_like_scope_subject(subject)
    ):
        return None
    answer = (
        f"我没能在当前商品资料里明确找到“{subject}”对应的具体 SKU。"
        f"你可以提供 SKU，或确认是哪一款商品，我再帮你判断这款商品的实时{label}类信息该去哪里确认。"
    )
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "unresolved_product_like_unknown_field_clarification",
            "requested_field": label,
            "evidence_status": "unresolved_product_like_subject",
        },
        "debug": {"agent_mode": "unresolved_product_like_unknown_field_clarification"},
        "skip_polish": True,
    }


def _generic_unresolved_product_like_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict:
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or "这款商品"
    answer = (
        f"我还没法把“{subject}”稳定对应到具体 SKU。"
        f"你可以提供 SKU 或更完整的商品名，我再帮你判断这款商品的实时{label}类信息该去哪里确认。"
    )
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "unresolved_product_like_unknown_field_clarification",
            "requested_field": label,
            "evidence_status": "unresolved_product_like_subject",
        },
        "debug": {"agent_mode": "unresolved_product_like_unknown_field_clarification"},
        "skip_polish": True,
    }


def _build_unknown_field_product_not_found_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict:
    extracted_skus = [str(item or "").strip().upper() for item in customer_agent_service._extract_skus(question) if str(item or "").strip()]
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or question
    target = extracted_skus[0] if extracted_skus else str(subject or "").strip()
    answer = f"没有找到“{target}”对应的产品资料，当前无法确认它的{label}信息。请确认 SKU 或产品名是否正确。"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {
            "source": "unknown_field_product_not_found",
            "requested_field": label,
            "evidence_status": "product_not_found",
        },
        "debug": {"agent_mode": "unknown_field_product_not_found"},
        "skip_polish": True,
    }


def _try_resolved_product_unknown_field_shortcut(db: Session, question: str) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    label = _resolved_entity_unknown_field_guard_label(text)
    if not label:
        return None

    products = db.query(Product).order_by(Product.sku.asc()).all()
    named_products = _products_named_in_question(db, text)
    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=text,
        fallback_product_like_subject=_product_like_scope_subject(text),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(text).strip(),
    )
    subject = subject_selection.entity_subject
    entity_selection = _choose_effective_entity_contract(
        text,
        products,
        resolver_candidates=named_products,
        override_subject=subject or None,
    )
    entity_contract = entity_selection.contract
    resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(
        entity_contract,
        products,
    )
    if resolution_decision.allowed:
        product = next(
            (item for item in products if str(item.sku or "").strip().upper() == resolution_decision.resolved_sku),
            None,
        )
        if not product:
            return None
        if _has_direct_structured_detail_answer(db, product, text):
            return None
        exact_qa = _best_product_qa_match(db, product, text)
        if exact_qa and _is_exact_product_qa_question_match(exact_qa, text):
            return None
        field_contract = customer_field_contract.detect_field_contract(text)
        field_type = str(field_contract.field_type or "").strip() if field_contract else ""
        # Warranty is a formal field. Its missing structured column may be
        # supplemented only by the later sealed same-SKU QA/RAG adapter; this
        # legacy unknown-field shortcut has no authority to decide that
        # evidence is absent before the formal contract runs.
        if field_type == "warranty":
            return None
        if field_type:
            compatible_qa = _best_product_qa_match(
                db,
                product,
                text,
                requested_field_type=field_type,
            )
            if compatible_qa is not None:
                # A compatible QA is not an alternate route: it is admissible
                # evidence for the existing formal FieldContract. Let the
                # central detail executor consume it after identity is sealed.
                return None
        return _build_resolved_product_unknown_field_result(
            db,
            product,
            label=label,
            source="resolved_entity_unknown_field_fallback",
            resolution_decision=resolution_decision,
        )
    if len(named_products) > 1:
        return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
    return None


def _pre_route_high_risk_contract_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_contract = customer_field_contract.detect_field_contract(text)
    # A current-availability contract is not a live sales feed.  A question
    # phrased as "still sold?" is therefore a current availability request
    # even if the semantic provider mistakenly calls it product QA.  This is
    # a safety veto only: it supplies neither a route answer nor a product
    # fact and lets the existing safe-missing contract retain the resolved
    # identity.
    current_availability_request = bool(
        field_contract and field_contract.field_type in {"inventory", "lifecycle_status"}
    )
    # A validated product-QA turn has its own sealed identity and same-SKU
    # evidence path. This guard protects realtime and legacy unknown fields;
    # it must not reinterpret a product-QA subject before that contract can
    # resolve the entity and retrieve bounded QA/KB evidence.
    if (
        _semantic_prefers_sealed_product_qa({"semantic_preplan": semantic_preplan})
        and not current_availability_request
    ):
        return None
    # An ordinal field follow-up has a sealed candidate-set identity in the
    # conversation.  It is not an unknown-product request, so this guard must
    # not consume it before the context resolver forms its entity contract.
    if _looks_like_ordinal_product_field_followup(text):
        return None
    generic_scope = customer_field_contract.select_entity_subject_for_routing(raw_question=text)
    if _is_generic_company_product_scope(generic_scope.entity_subject):
        # “你们产品” / “本店商品” denotes the merchant catalogue, never a
        # single product identity.  Let the generic business/FAQ route answer
        # it instead of converting a formal field signal into an unresolved
        # product clarification.
        return None
    # Ordinals resolve against the persisted candidate set, not against a new
    # free-text entity span.  Let the dedicated conversation resolver consume
    # them before this current-turn entity guard tries to fail them closed.
    if _looks_like_ordinal_product_field_followup(text):
        return None
    if field_contract and field_contract.field_type in {"accessories", "warranty", "gift", "manual"}:
        return None
    high_risk_field_types = {
        "after_sales_contact",
        "inventory",
        "price",
        "warranty",
        "shipping",
        "manual",
        "lifecycle_status",
    }
    # This early guard exists only for realtime/commercial or legacy unknown
    # facts. A different formal database field may contain a high-risk-looking
    # word (for example price_positioning contains "price"); it must continue
    # to the central FieldContract/EntityResolutionContract detail path.
    semantic_unknown_realtime = _semantic_preplan_unknown_realtime_subtype(semantic_preplan, text)
    if (
        field_contract
        and field_contract.field_type not in high_risk_field_types
        and not semantic_unknown_realtime
    ):
        return None
    semantic_field = str((semantic_preplan or {}).get("field_type") or "").strip()
    if (
        semantic_field
        and semantic_field in customer_field_contract.FORMAL_DETAIL_FIELDS
        and not bool((semantic_preplan or {}).get("fallback_reason"))
        and not bool((semantic_preplan or {}).get("ambiguity"))
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
    ):
        # A schema-validated semantic detail field must reach Phase 2 before
        # broad legacy words such as "认证" or "价格" can trigger an
        # unknown-fact guard. This remains true when a weaker lexical parser
        # found a conflicting field such as price inside price positioning.
        # The semantic layer still supplies no identity or evidence.
        return None
    has_semantic_preplan = isinstance(semantic_preplan, dict) and semantic_preplan.get("called")
    deterministic_unknown_fields = {"manual", "after_sales_contact"}
    if not has_semantic_preplan and not (
        field_contract and field_contract.field_type in deterministic_unknown_fields
    ):
        return None
    if _looks_like_semantic_waterware_capability_query(text):
        return None
    # The semantic provider owns meaning for natural current-purchasability
    # wording.  Once it has emitted the validated unknown-realtime contract,
    # this layer supplies only the safe display label and sealed identity; it
    # must not require a second lexical alias before refusing an unverifiable
    # live-sales claim.
    label = (
        "在售状态"
        if current_availability_request or semantic_unknown_realtime
        else (_resolved_entity_realtime_commercial_field_guard_label(text) or _detect_unknown_product_fact_label(text))
    )
    if not label and field_contract and field_contract.field_type in deterministic_unknown_fields:
        label = customer_field_contract.product_detail_field_label(field_contract.field_type)
    if not label:
        return None
    supported_detail_field = customer_field_contract.is_supported_detail_field(
        field_contract.field_type if field_contract else None
    )
    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=text,
        fallback_product_like_subject=_product_like_scope_subject(text),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(text).strip(),
    )
    subject = subject_selection.entity_subject
    contract_products: list[Product] = []
    try:
        contract_products = db.query(Product).order_by(Product.sku.asc()).all()
        # Prefer a unique full catalogue mention contained in the current
        # turn over a field-adjacent subject polluted by a trailing discourse
        # pronoun (for example, "<product> it still sold?").  This is only
        # identity normalization: it neither chooses a field nor turns a
        # generic request into a product question.
        canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
            text,
            contract_products,
        )
        entity_selection = _choose_effective_entity_contract(
            text,
            contract_products,
            override_subject=canonical_subject or subject or None,
        )
        entity_contract = entity_selection.contract
    except Exception:
        entity_contract = None
    resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(
        entity_contract,
        contract_products,
    )
    displayable_ambiguity_skus = _displayable_phase2_clarification_candidate_skus(entity_contract)
    if displayable_ambiguity_skus:
        displayable_set = set(displayable_ambiguity_skus)
        result = _build_ambiguous_named_product_unknown_field_result(
            [
                product
                for product in contract_products
                if str(product.sku or "").strip().upper() in displayable_set
            ],
            label=label,
            question=text,
        )
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["entity_resolution_contract"] = entity_contract.to_dict()
        result["debug"] = debug
        return result
    # A semantic ambiguity verdict is authoritative for identity safety. It
    # must be handled before a permissive lexical resolver can turn one of the
    # candidate names into a resolved product and answer a high-risk field.
    entity_scope_hint = str((semantic_preplan or {}).get("entity_scope") or "").strip()
    if entity_scope_hint == "ambiguous_product_name":
        named_products = _products_named_in_question(db, text)
        if len(named_products) > 1:
            return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
        return _build_generic_ambiguous_unknown_field_clarification_result(
            text,
            label=label,
            products=named_products,
            subject_override=str(((semantic_preplan or {}).get("entities") or [""])[0] or ""),
        )
    if resolution_decision.allowed:
        product = next(
            (
                item
                for item in contract_products
                if str(item.sku or "").strip().upper() == resolution_decision.resolved_sku
            ),
            None,
        )
        if product:
            field_type = str(field_contract.field_type or "").strip() if field_contract else ""
            if field_type and _best_product_qa_match(
                db,
                product,
                text,
                requested_field_type=field_type,
            ) is not None:
                # A same-SKU QA compatible with the already recognised formal
                # field is evidence for the central detail executor, not a
                # reason to emit a generic realtime-safe fallback early.
                return None
            result = _build_resolved_product_unknown_field_result(
                db,
                product,
                label=label,
                source="resolved_entity_unknown_field_fallback",
                resolution_decision=resolution_decision,
            )
            debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
            debug["entity_resolution_contract"] = entity_contract.to_dict()
            result["debug"] = debug
            return result
    subtype = str((semantic_preplan or {}).get("subtype") or "").strip()
    entity_scope_hint = str((semantic_preplan or {}).get("entity_scope") or "").strip()
    entity_texts = [
        str(item or "").strip()
        for item in ((semantic_preplan or {}).get("entities") or [])
        if str(item or "").strip()
    ]
    primary_entity = entity_texts[0] if entity_texts else ""

    named_products = _products_named_in_question(db, text)
    if primary_entity:
        entity_named_products = customer_agent_service.resolve_named_product_candidates(
            primary_entity,
            db.query(Product).all(),
            subject=primary_entity,
        )
        if len(entity_named_products) > len(named_products):
            named_products = entity_named_products
    if entity_scope_hint == "ambiguous_product_name":
        if len(named_products) > 1:
            return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
        return _build_generic_ambiguous_unknown_field_clarification_result(
            text,
            label=label,
            products=named_products,
            subject_override=primary_entity,
        )
    if len(named_products) > 1:
        return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
    if subtype == "no_match":
        return _build_unknown_field_product_not_found_result(text, label=label, subject_override=primary_entity)
    unresolved_clarification = _build_unresolved_product_like_unknown_field_clarification_result(
        text,
        label=label,
        subject_override=primary_entity,
    )
    if unresolved_clarification:
        return unresolved_clarification
    if entity_scope_hint == "unresolved_product_like":
        return _generic_unresolved_product_like_unknown_field_clarification_result(
            text,
            label=label,
            subject_override=primary_entity,
        )
    if customer_agent_service._extract_skus(text):
        return _build_unknown_field_product_not_found_result(text, label=label, subject_override=primary_entity)
    if subtype in _SEMANTIC_UNKNOWN_REALTIME_SUBTYPES:
        return unresolved_clarification
    if label == "价格" and _looks_like_generic_constraint_category_query(text):
        return None
    if (
        not _contains_explicit_negative_product_marker(text)
        and not _looks_like_recommendation_request(text)
        and not customer_agent_intent_service._looks_like_contents_grounding_question(text)
        and (
            customer_agent_intent_service._looks_like_usage_care_question(text)
            or _looks_like_product_detail_field_question(text)
            or (
                supported_detail_field
                and str((semantic_preplan or {}).get("route_hint") or "").strip() == "product_detail"
            )
        )
    ):
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"我还不能把“{primary_entity or subject or '该商品'}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名，我再继续确认这个问题。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "needs_clarification": True,
            "answer_metadata": {"source": "entity_scope_ambiguous_clarification", "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": "entity_scope_ambiguous_clarification"},
            "skip_polish": True,
        }
    if not primary_entity and not _has_unresolved_product_like_scope(db, text):
        return _unknown_product_fact_result(text)
    return None


def _semantic_outage_named_product_field_clarification_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    """Fail closed before legacy routes when semantic field understanding is unavailable.

    A current-turn product reference seals only identity; it must not authorize a
    free-form product fact when the semantic layer could not classify the field.
    Deterministically recognized FieldContracts keep their normal central path.
    """
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    fallback_reason = str(preplan.get("fallback_reason") or "").strip()
    if not (preplan.get("called") and fallback_reason.startswith("llm_error:")):
        return None
    # A comparison is a multi-entity contract even while semantic planning is
    # unavailable.  Its deterministic comparator already seals every explicit
    # SKU, so this single-entity safety guard must never consume it first.
    if customer_agent_intent_service._is_compare_question(question):
        return None
    # A pure exact-SKU identity question has no product field to classify:
    # identity is the requested fact.  The semantic preplan has already had
    # first opportunity to interpret the turn; when it is unavailable, defer
    # to the existing exact-SKU identity contract rather than mistaking the
    # request for an unclassified product field.  That contract independently
    # seals the SKU before it reads the product's own identity data.
    if _is_explicit_sku_identity_only_question(question):
        return None
    # Use the same central adapter as Phase 2.  Calling the raw registry here
    # skipped its controlled planner/legacy compatibility inputs during an
    # outage, so a product-agnostic capability predicate could be clarified
    # despite the normal FieldContract fallback being able to classify it.
    field_request = resolve_requested_field_contract(
        question,
        {"semantic_preplan": preplan},
    )
    # A field can be formally recognized yet deliberately safe-unsupported
    # (for example gift/manual/realtime commercial fields).  It still owns a
    # canonical FieldContract and must reach its entity-bound safe-missing
    # formatter rather than being replaced by generic semantic clarification.
    # ``field_type`` is intentionally None for a compound contract.  The
    # semantic-outage guard must therefore inspect the canonical contract as
    # a whole; otherwise a deterministic, formally supported multi-field
    # request is mistaken for an unclassified free-form fact and is
    # needlessly clarified before the central executor can run.
    if field_request.get("canonical_fields"):
        return None
    products = db.query(Product).order_by(Product.sku.asc()).all()
    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=question,
        fallback_product_like_subject=_product_like_scope_subject(question),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(question).strip(),
    )
    entity_selection = _choose_effective_entity_contract(
        question,
        products,
        resolver_candidates=_products_named_in_question(db, question),
        override_subject=subject_selection.entity_subject or None,
    )
    entity_contract = entity_selection.contract
    resolution = customer_entity_resolution_contract.can_resolve_single_product(
        entity_contract,
        products,
    )
    if not resolution.allowed:
        canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            products,
        )
        if canonical_subject:
            canonical_selection = _choose_effective_entity_contract(
                question,
                products,
                resolver_candidates=_products_named_in_question(db, question),
                override_subject=canonical_subject,
            )
            canonical_resolution = customer_entity_resolution_contract.can_resolve_single_product(
                canonical_selection.contract,
                products,
            )
            if canonical_resolution.allowed:
                entity_contract = canonical_selection.contract
                resolution = canonical_resolution
    if not resolution.allowed:
        return None
    resolved_sku = str(resolution.resolved_sku or "").strip().upper()
    if not resolved_sku:
        return None
    product = next((item for item in products if str(item.sku or "").strip().upper() == resolved_sku), None)
    qa_matches = _exact_same_sku_product_qa_matches(db, product, question) if product is not None else []
    if qa_matches:
        qa_evidence_types = [
            customer_field_contract.classify_product_qa_evidence_type(
                str(qa.question or ""),
                str(getattr(qa, "tags", "") or ""),
            )
            for qa in qa_matches
        ]
        usage_care_only = bool(qa_evidence_types) and all(kind == "usage_care" for kind in qa_evidence_types)
        answer_type = "product_usage_care" if usage_care_only else "product_detail"
        evidence = [
            {
                "field": "product_qa",
                "sku": resolved_sku,
                "source": f"product_qa:{qa.id}",
                "value": str(qa.answer or "").strip(),
                "status": "structured",
                "missing": False,
            }
            for qa in qa_matches
        ]
        sources = [
            {
                "type": "product_qa",
                "sku": resolved_sku,
                "label": "同 SKU 商品问答",
                "question": str(qa.question or "").strip(),
            }
            for qa in qa_matches
        ]
        answer_lines = [f"{str(product.product_name_cn or product.product_name_en or resolved_sku).strip()}（{resolved_sku}）"]
        answer_lines.extend(
            f"{str(qa.question or '').strip().rstrip('？?')}：{str(qa.answer or '').strip()}"
            for qa in qa_matches
        )
        return {
            "intent": answer_type,
            "answer_type": answer_type,
            "answer": "\n".join(answer_lines),
            "results": [{"sku": resolved_sku, "product_name_cn": product.product_name_cn or product.product_name_en or resolved_sku}],
            "sku": resolved_sku,
            "result_skus": [resolved_sku],
            "candidate_skus": [resolved_sku],
            "sources": sources,
            "evidence": evidence,
            "answer_metadata": {
                "source": "semantic_outage_same_sku_exact_qa_evidence",
                "evidence_status": "structured",
                "evidence_sku": resolved_sku,
                "contract_field_type": None,
            },
            "debug": {
                "agent_mode": "semantic_outage_same_sku_exact_qa_usage_care_evidence" if usage_care_only else "semantic_outage_same_sku_exact_qa_evidence",
                "entity_resolution_contract": entity_contract.to_dict(),
                "field_contract": field_request,
            },
            "skip_polish": True,
        }
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "我已经定位到这款商品，但当前无法稳定识别你要查询的具体字段。请说明想了解系列、分类、材质、规格或其他商品信息。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [resolved_sku],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_outage_named_product_field_clarification",
            "evidence_status": "field_semantic_unavailable",
        },
        "debug": {
            "agent_mode": "semantic_outage_named_product_field_clarification",
            "entity_resolution_contract": entity_contract.to_dict(),
            "field_contract": field_request,
        },
        "skip_polish": True,
    }


def _exact_same_sku_product_qa_matches(db: Session, product: Product | None, question: str) -> list[ProductQa]:
    """Return exact QA evidence only after a unique entity contract is sealed."""
    if product is None or not str(question or "").strip():
        return []
    normalized_question = _normalize_qa_question_text(question)
    matches: list[tuple[int, ProductQa]] = []
    for qa in product_service.customer_visible_product_qas(db, product.id)[:20]:
        qa_question = _normalize_qa_question_text(str(qa.question or ""))
        answer = str(qa.answer or "").strip()
        if qa_question and answer and qa_question in normalized_question:
            matches.append((normalized_question.index(qa_question), qa))
    return [qa for _position, qa in sorted(matches, key=lambda item: item[0])]


def _unknown_product_fact_result(question: str, *, semantic_authorized: bool = False) -> dict | None:
    # This legacy guard predates FieldContract/EntityResolutionContract.  It
    # may provide a safe generic answer only when the question has no formal
    # customer field signal.  Otherwise it would consume a token such as
    # ``价格`` inside the distinct canonical field ``价格定位`` before the
    # conversation anchor can bind the product and before same-SKU evidence is
    # considered.
    if _looks_like_ordinal_product_field_followup(question):
        return None
    formal_contract = customer_field_contract.detect_field_contract(question)
    if not semantic_authorized and formal_contract is not None and formal_contract.field_type != "price":
        return None
    label = _detect_unknown_product_fact_label(question)
    if not label:
        return None
    text = str(question or "").strip()
    scope = _semantic_catalog_product_ref(text)
    if label == "库存":
        answer = "当前资料未标注库存，也不能仅凭现有数据库确认实时库存；如需确认现货情况，建议联系人工客服或后台查询。"
    elif label == "销量":
        answer = "当前资料未标注销量，不能仅凭现有资料判断哪款销量最高。"
    elif label == "评价":
        answer = "当前资料未标注客户评价或好评率，不能仅凭现有资料判断评价高低。"
    elif label == "价格":
        answer = "当前资料未标注实时价格，不能仅凭现有资料确认当前售价；如需价格请联系人工客服或后台查询。"
    elif label == "保修":
        answer = "当前资料未标注保修信息，不能仅凭现有资料确认质保范围；建议联系人工客服确认。"
    elif label == "认证":
        answer = "当前资料未标注对应认证或检测信息，不能仅凭现有资料确认。"
    elif label == "官方说明书":
        answer = "当前资料未维护官方说明书信息，如需确认建议联系人工客服。"
    elif label == "售后电话":
        answer = "当前资料未维护正式售后电话号码，无法提供可核验的联系电话；请通过购买平台的官方客服入口确认。"
    elif label == "安装视频":
        answer = "当前资料未维护安装视频信息，如需确认建议联系人工客服。"
    else:
        return None
    if scope != "产品" and scope not in {"烤盘", "锅具", "炉具", "水具", "水壶", "咖啡器具", "茶具", "桌椅", "餐具", "配件", "天幕/地垫/帐篷"}:
        scope = "产品"
    if scope != "产品" and not SKU_RE.search(text):
        answer = f"关于【{scope}】类产品，{answer}"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {"source": "structured_unknown_field_guard", "requested_field": label},
        "debug": {
            "agent_mode": "structured_unknown_field_guard",
            "plan": {"primary_intent": "product_field", "requested_field": label, "product_ref": ""},
            "raw_results": [],
        },
        "skip_polish": True,
    }


def _structured_filter_field_and_value(question: str) -> tuple[str, str] | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_aliases = {
        "材质": ("材质", "材料"),
        "热源": ("热源", "燃气炉", "卡式炉", "明火", "酒精炉"),
    }
    value_aliases = {
        "不锈钢": ("不锈钢", "304", "316"),
        "铝合金": ("铝合金", "铝"),
        "燃气炉": ("燃气炉", "卡式炉", "明火"),
    }
    matched_field = None
    for field_name, aliases in field_aliases.items():
        if any(alias in text for alias in aliases):
            matched_field = field_name
            break
    matched_value = None
    for value_name, aliases in value_aliases.items():
        if any(alias in text for alias in aliases):
            matched_value = value_name
            break
    if matched_field is None and matched_value in {"不锈钢", "铝合金"}:
        material_shortcuts = (
            f"是{matched_value}的",
            f"要{matched_value}的",
            f"选{matched_value}的",
        )
        if any(pattern in text for pattern in material_shortcuts):
            matched_field = "材质"
    if matched_field == "热源" and matched_value == "燃气炉":
        return matched_field, matched_value
    if matched_field == "材质" and matched_value in {"不锈钢", "铝合金"}:
        return matched_field, matched_value
    return None


def _phase1_structured_field_filter_intent(question: str):
    text = str(question or "").strip()
    if _looks_like_semantic_waterware_capability_query(text):
        return None
    if "咖啡器具" in text and "手冲" in text and "配件" not in text:
        return None
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return None
    if _looks_like_multi_condition_cookware_recommendation(text):
        return None
    if not any(term in text for term in ("哪些", "有哪些", "哪一些", "列出")):
        return None
    intent = customer_agent_intent_service.parse_intent(text, previous_result_skus=[])
    if not intent or intent.intent != "query_products":
        return None
    filters = intent.filters or {}
    if not str(filters.get("product.category") or "").strip():
        return None
    if str(filters.get("specs.body_material") or "").strip():
        return intent
    if str(filters.get("specs.heat_source") or "").strip():
        return intent
    if str(filters.get("business.usage_scenarios") or "").strip():
        return intent
    if str(filters.get("specs.capacity") or "").strip():
        return intent
    if str(filters.get("specs.gross_weight_g") or "").strip():
        return intent
    if str(filters.get("business.target_audience") or "").strip():
        return intent
    if str(filters.get("business.price_positioning") or "").strip():
        return intent
    if intent.negative_filters:
        return intent
    return None


def _structured_hard_filter_contract(question: str) -> dict[str, Any]:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return {}
    target_category = _structured_target_category_from_question(text)
    if not target_category:
        semantic_category = _semantic_catalog_product_ref(text)
        if semantic_category != "产品":
            target_category = semantic_category
    # This is deliberately a narrow execution adapter, rather than an
    # alternate intent router.  A customer can ask to select a generic
    # catalogue category by one formally supported, evidence-backed property.
    # The category plus formal field are the executable contract; no wording
    # list decides whether a customer is "really" selecting products.
    # Named products are excluded above by the entity contract before this
    # function is allowed to execute.
    explicit_dishwasher_catalog_selection = bool(target_category and "洗碗机" in text)
    targeted_heat_recommendation = bool(
        target_category
        and "推荐" in text
        and any(term in text for term in ("燃气炉", "卡式炉", "电磁炉", "电陶炉", "酒精炉", "明火"))
    )
    if (
        not any(term in text for term in ("哪些", "有哪些", "哪一些", "列出"))
        and not targeted_heat_recommendation
        and not explicit_dishwasher_catalog_selection
    ):
        return {}
    if _looks_like_semantic_waterware_capability_query(text):
        return {}
    if "咖啡器具" in text and "手冲" in text and "配件" not in text:
        return {}
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return {}
    if _looks_like_multi_condition_cookware_recommendation(text):
        return {}
    soft_preference_count = sum(
        1
        for matched in (
            any(term in text for term in ("两个人", "两人", "2人", "双人")),
            any(term in text for term in ("轻量", "轻便", "别太重")),
            any(term in text for term in ("预算低", "预算不高", "预算低一点", "便宜点", "性价比")),
            "新手" in text,
        )
        if matched
    )
    if soft_preference_count >= 2 and any(term in text for term in ("锅具", "锅", "炉具", "炉")):
        return {}

    intent = customer_agent_intent_service.parse_intent(text, previous_result_skus=[])
    filters = dict((intent.filters or {}) if intent else {})
    negative_filters = dict((intent.negative_filters or {}) if intent else {})
    requested_fields = list((intent.requested_fields or []) if intent else [])

    lowered = text.lower()
    product_ref = str(filters.get("product.category") or "").strip()
    if target_category:
        product_ref = target_category
        filters["product.category"] = target_category
    elif "水壶" in text or ("哪些壶" in text and "咖啡壶" not in text and "茶壶" not in text):
        product_ref = "水壶"
        filters["product.category"] = "水壶"
    elif any(term in text for term in ("水杯", "杯子", "钛杯", "杯")):
        product_ref = "水具"
        filters["product.category"] = "水杯"
    elif any(term in text for term in ("锅具", "套锅", "单锅")) or ("锅" in text and "火锅" not in text):
        product_ref = "锅具"
        filters["product.category"] = "锅具"
    elif any(term in text for term in ("炉具", "炉子", "卡式炉", "酒精炉")):
        product_ref = "炉具"
        filters["product.category"] = "炉具"
    elif "配件" in text:
        product_ref = "配件"
        filters["product.category"] = "配件"
    elif "咖啡器具" in text:
        product_ref = "咖啡器具"
        filters["product.category"] = "咖啡器具"
    elif "水具" in text:
        product_ref = "水具"
        filters["product.category"] = "水具"

    if not str(filters.get("specs.body_material") or "").strip():
        for raw_value in ("硬质氧化铝合金", "硬质氧化铝", "铝合金", "不锈钢", "钛"):
            if raw_value in text:
                normalized = customer_agent_intent_service._normalize_structured_filter_value("specs.body_material", raw_value)
                if normalized:
                    filters["specs.body_material"] = normalized
                    if "材质" not in requested_fields:
                        requested_fields.append("材质")
                    break

    if not str(filters.get("specs.heat_source") or "").strip():
        if "酒精炉" in text:
            filters["specs.heat_source"] = "酒精炉"
        elif "卡式炉" in text:
            filters["specs.heat_source"] = "卡式炉"
        elif "电磁炉" in text:
            filters["specs.heat_source"] = "电磁炉"
        elif "电陶炉" in text:
            filters["specs.heat_source"] = "电陶炉"
        elif "明火直烧" in text:
            filters["specs.heat_source"] = "明火直烧"
        elif "明火" in text or "直接加热" in text:
            filters["specs.heat_source"] = "明火"
        if str(filters.get("specs.heat_source") or "").strip() and "热源" not in requested_fields:
            requested_fields.append("热源")

    usage_filter = str(filters.get("business.usage_scenarios") or "").strip()
    heat_source_filter = str(filters.get("specs.heat_source") or "").strip()
    if target_category and heat_source_filter and heat_source_filter in usage_filter:
        filters.pop("business.usage_scenarios", None)
        requested_fields = [field for field in requested_fields if field != "适用场景"]

    if not str(filters.get("business.usage_scenarios") or "").strip():
        if "徒步" in text:
            filters["business.usage_scenarios"] = "徒步"
        elif "咖啡相关配件" in text:
            filters["business.usage_scenarios"] = "咖啡"
        if str(filters.get("business.usage_scenarios") or "").strip() and "适用场景" not in requested_fields:
            requested_fields.append("适用场景")

    dishwasher_field_requested = explicit_dishwasher_catalog_selection or _structured_contract_requests_dishwasher_field(
        text=text,
        requested_fields=requested_fields,
        filters=filters,
        negative_filters=negative_filters,
    )
    if dishwasher_field_requested:
        filters["_contract.dishwasher"] = "洗碗机"
    if "不能进洗碗机" in text or "不能放洗碗机" in text or "不可进洗碗机" in text or "不适合洗碗机" in text:
        negative_filters["_contract.dishwasher"] = "洗碗机"
        filters.pop("_contract.dishwasher", None)
    if "轻量" in text or "轻便" in text or "别太重" in text or "比较轻" in text:
        filters["_contract.lightweight"] = "true"
    if "徒步" in text:
        filters["_contract.hiking"] = "true"
    if "两个人" in text or "两人" in text or "2人" in text or "双人" in text:
        filters["_contract.two_person"] = "true"
    if "新手" in text:
        filters["_contract.beginner"] = "true"
    if "预算低" in text or "预算不高" in text or "预算低一点" in text or "便宜点" in text or "性价比" in text:
        filters["_contract.budget"] = "true"
    if "咖啡相关配件" in text:
        filters["_contract.coffee_accessory"] = "true"

    if not product_ref:
        product_ref = _semantic_catalog_product_ref(text)
    if product_ref == "产品":
        product_ref = ""

    hard_filter_keys = {
        key
        for key in filters.keys()
        if key != "product.category"
    }
    hard_filter_keys.update(negative_filters.keys())
    if not product_ref or not hard_filter_keys:
        return {}
    return {
        "intent": intent,
        "product_ref": product_ref,
        "filters": filters,
        "negative_filters": negative_filters,
        "requested_fields": requested_fields,
    }


def _semantic_schema_failed_hard_filter_repair(
    semantic_preplan: dict[str, Any] | None,
    *,
    question: str,
) -> bool:
    """Allow a validated local filter only after a semantic schema failure.

    The semantic preplan remains the intent authority.  This only preserves a
    generic category request when its route was structured_query but the model
    serialized a non-allowlisted predicate, and the central contract can
    independently prove a supported hard filter from the same turn.
    """
    if not isinstance(semantic_preplan, dict) or not semantic_preplan.get("called"):
        return False
    if str(semantic_preplan.get("semantic_route_family_hint") or "").strip() != "structured_query":
        return False
    if str(semantic_preplan.get("fallback_reason") or "").strip() not in {
        "invalid_structured_query_constraints",
        "structured_query_constraints_outside_structured_query",
        "structured_query_constraints_field_mismatch",
        "missing_structured_query_constraints",
    }:
        return False
    contract = _structured_hard_filter_contract(question)
    return bool(contract and contract.get("product_ref") and contract.get("filters"))


def _structured_contract_requests_dishwasher_field(
    *,
    text: str,
    requested_fields: list[str],
    filters: dict[str, Any],
    negative_filters: dict[str, Any],
) -> bool:
    if str(negative_filters.get("_contract.dishwasher") or "").strip():
        return False
    if str(filters.get("_contract.dishwasher") or "").strip():
        return True
    requested_field_paths = {
        str(customer_agent_intent_service._resolve_query_field(field) or "").strip()
        for field in requested_fields
        if field
    }
    if "specs.usage_instruction" not in requested_field_paths:
        return False
    dishwasher_signals = {"洗碗机"}
    if any(signal in str(text or "") for signal in dishwasher_signals):
        return True
    return False


def _structured_row_matches_contract(row: dict[str, Any], contract: dict[str, Any]) -> bool:
    filters = dict(contract.get("filters") or {})
    negative_filters = dict(contract.get("negative_filters") or {})
    row_text = _structured_query_row_text(row)
    row_text_lower = row_text.lower()
    weight_raw = row.get("gross_weight_g")
    try:
        weight_value = float(weight_raw or 0)
    except (TypeError, ValueError):
        weight_value = 0.0
    capacity_text = str(row.get("capacity") or "")
    price_positioning = str(row.get("price_positioning") or "")

    dishwasher_required = bool(filters.pop("_contract.dishwasher", ""))
    dishwasher_required_negative = bool(negative_filters.pop("_contract.dishwasher", ""))
    lightweight_required = bool(filters.pop("_contract.lightweight", ""))
    hiking_required = bool(filters.pop("_contract.hiking", ""))
    two_person_required = bool(filters.pop("_contract.two_person", ""))
    beginner_required = bool(filters.pop("_contract.beginner", ""))
    budget_required = bool(filters.pop("_contract.budget", ""))
    coffee_accessory_required = bool(filters.pop("_contract.coffee_accessory", ""))

    category_value = str(filters.pop("product.category", "") or "").strip()
    body_material_value = str(filters.pop("specs.body_material", "") or "").strip()
    heat_source_value = str(filters.pop("specs.heat_source", "") or "").strip()
    usage_value = str(filters.pop("business.usage_scenarios", "") or "").strip()

    if body_material_value:
        material_contract = customer_structured_query_contract.StructuredQueryContract(
            subject_category=category_value or "all_products",
            field="material",
            operator="contains",
            value=body_material_value,
            status="resolved",
        )
        if not customer_structured_query_contract.match_material_condition(
            contract=material_contract,
            row=row,
        )["matched"]:
            return False
    elif category_value and not _structured_row_matches_category_value(row, category_value):
        return False
    if heat_source_value and not _structured_row_matches_heat_value(row, heat_source_value):
        return False
    if usage_value and not _structured_row_matches_usage_value(row, usage_value):
        return False
    if filters and not customer_agent_intent_service._filter_rows([row], filters=filters, negative_filters={}, term=""):
        return False
    if negative_filters and not customer_agent_intent_service._filter_rows([row], filters={}, negative_filters=negative_filters, term=""):
        return False

    if coffee_accessory_required and not any(term in row_text for term in ("咖啡", "手冲", "滤杯", "细口壶", "分享壶")):
        return False
    if dishwasher_required and not any(
        term in row_text
        for term in ("洗碗机", "可放入洗碗机", "可进洗碗机", "适合洗碗机", "可洗碗机清洗")
    ):
        return False
    if dishwasher_required_negative and not any(
        term in row_text
        for term in ("不适合洗碗机", "不可放入洗碗机", "不能放进洗碗机", "不能进洗碗机", "勿入洗碗机")
    ):
        return False
    if lightweight_required and not (
        any(term in row_text for term in ("轻量", "轻便", "便携"))
        or (0 < weight_value <= 350)
    ):
        return False
    if hiking_required and not any(term in row_text for term in ("徒步", "轻量", "便携")):
        return False
    if two_person_required and not (
        any(term in row_text for term in ("两人", "两个人", "2人", "双人", "1-2人"))
        or any(term in capacity_text for term in ("1-2人", "2人"))
    ):
        return False
    if beginner_required and not any(term in row_text for term in ("新手", "入门", "基础", "性价比")):
        return False
    if budget_required and not any(term in f"{row_text_lower} {price_positioning.lower()}" for term in ("基础", "性价比")):
        return False
    return True


def _looks_like_structured_field_filter_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return False
    if _looks_like_multi_condition_cookware_recommendation(text):
        return False
    if _structured_hard_filter_contract(text):
        return True
    if _phase1_structured_field_filter_intent(text):
        return True
    if not any(term in text for term in ("有哪些", "哪些", "哪一些", "推荐", "找")):
        return False
    if _semantic_catalog_product_ref(text) == "产品":
        return False
    return _structured_filter_field_and_value(text) is not None


def _looks_like_semantic_waterware_capability_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if any(term in text for term in ("怎么选", "推荐", "想买", "买个", "买一", "选哪", "哪款", "哪种")):
        return False
    if not any(term in text for term in ("有哪些", "哪一些", "找", "列出")):
        return False
    if not any(term in text for term in ("水具", "水壶", "水杯")):
        return False
    return any(term in text for term in ("冷水", "补水", "饮水", "热水", "装热水", "喝热水"))


def _structured_field_filter_result(db: Session, question: str) -> dict | None:
    text = str(question or "").strip()
    if not _looks_like_structured_field_filter_query(text):
        return None
    contract = _structured_hard_filter_contract(text)
    intent = contract.get("intent") if contract else _phase1_structured_field_filter_intent(text)
    filters = dict((contract.get("filters") or {}) if contract else dict((intent.filters or {}) if intent else {}))
    negative_filters = dict((contract.get("negative_filters") or {}) if contract else {})
    product_ref = str((contract.get("product_ref") if contract else filters.get("product.category")) or "").strip() or _semantic_catalog_product_ref(text)
    if not product_ref or product_ref == "产品":
        return None
    if product_ref == "水壶":
        source_rows = [
            row for row in _phase1_catalog_rows(db, "产品")
            if _phase1_is_strict_water_kettle_candidate(row)
            and str(row.get("category") or "").strip() == "水壶"
        ]
    else:
        source_rows = _phase1_catalog_rows(db, product_ref)
    if product_ref == "锅具" and str(filters.get("specs.heat_source") or "").strip() == "酒精炉":
        source_rows = [
            row for row in source_rows
            if _is_service_pot_or_cookware_set_candidate(row)
            and _phase1_row_has_explicit_alcohol_stove_support(db, row)
        ]
    rows = [row for row in source_rows if _structured_row_matches_contract(row, {"filters": filters, "negative_filters": negative_filters})]
    if not rows:
        answer = "当前结构化商品库未找到符合条件的商品，可以尝试放宽筛选条件。"
        return {
            "intent": "query_products",
            "answer_type": "product_query",
            "answer": answer,
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "answer_metadata": {"source": "structured_category_field_filter_query", "product_ref": product_ref, "matched_count": 0},
            "debug": {"agent_mode": "structured_category_field_filter_query", "raw_results": [], "candidate_skus": []},
            "skip_polish": True,
        }
    return _structured_product_query_result(
        question=text,
        product_ref=product_ref,
        rows=rows,
        source="structured_category_field_filter_query",
        reason_label=f"{product_ref} / 结构化硬筛选条件",
    )


def _candidate_context_formal_field_filter_result(
    db: Session,
    *,
    question: str,
    field_request: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Filter a sealed candidate set from one formal field contract.

    This is deliberately field-policy driven: it does not resolve a new
    product, infer a value from a name, or run a catalogue-wide search.  It is
    only available when the current question explicitly refers to the prior
    candidate set and contains an actual value from the contracted column.
    """
    if not isinstance(field_request, dict) or not isinstance(candidate_context, dict):
        return None
    field_type = str(field_request.get("field_type") or "").strip()
    if (
        not field_type
        or len(field_request.get("supported_fields") or []) != 1
        or not customer_agent_intent_service._has_context_reference(question)
    ):
        return None
    if not _candidate_context_formal_field_filter_eligible(
        question,
        field_request=field_request,
        candidate_context=candidate_context,
    ):
        return None
    policy = customer_field_contract.field_evidence_policy(field_type)
    if not policy or not policy.structured_fields:
        return None
    domain_skus = [
        str(sku or "").strip().upper()
        for sku in (
            candidate_context.get("ordered_result_skus")
            or candidate_context.get("candidate_skus")
            or []
        )
        if str(sku or "").strip()
    ]
    if len(domain_skus) < 2:
        return None
    # The formal FieldContract decides *which* field the user is asking
    # about.  The existing structured-query contract is then used only to
    # validate an explicit filter value against that field's same-SKU column.
    # This avoids treating a shorter cell value as a match merely because it
    # is a substring of a more specific phrase in the question.
    scoped_intent = customer_agent_intent_service.parse_intent(
        question,
        previous_result_skus=domain_skus,
    )
    predicate_filters = {
        source: value
        for source, value in dict(getattr(scoped_intent, "filters", {}) or {}).items()
        if source in policy.structured_fields and str(value or "").strip()
    }
    if not predicate_filters:
        return None
    predicate_contract = {"filters": predicate_filters, "negative_filters": {}}
    rows_by_sku = {
        str(row.get("sku") or "").strip().upper(): row
        for row in _phase1_catalog_rows(db, "产品")
        if isinstance(row, dict) and str(row.get("sku") or "").strip().upper() in set(domain_skus)
    }
    matched_rows: list[dict[str, Any]] = []
    evidence: list[dict[str, Any]] = []
    for sku in domain_skus:
        row = rows_by_sku.get(sku)
        if not row:
            continue
        values: list[tuple[str, str]] = []
        for source in policy.structured_fields:
            column = str(source or "").rsplit(".", 1)[-1]
            raw_value = row.get(column)
            if not _is_valid_structured_field_value(field_type, raw_value):
                continue
            display_value = _display_value(raw_value).strip()
            if display_value:
                values.append((str(source), display_value))
        if not values:
            continue
        # Match with the shared structured contract rather than raw substring
        # containment.  The latter would incorrectly make "铝合金" satisfy
        # a request for the narrower "硬质氧化铝合金".
        if not _structured_row_matches_contract(row, predicate_contract):
            continue
        # The selected proof must itself contain the normalized filter value.
        # This preserves the concrete same-SKU column that justified the
        # subset, instead of reprinting an unrelated value from the field.
        matching_values = [
            (source, value)
            for source, value in values
            if any(str(target).strip().lower() in value.lower() for target in predicate_filters.values())
        ]
        if not matching_values:
            continue
        matched_rows.append(row)
        for source, value in matching_values:
            evidence.append({"type": "product_field", "sku": sku, "field": field_type, "source": source, "value": value})
    # A candidate follow-up is a sealed prior result set.  For an alcohol-stove
    # cookware query, remove explicit pans/griddles but do not require every
    # remaining candidate title to repeat a cookware keyword: a valid prior
    # cookware set may be named only as a scenario-oriented “自驾套装”.  This
    # remains a same-SKU heat-source filter, not a new entity resolution or
    # SKU rule.
    if (
        field_type == "heat_source"
        and any("酒精" in str(value or "") for value in predicate_filters.values())
        and _is_service_pot_cookware_scope(
            str(candidate_context.get("product_scope") or ""),
            " ".join((question, str(candidate_context.get("user_question") or ""))),
        )
    ):
        def is_explicit_non_pot_identity(row: dict[str, Any]) -> bool:
            identity_text = " ".join(
                str(row.get(key) or "")
                for key in ("product_name_cn", "product_name_en", "name", "title", "sub_category")
            ).lower()
            return (
                _is_service_pan_or_griddle_candidate_text(identity_text)
                or any(term in identity_text for term in ("水壶", "茶壶", "烧水壶", "kettle", "bottle", "flask", "cup", "杯"))
            )

        matched_rows = [row for row in matched_rows if not is_explicit_non_pot_identity(row)]
        matched_skus = {str(row.get("sku") or "").strip().upper() for row in matched_rows}
        evidence = [item for item in evidence if str(item.get("sku") or "").strip().upper() in matched_skus]
    if not matched_rows:
        # A formal, value-bearing field filter has consumed the sealed
        # candidate domain.  An empty match is therefore an empty subset, not
        # permission for an older context shortcut to reopen the catalogue.
        empty_context = dict(candidate_context)
        empty_context.update({
            "candidate_skus": [],
            "ordered_result_skus": [],
            "original_candidate_skus": domain_skus,
            "parent_candidate_skus": domain_skus,
            "applied_filter": {"field": field_type, "filters": predicate_filters},
            "empty_subset": True,
        })
        result = _empty_candidate_subset_followup_result(question, empty_context)
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["agent_mode"] = "candidate_context_formal_field_filter"
        debug["field_contract"] = dict(field_request)
        debug["candidate_skus"] = []
        debug["intent"] = {"intent": "query_products", "source_context": "previous_results", "target_skus": domain_skus}
        result["debug"] = debug
        return result
    result_skus = [str(row.get("sku") or "").strip().upper() for row in matched_rows]
    label = customer_field_contract.product_detail_field_label(field_type) or field_type
    detail_lines = []
    for row in matched_rows:
        sku = str(row.get("sku") or "").strip().upper()
        name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
        row_values = [item["value"] for item in evidence if item["sku"] == sku]
        detail_lines.append(f"- {name}（{sku}）：{'；'.join(dict.fromkeys(row_values))}")
    answer = f"已在上一轮候选范围内按{label}筛到 {len(matched_rows)} 款：\n" + "\n".join(detail_lines)
    scoped_context = {
        "candidate_skus": result_skus,
        "ordered_result_skus": result_skus,
        "filtered_skus": result_skus,
        "original_candidate_skus": domain_skus,
        "parent_candidate_skus": domain_skus,
        "recommended_skus": [],
        "user_question": question,
        "product_scope": str(candidate_context.get("product_scope") or "").strip(),
        "empty_subset": False,
        "applied_filter": {"field": field_type},
    }
    return {
        "intent": "query_products",
        "answer_type": "product_query",
        "answer": answer,
        "results": matched_rows,
        "result_skus": result_skus,
        "candidate_skus": result_skus,
        "evidence": evidence,
        "sources": [{"type": "agent_meta", "candidate_context": scoped_context}],
        "debug": {
            "agent_mode": "candidate_context_formal_field_filter",
            "field_contract": dict(field_request),
            "candidate_skus": result_skus,
            "raw_results": matched_rows,
            "intent": {"intent": "query_products", "source_context": "previous_results", "target_skus": domain_skus},
        },
        "skip_polish": True,
    }


def _candidate_context_formal_field_filter_eligible(
    question: str,
    *,
    field_request: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None,
) -> bool:
    if not isinstance(field_request, dict) or not isinstance(candidate_context, dict):
        return False
    # An ordinal selects one identity from the sealed candidate order.  It is
    # therefore a single-product field follow-up, not a request to filter the
    # whole prior set by a field value.
    if _looks_like_ordinal_product_field_followup(question):
        return False
    # A grammatical singular reference is a product-bound follow-up.  The
    # candidate set may provide the anchor, but it must not turn "it" into a
    # plural filter over every prior candidate; that path would bypass the
    # EntityResolutionContract required for a product fact.
    if re.match(r"^\s*(?:那|这)?(?:它|这个|这款|该商品|该产品|这个商品|这件商品|本产品)", str(question or "")):
        return False
    domain_skus = candidate_context.get("ordered_result_skus") or candidate_context.get("candidate_skus") or []
    return bool(
        len([sku for sku in domain_skus if str(sku or "").strip()]) >= 2
        and len(field_request.get("supported_fields") or []) == 1
        and customer_agent_intent_service._has_context_reference(question)
        and not customer_agent_service._extract_skus(question)
    )


def _looks_like_multi_condition_cookware_recommendation(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if not any(term in text for term in ("锅具", "锅", "套锅", "炊具")):
        return False
    if any(term in text for term in ("水壶", "水具", "水杯", "壶")):
        return False
    has_group_or_scene = any(term in text for term in ("4人以上", "4人", "四口", "多人", "家庭", "露营", "户外", "新手"))
    has_constraints = any(term in text for term in ("容量大", "容量要大", "大容量", "燃气炉", "卡式炉", "明火", "别太重", "轻", "轻量", "轻便"))
    has_budget_preference = any(term in text for term in ("价格别太高", "别太贵", "不要太贵", "预算不高", "预算有限", "便宜点", "性价比"))
    has_selection = any(term in text for term in ("推荐", "怎么选", "买什么", "买锅具", "有哪些", "用什么"))
    return has_group_or_scene and (has_constraints or has_budget_preference) and (has_selection or "。" in text)


def _structured_cookware_multi_condition_recommendation_result(db: Session, question: str) -> dict | None:
    text = str(question or "").strip()
    if not _looks_like_multi_condition_cookware_recommendation(text):
        return None
    rows = [row for row in _phase1_catalog_rows(db, "产品") if _is_service_pot_or_cookware_set_candidate(row)]
    if not rows:
        return None
    verification_contract = customer_recommendation_verification_contract.build_recommendation_request_contract(text)
    verifications = customer_recommendation_verification_contract.verify_recommendation_candidates(
        verification_contract,
        rows,
    )
    verified_rows = customer_recommendation_verification_contract.select_recommendation_candidates(
        rows,
        verifications,
    )
    rejected_candidates = [item.to_dict() for item in verifications if item.verification_level == "rejected"]
    wants_group_capacity = any(term in text for term in ("4人以上", "4人", "多人", "家庭", "大容量", "容量大"))
    wants_gas = any(term in text for term in ("燃气炉", "卡式炉", "明火"))
    wants_light = any(term in text for term in ("别太重", "轻", "轻量", "轻便"))
    wants_beginner = "新手" in text
    wants_budget = any(term in text for term in ("价格别太高", "别太贵", "不要太贵", "预算不高", "预算有限", "便宜点", "性价比"))

    def _rank(row: dict[str, Any]) -> tuple[int, str]:
        row_text = " ".join(
            str(row.get(key) or "")
            for key in (
                "product_name_cn",
                "category",
                "capacity",
                "features",
                "usage_scenarios",
                "positioning",
                "price_positioning",
                "long_description_cn",
            )
        )
        score = 0
        if wants_group_capacity and any(term in row_text for term in ("4人", "2-4人", "多人", "家庭", "3L", "3700ML", "大容量")):
            score += 10
        if wants_gas and any(term in row_text for term in ("燃气炉", "卡式炉", "明火")):
            score += 8
        if wants_light and any(term in row_text for term in ("轻量", "轻便", "便携", "套娃", "收纳")):
            score += 6
        if wants_beginner and any(term in row_text for term in ("入门", "基础", "性价比", "周末野餐")):
            score += 5
        if wants_budget and any(term in row_text for term in ("入门", "性价比", "基础", "中端")):
            score += 4
        if any(term in row_text for term in ("套锅", "套装", "锅具套装", "炊具套装")):
            score += 3
        weight = row.get("gross_weight_g")
        try:
            weight_value = float(weight or 0)
        except (TypeError, ValueError):
            weight_value = 0
        if wants_light:
            if 0 < weight_value <= 800:
                score += 4
            elif 800 < weight_value <= 1200:
                score += 2
            elif weight_value >= 1800:
                score -= 3
        return (-score, str(row.get("sku") or ""))

    selected = sorted(verified_rows, key=_rank)[:5]
    if not selected:
        answer = customer_recommendation_verification_contract.build_verified_recommendation_answer(
            verification_contract,
            [],
            verifications,
        )
    else:
        answer = customer_recommendation_verification_contract.build_verified_recommendation_answer(
            verification_contract,
            selected,
            verifications,
        )
    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {
            "agent_mode": "planner_recommendation_guard_rebuild",
            "initial_candidate_skus": [
                str(row.get("sku") or "").strip().upper()
                for row in rows
                if str(row.get("sku") or "").strip()
            ],
            "verified_candidate_skus": skus,
            "candidate_verifications": [
                item.to_dict()
                for item in verifications
                if item.sku in skus
            ],
            "fully_verified_candidates": [item.to_dict() for item in verifications if item.verification_level == "fully_verified"],
            "partially_verified_candidates": [item.to_dict() for item in verifications if item.verification_level == "partially_verified"],
            "rejected_candidates": rejected_candidates,
        },
        "answer_metadata": {
            "source": "product_catalog_structured_recommendation",
            "preserved_scope_statement": "本次优先从锅具/套锅里选，不先把水壶当主推。",
            "recommendation_contract": verification_contract.to_dict(),
            "verification_level": (
                "fully_verified"
                if any(item.verification_level == "fully_verified" and item.sku in skus for item in verifications)
                else "partially_verified" if skus else "rejected"
            ),
            "fully_verified_count": sum(item.verification_level == "fully_verified" for item in verifications),
            "partially_verified_count": sum(item.verification_level == "partially_verified" for item in verifications),
            "rejected_count": sum(item.verification_level == "rejected" for item in verifications),
        },
        "skip_polish": True,
    }


def _semantic_structured_query_result(
    db: Session,
    question: str,
    *,
    candidate_context: dict[str, Any] | None = None,
    semantic_preplan: dict[str, Any] | None = None,
) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    # A high-confidence semantic product-QA decision owns the whole-turn
    # meaning.  This catalogue executor is only a fallback for genuine
    # category/filter/recommendation requests, so it must yield before any
    # deterministic cookware or category heuristic can reinterpret the
    # named product as a set of alternatives. Entity and same-SKU evidence
    # validation continue in the later sealed product-QA path.
    if _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan):
        return None
    if _should_keep_preruntime_for_scoped_heat_source_followup(
        text,
        candidate_context=candidate_context,
    ):
        return None
    if _has_resolved_entity_contents_accessories_question(db, text):
        return None
    # A catalogue route must not consume a question for which the current
    # utterance already has an exact, sealable same-SKU QA fact.  The QA
    # helper performs entity arbitration itself; returning here only lets the
    # later canonical QA contract own the response instead of converting the
    # product name into a category filter.
    exact_qa_result = _try_product_qa_shortcut(db, text)
    if exact_qa_result is not None:
        return exact_qa_result
    # A generic catalogue recommendation cannot consume a product-like
    # subject that EntityResolutionContract cannot bind.  Otherwise an
    # unrecognised name followed by “推荐” silently becomes a recommendation
    # for a different catalogue product.
    if _has_unresolved_product_like_scope(db, text):
        return None
    cookware_multi_condition = _structured_cookware_multi_condition_recommendation_result(db, text)
    if cookware_multi_condition:
        return cookware_multi_condition
    # A structured catalogue query never owns the field meaning of an already
    # resolved product. A loose name recall is not enough here: a generic
    # attribute phrase such as "轻量锅具" may overlap an unrelated product name
    # (for example "轻量保温杯"). Only a sealed EntityResolutionContract may
    # defer this catalogue query to product detail.
    if _has_resolved_named_product_contract(db, text):
        return None
    # For a high-confidence catalogue request, semantic planning has already
    # interpreted the whole utterance and supplied only a generic catalogue
    # scope.  Resolve that scope through the database search provider instead
    # of requiring a second lexical recognizer to rediscover the same term.
    # The plan cannot supply products, SKUs, or facts: all candidates remain
    # bounded by the actual database result set.
    semantic_subject = str((semantic_preplan or {}).get("subject_text") or "").strip()
    semantic_fields = list((semantic_preplan or {}).get("canonical_fields") or [])
    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) == "structured_query"
        and semantic_fields == ["category"]
        and semantic_subject
    ):
        # Semantic planning owns the meaning "this is a catalogue category
        # request"; this adapter only resolves that abstract subject against
        # the categories actually present in the database.  A lexical product
        # search is deliberately not an acceptable substitute: "锅" may
        # occur in a kettle or stove name while the customer asks for the
        # database's cookware category.
        category_rows = _phase1_catalog_rows(db, "产品")
        category_ref = _database_category_scope_ref(category_rows, semantic_subject)
        if category_ref:
            if any(token in text for token in ("多少", "几款", "几种", "几个")):
                return _phase1_catalog_count_result(
                    db,
                    {"product_ref": category_ref, "raw_question": text},
                )
            rows = _phase1_catalog_rows(db, category_ref)
            return _structured_product_query_result(
                question=text,
                product_ref=category_ref,
                rows=rows,
                source="structured_catalog_semantic_category_scope",
                reason_label="语义目录范围",
                answer_type="query_products",
                metadata_source="product_catalog_structured_query",
            )
        rows = customer_agent_service.search_products(db, semantic_subject, limit=50)
        return _structured_product_query_result(
            question=text,
            product_ref=semantic_subject,
            rows=rows,
            source="structured_catalog_count",
            reason_label="语义目录范围",
            answer_type="query_products",
            metadata_source="product_catalog_structured_query",
        )
    structured_field_filter = _structured_field_filter_result(db, text)
    if structured_field_filter:
        return structured_field_filter
    if any(term in text for term in ("咖啡器具", "咖啡")) and "手冲" in text:
        rows = [row for row in _phase1_catalog_rows(db, "咖啡器具") if any(term in _structured_query_row_text(row) for term in ("手冲", "细口壶", "咖啡", "滤杯"))]
        return _structured_product_query_result(
            question=text,
            product_ref="咖啡器具",
            rows=rows,
            source="structured_coffee_handpour_query",
            reason_label="手冲 / 咖啡器具语义",
        )
    is_waterware_selection_request = any(term in text for term in ("怎么选", "推荐", "想买", "买个", "买一", "选哪", "哪款", "哪种"))
    if (
        not is_waterware_selection_request
        and any(term in text for term in ("水具", "水壶", "水杯"))
        and any(term in text for term in ("冷水", "补水", "饮水", "热水"))
    ):
        product_ref = "水壶" if "水壶" in text else "水具"
        candidate_predicate = _phase1_is_strict_water_kettle_candidate
        rows = [row for row in _phase1_catalog_rows(db, "产品") if candidate_predicate(row)]
        filtered: list[dict[str, Any]] = []
        for row in rows:
            row_text = _structured_query_row_text(row)
            score = 0
            if any(term in row_text for term in ("补水", "饮水", "冷水", "水杯", "随行杯", "保温杯", "便携")):
                score += 6
            if any(term in row_text for term in ("热水", "保温")):
                score += 3
            if any(term in row_text for term in ("烧水", "煮水", "泡茶")):
                score -= 4
            if score > 0:
                new_row = dict(row)
                new_row["_score"] = score
                filtered.append(new_row)
        filtered.sort(key=lambda item: (-int(item.get("_score") or 0), str(item.get("sku") or "")))
        return _structured_product_query_result(
            question=text,
            product_ref=product_ref,
            rows=filtered,
            source="structured_waterware_capability_query",
            reason_label=f"{product_ref} / 冷水 / 热水 / 补水语义",
        )
    is_griddle_selection_request = any(term in text for term in ("怎么搭", "怎么配", "先买", "哪个", "推荐", "更合适", "更值得"))
    if (
        not is_griddle_selection_request
        and any(term in text for term in ("烤盘", "煎盘"))
        and any(term in text for term in ("炉具", "炉子", "卡式炉", "分体炉", "露营炉", "烧烤"))
    ):
        rows = []
        for row in _phase1_catalog_rows(db, "产品"):
            row_text = _structured_query_row_text(row)
            if not any(term in row_text for term in ("烤盘", "煎盘")):
                continue
            score = 0
            if any(term in row_text for term in ("炉具", "卡式炉", "分体炉", "一体炉", "烧烤", "明火")):
                score += 8
            if any(term in row_text for term in ("早餐", "煎烤", "烤盘")):
                score += 3
            if score <= 0:
                continue
            new_row = dict(row)
            new_row["_score"] = score
            rows.append(new_row)
        rows.sort(key=lambda item: (-int(item.get("_score") or 0), str(item.get("sku") or "")))
        return _structured_product_query_result(
            question=text,
            product_ref="烤盘",
            rows=rows,
            source="structured_griddle_stove_query",
            reason_label="烤盘 + 炉具搭配语义",
        )
    if (
        any(term in text for term in ("配件", "附件"))
        and any(term in text for term in ("收纳", "整理", "归纳"))
        and any(term in text for term in ("有哪些", "推荐", "适合", "更偏"))
    ):
        rows = []
        for row in _phase1_catalog_rows(db, "配件"):
            row_text = _structured_query_row_text(row)
            score = 0
            if any(term in row_text for term in ("收纳", "整理", "归纳", "好收纳", "收纳包", "收纳方便", "集中收纳")):
                score += 8
            if any(term in row_text for term in ("配件", "附件", "餐厨配件", "露营收纳")):
                score += 4
            if any(term in row_text for term in ("调料瓶", "喷枪", "水壶", "水具")):
                score -= 5
            if score <= 0:
                continue
            new_row = dict(row)
            new_row["_score"] = score
            rows.append(new_row)
        rows.sort(key=lambda item: (-int(item.get("_score") or 0), str(item.get("sku") or "")))
        return _structured_product_query_result(
            question=text,
            product_ref="配件",
            rows=rows,
            source="structured_accessory_storage_query",
            reason_label="配件 / 收纳语义",
        )
    if (
        not _has_resolved_entity_contents_accessories_question(db, text)
        and any(term in text for term in ("配件", "附件"))
        and any(term in text for term in ("有什么", "有啥"))
    ):
        return _phase1_catalog_count_result(db, {"product_ref": "配件", "raw_question": text})
    if _looks_like_semantic_catalog_query(text):
        # Preserve the semantic input for the aggregate contract. Product
        # discovery and a catalogue count have different population rules.
        return _phase1_catalog_count_result(
            db,
            {"product_ref": _semantic_catalog_product_ref(text), "raw_question": text},
        )
    # An unresolved product-like subject must reach central entity arbitration;
    # this legacy fallback has no EntityResolutionContract and therefore cannot
    # safely turn a product-specific unknown field into a generic answer.
    if _has_unresolved_product_like_scope(db, text):
        return None
    return _unknown_product_fact_result(text)


def _semantic_prefers_sealed_product_qa(phase1_plan: dict[str, Any]) -> bool:
    """Reserve generic product facts for the sealed same-SKU QA path.

    The semantic preplan owns the meaning of an utterance.  This guard only
    recognizes its schema-validated decision that a named product asks for a
    product-specific fact outside the formal field taxonomy; it never derives
    a field, product, or answer from wording.  Entity resolution and exact
    same-SKU QA matching remain mandatory in ``_try_product_qa_shortcut``.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    preplan = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    if not _semantic_preplan_confident(preplan, minimum=0.9):
        return False
    if str(preplan.get("route_family") or "").strip() != "product_bound_qa":
        return False
    if str(preplan.get("evidence_kind") or "").strip() != "product_qa":
        return False
    if preplan.get("ambiguity") or (preplan.get("canonical_fields") or []):
        return False
    if str(preplan.get("field_type") or preplan.get("field_hint") or "").strip():
        return False
    # The family itself is schema-validated.  Providers may omit the legacy
    # route_hint compatibility mirror, so it must not reopen an old usage/care
    # shortcut after the model has explicitly selected sealed product QA.
    return str(preplan.get("route_hint") or "").strip() in {"", "product_detail"}


def _semantic_allows_exact_sealed_product_qa(phase1_plan: dict[str, Any]) -> bool:
    """Accept an exact QA only for the semantic product-detail family."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    preplan = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    return bool(
        _semantic_preplan_confident(preplan, minimum=0.9)
        and str(preplan.get("route_family") or "").strip() == "product_bound_qa"
        and str(preplan.get("route_hint") or "").strip() == "product_detail"
        and not preplan.get("ambiguity")
    )


def _semantic_formal_field_preempts_legacy_shortcuts(preplan: dict[str, Any] | None) -> bool:
    """Reserve a validated semantic field for central contract arbitration.

    This is deliberately only a shortcut veto.  It neither supplies an
    entity nor authorizes evidence: FieldContract validation and
    EntityResolutionContract still decide whether the request can be answered
    or must be clarified.  Its purpose is to prevent a legacy usage/care or
    contents heuristic from replacing a high-confidence, allowlisted semantic
    field before those central contracts have run.
    """
    value = preplan if isinstance(preplan, dict) else {}
    if not _semantic_preplan_confident(value, minimum=0.9):
        return False
    if value.get("fallback_reason") or value.get("ambiguity"):
        return False
    fields = {
        customer_field_contract.semantic_preplan_field_type(item)
        for item in [
            value.get("field_type"),
            value.get("field_hint"),
            *(value.get("canonical_fields") or []),
        ]
    }
    fields.discard("")
    return bool(fields) and fields.issubset(customer_field_contract.FORMAL_DETAIL_FIELDS)


def _semantic_product_qa_preempts_legacy_shortcuts(preplan: dict[str, Any] | None) -> bool:
    """Keep an explicit semantic QA decision ahead of legacy shortcut routers.

    This is another veto only. It has no lexical interpretation and does not
    choose a QA record; it preserves the model's schema-validated decision so
    the later same-SKU EntityResolution/QA contract can run or fail closed.
    """
    value = preplan if isinstance(preplan, dict) else {}
    return bool(
        _semantic_preplan_confident(value, minimum=0.9)
        and not value.get("fallback_reason")
        and not value.get("ambiguity")
        and str(value.get("route_family") or "").strip() == "product_bound_qa"
        and str(value.get("evidence_kind") or "").strip() == "product_qa"
        and not (value.get("canonical_fields") or [])
        and not str(value.get("field_type") or value.get("field_hint") or "").strip()
    )


def _formal_field_contract_preempts_product_qa(question: str, phase1_plan: dict[str, Any] | None) -> bool:
    """Keep product QA as evidence, never the route for a formal field.

    The semantic preplan and the FieldContract own the field meaning.  A
    same-SKU QA record can still be consulted by a field-specific evidence
    provider, but it cannot replace the contract with a QA response before
    entity arbitration reaches the structured detail executor.
    """
    semantic_preplan = (
        phase1_plan.get("semantic_preplan")
        if isinstance(phase1_plan, dict) and isinstance(phase1_plan.get("semantic_preplan"), dict)
        else {}
    )
    field_request = customer_field_contract.resolve_requested_field_contract(
        question,
        phase1_plan if isinstance(phase1_plan, dict) else {},
    )
    field_type = str(field_request.get("field_type") or "").strip()
    if field_type in customer_field_contract.FORMAL_DETAIL_FIELDS:
        semantic_subject = str(semantic_preplan.get("subject_text") or "").strip()
        subject_start = str(question or "").find(semantic_subject) if semantic_subject else -1
        subject_end = subject_start + len(semantic_subject) if subject_start >= 0 else -1
        field_spans = [
            item
            for item in (field_request.get("field_spans") or [])
            if isinstance(item, dict)
            and isinstance(item.get("start"), int)
            and isinstance(item.get("end"), int)
        ]
        alias_is_inside_bound_subject = bool(
            subject_start >= 0
            and field_spans
            and all(
                subject_start <= int(item["start"])
                and int(item["end"]) <= subject_end
                for item in field_spans
            )
        )
        if (
            _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan)
            and alias_is_inside_bound_subject
        ):
            # A noun embedded in the already-bound product title is not the
            # requested predicate. Preserve the validated semantic QA route;
            # full-predicate FieldContracts (for example "拿着重不重" or
            # "应该怎么使用") still preempt as formal customer questions.
            return False
        return True
    return False


def _should_prioritize_semantic_structured_route(question: str, phase1_plan: dict[str, Any]) -> bool:
    text = str(question or "").strip()
    semantic_preplan = (
        phase1_plan.get("semantic_preplan")
        if isinstance(phase1_plan, dict) and isinstance(phase1_plan.get("semantic_preplan"), dict)
        else None
    )
    # ``category`` is catalogue scope, not a product-detail FieldContract.
    # A validated semantic catalogue plan must reach the DB-backed structured
    # executor before the generic formal-field shortcut veto is considered.
    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) == "structured_query"
        and list((semantic_preplan or {}).get("canonical_fields") or []) == ["category"]
        and str((semantic_preplan or {}).get("subject_text") or "").strip()
    ):
        return True
    # A legacy catalogue plan can retain a category-shaped reading from the
    # product name. It is a fallback only: a validated formal semantic field
    # must first reach the central FieldContract -> EntityResolutionContract
    # path, which will still distinguish a named product from a true category.
    if _semantic_formal_field_preempts_legacy_shortcuts(semantic_preplan):
        return False
    # This is an explicitly generic catalogue capability request; "水壶" is
    # its category scope, not an unresolved product-like name.  Preserve that
    # structured contract before the fail-closed single-entity guard.
    if _looks_like_semantic_waterware_capability_query(text):
        return True
    db = phase1_plan.get("_db") if isinstance(phase1_plan, dict) else None
    if db is not None and _has_unresolved_product_like_scope(db, text):
        return False
    # Recommendation grammar may occur after a product-like subject.  The
    # entity contract has to reject an unresolved named subject before the
    # generic catalogue recommender is allowed to construct any candidates.
    # This is scope arbitration, not a product or wording exception.
    if _looks_like_multi_condition_cookware_recommendation(text):
        return True
    if _looks_like_recommendation_request(text):
        return False
    if any(term in text for term in ("推荐", "哪款", "选什么", "帮我选", "帮我挑", "推荐一个", "推荐几个")):
        return False
    if _structured_hard_filter_contract(text):
        return True
    primary_intent = str((phase1_plan or {}).get("primary_intent") or "")
    if primary_intent not in {"product_field", "catalog_count"}:
        return False
    return _looks_like_structured_field_filter_query(text) or _looks_like_multi_condition_cookware_recommendation(text)


def _semantic_structured_override_plan(question: str, phase1_plan: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    merged = dict(phase1_plan or {})
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    answer_type = str(result.get("answer_type") or "")
    if answer_type in {"product_query", "query_products"}:
        merged["primary_intent"] = "catalog_count"
        merged["answer_type"] = answer_type
        merged["product_ref"] = str(metadata.get("product_ref") or _semantic_catalog_product_ref(question) or "").strip()
        merged["requested_field"] = ""
    elif answer_type == "recommendation":
        merged["primary_intent"] = "recommendation"
        merged["answer_type"] = "recommendation"
        merged["scenario"] = str(question or "").strip()
        merged["product_ref"] = ""
        merged["requested_field"] = ""
    return merged


def _phase1_explicit_sku_alcohol_people_result(db: Session, question: str) -> dict | None:
    text = str(question or "")
    if "酒精炉" not in text and "酒精" not in text:
        return None
    if not any(term in text for term in ("适合几个人", "适合几人", "几个人", "几人", "多少人", "人数")):
        return None
    sku = _resolve_sku(db, text, None)
    if not sku:
        return None
    product, specs, business, content = _phase1_product_bundle_by_ref(db, sku)
    if not product:
        return None
    row = _product_row_from_model(product, specs, business, content)
    canonical_fields = [
        field
        for field in customer_field_contract.detect_field_types(text)
        if customer_field_contract.is_supported_detail_field(field)
    ]
    canonical_fields = list(dict.fromkeys(canonical_fields))
    if not {"heat_source", "people"}.issubset(set(canonical_fields)):
        return None
    base_field_contract = resolve_requested_field_contract(text, None)
    field_contract = dict(base_field_contract)
    field_contract.update({
        "field_type": "heat_source",
        "requested_field": "heat_source",
        "requested_fields": canonical_fields,
        "canonical_fields": canonical_fields,
        "supported_fields": canonical_fields,
        "compound": True,
    })
    all_products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        text,
        all_products,
        resolver_candidates=[product],
        entity_text_override=str(product.sku or "").strip(),
        field_type_override="heat_source",
    )
    if not customer_entity_resolution_contract.can_resolve_single_product(entity_contract, all_products).allowed:
        return None
    compatibility_answer, evidence_status = _phase1_alcohol_stove_compatibility_answer(db, row)
    people_metadata: dict[str, Any] = {}
    people_answer = _phase1_people_capacity_answer(row, evidence_metadata=people_metadata)
    answer = f"{compatibility_answer} {people_answer}"
    sku_code = str(product.sku or "").strip().upper()
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "sku": sku_code,
        "answer": answer,
        "results": [row],
        "result_skus": [sku_code],
        "candidate_skus": [sku_code],
        "answer_metadata": {
            "answer_policy": "explicit_sku_compatibility_and_people",
            "requested_fields": canonical_fields,
            "evidence_status": evidence_status,
        },
        "evidence": [
            {
                "type": "product_field",
                "sku": sku_code,
                "field": "heat_source",
                "source": "specs.heat_source",
                "value": str(row.get("heat_source") or "").strip(),
            },
            {
                "type": "product_field",
                "sku": sku_code,
                "field": "people",
                "source": people_metadata.get("evidence_source"),
                "value": people_metadata.get("evidence_value"),
            },
        ],
        "debug": {
            "agent_mode": "explicit_sku_compatibility_people",
            "raw_results": [row],
            "candidate_skus": [sku_code],
            "field_contract": field_contract,
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "skip_polish": True,
    }


def _explicit_sku_detail_requested_fields(question: str) -> list[str]:
    text = str(question or "").strip()
    if not text:
        return []
    fields = list(customer_agent_intent_service._requested_fields_for_detail_question(text))
    if any(term in text for term in ("酒精炉", "明火", "明火直烧", "热源", "燃料", "火源", "能用", "能不能用", "可以用", "直接加热", "卡式炉", "燃气炉", "气炉", "分体炉", "一体炉")) and "热源" not in fields:
        fields.append("热源")
    people_terms = ("适合几个人", "适合几人", "几个人", "几人用", "几人使用", "多少人", "人数", "适用人数")
    if any(term in text for term in people_terms) and "适用人数" not in fields:
        fields.append("适用人数")
    if (
        any(term in text for term in ("适合", "场景", "干嘛用", "露营用", "适用人群"))
        and not any(term in text for term in people_terms)
        and "适用场景" not in fields
    ):
        fields.append("适用场景")
    return fields


def _is_explicit_sku_detail_question(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if customer_agent_intent_service._is_compare_question(text):
        return False
    if customer_agent_intent_service._looks_like_multi_product_relation_question(text):
        return False
    if any(term in text for term in ("有哪些", "列出", "推荐哪套", "推荐哪个", "推荐哪款", "怎么选", "先买哪个")):
        return False
    fields = _explicit_sku_detail_requested_fields(text)
    if fields:
        return True
    return any(term in text for term in ("是什么", "是什么产品", "介绍一下", "适合什么场景", "适合露营", "适合几个人", "干嘛用", "能不能用明火", "能不能用酒精炉", "直接加热", "明火直烧", "卡式炉", "燃气炉", "分体炉", "一体炉"))


def _is_explicit_sku_heat_source_question(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    return any(
        term in text
        for term in (
            "酒精炉",
            "酒精",
            "直接加热",
            "明火加热",
            "上火加热",
            "明火直烧",
            "热源",
            "燃料",
            "卡式炉",
            "燃气炉",
            "气炉",
            "分体炉",
            "一体炉",
        )
    )


def _is_explicit_sku_identity_only_question(question: str) -> bool:
    """Recognize an exact-SKU identity request without assigning any field.

    This is deliberately an outage-only availability predicate.  It does not
    resolve a SKU, infer a product, or produce an answer; the downstream
    EntityResolutionContract remains the sole authority for all three.
    """
    text = str(question or "").strip()
    explicit_skus = customer_agent_service._extract_skus(text)
    if not text or not explicit_skus:
        return False
    for reference in sorted({str(value or "") for value in explicit_skus if str(value or "")}, key=len, reverse=True):
        remainder = re.sub(
            rf"^\s*{re.escape(reference)}",
            "",
            text,
            count=1,
            flags=re.IGNORECASE,
        ).strip(" 。！？!?，,；;：:")
        if remainder in {"是什么", "是什么产品", "介绍一下"}:
            return True
    return False


async def _try_explicit_sku_detail_shortcut(db: Session, question: str) -> dict | None:
    text = str(question or "").strip()
    explicit_skus = customer_agent_service._extract_skus(text)
    if not text or not explicit_skus:
        return None
    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return None
    if _resolved_entity_realtime_commercial_field_guard_label(text):
        return None
    if not _is_explicit_sku_detail_question(text):
        return None
    resolved_candidates: list[str] = []
    for candidate in explicit_skus:
        resolved_candidate = _resolve_exact_sku_variant(db, candidate)
        if resolved_candidate and resolved_candidate not in resolved_candidates:
            resolved_candidates.append(resolved_candidate)
    # This shortcut is deliberately single-entity only. When the current
    # utterance names multiple canonical SKUs, selecting the first one would
    # discard a participant before the comparison contract can seal both.
    if len(resolved_candidates) > 1:
        return None
    resolved_sku = resolved_candidates[0] if len(resolved_candidates) == 1 else _resolve_sku(db, text, None)
    if not resolved_sku:
        return None
    requested_fields = _explicit_sku_detail_requested_fields(text)
    identity_references = sorted(
        {str(reference or "") for reference in [*explicit_skus, resolved_sku] if reference},
        key=len,
        reverse=True,
    )
    identity_overview_request = False
    for reference in identity_references:
        stripped_query = re.sub(
            rf"^\s*{re.escape(reference)}",
            "",
            text,
            count=1,
            flags=re.IGNORECASE,
        )
        identity_query = stripped_query.strip(" 。！？!?，,；;：:")
        if identity_query in {"是什么", "是什么产品", "介绍一下"}:
            identity_overview_request = True
            break
    if identity_overview_request:
        product = db.query(Product).filter(Product.sku == resolved_sku).first()
        detail = product_service.get_product_detail(db, resolved_sku) if product else None
        if isinstance(detail, dict) and detail:
            result = _named_product_context_result(text, detail, identity_overview=True)
            all_products = db.query(Product).order_by(Product.sku.asc()).all()
            entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
                text,
                all_products,
                resolver_candidates=[product],
                entity_text_override=resolved_sku,
            )
            debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
            debug.update({
                "agent_mode": "explicit_sku_context_shortcut",
                "entity_resolution_contract": entity_contract.to_dict(),
            })
            result["debug"] = debug
            result["sku"] = resolved_sku
            result["result_skus"] = [resolved_sku]
            result["candidate_skus"] = [resolved_sku]
            return result
    if (
        requested_fields
        and set(requested_fields).issubset({"热源", "适配情况"})
        and _is_explicit_sku_heat_source_question(text)
    ):
        return _phase1_product_field_result(
            db,
            {
                "primary_intent": "product_field",
                "product_ref": resolved_sku,
                "product_identity_source": "explicit_sku_exact",
                "requested_field": "heat_source",
                "raw_question": text,
                "sku": resolved_sku,
            },
        )
    intent = customer_agent_intent_service.CustomerIntent(
        intent="product_detail",
        target_skus=[resolved_sku],
        requested_fields=requested_fields,
        semantic_query=text,
        term=resolved_sku,
        source_context="question",
        is_single_field_sufficient=customer_agent_intent_service._is_single_field_sufficient(text, requested_fields, [resolved_sku]),
    )
    result = await customer_agent_intent_service._product_detail_result(
        db,
        intent,
        original_question=text,
    )
    product = db.query(Product).filter(Product.sku == resolved_sku).first()
    if product and any(term in text for term in ("酒精炉", "酒精")) and any(
        term in text for term in ("能用", "可以用", "支持", "适合", "能不能", "是否支持")
    ):
        bundle = _phase1_product_bundle_by_ref(db, resolved_sku)
        if bundle[0]:
            row = _product_row_from_model(*bundle)
            compatibility_answer, evidence_status = _phase1_alcohol_stove_compatibility_answer(db, row)
            if evidence_status in {"supported", "unsupported", "not_listed"}:
                result["answer"] = compatibility_answer
                answer_meta = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
                answer_meta["requested_field"] = "heat_source"
                answer_meta["evidence_status"] = evidence_status
                result["answer_metadata"] = answer_meta
    if (
        product
        and any(term in text for term in ("酒精炉", "酒精"))
        and any(term in text for term in ("能用", "可以用", "支持", "适合", "能不能", "是否支持"))
        and str(getattr(product, "category", "") or "").strip() not in {"锅具", "炉具", "水壶", "水具", "餐具", "酒具"}
        and not _result_has_positive_capability_evidence(result, text)
    ):
        detail = product_service.get_product_detail(db, resolved_sku)
        title = detail.get("product_name_cn") or detail.get("product_name_en") or resolved_sku
        usage = str((detail.get("business") or {}).get("usage_scenarios") or "").strip()
        conservative = f"{title}（{resolved_sku}）"
        if usage and "适合什么场景" in text:
            conservative += f"：使用场景：{usage}；"
        else:
            conservative += "："
        conservative += f"它属于{product.category}类产品，不是炉具或炊具；当前资料未标注适用酒精炉，不建议按酒精炉适配产品理解。"
        result["answer"] = conservative
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    requested_field = ""
    if "热源" in requested_fields:
        requested_field = "heat_source"
    elif requested_fields:
        requested_field = requested_fields[0]
    debug["agent_mode"] = "explicit_sku_detail_shortcut"
    debug["plan"] = {
        "primary_intent": "product_field",
        "product_ref": resolved_sku,
        "requested_field": requested_field,
        "raw_question": text,
    }
    result["debug"] = debug
    result["sku"] = resolved_sku
    result["result_skus"] = [resolved_sku]
    result["candidate_skus"] = [resolved_sku]
    return result


def _phase1_people_capacity_answer(
    row: dict[str, Any],
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> str:
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    audience = str(row.get("target_audience") or "").strip()
    people_match = re.search(
        r"(?:(?:\d+\s*[-~至]\s*\d+)|(?:\d+)|[一二两三四五六七八九十]+)\s*(?:个)?人",
        audience,
    )
    if people_match:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": people_match.group(0),
                "evidence_source": "business.target_audience",
                "evidence_scope": "subject",
            })
        return f"{name}的适用人数资料显示为：{people_match.group(0)}。"
    if evidence_metadata is not None:
        evidence_metadata.clear()
    return f"当前产品资料中未维护{name}的明确适用人数，无法确认适合几个人。"


def _phase1_except_alcohol_stove_cookware_result(db: Session, question: str) -> dict | None:
    text = str(question or "")
    if not any(term in text for term in ("除了", "除开", "除去")):
        return None
    if "酒精炉" not in text and "酒精" not in text:
        return None
    if not any(term in text for term in ("锅", "锅具", "套锅", "单锅", "炊具")):
        return None
    excluded_skus = {
        str(item or "").strip().upper()
        for item in customer_agent_service._extract_skus(text)
        if str(item or "").strip()
    }
    if not excluded_skus:
        return None
    rows = [
        row for row in _phase1_catalog_rows(db, "锅具")
        if str(row.get("sku") or "").strip().upper() not in excluded_skus
        and _is_service_pot_or_cookware_set_candidate(row)
        and _phase1_row_has_explicit_alcohol_stove_support(db, row)
    ]
    skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
    excluded_label = "、".join(sorted(excluded_skus))
    if rows:
        lines = [
            f"除了 {excluded_label}，当前资料还明确找到以下支持酒精炉的锅具：",
        ]
        for row in rows[:10]:
            name = row.get("product_name_cn") or row.get("name") or row.get("sku")
            sku = str(row.get("sku") or "").strip().upper()
            heat_source = str(row.get("heat_source") or "").strip()
            lines.append(f"- {name}（{sku}），明确证据：{heat_source or '同SKU资料/问答明确显示支持酒精炉'}")
    else:
        lines = [
            f"按当前资料，只明确找到 {excluded_label} 支持酒精炉；除了它，暂未找到其他明确标注支持酒精炉的锅具。",
            "仅支持明火、卡式炉、分体炉或一体炉的锅具，我不会直接归为酒精炉适用。",
        ]
    return {
        "intent": "query_products",
        "answer_type": "product_query",
        "answer": "\n".join(lines),
        "results": rows[:10],
        "result_skus": skus[:10],
        "candidate_skus": skus[:10],
        "answer_metadata": {
            "source": "structured_alcohol_stove_cookware_exclusion",
            "excluded_skus": sorted(excluded_skus),
            "display_count": min(len(rows), 10),
        },
        "debug": {
            "agent_mode": "structured_alcohol_stove_cookware_exclusion",
            "raw_results": rows[:10],
            "candidate_skus": skus[:10],
        },
        "skip_polish": True,
    }


def _phase1_comparison_evidence_value(canonical_field: str, value: Any) -> str:
    """Normalize legacy comparison evidence through the central value guard."""
    if canonical_field == "capacity":
        return _capacity_field_evidence(value)
    if value in (None, "", 0):
        return ""
    display = _compound_display_value(value).strip()
    if display.startswith("{") and display.endswith("}"):
        try:
            display = _display_value(json.loads(display)).strip()
        except (TypeError, ValueError, json.JSONDecodeError):
            pass
    return display if _is_valid_structured_field_value(canonical_field, display) else ""


def _phase1_product_evidence_text(row: dict, *, max_fields: int | None = None) -> str:
    fields = (
        ("capacity", "capacity"),
        ("body_material", "material"),
        ("gross_weight_g", "weight"),
        ("features", "technical_advantages"),
        ("usage_scenarios", "usage_scene"),
        ("positioning", "positioning"),
        ("long_description_cn", "long_description_cn"),
    )
    if max_fields is not None:
        # The decision fallback is a concise comparison aid, not a product
        # payload renderer. Long descriptions remain available to dedicated
        # content-field requests and cannot crowd out comparable evidence.
        fields = tuple(item for item in fields if item[0] != "long_description_cn")
    values = [
        evidence
        for key, canonical_field in fields
        if (evidence := _phase1_comparison_evidence_value(canonical_field, row.get(key)))
    ]
    return "；".join(values[:max_fields] if max_fields is not None else values)


def _validate_semantic_comparison_adjudication(
    data: dict[str, Any] | None,
    *,
    participant_count: int,
    allowed_evidence_fields: set[str],
) -> dict[str, Any] | None:
    """Accept an LLM comparison choice only as a sealed index-plus-evidence contract.

    The semantic model may interpret suitability, but it never supplies an SKU,
    product identity, database value, or customer-facing answer.  This validator
    only maps a bounded participant index back onto already sealed entities and
    accepts field keys that the executor actually supplied as same-SKU evidence.
    """
    if not isinstance(data, dict) or participant_count < 2:
        return None
    forbidden = {
        "sku", "selected_sku", "product", "product_name", "selected_product",
        "answer", "final_answer", "facts", "evidence_values", "raw_evidence",
    }
    if forbidden.intersection(data):
        return None
    selected_index = data.get("selected_index")
    if isinstance(selected_index, bool):
        return None
    if selected_index is not None and (
        not isinstance(selected_index, int) or selected_index < 0 or selected_index >= participant_count
    ):
        return None
    raw_fields = data.get("evidence_fields")
    if not isinstance(raw_fields, list):
        return None
    evidence_fields = list(dict.fromkeys(str(field or "").strip() for field in raw_fields))
    if selected_index is None and not evidence_fields:
        reasoning_summary = str(data.get("reasoning_summary") or "").strip()[:300]
        return {
            "selected_index": None,
            "evidence_fields": [],
            "reasoning_summary": reasoning_summary,
        }
    if not evidence_fields or any(field not in allowed_evidence_fields for field in evidence_fields):
        return None
    reasoning_summary = str(data.get("reasoning_summary") or "").strip()[:300]
    return {
        "selected_index": selected_index,
        "evidence_fields": evidence_fields,
        "reasoning_summary": reasoning_summary,
    }


def _comparison_adjudication_evidence(
    *,
    db: Session,
    bundles: list[tuple[Product | None, ProductSpecs | None, ProductBusiness | None, ProductContent | None]],
    include_partial: bool = False,
) -> dict[str, list[dict[str, Any]]]:
    """Build an opaque, same-SKU evidence packet for semantic comparison.

    Product identities never enter this packet. By default a field is present
    only when every sealed participant has a validated value. A decision
    adjudicator may explicitly request partial fields so an observed hard
    contradiction is not discarded; absent participant rows remain unknown
    and never become positive evidence.
    """
    candidates = sorted(
        field
        for field in customer_field_contract.FORMAL_DETAIL_FIELDS
        if customer_field_contract.is_supported_detail_field(field)
        and field not in {"sku", "barcode", "product_name", "product_name_en", "category"}
    )
    packet: dict[str, list[dict[str, Any]]] = {}
    for field in candidates:
        rows: list[dict[str, Any]] = []
        for index, (product, specs, business, content) in enumerate(bundles):
            if product is None:
                rows = []
                break
            value, source = _structured_product_field_evidence(
                field,
                db=db,
                product=product,
                specs=specs,
                business=business,
                content=content,
            )
            if not value:
                if include_partial:
                    continue
                rows = []
                break
            rows.append(
                {
                    "participant_index": index,
                    "sku": str(product.sku or "").strip().upper(),
                    "value": str(value).strip()[:600],
                    "source": str(source or "").strip(),
                }
            )
        if len(rows) == len(bundles) or (include_partial and rows):
            packet[field] = rows
    return packet


def _parse_semantic_json_object(content: str) -> dict[str, Any] | None:
    text = str(content or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.I)
        text = re.sub(r"\s*```$", "", text)
    try:
        data = json.loads(text)
    except (TypeError, json.JSONDecodeError):
        return None
    return data if isinstance(data, dict) else None


def _validate_semantic_recommendation_narrative(
    data: dict[str, Any] | None,
    *,
    candidate_count: int,
    verified_fields_by_index: dict[int, set[str]],
    candidate_identity_tokens_by_index: dict[int, set[str]] | None = None,
) -> dict[str, Any] | None:
    """Accept a narrative only when it cites the sealed candidate evidence."""
    if not isinstance(data, dict) or set(data) != {"ranked_candidate_indexes", "evidence_usage", "answer"}:
        return None
    ranked = data.get("ranked_candidate_indexes")
    usages = data.get("evidence_usage")
    answer = str(data.get("answer") or "").strip()
    if not isinstance(ranked, list) or not ranked or len(ranked) > min(candidate_count, 5):
        return None
    if any(type(index) is not int or not (0 <= index < candidate_count) for index in ranked):
        return None
    if len(set(ranked)) != len(ranked) or not isinstance(usages, list) or len(usages) != len(ranked):
        return None
    if not (20 <= len(answer) <= 1200) or "http://" in answer.lower() or "https://" in answer.lower():
        return None
    # Candidate indices are schema-only handles, never customer-facing language.
    if re.search(r"(?:候选\s*(?:索引)?|索引)\s*[#：:]?\s*\d+", answer, flags=re.IGNORECASE):
        return None
    # The model is free to choose a natural explanation, but it cannot name a
    # sealed product which its own ranked/evidence handles did not select.
    # Without this check a later result reordering can bind the prose for one
    # product to another product's evidence.  Identity tokens are supplied
    # from the sealed catalogue rows; this is contract validation, never a
    # product-name routing rule.
    if candidate_identity_tokens_by_index:
        normalized_answer = re.sub(r"\s+", "", answer).casefold()
        for index in ranked:
            selected_tokens = {
                re.sub(r"\s+", "", str(token or "")).casefold()
                for token in candidate_identity_tokens_by_index.get(index, set())
                if len(re.sub(r"\s+", "", str(token or ""))) >= 3
            }
            if selected_tokens and not any(token in normalized_answer for token in selected_tokens):
                # A customer-facing recommendation must identify every
                # product it ranks. Otherwise a later verifier cannot safely
                # bind pronouns such as “这款” to the visible result SKU and
                # may replace good semantic prose with an internal template.
                return None
        ranked_tokens = {
            re.sub(r"\s+", "", str(token or "")).casefold()
            for index in ranked
            for token in candidate_identity_tokens_by_index.get(index, set())
            if len(re.sub(r"\s+", "", str(token or ""))) >= 3
        }
        for index, tokens in candidate_identity_tokens_by_index.items():
            if index in ranked:
                continue
            for token in tokens:
                normalized_token = re.sub(r"\s+", "", str(token or "")).casefold()
                if (
                    len(normalized_token) >= 3
                    and normalized_token not in ranked_tokens
                    and normalized_token in normalized_answer
                ):
                    # A family/base identity can be a literal prefix of the
                    # selected variant's canonical name or SKU (for example
                    # ``城市出逃套锅`` inside ``城市出逃套锅大锅``).  The answer
                    # has not named an outside product in that case; it has
                    # named the selected identity.  Reject only a token that
                    # is not contained by any selected identity token.
                    if any(normalized_token in ranked_token for ranked_token in ranked_tokens):
                        continue
                    return None
    used_indexes: set[int] = set()
    normalized_usage: list[dict[str, Any]] = []
    for item in usages:
        if not isinstance(item, dict) or set(item) != {"candidate_index", "fields"}:
            return None
        index, fields = item.get("candidate_index"), item.get("fields")
        if type(index) is not int or index not in ranked or index in used_indexes:
            return None
        if not isinstance(fields, list) or not fields or len(fields) > 8:
            return None
        if any(not isinstance(field, str) or field not in verified_fields_by_index.get(index, set()) for field in fields):
            return None
        used_indexes.add(index)
        normalized_usage.append({"candidate_index": index, "fields": list(dict.fromkeys(fields))})
    if used_indexes != set(ranked):
        return None
    return {"ranked_candidate_indexes": ranked, "evidence_usage": normalized_usage, "answer": answer}


def _validate_semantic_recommendation_narrative_grounding_review(data: dict[str, Any] | None) -> dict[str, Any] | None:
    """Return a semantic reviewer decision only for the exact closed schema."""
    if not isinstance(data, dict) or set(data) != {"approved", "unsupported_claims"}:
        return None
    if type(data.get("approved")) is not bool:
        return None
    unsupported_claims = data.get("unsupported_claims")
    # The review is an actionable correction signal, not an exhaustive critique.
    # A compact bounded schema prevents a verbose rejection from being truncated
    # by the semantic provider before the one evidence-bounded rewrite can run.
    if not isinstance(unsupported_claims, list) or len(unsupported_claims) > 5:
        return None
    if any(not isinstance(item, str) or not item.strip() or len(item) > 80 for item in unsupported_claims):
        return None
    # A reviewer cannot approve while also naming unsupported claims.
    if data["approved"] and unsupported_claims:
        return None
    return {
        "approved": bool(data["approved"]),
        "unsupported_claims": list(data["unsupported_claims"]),
    }


_RECOMMENDATION_UNPROVED_COMPARATIVE_CLAIM_RE = re.compile(
    r"(?:最)\s*(?:轻|重|便宜|贵|省钱|耐用|实用|适合|好|佳|优|快|慢|小|大|强|弱|安全|稳定|方便|便携|可靠|省事|均衡|全能)"
    r"|(?:综合\s*(?:首选|推荐|最佳)|首选|最佳)"
)
def _recommendation_unproved_comparative_claims(answer: str) -> list[str]:
    """Return catalogue-wide rankings no selected-candidate evidence can prove.

    This is deliberately an output safety gate, never a field or product
    router.  Recommendation verification validates a candidate against the
    customer's stated constraints; it does not establish an ordering across a
    complete comparable population.  The semantic reviewer owns contextual
    claims such as relative lightness because it sees the sealed candidate
    values.  This bounded guard only prevents a reviewer false positive from
    exposing an unproved catalogue-wide superlative as fact.
    """
    text = str(answer or "")
    return list(dict.fromkeys(match.group(0) for match in _RECOMMENDATION_UNPROVED_COMPARATIVE_CLAIM_RE.finditer(text)))


_RECOMMENDATION_INTERNAL_PROCESS_CLAIM_RE = re.compile(
    r"同\s*SKU\s*(?:来源字段|条件(?:资料)?(?:已经|已)?(?:通过)?(?:验证|核验))"
    r"|(?:通过|经过|已通过).{0,12}(?:可验证|验证|核验|硬条件)"
    r"|可验证的硬条件"
    r"|本次仅采用"
    r"|(?:候选|索引)\s*[#：:]?\s*\d+",
    flags=re.IGNORECASE,
)


def _recommendation_internal_process_claims(answer: str) -> list[str]:
    """Reject internal verification/process wording from customer prose."""
    text = str(answer or "")
    return list(dict.fromkeys(
        match.group(0)
        for match in _RECOMMENDATION_INTERNAL_PROCESS_CLAIM_RE.finditer(text)
    ))


def _recommendation_rewrite_candidates(candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Keep a rejected narrative's rewrite inside the same sealed SKU packet.

    A rewrite must be able to replace an unsupported conclusion with the
    literal same-SKU context that could actually explain the recommendation.
    Removing that context after the first draft turns a valid recovery into a
    category-only list, even when usage, audience, or product-content evidence
    was already sealed for the selected product.  The rewrite remains bounded
    by the exact packet and goes through the same semantic grounding review;
    it cannot introduce a new candidate, fact, rank, or inferred suitability.
    """
    recovery: list[dict[str, Any]] = []
    for candidate in candidates:
        verified_constraints = [
            str(field)
            for field in candidate.get("verified_constraints") or []
            if isinstance(field, str) and field
        ]
        sealed_evidence = candidate.get("sealed_evidence") or {}
        recovery.append({
            **candidate,
            "sealed_evidence": {
                str(field): value
                for field, value in sealed_evidence.items()
                if str(field).strip() and str(value or "").strip()
            },
            "verified_constraints": verified_constraints,
        })
    return recovery


async def _semantic_recommendation_narrative_grounding_review(
    db: Session,
    *,
    question: str,
    candidates: list[dict[str, Any]],
    narrative: dict[str, Any],
    soft_preferences: list[str] | None = None,
    diagnostic: dict[str, str] | None = None,
) -> dict[str, Any] | None:
    """Use the semantic model to reject, never repair, unsupported prose claims."""
    messages = [
        {
            "role": "system",
            "content": (
                "Return only JSON. Audit whether every product-specific factual, comparative, superlative, "
                "or suitability claim in answer is directly entailed by sealed_candidates' sealed_evidence or verified_constraints. "
                "The question is not evidence. Do not infer missing facts, and do not accept a claim merely "
                "because it sounds plausible. A numeric field does not establish a relative, qualitative, or suitability claim. "
                "In particular, a recorded weight such as 960g or 340g never by itself proves that a candidate is '轻量', "
                "'轻便', '较轻', or '极致轻便'; reject those labels unless that exact qualitative wording appears in that "
                "candidate's sealed evidence. This remains true when the customer has expressed a lightweight preference. "
                "Reject any ungrounded comparative or superlative language, including Chinese claims such as '更安全', '更稳定', '非常适合', '首选', or '综合推荐'; "
                "a single candidate's evidence cannot establish those claims without an explicit comparison or the exact literal wording in that candidate's sealed evidence. "
                "verified_constraints are internal selection gates, not customer-facing facts. Reject any answer that exposes validation, verification, contracts, checks, or the selection process. "
                "soft_customer_preferences are literal user priorities but are not evidence. Reject any claim that a candidate meets one unless the exact support appears in sealed_evidence. "
                "content.usage_scenarios supports a direct scenario statement such as '资料标注场景为露营' or a direct scenario statement that the candidate is for that same listed scenario; "
                "content.target_audience and heat_source likewise support only their directly listed audience or heat-source statements. "
                "For a customer decision, a conditional choice is allowed only when its stated condition is directly and narrowly restated from that selected candidate's sealed scenario, audience, or other sealed evidence. The answer must make that condition explicit rather than claiming an unconditional winner or broad suitability. "
                "You must approve a direct literal restatement such as '资料标注使用场景包括家庭露营' when that exact scenario is present in the selected candidate's content.usage_scenarios and evidence_usage cites it; "
                "this is an evidence citation, not an unsupported broad suitability claim. "
                "Candidate indexes are internal handles, never customer language. "
                "Schema exactly: {\"approved\":boolean,\"unsupported_claims\":[\"brief claim\"]}. "
                "If rejecting, return at most five concise unsupported claim snippets, each at most 80 characters; "
                "prioritize the highest-impact unsupported claims and do not enumerate every sentence. "
                "Set approved true only when unsupported_claims is empty."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "soft_customer_preferences": list(soft_preferences or []),
                    "sealed_candidates": candidates,
                    "ranked_candidate_indexes": narrative["ranked_candidate_indexes"],
                    "evidence_usage": narrative["evidence_usage"],
                    "answer": narrative["answer"],
                },
                ensure_ascii=False,
            ),
        },
    ]
    # A completed recommendation draft has already passed its closed evidence
    # schema. One malformed reviewer reply is a provider-format transient, not
    # evidence that the draft is unsafe. Retry the same semantic audit once,
    # then remain fail-closed if it still cannot return the review contract.
    # This never approves a draft without an explicit DeepSeek review and
    # never synthesizes a deterministic recommendation verdict.
    last_status = "unavailable_or_invalid"
    for _attempt in range(2):
        try:
            content = await customer_llm_service.chat_completion(
                db,
                messages=messages,
                temperature=0,
                max_tokens=400,
                purpose="semantic_recommendation_narrative_grounding_review",
                # Recommendation writing/review is customer-facing reasoning, not
                # the latency-oriented semantic preplan. Use the configured chat
                # model so the same DeepSeek service owns both prose and review.
                api_model_override=None,
                response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
                thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
            )
        except Exception:
            last_status = "provider_error"
            continue
        parsed = _parse_semantic_json_object(content)
        result = _validate_semantic_recommendation_narrative_grounding_review(parsed)
        if result is not None:
            return result
        last_status = "invalid_json" if parsed is None else "invalid_contract"
    if diagnostic is not None:
        diagnostic["status"] = last_status
    return None


def _semantic_catalog_value_query_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    """Execute a semantic, database-grounded catalogue-value filter.

    The planner decides whether a phrase names a public catalogue field.  This
    executor only verifies that the semantic subject actually matches that
    field in the live development database before exposing any product rows.
    """
    plan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    field = str(plan.get("field_type") or plan.get("catalogue_field_candidate") or "").strip()
    subject = str(plan.get("subject_text") or "").strip()
    if not (
        field in {"series", "brand", "category", "product_level"}
        and (
            (
                str(plan.get("route_family") or "").strip() == "structured_query"
                and str(plan.get("route_hint") or "").strip() == "query_products"
            )
            or str(plan.get("semantic_route_family_hint") or "").strip() == "structured_query"
        )
        and _semantic_preplan_confident(plan, minimum=0.9)
        and not (plan.get("entities") or [])
    ):
        return None
    normalized_subject = customer_agent_service.normalize_search_text(subject).lower()
    normalized_question = customer_agent_service.normalize_search_text(question).lower()
    if field == "category" and normalized_subject and normalized_subject not in normalized_question:
        direct_categories = [
            str(value or "").strip()
            for (value,) in db.query(Product.category).distinct().all()
            if str(value or "").strip()
            and customer_agent_service.normalize_search_text(str(value)).lower() in normalized_question
        ]
        if direct_categories:
            shortest = min(len(customer_agent_service.normalize_search_text(value)) for value in direct_categories)
            direct_categories = [value for value in direct_categories if len(customer_agent_service.normalize_search_text(value)) == shortest]
        if len(direct_categories) == 1:
            subject = direct_categories[0]
            normalized_subject = customer_agent_service.normalize_search_text(subject).lower()
    subject_candidates = [normalized_subject]
    field_contract = customer_field_contract.field_contract_for_type(field)
    field_labels = [customer_field_contract.product_detail_field_label(field)]
    if field_contract:
        field_labels.extend(field_contract.aliases)
    # The concise terminal token of a registered field label is still a
    # display modifier, not part of the database value (for example the
    # ``系列`` suffix in a semantic subject such as “城市出逃系列”).
    field_labels.extend(str(label or "")[-2:] for label in field_labels if len(str(label or "")) > 2)
    for label in field_labels:
        normalized_label = customer_agent_service.normalize_search_text(label).lower()
        if normalized_label and normalized_subject.endswith(normalized_label):
            subject_candidates.append(normalized_subject[:-len(normalized_label)].strip())
        if normalized_label and normalized_subject.startswith(normalized_label):
            subject_candidates.append(normalized_subject[len(normalized_label):].strip())
    subject_candidates = list(dict.fromkeys(item for item in subject_candidates if len(item) >= 2))
    if not subject_candidates:
        return None
    rows = [
        row for row in _phase1_catalog_rows(db, "产品")
        if any(
            candidate in customer_agent_service.normalize_search_text(row.get(field) or "").lower()
            for candidate in subject_candidates
        )
    ]
    reason_label = f"数据库{customer_field_contract.product_detail_field_label(field)}字段"
    if not rows:
        # A multilingual collection label can be stored in the customer-facing
        # content of a product while its canonical catalogue value remains in
        # a Chinese series/category column.  Do not translate, guess, or use a
        # global alias: prove the mapping on the same row, and accept it only
        # when every matched row yields one unambiguous formal field value.
        content_keys = (
            "product_name_en",
            "title_en",
            "website_title",
            "amazon_title",
            "long_description_en",
            "long_description_cn",
        )
        content_matches = [
            row for row in _phase1_catalog_rows(db, "产品")
            if any(
                candidate in customer_agent_service.normalize_search_text(
                    " ".join(str(row.get(key) or "") for key in content_keys)
                ).lower()
                for candidate in subject_candidates
            )
        ]
        matched_values = {
            str(row.get(field) or "").strip()
            for row in content_matches
            if str(row.get(field) or "").strip()
        }
        if len(matched_values) != 1:
            return None
        canonical_value = next(iter(matched_values))
        normalized_value = customer_agent_service.normalize_search_text(canonical_value).lower()
        rows = [
            row for row in _phase1_catalog_rows(db, "产品")
            if customer_agent_service.normalize_search_text(row.get(field) or "").lower() == normalized_value
        ]
        if not rows:
            return None
        reason_label += "（同商品内容映射）"
    return _structured_product_query_result(
        question=question,
        product_ref=subject,
        rows=rows,
        source="semantic_database_value_catalog_filter",
        reason_label=reason_label,
        membership_field=field,
    )


async def _semantic_catalog_value_exact_adapter(
    db: Session,
    *,
    question: str,
    semantic_preplan: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Map a semantic catalogue value only to an exact live DB value.

    The semantic plan already owns intent and field selection.  This adapter
    runs only after literal/content verification failed and gives the model a
    small closed set of actual field values.  Its output is accepted only when
    it returns one of those values verbatim, so it cannot invent a series,
    brand, category, level, SKU, or answer.
    """
    plan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    field = str(plan.get("field_type") or plan.get("catalogue_field_candidate") or "").strip()
    subject = str(plan.get("subject_text") or "").strip()
    if not (
        field in {"series", "brand", "category", "product_level"}
        and (
            (
                str(plan.get("route_family") or "").strip() == "structured_query"
                and str(plan.get("route_hint") or "").strip() == "query_products"
            )
            or str(plan.get("semantic_route_family_hint") or "").strip() == "structured_query"
        )
        and _semantic_preplan_confident(plan, minimum=0.9)
        and not (plan.get("entities") or [])
    ):
        return None
    column = getattr(Product, field, None)
    if column is None:
        return None
    values = sorted({
        str(value or "").strip()
        for (value,) in db.query(column).distinct().all()
        if str(value or "").strip() and str(value or "").strip() not in {"/", "未分类", "暂无", "未知"}
    })
    if not values or len(values) > 40:
        return None
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    messages = [
        {
            "role": "system",
            "content": (
                "You resolve one customer catalogue filter into an exact value from a closed database list. "
                "Understand Chinese/English paraphrase or translation, but never invent, translate, shorten, "
                "combine, or return a value outside the list. Return JSON only: {\"value\": \"exact list value or empty\"}."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "field": field,
                    # A semantic planner may correctly classify a catalogue
                    # field while omitting its foreign-language value span.
                    # The whole turn is still safe input because the model
                    # can only select an exact entry from allowed_values.
                    "customer_value": subject or str(question or "").strip(),
                    "allowed_values": values,
                },
                ensure_ascii=False,
            ),
        },
    ]
    selected_values: list[str] = []
    for _ in range(2):
        try:
            content = await customer_llm_service.chat_completion(
                db, messages, temperature=0.0, max_tokens=80,
                purpose="semantic_catalog_value_exact_adapter",
                api_model_override=runtime["model"],
                response_format={"type": "json_object"}, thinking=False,
            )
            payload = json.loads(str(content or ""))
        except (ValueError, TypeError, json.JSONDecodeError):
            continue
        value = str(payload.get("value") or "").strip() if isinstance(payload, dict) else ""
        if value in values:
            selected_values.append(value)
    if len(selected_values) != 2 or len(set(selected_values)) != 1:
        return None
    value = selected_values[0]
    adapted = dict(plan)
    adapted["subject_text"] = value
    adapted["catalog_value_adapter"] = "semantic_exact_live_value"
    return adapted


async def _semantic_recommendation_narrative_rewrite(
    db: Session,
    *,
    question: str,
    candidates: list[dict[str, Any]],
    rejected_narrative: dict[str, Any],
    unsupported_claims: list[str],
    soft_preferences: list[str] | None = None,
) -> dict[str, Any] | None:
    """Ask the semantic model for one evidence-bounded rewrite after a rejection."""
    messages = [
        {
            "role": "system",
            "content": (
                "Return only JSON. Rewrite the customer-facing recommendation using only sealed_candidates' "
                "sealed_evidence. verified_constraints are internal selection gates and must never appear in customer prose. soft_customer_preferences are not evidence: do not claim that a candidate meets them unless the exact support appears in sealed_evidence. Remove every rejected claim; do not replace it with a synonym, inference, "
                "ranking claim, new product fact, or a qualitative conclusion from a numeric value. Keep the prose natural and useful. candidate_index is an "
                "internal JSON handle only and must not appear in answer. Name only product_name values belonging to your ranked_candidate_indexes; "
                "never describe or name a different sealed candidate. Schema exactly: "
                "{\"ranked_candidate_indexes\":[integer],\"evidence_usage\":[{\"candidate_index\":integer,"
                "\"fields\":[\"evidence field\"]}],\"answer\":\"natural Chinese recommendation\"}. "
                "硬性恢复规则：最多选择三款；若恢复包只提供场景或产品类型证据，只能写‘资料标注使用场景包括…’或‘资料标注产品类型为…’这类来源绑定陈述。若回答选择问题，只能在所写条件直接、狭义复述某候选的 sealed_evidence 时给出条件化选择；必须写明条件和来源，不能给出无条件优胜或把用户偏好当作产品事实。 "
                "不得写‘适合…’、‘首选’、‘更安全’、‘更稳定’、‘最好’或任何比较、承诺、卖点扩写；没有其他可核验理由时，直接场景陈述就是完整推荐理由。"
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "soft_customer_preferences": list(soft_preferences or []),
                    "sealed_candidates": candidates,
                    "rejected_answer": rejected_narrative["answer"],
                    "rejected_claims": unsupported_claims,
                },
                ensure_ascii=False,
            ),
        },
    ]
    try:
        content = await customer_llm_service.chat_completion(
            db,
            messages=messages,
            temperature=0,
            max_tokens=700,
            purpose="semantic_recommendation_narrative_rewrite",
            api_model_override=None,
            response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
            thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
        )
    except Exception:
        return None
    return _validate_semantic_recommendation_narrative(
        _parse_semantic_json_object(content),
        candidate_count=len(candidates),
        verified_fields_by_index={
            index: set(candidate.get("sealed_evidence") or {})
            for index, candidate in enumerate(candidates)
        },
        candidate_identity_tokens_by_index={
            index: {str(candidate.get("product_name") or "").strip(), str(candidate.get("sku") or "").strip()}
            for index, candidate in enumerate(candidates)
        },
    )


async def _semantic_recommendation_narrative(
    db: Session,
    *,
    question: str,
    rows: list[dict[str, Any]],
    verifications: list[Any],
    soft_preferences: list[str] | None = None,
    diagnostics: list[dict[str, Any]] | None = None,
) -> dict[str, Any] | None:
    verification_by_sku = {str(item.sku or "").strip().upper(): item for item in verifications}
    candidates: list[dict[str, Any]] = []
    verified_fields_by_index: dict[int, set[str]] = {}
    content_evidence_fields = ("features", "usage_scenarios", "target_audience", "positioning", "top_selling_points", "long_description_cn")
    for index, row in enumerate(rows):
        sku = str(row.get("sku") or "").strip().upper()
        verification = verification_by_sku.get(sku)
        if not verification:
            return None
        evidence_by_field = {
            field: item.get("raw_value")
            for field, item in verification.evidence_by_constraint.items()
            if isinstance(item, dict) and item.get("status") == "verified"
        }
        for field in content_evidence_fields:
            value = row.get(field)
            if str(value or "").strip():
                evidence_by_field[f"content.{field}"] = value
        if not evidence_by_field:
            return None
        verified_fields_by_index[index] = set(evidence_by_field)
        candidates.append({
            "candidate_index": index,
            "product_name": str(row.get("product_name_cn") or sku).strip(),
            "sku": sku,
            "sealed_evidence": evidence_by_field,
            "verified_constraints": [
                field
                for field, item in verification.evidence_by_constraint.items()
                if isinstance(item, dict) and item.get("status") == "verified"
            ],
            "uncertainties": list(dict.fromkeys([*verification.unsupported_constraints, *verification.unsupported_preferences])),
        })
    messages = [
        {
            "role": "system",
            "content": (
                "Return only JSON. You are a customer-facing recommendation writer. "
                "Use only the sealed candidates and their sealed_evidence; do not infer, add, or generalize product facts. "
                "Choose one to three focused candidates, at most three; do not exhaustively list every candidate. "
                "verified_constraints are internal selection gates. Never reveal validation, verification, contracts, checks, candidate selection, or any internal process in customer prose. "
                "A numeric value or an evidence field never licenses a comparative, superlative, qualitative, or suitability claim beyond its literal value. "
                "Do not use ungrounded comparative or superlative language such as '更安全', '更稳定', '非常适合', '首选', or '综合推荐' unless that exact claim is sealed evidence. "
                "Keep the recommendation natural, but every product-specific reason must be a literal sealed_evidence value. "
                "When using content.usage_scenarios, phrase it as a source-bound statement such as '资料标注使用场景包括…'; do not write '适合…' or turn it into an unqualified broader suitability conclusion. "
                "When the question asks to choose between product directions, you may give a conditional choice only when the condition is a narrow literal restatement of that selected candidate's sealed evidence; state the condition and cite the evidence, never call it an unconditional best choice. "
                "soft_customer_preferences are literal customer priorities that the semantic preplan classified as non-binding. They may guide the explanation's tone or a transparent caveat, but never prove, filter, rank, or assert a product fact. State an uncertainty if it matters to the requested choice. Never introduce a product, SKU, price, stock, certification, warranty, or factual claim outside the input. "
                "candidate_index is an internal JSON handle only: never mention a candidate index, ranking index, or ordinal label in answer; refer to the product_name instead. "
                "You may name only the product_name belonging to your ranked_candidate_indexes; never describe or name a different sealed candidate. "
                "For every evidence_usage item, fields must be exact key strings that are actually present in that same candidate's sealed_evidence object. Do not copy an evidence key from another candidate, invent a content.* key, or cite a field merely because a similar candidate has it. "
                "Schema exactly: {\"ranked_candidate_indexes\":[integer],\"evidence_usage\":[{\"candidate_index\":integer,\"fields\":[\"evidence field\"]}],\"answer\":\"natural Chinese recommendation\"}."
            ),
        },
        {"role": "user", "content": json.dumps({
            "question": question,
            "soft_customer_preferences": list(soft_preferences or []),
            "sealed_candidates": candidates,
        }, ensure_ascii=False)},
    ]
    # A provider can occasionally produce malformed JSON even with JSON mode.
    # Retry one independent semantic draft before abandoning an otherwise fully
    # verified catalogue result.  Both drafts and any rewrite remain subject to
    # the exact same sealed-evidence validator and semantic grounding review;
    # this is resilience for the LLM writer, not a deterministic answer path.
    prior_invalid_draft: dict[str, Any] | None = None
    for _attempt in range(2):
        attempt_number = _attempt + 1
        attempt_messages = [dict(message) for message in messages]
        if _attempt:
            attempt_messages[0]["content"] += (
                " The previous draft was rejected at the closed evidence schema. Rebuild it from scratch: "
                "for each selected candidate, use only exact sealed_evidence keys present on that candidate, and choose fewer candidates or fewer claims if needed."
            )
            if prior_invalid_draft is not None:
                attempt_messages.append({
                    "role": "user",
                    "content": json.dumps(
                        {
                            "previous_invalid_draft": prior_invalid_draft,
                            "repair_task": "Return a replacement JSON object only. Keep a product-specific claim only when its selected candidate has the exact cited sealed_evidence key; otherwise remove that claim or choose a different candidate.",
                        },
                        ensure_ascii=False,
                    ),
                })
        try:
            content = await customer_llm_service.chat_completion(
                db,
                messages=attempt_messages,
                temperature=0,
                max_tokens=700,
                purpose="semantic_recommendation_narrative",
                api_model_override=None,
                response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
                thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
            )
        except Exception:
            if diagnostics is not None:
                diagnostics.append({"attempt": attempt_number, "stage": "draft", "status": "provider_error"})
            continue
        parsed_narrative = _parse_semantic_json_object(content)
        narrative = _validate_semantic_recommendation_narrative(
            parsed_narrative,
            candidate_count=len(rows),
            verified_fields_by_index=verified_fields_by_index,
            candidate_identity_tokens_by_index={
                index: {str(candidate.get("product_name") or "").strip(), str(candidate.get("sku") or "").strip()}
                for index, candidate in enumerate(candidates)
            },
        )
        if narrative is None:
            prior_invalid_draft = parsed_narrative
            if diagnostics is not None:
                diagnostics.append({"attempt": attempt_number, "stage": "draft", "status": "invalid_schema"})
            continue
        review_diagnostic: dict[str, str] = {}
        review = await _semantic_recommendation_narrative_grounding_review(
            db,
            question=question,
            candidates=candidates,
            narrative=narrative,
            soft_preferences=soft_preferences,
            diagnostic=review_diagnostic,
        )
        local_unsupported_claims = list(dict.fromkeys([
            *_recommendation_unproved_comparative_claims(narrative["answer"]),
            *_recommendation_internal_process_claims(narrative["answer"]),
        ]))
        if review and review["approved"] and not local_unsupported_claims:
            if diagnostics is not None:
                diagnostics.append({"attempt": attempt_number, "stage": "grounding_review", "status": "approved"})
            return narrative
        if local_unsupported_claims and diagnostics is not None:
            diagnostics.append({
                "attempt": attempt_number,
                "stage": "narrative_safety_gate",
                "status": "rejected",
                "unsupported_claims": local_unsupported_claims,
            })
        reviewer_unsupported_claims = list(review["unsupported_claims"]) if review else []
        unsupported_claims = list(dict.fromkeys([*reviewer_unsupported_claims, *local_unsupported_claims]))
        if not review or not unsupported_claims:
            if diagnostics is not None:
                diagnostics.append({
                    "attempt": attempt_number,
                    "stage": "grounding_review",
                    "status": review_diagnostic.get("status") or "unavailable_or_invalid",
                })
            continue
        if diagnostics is not None:
            diagnostics.append({
                "attempt": attempt_number,
                "stage": "grounding_review",
                "status": "rejected",
                "unsupported_claims": unsupported_claims,
            })
        recovery_candidates = _recommendation_rewrite_candidates(candidates)
        rewritten = await _semantic_recommendation_narrative_rewrite(
            db,
            question=question,
            candidates=recovery_candidates,
            rejected_narrative=narrative,
            unsupported_claims=unsupported_claims,
            soft_preferences=soft_preferences,
        )
        if rewritten is None:
            if diagnostics is not None:
                diagnostics.append({"attempt": attempt_number, "stage": "rewrite", "status": "invalid_schema_or_provider_error"})
            continue
        rewritten_review = await _semantic_recommendation_narrative_grounding_review(
            db,
            question=question,
            candidates=recovery_candidates,
            narrative=rewritten,
            soft_preferences=soft_preferences,
        )
        rewritten_local_unsupported_claims = list(dict.fromkeys([
            *_recommendation_unproved_comparative_claims(rewritten["answer"]),
            *_recommendation_internal_process_claims(rewritten["answer"]),
        ]))
        if rewritten_review and rewritten_review["approved"] and not rewritten_local_unsupported_claims:
            if diagnostics is not None:
                diagnostics.append({"attempt": attempt_number, "stage": "rewrite_grounding_review", "status": "approved"})
            return rewritten
        if diagnostics is not None:
            diagnostics.append({"attempt": attempt_number, "stage": "rewrite_grounding_review", "status": "unavailable_or_rejected"})
    return None


async def _semantic_comparison_adjudication(
    db: Session,
    *,
    question: str,
    evidence_packet: dict[str, list[dict[str, Any]]],
    participant_count: int,
) -> dict[str, Any] | None:
    """Ask the semantic model to judge only a sealed comparison evidence set."""
    if participant_count < 2 or not evidence_packet:
        return None
    model_packet = {
        field: [
            {"participant_index": row["participant_index"], "value": row["value"]}
            for row in rows
        ]
        for field, rows in evidence_packet.items()
    }
    messages = [
        {
            "role": "system",
            "content": (
                "Return only JSON. You are a semantic comparison adjudicator, not a product-answer writer. "
                "Use only the supplied sealed_evidence. Ignore product names, version labels, SKU-like text, and any facts outside that evidence. "
                "Choose selected_index only when the evidence directly supports one participant for the user's stated need; otherwise use null. "
                "A field may contain rows for only some participants: a missing participant row means unknown, never positive evidence. "
                "A bounded relative choice is allowed when another participant is explicitly contradicted by a stated hard requirement and the selected participant has separate directly supportive evidence for the need; never choose merely because its requested field is missing. "
                "evidence_fields must list only the minimal, directly sufficient evidence fields actually used; do not pad the list with merely related fields. Never return a SKU, product name, answer text, or copied evidence value. "
                "Whether or not a winner is supported, evidence_fields must select one to four complete fields that most directly answer the requested comparison when such evidence exists; use an empty list only when no supplied field is directly relevant. Omit merely incidental differences. "
                "Schema: {\"selected_index\":0|1|null,\"evidence_fields\":[\"canonical_field\"],\"reasoning_summary\":\"brief audit reason\"}."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "participant_count": participant_count,
                    "sealed_evidence": model_packet,
                },
                ensure_ascii=False,
            ),
        },
    ]
    try:
        content = await customer_llm_service.chat_completion(
            db,
            messages=messages,
            temperature=0,
            max_tokens=240,
            purpose="semantic_comparison_adjudication",
            api_model_override=str(settings.SEMANTIC_PREPLAN_MODEL or "").strip() or None,
            response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
            thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
        )
    except Exception:
        return None
    decision = _validate_semantic_comparison_adjudication(
        _parse_semantic_json_object(content),
        participant_count=participant_count,
        allowed_evidence_fields=set(evidence_packet),
    )
    if decision is None or decision.get("selected_index") is None:
        return decision
    review_packet = {
        field: model_packet[field]
        for field in decision["evidence_fields"]
        if field in model_packet
    }
    review_messages = [
        {
            "role": "system",
            "content": (
                "Return only JSON. Audit the grounding of a proposed semantic product-comparison choice using only "
                "the customer question and sealed_evidence. Do not independently re-decide which participant is more suitable; "
                "the preceding semantic adjudicator owns that decision. Reject only when the proposed evidence fields are absent, "
                "irrelevant to the requested need, or directly contradict the proposed choice. A larger number, more fields, or "
                "merely related usage text is not sufficient by itself. A missing participant row means unknown, never support. "
                "A bounded relative choice may be approved when another participant is explicitly contradicted by a stated hard "
                "requirement and the selected participant has separate directly supportive evidence; missing data alone can never "
                "justify the choice. Do not require an exact requested-value row for the selected participant when those two "
                "bounded-relative conditions are both satisfied. Never use product names or facts outside the packet. "
                "Return only JSON: {\"approved\":boolean}. Do not explain."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "participant_count": participant_count,
                    "sealed_evidence": review_packet,
                    "proposed_decision": {
                        "selected_index": decision["selected_index"],
                        "evidence_fields": decision["evidence_fields"],
                    },
                },
                ensure_ascii=False,
            ),
        },
    ]
    try:
        review_content = await customer_llm_service.chat_completion(
            db,
            messages=review_messages,
            temperature=0,
            max_tokens=40,
            purpose="semantic_comparison_adjudication_grounding_review",
            api_model_override=str(settings.SEMANTIC_PREPLAN_MODEL or "").strip() or None,
            response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
            thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
        )
    except Exception:
        review_content = ""
    review = _parse_semantic_json_object(review_content)
    if (
        isinstance(review, dict)
        and set(review).issubset({"approved", "reasoning_summary"})
        and review.get("approved") is True
    ):
        return decision
    return {
        "selected_index": None,
        "evidence_fields": list(decision.get("evidence_fields") or []),
        "reasoning_summary": str(
            (review or {}).get("reasoning_summary")
            or "Independent grounding review did not approve the proposed choice."
        ).strip(),
    }


async def _phase1_compare_choice_result(db: Session, plan: dict) -> dict | None:
    # Explicit SKUs in the current utterance are the strongest sealed identity
    # set for a comparison.  Planner product_refs may be a lossy semantic
    # summary, so it must not replace two literal comparison participants.
    raw_question = str(plan.get("raw_question") or "")
    explicit_skus = list(dict.fromkeys(
        str(sku or "").strip().upper()
        for sku in customer_agent_service._extract_skus(raw_question)
        if str(sku or "").strip()
    ))
    product_refs = (
        explicit_skus
        if len(explicit_skus) >= 2
        else [str(item or "").strip() for item in plan.get("product_refs") or [] if str(item or "").strip()]
    )
    if len(product_refs) < 2:
        return None
    # Explicit comparison references are a sealed identity set.  Do not
    # silently discard the third (or later) entity merely because the older
    # comparison formatter was written for a pair.
    bundles = [_phase1_product_bundle_by_ref(db, ref) for ref in product_refs]
    if not all(bundle[0] for bundle in bundles):
        return None
    rows = [_product_row_from_model(product, specs, business, content) for product, specs, business, content in bundles if product]
    first, second = rows[0], rows[1]
    first_name = first.get("product_name_cn") or product_refs[0]
    second_name = second.get("product_name_cn") or product_refs[1]
    field_request = resolve_requested_field_contract(
        str(plan.get("raw_question") or ""),
        plan,
    )
    canonical_field = str(field_request.get("field_type") or "").strip()
    semantic_preplan = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    semantic_comparison_fields = [
        str(field or "").strip()
        for field in (semantic_preplan.get("canonical_fields") or [])
        if customer_field_contract.is_supported_detail_field(str(field or "").strip())
    ]
    if (
        plan.get("semantic_comparison_entity_contracts")
        and not canonical_field
        and len(semantic_comparison_fields) == 1
    ):
        canonical_field = semantic_comparison_fields[0]
        field_request = {
            **field_request,
            "field_type": canonical_field,
            "canonical_fields": [canonical_field],
            "source": "validated_semantic_preplan",
        }
    # Semantic planning has explicitly identified a non-decisive comparison
    # with no customer-specified criterion. This is an evidence presentation,
    # not a deterministic choice of a field route: show only recorded values
    # that differ across every sealed participant.
    if (
        plan.get("semantic_comparison_entity_contracts")
        and _semantic_structured_comparison_overview_contract(semantic_preplan)
    ):
        overview_fields = (
            "series", "category", "dimensions", "weight", "material",
            "capacity", "people", "target_audience", "color",
            "usage_scene", "selling_point",
        )
        evidence_bundles: list[customer_evidence_bundle.CustomerEvidenceBundle] = []
        for product, specs, business, content in bundles:
            if product is None:
                continue
            sku = str(product.sku or "").strip().upper()
            name = str(product.product_name_cn or product.product_name_en or sku).strip()
            structured_items: list[dict[str, Any]] = []
            for field in overview_fields:
                value, source = _structured_product_field_evidence(
                    field,
                    db=db,
                    product=product,
                    specs=specs,
                    business=business,
                    content=content,
                )
                if value and source:
                    structured_items.append({
                        "evidence_id": f"{sku}:field:{field}:{source}",
                        "sku": sku,
                        "source_type": "structured_field",
                        "source": str(source),
                        "field": field,
                        "value": str(value),
                        "visibility": "customer_visible",
                    })
            evidence_bundles.append(
                customer_evidence_bundle.build_customer_evidence_bundle(
                    sku=sku,
                    product_name=name,
                    evidence_items=structured_items,
                )
            )
        lines: list[str] = []
        sources: list[dict[str, Any]] = []
        lines_by_field: dict[str, str] = {}
        sources_by_field: dict[str, list[dict[str, Any]]] = {}
        for field in overview_fields:
            values: list[tuple[str, str, str, str]] = []
            for evidence_bundle in evidence_bundles:
                field_evidence = evidence_bundle.evidence_for_field(field)
                if not field_evidence:
                    values = []
                    break
                item = field_evidence[0]
                values.append((
                    evidence_bundle.sku,
                    evidence_bundle.product_name,
                    item.value,
                    item.source,
                ))
            if (
                len(values) != len(evidence_bundles)
                or len(evidence_bundles) != len(bundles)
                or len({value for _, _, value, _ in values}) < 2
            ):
                continue
            label = customer_field_contract.product_detail_field_label(field) or field
            rendered_line = (
                f"- {label}：" + "；".join(
                    f"{name}（{sku}）为{value}" for sku, name, value, _source in values
                ) + "。"
            )
            field_sources = [
                {"type": "product_field", "sku": sku, "field": field, "source": source, "value": value}
                for sku, _name, value, source in values
            ]
            lines.append(rendered_line)
            sources.extend(field_sources)
            lines_by_field[field] = rendered_line
            sources_by_field[field] = field_sources
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        try:
            overview_evidence_packet = _comparison_adjudication_evidence(
                db=db,
                bundles=bundles,
            )
        except Exception:
            overview_evidence_packet = {}
        overview_adjudication = (
            await _semantic_comparison_adjudication(
                db,
                question=raw_question,
                evidence_packet=overview_evidence_packet,
                participant_count=len(bundles),
            )
            if overview_evidence_packet
            else None
        )
        overview_selected_index = (
            overview_adjudication.get("selected_index")
            if isinstance(overview_adjudication, dict)
            else None
        )
        overview_selected_sku = None
        overview_choice_line = ""
        overview_evidence_fields = [
            str(field or "").strip()
            for field in (
                overview_adjudication.get("evidence_fields") or []
                if isinstance(overview_adjudication, dict)
                else []
            )
            if str(field or "").strip() in lines_by_field
        ]
        if overview_evidence_fields:
            lines = [lines_by_field[field] for field in overview_evidence_fields]
            sources = [
                source
                for field in overview_evidence_fields
                for source in sources_by_field[field]
            ]
        if (
            isinstance(overview_selected_index, int)
            and 0 <= overview_selected_index < len(bundles)
            and (overview_adjudication.get("evidence_fields") or [])
            and bundles[overview_selected_index][0] is not None
        ):
            selected_product = bundles[overview_selected_index][0]
            overview_selected_sku = str(selected_product.sku or "").strip().upper()
            selected_name = str(
                selected_product.product_name_cn
                or selected_product.product_name_en
                or overview_selected_sku
            ).strip()
            overview_choice_line = (
                f"\n结合这些已核验资料，更符合你所述需求的是"
                f"{selected_name}（{overview_selected_sku}）。"
            )
        answer = (
            "按两款商品当前已标注且可直接对照的资料，主要差异如下：\n"
            + "\n".join(lines)
            + overview_choice_line
            if lines
            else "两款商品已锁定，但当前没有找到可同时核验且存在差异的同字段资料；请告诉我更关心容量、重量、材质或使用场景，我会按该字段继续比较。"
        )
        return {
            "intent": "compare_products", "answer_type": "comparison", "answer": answer,
            "results": rows, "result_skus": result_skus, "candidate_skus": result_skus,
            "sources": sources,
            "answer_metadata": {
                "source": "semantic_pairwise_structured_overview_contract",
                "contract_field_types": [],
                "evidence_status": "supported" if lines else "missing",
                "final_choice_sku": overview_selected_sku,
                "semantic_comparison_adjudication": overview_adjudication,
                "evidence_bundle_skus": [bundle.sku for bundle in evidence_bundles],
            },
            "debug": {
                "agent_mode": "semantic_pairwise_structured_overview_contract",
                "field_contract": {"field_type": "comparison_overview", "canonical_fields": [], "source": "validated_semantic_preplan"},
                "entity_resolution_contracts": plan.get("semantic_comparison_entity_contracts"),
            },
            "skip_polish": True,
        }
    if (
        plan.get("semantic_comparison_entity_contracts")
        and semantic_preplan.get("comparison_qa_concepts")
    ):
        # A semantic comparison may combine published fields with a
        # non-column concept. Keep the two evidence classes separate, but
        # bind both to the already sealed participant identities.
        concept_queries = {
            "storage": "收纳方式和便携性",
            "durability": "耐用性",
            "handling": "使用和收纳便利性",
            "suitability": "适用性",
        }
        lines: list[str] = []
        sources: list[dict[str, Any]] = []
        for field in [item for item in semantic_preplan.get("canonical_fields") or [] if customer_field_contract.is_supported_detail_field(str(item or ""))]:
            values: list[tuple[str, str, str, str]] = []
            for product, specs, business, content in bundles:
                value, source = _structured_product_field_evidence(field, db=db, product=product, specs=specs, business=business, content=content)
                if not value:
                    values = []
                    break
                sku = str(product.sku or "").strip().upper()
                name = str(product.product_name_cn or product.product_name_en or sku).strip()
                values.append((sku, name, str(value), str(source or "")))
            if values:
                label = customer_field_contract.product_detail_field_label(field) or field
                lines.append(f"- {label}：" + "；".join(f"{name}（{sku}）为{value}" for sku, name, value, _ in values) + "。")
                sources.extend({"type": "product_field", "sku": sku, "field": field, "source": source, "value": value} for sku, _name, value, source in values)
        for concept in semantic_preplan.get("comparison_qa_concepts") or []:
            query = concept_queries.get(str(concept or ""))
            if not query:
                continue
            values = []
            for product, _specs, _business, _content in bundles:
                qa = await _select_same_sku_product_qa_with_semantic_selection(db, product, raw_question, semantic_query=query, comparison_criterion=query)
                sku = str(product.sku or "").strip().upper()
                name = str(product.product_name_cn or product.product_name_en or sku).strip()
                if qa is None or not str(qa.answer or "").strip():
                    values.append(f"{name}（{sku}）暂无可直接核验的相关资料")
                else:
                    answer = str(qa.answer or "").strip()
                    values.append(f"{name}（{sku}）：{answer}")
                    sources.append({"type": "product_qa", "sku": sku, "source": f"product_qa:{qa.id}", "value": answer})
            if values:
                lines.append("- 收纳与便携：" + "；".join(values) + "。")
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        return {"intent": "compare_products", "answer_type": "comparison", "answer": "按已核验的同 SKU 资料对比：\n" + "\n".join(lines), "results": rows, "result_skus": result_skus, "candidate_skus": result_skus, "sources": sources, "answer_metadata": {"source": "semantic_pairwise_composite_evidence_contract", "evidence_status": "supported" if lines else "missing", "final_choice_sku": None}, "debug": {"agent_mode": "semantic_pairwise_composite_evidence_contract", "entity_resolution_contracts": plan.get("semantic_comparison_entity_contracts")}, "skip_polish": True}
    if (
        plan.get("semantic_comparison_entity_contracts")
        and str(semantic_preplan.get("evidence_kind") or "") == "product_qa"
    ):
        qa_query = str(semantic_preplan.get("qa_evidence_query") or raw_question).strip()
        lines: list[str] = []
        sources: list[dict[str, Any]] = []
        complete = True
        for product, _specs, _business, _content in bundles:
            if product is None:
                complete = False
                continue
            # Pairwise capability comparisons must not use the legacy matcher:
            # it scores answer text, so a generic word such as "camping" in a
            # gifting answer could masquerade as evidence for cooking or water
            # capability. The bounded selector sees only this sealed SKU's QA
            # questions and must reject a merely related record.
            qa = await _select_same_sku_product_qa_with_semantic_selection(
                db,
                product,
                raw_question,
                semantic_query=qa_query,
                comparison_criterion=qa_query,
            )
            sku = str(product.sku or "").strip().upper()
            name = str(product.product_name_cn or product.product_name_en or sku).strip()
            if qa is None or not str(qa.answer or "").strip():
                complete = False
                lines.append(f"- {name}（{sku}）：当前同 SKU 资料未找到可直接比较该能力的产品问答。")
                continue
            value = str(qa.answer or "").strip()
            lines.append(f"- {name}（{sku}）：{value}")
            sources.append({"type": "product_qa", "sku": sku, "source": f"product_qa:{qa.id}", "value": value})
        if not complete and plan.get("must_make_choice"):
            try:
                evidence_packet = _comparison_adjudication_evidence(db=db, bundles=bundles)
            except Exception:
                evidence_packet = {}
            adjudication = (
                await _semantic_comparison_adjudication(
                    db,
                    question=raw_question,
                    evidence_packet=evidence_packet,
                    participant_count=len(bundles),
                )
                if evidence_packet
                else None
            )
            selected_index = (
                adjudication.get("selected_index")
                if isinstance(adjudication, dict)
                else None
            )
            evidence_fields = [
                str(field or "").strip()
                for field in (
                    adjudication.get("evidence_fields") or []
                    if isinstance(adjudication, dict)
                    else []
                )
                if str(field or "").strip() in evidence_packet
            ]
            if evidence_fields:
                structured_lines: list[str] = []
                structured_sources: list[dict[str, Any]] = []
                for field in evidence_fields:
                    label = customer_field_contract.product_detail_field_label(field) or field
                    rendered_values: list[str] = []
                    for evidence_row in evidence_packet[field]:
                        participant_index = int(evidence_row["participant_index"])
                        product = bundles[participant_index][0]
                        if product is None:
                            continue
                        participant_sku = str(product.sku or "").strip().upper()
                        participant_name = str(
                            product.product_name_cn
                            or product.product_name_en
                            or participant_sku
                        ).strip()
                        rendered_values.append(
                            f"{participant_name}（{participant_sku}）为{evidence_row['value']}"
                        )
                        structured_sources.append({
                            "type": "product_field",
                            "sku": participant_sku,
                            "field": field,
                            "source": evidence_row["source"],
                            "value": evidence_row["value"],
                        })
                    if rendered_values:
                        structured_lines.append(
                            f"- {label}：" + "；".join(rendered_values) + "。"
                        )
                selected_sku = None
                if (
                    isinstance(selected_index, int)
                    and 0 <= selected_index < len(bundles)
                    and bundles[selected_index][0] is not None
                ):
                    selected_product = bundles[selected_index][0]
                    selected_sku = str(selected_product.sku or "").strip().upper()
                    selected_name = str(
                        selected_product.product_name_cn
                        or selected_product.product_name_en
                        or selected_sku
                    ).strip()
                    structured_lines.append(
                        f"结合以上已核验资料，更适合你所述需求的是"
                        f"{selected_name}（{selected_sku}）。"
                    )
                else:
                    structured_lines.append(
                        "这些同 SKU 资料可以说明差异，但不足以可靠指定其中一款更适合。"
                    )
                result_skus = [
                    str(row.get("sku") or "").strip().upper()
                    for row in rows
                    if str(row.get("sku") or "").strip()
                ]
                return {
                    "intent": "compare_products",
                    "answer_type": "comparison",
                    "answer": "按与你需求直接相关的已知资料对比：\n" + "\n".join(structured_lines),
                    "results": rows,
                    "result_skus": result_skus,
                    "candidate_skus": result_skus,
                    "sources": structured_sources,
                    "answer_metadata": {
                        "source": "semantic_pairwise_structured_best_effort_contract",
                        "contract_field_types": evidence_fields,
                        "evidence_status": (
                            "supported" if selected_sku else "supported_without_choice"
                        ),
                        "final_choice_sku": selected_sku,
                        "semantic_comparison_adjudication": adjudication,
                        "evidence_bundle_skus": result_skus,
                    },
                    "debug": {
                        "agent_mode": (
                            "semantic_pairwise_structured_best_effort_contract"
                            if selected_sku
                            else "semantic_pairwise_structured_evidence_no_choice"
                        ),
                        "field_contract": {
                            "field_type": "product_qa",
                            "canonical_fields": [],
                            "source": "validated_semantic_preplan",
                        },
                        "entity_resolution_contracts": plan.get(
                            "semantic_comparison_entity_contracts"
                        ),
                    },
                    "skip_polish": True,
                }
        if complete and plan.get("must_make_choice"):
            lines.append("以上为两款商品各自已核验的同 SKU 产品问答；如需我进一步替你做选择，请结合你更看重的火力、重量或收纳条件。")
        elif not complete:
            lines.append("由于至少一款缺少同 SKU 对应资料，当前不能据此指定其中一款更适合。")
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        return {
            "intent": "compare_products", "answer_type": "comparison",
            "answer": "按请求能力对比：\n" + "\n".join(lines), "results": rows,
            "result_skus": result_skus, "candidate_skus": result_skus, "sources": sources,
            "answer_metadata": {"source": "semantic_pairwise_product_qa_contract", "contract_field_type": "product_qa", "evidence_status": "supported" if complete else "missing", "final_choice_sku": None},
            "debug": {"agent_mode": "semantic_pairwise_product_qa_contract" if complete else "semantic_pairwise_product_qa_insufficient", "field_contract": {"field_type": "product_qa", "canonical_fields": ["product_qa"], "source": "validated_semantic_preplan"}, "entity_resolution_contracts": plan.get("semantic_comparison_entity_contracts")},
            "skip_polish": True,
        }
    semantic_requested_fields = list(dict.fromkeys(
        customer_field_contract.semantic_preplan_field_type(field)
        for field in (semantic_preplan.get("canonical_fields") or [])
        if customer_field_contract.semantic_preplan_field_type(field)
    ))
    if (
        plan.get("semantic_comparison_entity_contracts")
        and semantic_requested_fields
        and all(field in {"price", "inventory"} for field in semantic_requested_fields)
    ):
        return _semantic_pairwise_realtime_fields_result(
            rows,
            list(plan.get("semantic_comparison_entity_contracts") or []),
            semantic_requested_fields,
        )
    if (
        plan.get("semantic_comparison_entity_contracts")
        and plan.get("must_make_choice")
        and not list(field_request.get("canonical_fields") or [])
    ):
        return _semantic_pairwise_missing_criterion_result(
            rows,
            list(plan.get("semantic_comparison_entity_contracts") or []),
        )
    requested_comparison_fields = [
        field
        for field in field_request.get("canonical_fields") or []
        if customer_field_contract.is_supported_detail_field(str(field or ""))
    ]
    # The semantic comparison plan has already interpreted the complete
    # sentence. The legacy field parser may retain only one surface field,
    # which would silently drop other customer-requested dimensions before
    # the sealed comparison renderer sees them. Merge only allowlisted fields
    # from that validated semantic plan; identity and values remain bounded by
    # the pairwise EntityResolutionContracts and same-SKU evidence below.
    if plan.get("semantic_comparison_entity_contracts"):
        requested_comparison_fields = list(dict.fromkeys([
            *requested_comparison_fields,
            *[
                field
                for field in (semantic_preplan.get("canonical_fields") or [])
                if customer_field_contract.is_supported_detail_field(str(field or ""))
            ],
        ]))
    # A semantic pairwise decision can carry several formal criteria.  It must
    # never fall through to the legacy capacity/people heuristic merely
    # because it is not a one-field comparison.  Build only sealed same-SKU
    # evidence for every requested criterion; if any one is unavailable, show
    # that gap and decline to pick a winner.
    if (
        plan.get("semantic_comparison_entity_contracts")
        and len(requested_comparison_fields) > 1
    ):
        evidence_packet = _comparison_adjudication_evidence(
            db=db,
            bundles=bundles,
            include_partial=True,
        )
        complete_fields = [
            field
            for field in requested_comparison_fields
            if len(evidence_packet.get(field) or []) == len(bundles)
        ]
        sources: list[dict[str, Any]] = []
        lines: list[str] = []
        for field in requested_comparison_fields:
            label = customer_field_contract.product_detail_field_label(field) or field
            evidence_rows = evidence_packet.get(field) or []
            if len(evidence_rows) != len(bundles):
                values_by_index = {int(item["participant_index"]): item for item in evidence_rows}
                rendered = []
                for index, bundle in enumerate(bundles):
                    product = bundle[0]
                    if product is None:
                        continue
                    sku = str(product.sku or "").strip().upper()
                    name = str(product.product_name_cn or product.product_name_en or sku).strip()
                    item = values_by_index.get(index)
                    if item is None:
                        rendered.append(f"{name}（{sku}）：当前未维护该项资料。")
                        continue
                    rendered.append(f"{name}（{sku}）：{item['value']}。")
                    sources.append({
                        "type": "product_field",
                        "sku": sku,
                        "field": field,
                        "source": item["source"],
                        "value": item["value"],
                    })
                lines.append(f"- {label}：" + " ".join(rendered))
                continue
            values_by_index = {int(item["participant_index"]): item for item in evidence_rows}
            rendered = []
            for index, bundle in enumerate(bundles):
                product = bundle[0]
                item = values_by_index.get(index)
                if product is None or item is None:
                    continue
                sku = str(product.sku or "").strip().upper()
                name = str(product.product_name_cn or product.product_name_en or sku).strip()
                rendered.append(f"{name}（{sku}）：{item['value']}。")
                sources.append({"type": "product_field", "sku": sku, "field": field, "source": item["source"], "value": item["value"]})
            lines.append(f"- {label}：" + " ".join(rendered))
        adjudication = (
            await _semantic_comparison_adjudication(
                db,
                question=str(plan.get("raw_question") or ""),
                evidence_packet=evidence_packet,
                participant_count=len(bundles),
            )
            if plan.get("must_make_choice") and evidence_packet
            else None
        )
        selected_index = adjudication.get("selected_index") if isinstance(adjudication, dict) else None
        selected_sku = (
            str(bundles[selected_index][0].sku or "").strip().upper()
            if isinstance(selected_index, int) and 0 <= selected_index < len(bundles) and bundles[selected_index][0] is not None
            else None
        )
        for field in [
            str(item or "").strip()
            for item in (
                adjudication.get("evidence_fields") or []
                if isinstance(adjudication, dict)
                else []
            )
            if str(item or "").strip() not in requested_comparison_fields
            and str(item or "").strip() in evidence_packet
        ]:
            label = customer_field_contract.product_detail_field_label(field) or field
            rendered = []
            for item in evidence_packet[field]:
                participant_index = int(item["participant_index"])
                product = bundles[participant_index][0]
                if product is None:
                    continue
                sku = str(product.sku or "").strip().upper()
                name = str(product.product_name_cn or product.product_name_en or sku).strip()
                rendered.append(f"{name}（{sku}）：{item['value']}。")
                sources.append({
                    "type": "product_field",
                    "sku": sku,
                    "field": field,
                    "source": item["source"],
                    "value": item["value"],
                })
            if rendered:
                lines.append(f"- 相关依据（{label}）：" + " ".join(rendered))
        if selected_sku:
            selected_product = bundles[int(selected_index)][0]
            selected_name = str(selected_product.product_name_cn or selected_product.product_name_en or selected_sku).strip()
            if len(complete_fields) == len(requested_comparison_fields):
                lines.append(f"基于上述已核验的同 SKU 资料，更适合该需求的是{selected_name}（{selected_sku}）。")
            else:
                lines.append(
                    f"在这两款现有可核验资料范围内，相对更符合该需求的是"
                    f"{selected_name}（{selected_sku}）；未维护的字段仍按未知处理。"
                )
        elif plan.get("must_make_choice"):
            lines.append("由于比较条件的同 SKU 资料不完整，当前不能据此指定其中一款更适合。")
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        return {
            "intent": "compare_products",
            "answer_type": "comparison",
            "answer": ("按请求条件对比：\n" if plan.get("must_make_choice") else "按已知资料对比：\n") + "\n".join(lines),
            "results": rows,
            "result_skus": result_skus,
            "candidate_skus": result_skus,
            "sources": sources,
            "answer_metadata": {
                "source": "semantic_pairwise_compound_evidence_contract",
                "contract_field_types": requested_comparison_fields,
                "evidence_status": (
                    "supported"
                    if len(complete_fields) == len(requested_comparison_fields)
                    else "supported_with_requested_field_gaps"
                    if selected_sku
                    else "missing"
                ),
                "final_choice_sku": selected_sku,
                "semantic_comparison_adjudication": adjudication,
            },
            "debug": {
                "agent_mode": "semantic_pairwise_compound_evidence_contract" if selected_sku else "semantic_pairwise_compound_evidence_insufficient",
                "field_contract": field_request,
                "entity_resolution_contracts": list(plan.get("semantic_comparison_entity_contracts") or []),
            },
            "skip_polish": True,
        }
    if (
        canonical_field
        and len(field_request.get("canonical_fields") or []) == 1
        and customer_field_contract.is_supported_detail_field(canonical_field)
        and (
            str(plan.get("comparison_kind") or "") != "multi_sku_intro"
            or bool(plan.get("semantic_comparison_entity_contracts"))
        )
        # In a compound comparison-plus-choice request, the field comparison
        # is evidence for the decision; it must not preempt the recommendation
        # task that the planner has retained in the same plan.
        and (not plan.get("must_make_choice") or plan.get("semantic_comparison_entity_contracts"))
    ):
        label = customer_field_contract.product_detail_field_label(canonical_field) or canonical_field
        lines = []
        sources: list[dict[str, Any]] = []
        evidence_rows: list[dict[str, Any]] = []
        for product, specs, business, content in bundles:
            if product is None:
                continue
            sku = str(product.sku or "").strip().upper()
            name = str(product.product_name_cn or product.product_name_en or sku).strip()
            value, source = _structured_product_field_evidence(
                canonical_field,
                db=db,
                product=product,
                specs=specs,
                business=business,
                content=content,
            )
            if value:
                lines.append(f"- {name}（{sku}）：{label}为 {value}。")
                sources.append({"type": "product_field", "sku": sku, "field": canonical_field, "source": source, "value": value})
                evidence_rows.append({"sku": sku, "value": value})
            else:
                lines.append(f"- {name}（{sku}）：当前资料未直接标注{label}，不能据此推断。")
        # A one-field comparison decision is only meaningful when that exact
        # contracted field is present for every sealed participant.  Do not
        # let a semantic adjudicator compensate for a missing requested value
        # by selecting on weight, dimensions, or any other adjacent evidence.
        # Those fields can be separately requested in a compound comparison.
        requested_field_complete = len(evidence_rows) == len(bundles)
        adjudication = (
            await _semantic_comparison_adjudication(
                db,
                question=str(plan.get("raw_question") or ""),
                evidence_packet={
                    canonical_field: [
                        {
                            "participant_index": index,
                            "sku": str(product.sku or "").strip().upper(),
                            "value": value,
                            "source": source,
                        }
                        for index, (product, _specs, _business, _content) in enumerate(bundles)
                        for value, source in [_structured_product_field_evidence(
                            canonical_field,
                            db=db,
                            product=product,
                            specs=_specs,
                            business=_business,
                            content=_content,
                        )]
                        if product is not None and value
                    ]
                },
                participant_count=len(bundles),
            )
            if plan.get("must_make_choice") and requested_field_complete
            else None
        )
        chosen_index = adjudication.get("selected_index") if isinstance(adjudication, dict) else None
        chosen_sku = (
            str(bundles[chosen_index][0].sku or "").strip().upper()
            if isinstance(chosen_index, int) and 0 <= chosen_index < len(bundles) and bundles[chosen_index][0] is not None
            else None
        )
        if plan.get("must_make_choice"):
            chosen_name = next(
                (
                    str(product.product_name_cn or product.product_name_en or chosen_sku).strip()
                    for product, _specs, _business, _content in bundles
                    if chosen_sku and str(product.sku or "").strip().upper() == chosen_sku
                ),
                "",
            )
            if chosen_sku and chosen_name:
                used_fields = list(adjudication.get("evidence_fields") or []) if isinstance(adjudication, dict) else []
                for field in used_fields:
                    if field == canonical_field:
                        continue
                    field_label = customer_field_contract.product_detail_field_label(field) or field
                    field_rows = evidence_packet.get(field) or []
                    evidence_lines = []
                    for row in field_rows:
                        product = bundles[int(row["participant_index"])][0]
                        if product is not None:
                            name = str(product.product_name_cn or product.product_name_en or product.sku).strip()
                            sku = str(product.sku or "").strip().upper()
                            evidence_lines.append(f"{name}（{sku}）：{field_label}为 {row['value']}。")
                            sources.append({"type": "product_field", "sku": sku, "field": field, "source": row["source"], "value": row["value"]})
                    if evidence_lines:
                        lines.append(f"选择依据（{field_label}）：" + " ".join(evidence_lines))
                lines.append(f"基于以上同 SKU 已标注资料，更适合该需求的是{chosen_name}（{chosen_sku}）。")
            else:
                lines.append(f"当前同 SKU {label}证据不足或不可直接排序，不能据此指定其中一款更适合。")
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        return {
            "intent": "compare_products",
            "answer_type": "comparison",
            "answer": f"按{label}对比：\n" + "\n".join(lines),
            "results": rows,
            "result_skus": result_skus,
            "candidate_skus": result_skus,
            "sources": sources,
            "answer_metadata": {
                "source": "planner_compare_formal_field_contract",
                "contract_field_type": canonical_field,
                "evidence_status": "supported" if requested_field_complete else "missing",
                "final_choice_sku": chosen_sku,
                "semantic_comparison_adjudication": adjudication,
            },
            "debug": {
                "agent_mode": "planner_compare_formal_field_contract",
                "field_contract": field_request,
                "entity_resolution_contracts": plan.get("semantic_comparison_entity_contracts") or [
                    {
                        "status": "resolved",
                        "resolved_sku": sku,
                        "candidate_skus": [sku],
                        "field_type": canonical_field,
                        "status_reason": "comparison_explicit_product_reference",
                    }
                    for sku in result_skus
                ],
            },
            "skip_polish": True,
        }
    relation_request = "关系" in str(plan.get("raw_question") or "")
    if relation_request:
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        categories = [str(row.get("category") or "").strip() for row in rows]
        common_category = categories[0] if categories and categories[0] and all(value == categories[0] for value in categories) else ""
        lines = []
        sources: list[dict[str, Any]] = []
        for row in rows:
            sku = str(row.get("sku") or "").strip().upper()
            name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
            evidence = _phase1_product_evidence_text(row)
            if evidence:
                lines.append(f"- {name}（{sku}）：{evidence}。")
                sources.append({"type": "product_relation_evidence", "sku": sku, "fields": ["category", "capacity", "body_material", "features", "usage_scenarios"]})
            else:
                lines.append(f"- {name}（{sku}）：当前资料仅能确认其商品身份，未标注更多可用于说明关系的字段。")
        common_statement = (
            f"它们当前都归为{common_category}；"
            if common_category
            else "它们的当前分类资料并不完全一致；"
        )
        return {
            "intent": "compare_products",
            "answer_type": "comparison",
            "answer": (
                f"这{len(rows)}件商品的资料关系如下：{common_statement}"
                "资料没有维护明确的套装从属或组成关系，因此以下仅按每件商品自己的资料说明，不把单品推断为套装组件。\n"
                + "\n".join(lines)
            ),
            "results": rows,
            "result_skus": result_skus,
            "candidate_skus": result_skus,
            "sources": sources,
            "answer_metadata": {
                "source": "planner_compare_explicit_relation",
                "evidence_status": "supported" if sources else "missing",
            },
            "debug": {
                "agent_mode": "planner_compare_explicit_relation",
                "entity_resolution_contracts": [
                    {
                        "status": "resolved",
                        "resolved_sku": sku,
                        "candidate_skus": [sku],
                        "status_reason": "comparison_explicit_product_reference",
                    }
                    for sku in result_skus
                ],
            },
            "skip_polish": True,
        }
    if str(plan.get("comparison_kind") or "") == "multi_sku_intro":
        result_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
        lines = [f"当前识别到 {len(result_skus)} 个不同 SKU：{'、'.join(result_skus)}。"]
        sources: list[dict[str, Any]] = []
        for row in rows:
            sku = str(row.get("sku") or "").strip().upper()
            name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
            evidence = _phase1_product_evidence_text(row)
            lines.append(f"- {name}（{sku}）：{evidence or '当前资料暂未补充更多字段'}。")
            if evidence:
                sources.append({"type": "product_intro_evidence", "sku": sku, "fields": ["category", "capacity", "body_material", "features", "usage_scenarios"]})
        lines.append("当前资料未提供明确差异字段时，我会如实保留相同项，不会把不同 SKU 合并成同一个产品。")
        return {
            "intent": "compare_products",
            "answer_type": "comparison",
            "answer": "\n".join(lines),
            "results": rows,
            "result_skus": result_skus,
            "candidate_skus": result_skus,
            "sources": sources,
            "answer_metadata": {"source": "planner_multi_sku_intro", "evidence_status": "supported" if sources else "missing"},
            "debug": {"agent_mode": "planner_multi_sku_intro"},
            "skip_polish": True,
        }
    first_evidence = _phase1_product_evidence_text(first, max_fields=3)
    second_evidence = _phase1_product_evidence_text(second, max_fields=3)
    requested_people = _phase1_requested_people_count(plan)
    choice = (
        second
        if _phase1_people_fit_score(second, requested_people) >= _phase1_people_fit_score(first, requested_people)
        else first
    )
    choice_name = choice.get("product_name_cn") or choice.get("sku")
    first_label = f"{first_name}（{first.get('sku')}）"
    second_label = f"{second_name}（{second.get('sku')}）"
    answer = (
        f"简单看，{first_label}和{second_label}都能作为候选，区别主要在容量、材质、使用场景和收纳取向。"
        f"{first_label}：{first_evidence or '当前资料未提供足够细项'}。"
        f"{second_label}：{second_evidence or '当前资料未提供足够细项'}。"
    )
    people_selection = bool(plan.get("must_make_choice") and requested_people is not None)
    if plan.get("must_make_choice"):
        people_basis = (
            f"对{requested_people}人的适用人数匹配"
            if requested_people is not None
            else "现有资料里的容量余量和户外吃饭场景"
        )
        answer += (
            f"如果你现在就要做选择，更建议选{choice_name}（{choice.get('sku')}）。"
            f"原因是它在现有资料里{people_basis}更稳妥；如果还要精确判断饭量，仍建议以实际容量和菜量为准。"
        )
    if people_selection:
        answer = (
            f"优先推荐{choice_name}（{choice.get('sku')}），它更匹配{requested_people}人的明确使用范围。\n"
            f"{answer}"
        )
    ordered_rows = [choice, first if choice is second else second] if people_selection else rows
    result_skus = [str(row.get("sku") or "") for row in ordered_rows if row.get("sku")]
    comparison_explanation_requested = bool(re.search(
        r"(?:\u533a\u522b|\u5dee\u5f02|\u4e0d\u540c|\u4f18\u7f3a\u70b9|\u5dee\u522b)",
        str(plan.get("raw_question") or ""),
    ))
    explicit_decision_comparison = bool(re.search(
        r"^\s*(?:\u5bf9\u6bd4|\u6bd4\u8f83)",
        str(plan.get("raw_question") or ""),
    ))
    return {
        # A named-pair question remains a comparison unless the user
        # explicitly frames it as a decision-only comparison. Both paths keep
        # the same sealed pair and same-SKU evidence; only the public response
        # contract differs.
        "intent": "recommendation" if people_selection and explicit_decision_comparison and not comparison_explanation_requested else "compare_products",
        "answer_type": "recommendation" if people_selection and explicit_decision_comparison and not comparison_explanation_requested else "comparison",
        "answer": answer,
        "results": ordered_rows,
        "result_skus": result_skus,
        "candidate_skus": result_skus,
        "answer_metadata": {
            "source": "planner_compare_choice",
            "final_choice_sku": choice.get("sku") if plan.get("must_make_choice") else None,
            "requested_people": requested_people,
        },
        "debug": {"agent_mode": "planner_compare_choice"},
        "skip_polish": True,
    }


def _phase1_requested_people_count(plan: dict) -> int | None:
    text = " ".join(
        str(plan.get(key) or "")
        for key in ("raw_question", "question", "scenario", "semantic_query")
    )
    match = re.search(r"([1-9]\d?)\s*(?:个)?人", text)
    if match:
        return int(match.group(1))
    # Planner scenarios preserve natural Chinese group sizes (for example
    # “两个人吃饱”).  Normalize that shared semantic constraint once here so
    # comparison and recommendation contracts use the same people evidence
    # rather than treating a Chinese numeral as no constraint at all.
    chinese_match = re.search(r"([一二三四五六七八九十两])\s*(?:个)?人", text)
    if not chinese_match:
        return None
    return {
        "一": 1,
        "二": 2,
        "两": 2,
        "三": 3,
        "四": 4,
        "五": 5,
        "六": 6,
        "七": 7,
        "八": 8,
        "九": 9,
        "十": 10,
    }.get(chinese_match.group(1))


def _phase1_people_fit_score(row: dict, requested_people: int | None) -> int:
    text = " ".join(str(row.get(key) or "") for key in ("capacity", "features", "usage_scenarios", "positioning", "long_description_cn"))
    if requested_people is not None:
        score = 0
        for match in re.finditer(r"(\d+)\s*[-－~至]\s*(\d+)\s*(?:个)?人", text):
            lower, upper = int(match.group(1)), int(match.group(2))
            if lower <= requested_people <= upper:
                score = max(score, 100 - abs((lower + upper) / 2 - requested_people))
            else:
                score = min(score, -100)
        for match in re.finditer(r"(?<![-－~至\d])(\d+)\s*(?:个)?人", text):
            if int(match.group(1)) == requested_people:
                score = max(score, 100)
        return score
    return _phase1_two_person_score(row)


def _phase1_two_person_score(row: dict) -> int:
    text = " ".join(str(row.get(key) or "") for key in ("capacity", "features", "usage_scenarios", "positioning", "long_description_cn"))
    score = 0
    for term in ("两人", "两个人", "2人", "2-3人", "双人"):
        if term in text:
            score += 4
    for term in ("1.5L", "1500", "2.0L", "2000", "锅1.5", "锅2."):
        if term in text:
            score += 2
    if "一个人" in text or "单人" in text:
        score -= 2
    return score


def _context_required_ordinal_compare_result(question: str) -> dict:
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "我这边没有看到你前面提到的第一个和第二个产品，请把两个产品名或 SKU 发我，我再帮你比较哪个更适合一个人背。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {"answer_policy": "context_required"},
        "debug": {"agent_mode": "context_required_ordinal_compare"},
        "skip_polish": True,
    }


def _looks_like_context_required_ordinal_compare(question: str) -> bool:
    text = str(question or "")
    return (
        any(term in text for term in ("刚才", "前面", "上面"))
        and any(term in text for term in ("第一个", "第一款"))
        and any(term in text for term in ("第二个", "第二款"))
        and any(term in text for term in ("哪个", "更适合", "比较", "比"))
    )


def _pronoun_heat_source_followup_target_sku(question: str, recommendation_context: dict[str, Any] | None) -> str:
    text = str(question or "")
    if not (
        any(term in text for term in ("它", "这个", "这款", "刚才推荐", "刚才那个", "前面那个"))
        and any(term in text for term in ("酒精炉", "酒精"))
        and any(term in text for term in ("能不能", "能用", "可以用", "可以配", "配", "支持", "是否支持"))
    ):
        return ""
    context = recommendation_context if isinstance(recommendation_context, dict) else {}
    last_referenced_sku = str(context.get("last_referenced_sku") or "").strip().upper()
    if last_referenced_sku:
        return last_referenced_sku
    top_recommended_sku = str(context.get("top_recommended_sku") or "").strip().upper()
    if top_recommended_sku:
        return top_recommended_sku
    for key in ("recommended_skus", "ordered_result_skus", "candidate_skus"):
        for sku in context.get(key) or []:
            value = str(sku or "").strip().upper()
            if value:
                return value
    return ""


def _followup_requested_field(question: str) -> str:
    text = str(question or "")
    if any(term in text for term in ("酒精炉", "酒精", "热源")):
        return "heat_source"
    return customer_agent_planner_service._requested_field(text)


def _ordered_context_skus(*contexts: dict[str, Any] | None) -> list[str]:
    for context in contexts:
        if not isinstance(context, dict):
            continue
        for key in ("ordered_result_skus", "recommended_skus", "candidate_skus"):
            ordered = [
                str(sku or "").strip().upper()
                for sku in context.get(key) or []
                if str(sku or "").strip()
            ]
            if ordered:
                return ordered
    return []


def _ordinal_followup_target_sku(
    question: str,
    recommendation_context: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None,
) -> str:
    text = str(question or "")
    ordered = _ordered_context_skus(recommendation_context, candidate_context)
    if not ordered:
        return ""
    if any(term in text for term in ("最后一个", "最后一款", "最后那个")):
        return ordered[-1]
    mapping = (
        ("第一个", 0),
        ("第一款", 0),
        ("最前面那个", 0),
        ("第二个", 1),
        ("第二款", 1),
        ("第三个", 2),
        ("第三款", 2),
    )
    for token, index in mapping:
        if token in text and index < len(ordered):
            return ordered[index]
    return ""


def _ordinal_followup_target_sku_from_ordered(question: str, ordered_skus: list[str]) -> str:
    ordered = [
        str(sku or "").strip().upper()
        for sku in (ordered_skus or [])
        if str(sku or "").strip()
    ]
    if not ordered:
        return ""
    text = str(question or "")
    ordinal_hits: list[tuple[int, int]] = []
    for token in ("最后一个", "最后一款", "最后那个"):
        position = text.rfind(token)
        if position >= 0:
            ordinal_hits.append((position, len(ordered) - 1))
    mapping = (
        ("第一个", 0),
        ("第一款", 0),
        ("最前面那个", 0),
        ("第二个", 1),
        ("第二款", 1),
        ("第三个", 2),
        ("第三款", 2),
    )
    for token, index in mapping:
        position = text.rfind(token)
        if position >= 0 and index < len(ordered):
            ordinal_hits.append((position, index))
    if ordinal_hits:
        ordinal_hits.sort(key=lambda item: item[0])
        return ordered[ordinal_hits[-1][1]]
    return ""


def _looks_like_ordinal_product_field_followup(question: str) -> bool:
    text = str(question or "")
    return any(term in text for term in ("第一个", "第一款", "最前面那个", "第二个", "第二款", "第三个", "第三款", "最后一个", "最后一款", "最后那个"))


def _product_field_followup_result(
    db: Session,
    sku: str,
    requested_field: str,
    question: str,
    *,
    identity_source: str | None = "explicit_sku_exact",
    field_request_override: dict[str, Any] | None = None,
) -> dict | None:
    if not sku or not requested_field:
        return None
    # A context anchor seals only the product. The current utterance still
    # owns field meaning, so establish its FieldContract before building the
    # legacy-compatible execution plan. Previously the plan could consume a
    # stale display label while the correct contract was attached only after
    # formatting, yielding an answer for a different field than the one shown
    # in debug/evidence metadata.
    field_request = dict(field_request_override or resolve_requested_field_contract(question))
    canonical_field = str(field_request.get("field_type") or "").strip()
    canonical_label = customer_field_contract.product_detail_field_label(canonical_field)
    if canonical_label:
        requested_field = canonical_label
    plan = {
        "primary_intent": "product_field",
        "answer_type": "product_detail",
        "product_ref": sku,
        "sku": sku,
        "requested_field": requested_field,
        "field_only": True,
        "confidence": "high",
        "product_identity_source": identity_source,
        "raw_question": question,
        "tasks": [{"type": "product_field", "product_ref": sku, "requested_field": requested_field}],
    }
    if canonical_field:
        plan["field_type_override"] = canonical_field
    result = _phase1_product_field_result(db, plan)
    if not result:
        return None
    # Context/ordinal follow-ups may supply the canonical SKU outside the raw
    # question (for example, "它多大尺寸？").  The SKU is still a sealed
    # identity, not permission for the legacy product-field shortcut to bypass
    # the central contracts.  Expose the same formal FieldContract and
    # EntityResolutionContract consumed by exact-name/SKU requests before the
    # result is returned.
    canonical_field = canonical_field or None
    product = db.query(Product).filter(Product.sku == str(sku or "").strip().upper()).first()
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["agent_mode"] = "recommendation_context_product_field"
    if canonical_field:
        plan["field_contract"] = dict(field_request)
        debug["field_contract"] = dict(field_request)
    if product is not None:
        canonical_sku = str(product.sku or "").strip().upper()
        entity_text = str(product.product_name_cn or product.product_name_en or canonical_sku).strip()
        entity_contract = customer_entity_resolution_contract.EntityResolutionContract(
            entity_text=entity_text,
            normalized_entity_text=entity_text.casefold(),
            status="resolved",
            resolved_sku=canonical_sku,
            resolver_candidate_skus=[canonical_sku],
            diagnostic_candidate_skus=[],
            candidate_skus=[canonical_sku],
            matched_by=str(identity_source or "context_anchor"),
            confidence="high",
            is_unique=True,
            matched_span=None,
            field_type=canonical_field,
            status_reason="resolved_sealed_context_identity",
        )
        debug["entity_resolution_contract"] = entity_contract.to_dict()
        debug["binding_provenance"] = "resolved_entity_contract"
    result["debug"] = debug
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    if canonical_field:
        metadata["contract_field_type"] = canonical_field
    result["answer_metadata"] = metadata
    return result


async def _active_product_anchor_field_followup_result(
    db: Session,
    question: str,
    recommendation_context: dict[str, Any] | None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict | None:
    text = str(question or "").strip()
    # An explicit current-turn SKU or product name is a new identity signal;
    # it must be resolved by the ordinary EntityResolutionContract before an
    # older pronoun/context anchor can supply identity.
    if _has_explicit_sku_text(text) or _products_named_in_question(db, text):
        return None
    # A plural anaphor refers to the preserved candidate/pair context.  It
    # must never be collapsed onto the last single-product anchor merely
    # because "它们" begins with the singular token "它".
    if _is_plural_heat_source_followup(text):
        return None
    explicit_anchor_terms = ("刚才那个", "刚刚那个", "前面那个", "上一个", "刚才说的那个", "刚才推荐的那个")
    # These are grammatical anaphora, not product aliases.  The anchored SKU
    # remains sealed from the preceding turn, while the current turn must
    # independently form its FieldContract through the normal adapter.
    # Leading discourse particles ("那它…" / "这款…") do not create an
    # identity.  They retain the same grammatical anaphora and therefore use
    # only the sealed active-product anchor below.
    pronoun_anchor = re.search(r"(?:它|这个|这款|该商品|该产品|这个商品|这件商品|本产品)", text) is not None
    semantic_preplan = (
        phase1_plan.get("semantic_preplan")
        if isinstance(phase1_plan, dict) and isinstance(phase1_plan.get("semantic_preplan"), dict)
        else {}
    )
    semantic_context_anchor = str(semantic_preplan.get("context_usage") or "").strip() == "entity_anchor"
    ordinal_reference = _looks_like_ordinal_product_field_followup(text)
    if not any(term in text for term in explicit_anchor_terms) and not pronoun_anchor and not semantic_context_anchor and not ordinal_reference:
        return None
    context = recommendation_context if isinstance(recommendation_context, dict) else {}
    # A replacement list is a second, explicitly labeled discourse target. It
    # does not overwrite the product the user was already discussing: only a
    # new-result anaphor may consume its ordered first candidate.
    replacement_reference = re.match(
        r"^\s*新[^，。！？!?]{0,8}(?:它|这个|这款|该商品|该产品|这个商品|这件商品|本产品)",
        text,
    ) is not None
    ordinal_sku = _ordinal_followup_target_sku(text, context, None) if ordinal_reference else ""
    anchor_sku = str(
        ordinal_sku
        or (
            context.get("replacement_top_sku")
            if replacement_reference and context.get("replacement_top_sku")
            else context.get("active_single_product_anchor")
        )
        or ""
    ).strip().upper()
    if not anchor_sku:
        return None
    field_request = resolve_requested_field_contract(text, phase1_plan)
    semantic_fields = [
        str(field or "").strip()
        for field in (semantic_preplan.get("canonical_fields") or [])
        if customer_field_contract.is_supported_detail_field(str(field or "").strip())
    ]
    semantic_fields = list(dict.fromkeys(semantic_fields))
    if len(semantic_fields) > 1 and _semantic_preplan_confident(semantic_preplan, minimum=0.9):
        # The semantic plan owns the current-turn field set.  A context anchor
        # may provide identity only; it must not collapse a validated
        # multi-field request back to the legacy parser's single display label.
        field_request = {
            **field_request,
            "field_type": "",
            "canonical_fields": semantic_fields,
            "requested_fields": [
                customer_field_contract.product_detail_field_label(field)
                for field in semantic_fields
                if customer_field_contract.product_detail_field_label(field)
            ],
            "source": "validated_semantic_preplan",
        }
    canonical_fields = list(field_request.get("canonical_fields") or [])
    if len(canonical_fields) > 1:
        product = db.query(Product).filter(Product.sku == anchor_sku).first()
        if product is not None:
            entity_text = str(product.product_name_cn or product.product_name_en or anchor_sku).strip()
            entity_contract = customer_entity_resolution_contract.EntityResolutionContract(
                entity_text=entity_text,
                normalized_entity_text=entity_text.casefold(),
                status="resolved",
                resolved_sku=anchor_sku,
                resolver_candidate_skus=[anchor_sku],
                diagnostic_candidate_skus=[],
                candidate_skus=[anchor_sku],
                matched_by="recommendation_context_anchor",
                confidence="high",
                is_unique=True,
                matched_span=None,
                field_type=None,
                status_reason="resolved_sealed_context_identity",
            )
            compound = _build_resolved_compound_evidence_result(
                db,
                question=text,
                entity_contract=entity_contract,
                field_request=field_request,
                phase1_plan=phase1_plan,
            )
            if isinstance(compound, dict):
                return compound
    field_contract = customer_field_contract.detect_field_contract(text)
    detected_fields = customer_field_contract.detect_field_types(text)
    field_type = str(field_request.get("field_type") or "").strip() or (
        field_contract.field_type if field_contract else (
            detected_fields[0] if len(detected_fields) == 1 else None
        )
    )
    if not field_type:
        classified_field = customer_field_contract.classify_product_qa_evidence_type(text)
        field_type = classified_field if classified_field == "usage_scene" else None
    if not field_type:
        # A high-confidence semantic QA follow-up still needs the same sealed
        # product identity.  The preplan owns the field meaning; this adapter
        # only supplies that identity to the bounded same-SKU QA selector.
        if _semantic_prefers_sealed_product_qa(phase1_plan or {}):
            product = db.query(Product).filter(Product.sku == anchor_sku).first()
            if product is not None:
                anchored_question = f"{product.product_name_cn or product.product_name_en or anchor_sku} {text}".strip()
                result = _try_product_qa_shortcut(
                    db,
                    anchored_question,
                    phase1_plan=phase1_plan,
                )
                if _is_sealed_product_qa_safe_missing(result):
                    # The context anchor has already sealed one canonical SKU.
                    # An exact QA miss is not an identity miss: continue only
                    # to the same-SKU knowledge provider before allowing the
                    # caller's deictic fail-closed guard to run.
                    result = await _try_sealed_same_sku_knowledge_answer(
                        db,
                        anchored_question,
                        phase1_plan,
                    ) or result
                if isinstance(result, dict):
                    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
                    debug.update({
                        "agent_mode": "recommendation_context_product_qa",
                        "product_identity_source": "recommendation_context_anchor",
                        "active_single_product_anchor": anchor_sku,
                    })
                    result["debug"] = debug
                    return _attach_recommendation_followup_contract(result, text, context, anchor_sku=anchor_sku)
        return None
    detail_label = (
        "适用场景"
        if field_type == "usage_scene"
        else customer_field_contract.product_detail_field_label(field_type)
    )
    if (
        field_type in {"usage_scene", "accessories"}
        or customer_field_contract.is_supported_detail_field(field_type)
    ) and detail_label:
        result = _product_field_followup_result(
            db,
            anchor_sku,
            detail_label,
            text,
            identity_source="recommendation_context_anchor",
            field_request_override=field_request,
        )
    else:
        product = db.query(Product).filter(Product.sku == anchor_sku).first()
        label = _resolved_entity_unknown_field_guard_label(text)
        if not product or not label:
            return None
        decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
            allowed=True,
            resolved_sku=anchor_sku,
            resolved_product_id=str(product.id),
            reason="resolved_context_anchor",
            match_level="recommendation_context_anchor",
        )
        result = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=label,
            source="recommendation_context_unknown_field",
            resolution_decision=decision,
        )
    if not isinstance(result, dict):
        return None
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug.update({
        "agent_mode": "recommendation_context_product_field",
        "product_identity_source": "recommendation_context_anchor",
        "active_single_product_anchor": anchor_sku,
    })
    # Safe-unsupported fields (manual, warranty, inventory, price, shipping,
    # etc.) use the guarded missing-field formatter above.  They still consume
    # the same sealed context identity and formal field request as supported
    # detail fields; a safe fallback is not a contract exemption.
    if not isinstance(debug.get("field_contract"), dict):
        field_request = field_request if field_request.get("field_type") else resolve_requested_field_contract(
            text,
            phase1_plan or {"requested_field": detail_label or _resolved_entity_unknown_field_guard_label(text)},
        )
        if field_request.get("field_type"):
            debug["field_contract"] = dict(field_request)
    if not isinstance(debug.get("entity_resolution_contract"), dict):
        product = db.query(Product).filter(Product.sku == anchor_sku).first()
        if product is not None:
            entity_text = str(product.product_name_cn or product.product_name_en or anchor_sku).strip()
            entity_contract = customer_entity_resolution_contract.EntityResolutionContract(
                entity_text=entity_text,
                normalized_entity_text=entity_text.casefold(),
                status="resolved",
                resolved_sku=anchor_sku,
                resolver_candidate_skus=[anchor_sku],
                diagnostic_candidate_skus=[],
                candidate_skus=[anchor_sku],
                matched_by="recommendation_context_anchor",
                confidence="high",
                is_unique=True,
                matched_span=None,
                field_type=field_type,
                status_reason="resolved_sealed_context_identity",
            )
            debug["entity_resolution_contract"] = entity_contract.to_dict()
            debug["binding_provenance"] = "resolved_entity_contract"
    result["debug"] = debug
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    metadata["contract_field_type"] = field_type
    result["answer_metadata"] = metadata
    return _attach_recommendation_followup_contract(
        result,
        text,
        context,
        anchor_sku=anchor_sku,
    )


def _ambiguity_candidate_attribute_followup_result(
    db: Session,
    question: str,
    candidate_context: dict[str, Any] | None,
) -> dict | None:
    context = candidate_context if isinstance(candidate_context, dict) else {}
    if context.get("source") != "entity_ambiguity":
        return None
    text = str(question or "").strip()
    if not text or not _is_clarification_followup_product_only_text(text):
        return None
    entity_text = str(context.get("entity_text") or "").strip()
    field_type = str(context.get("field_type") or "").strip()
    if not entity_text or not field_type:
        return None
    products = db.query(Product).order_by(Product.sku.asc()).all()
    selection = _choose_effective_entity_contract(
        f"{entity_text}{text}",
        products,
        override_subject=f"{entity_text}{text}",
    )
    contract = selection.contract
    decision = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
    if not decision.allowed:
        return None
    detail_label = customer_field_contract.product_detail_field_label(field_type)
    if customer_field_contract.is_supported_detail_field(field_type) and detail_label:
        field_contract = next(
            (item for item in customer_field_contract.FIELD_CONTRACTS if item.field_type == field_type),
            None,
        )
        if field_contract is None:
            return None
        result = _build_phase2_entity_state_response(
            db,
            text,
            {
                "action": "resolved_detail",
                "contract": contract,
                "products": products,
                "field": field_contract,
                "requested_field": detail_label,
            },
        )
    else:
        product = next(
            (product for product in products if str(product.sku or "").strip().upper() == decision.resolved_sku),
            None,
        )
        label = customer_field_contract.product_detail_field_label(field_type)
        if not product or not label:
            return None
        result = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=label,
            source="candidate_context_variant_refinement",
            resolution_decision=decision,
        )
    if not isinstance(result, dict):
        return None
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug.update({
        "agent_mode": "candidate_context_variant_refinement",
        "entity_resolution_contract": contract.to_dict(),
    })
    result["debug"] = debug
    return result


def _product_heat_source_followup_result(db: Session, question: str, sku: str) -> dict | None:
    result = _product_field_followup_result(
        db,
        sku,
        "heat_source",
        question,
        identity_source="recommendation_context_anchor",
    )
    if isinstance(result, dict):
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["agent_mode"] = "recommendation_context_product_compatibility"
        result["debug"] = debug
    return result


async def _explicit_multi_product_compatibility_contract_result(
    db: Session,
    question: str,
) -> dict | None:
    """Seal explicit co-use requests before any single-product context route."""
    if not customer_agent_intent_service._looks_like_product_compatibility_question(question):
        return None
    named_products = _products_named_in_question(db, question)
    if len(named_products) < 2:
        return None
    result = await customer_agent_intent_service._explicit_product_compatibility_result(db, question)
    if not isinstance(result, dict):
        return None
    result_skus = [
        str(row.get("sku") or "").strip().upper()
        for row in result.get("results") or []
        if isinstance(row, dict) and str(row.get("sku") or "").strip()
    ]
    named_by_sku = {
        str(product.sku or "").strip().upper(): product
        for product in named_products
        if str(product.sku or "").strip()
    }
    if len(result_skus) < 2 or not set(result_skus).issubset(set(named_by_sku)):
        return None
    field_request = customer_field_contract.resolve_requested_field_contract(
        question,
        compatibility_fields=["heat_source"],
    )
    if str(field_request.get("field_type") or "") != "heat_source":
        return None
    entity_contracts = []
    for sku in result_skus:
        product = named_by_sku[sku]
        entity_text = str(product.product_name_cn or product.product_name_en or sku).strip()
        entity_contracts.append(
            customer_entity_resolution_contract.EntityResolutionContract(
                entity_text=entity_text,
                normalized_entity_text=entity_text.casefold(),
                status="resolved",
                resolved_sku=sku,
                resolver_candidate_skus=[sku],
                diagnostic_candidate_skus=[],
                candidate_skus=[sku],
                matched_by="explicit_current_turn_multi_entity",
                confidence="high",
                is_unique=True,
                matched_span=None,
                field_type="heat_source",
                status_reason="resolved_exact_multi_entity_compatibility",
            ).to_dict()
        )
    debug = dict(result.get("debug") or {})
    debug.update(
        {
            "agent_mode": "explicit_multi_entity_compatibility_contract",
            "field_contract": dict(field_request),
            "entity_resolution_contracts": entity_contracts,
            "binding_provenance": "explicit_current_turn_multi_entity",
        }
    )
    result["debug"] = debug
    metadata = dict(result.get("answer_metadata") or {})
    metadata.update(
        {
            "contract_field_type": "heat_source",
            "evidence_skus": result_skus,
            "entity_resolution_contracts": entity_contracts,
        }
    )
    result["answer_metadata"] = metadata
    return result


def _recommendation_context_turn(context: dict[str, Any] | None) -> int:
    values = (context or {}).get("contract_merge_provenance") or {}
    turns = [
        int(item.get("source_turn") or 0)
        for item in values.values()
        if isinstance(item, dict)
    ]
    return max(turns or [1]) + 1


def _attach_recommendation_followup_contract(
    result: dict | None,
    question: str,
    recommendation_context: dict[str, Any] | None,
    *,
    anchor_sku: str | None = None,
) -> dict | None:
    if not isinstance(result, dict) or not isinstance(recommendation_context, dict):
        return result
    inherited_data = (
        recommendation_context.get("effective_recommendation_contract")
        or recommendation_context.get("recommendation_request_contract")
    )
    if not isinstance(inherited_data, dict):
        return result
    inherited = customer_recommendation_verification_contract.RecommendationRequestContract.from_dict(inherited_data)
    current = customer_recommendation_verification_contract.build_recommendation_request_contract(question)
    effective, provenance = customer_recommendation_verification_contract.merge_recommendation_request_contracts(
        inherited,
        current,
        previous_result_skus=list(recommendation_context.get("previous_result_skus") or []),
        anchor_sku=anchor_sku,
        current_turn=_recommendation_context_turn(recommendation_context),
    )
    metadata = dict(result.get("answer_metadata") or {})
    metadata.update(
        {
            "current_recommendation_contract": current.to_dict(),
            "inherited_recommendation_contract": inherited.to_dict(),
            "effective_recommendation_contract": effective.to_dict(),
            "contract_merge_provenance": provenance,
        }
    )
    result["answer_metadata"] = metadata
    return result


def _alternative_recommendation_followup_result(
    db: Session,
    question: str,
    recommendation_context: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None,
) -> dict | None:
    # A replacement must search the preserved candidate domain, while the
    # recommendation context still supplies the single SKU to exclude.
    ordered = _ordered_context_skus(candidate_context, recommendation_context)
    context = recommendation_context if isinstance(recommendation_context, dict) else {}
    inherited_data = context.get("effective_recommendation_contract") or context.get("recommendation_request_contract")
    if not isinstance(inherited_data, dict):
        return None
    inherited = customer_recommendation_verification_contract.RecommendationRequestContract.from_dict(inherited_data)
    anchor_sku = str(
        context.get("last_referenced_sku")
        or context.get("top_recommended_sku")
        or (ordered[0] if ordered else "")
    ).strip().upper()
    # A prior “recommend one” result has a one-SKU visible set, but that is
    # not a sealed one-product universe.  For an alternative, rebuild the
    # domain from the inherited request contract, then verify and exclude the
    # anchor; never silently re-return the same product.
    if len(ordered) < 2:
        subject_category = str(inherited.subject_category or "").strip()
        catalog_rows = _phase1_catalog_rows(db, "产品")
        if subject_category:
            catalog_rows = [
                row for row in catalog_rows
                if str(row.get("category") or "").strip() == subject_category
            ]
        ordered = [
            anchor_sku,
            *[
                str(row.get("sku") or "").strip().upper()
                for row in catalog_rows
                if str(row.get("sku") or "").strip().upper()
                and str(row.get("sku") or "").strip().upper() != anchor_sku
            ],
        ]
    alternative_skus = [sku for sku in ordered if sku and sku != anchor_sku]
    if not alternative_skus:
        alternative_skus = ordered[1:]
    if not alternative_skus:
        return None

    products = db.query(Product).filter(Product.sku.in_(alternative_skus)).all()
    by_sku = {str(product.sku or "").strip().upper(): product for product in products}
    rows: list[dict] = []
    for sku in alternative_skus:
        product = by_sku.get(sku)
        if not product:
            continue
        specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == product.id).first()
        business = db.query(ProductBusiness).filter(ProductBusiness.product_id == product.id).first()
        content = db.query(ProductContent).filter(ProductContent.product_id == product.id).first()
        rows.append(_product_row_from_model(product, specs, business, content))
    if not rows:
        return None

    current = customer_recommendation_verification_contract.build_recommendation_request_contract(question)
    effective, provenance = customer_recommendation_verification_contract.merge_recommendation_request_contracts(
        inherited,
        current,
        previous_result_skus=ordered,
        anchor_sku=anchor_sku,
        current_turn=_recommendation_context_turn(context),
    )
    verifications = customer_recommendation_verification_contract.verify_recommendation_candidates(effective, rows)
    selected = customer_recommendation_verification_contract.select_recommendation_candidates(rows, verifications)[:3]
    answer = customer_recommendation_verification_contract.build_verified_recommendation_answer(
        effective,
        selected,
        verifications,
    )
    if effective.relative_price_preference:
        answer = (
            "现有资料没有可靠价格信息，无法验证是否比上一款更便宜。"
            "以下候选仅按已继承的其他条件重新核验，并已排除上一款。\n" + answer
        )

    result_skus = [str(row.get("sku") or "").strip().upper() for row in selected if str(row.get("sku") or "").strip()]
    result = {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": selected,
        "result_skus": result_skus,
        "candidate_skus": result_skus,
        "debug": {
            "agent_mode": "recommendation_context_alternative_followup",
            "initial_candidate_skus": [str(row.get("sku") or "").strip().upper() for row in rows],
            "fully_verified_candidates": [item.to_dict() for item in verifications if item.verification_level == "fully_verified"],
            "partially_verified_candidates": [item.to_dict() for item in verifications if item.verification_level == "partially_verified"],
            "rejected_candidates": [item.to_dict() for item in verifications if item.verification_level == "rejected"],
        },
        "answer_metadata": {
            "source": "recommendation_context_alternative_followup",
            "current_recommendation_contract": current.to_dict(),
            "inherited_recommendation_contract": inherited.to_dict(),
            "effective_recommendation_contract": effective.to_dict(),
            "contract_merge_provenance": provenance,
        },
        "skip_polish": True,
    }
    return result


def _recommendation_explanation_followup_result(
    db: Session,
    question: str,
    recommendation_context: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None = None,
) -> dict | None:
    text = str(question or "")
    explanation_terms = (
        "为什么推荐",
        "推荐理由",
        "理由是什么",
        "解释一下为什么",
        "为什么选",
        "为什么是第一个",
        "推荐依据",
    )
    if not any(term in text for term in explanation_terms):
        return None
    context = recommendation_context if isinstance(recommendation_context, dict) else {}
    candidate_scope = candidate_context if isinstance(candidate_context, dict) else {}
    ordered = [
        str(sku or "").strip().upper()
        for sku in (context.get("ordered_result_skus") or context.get("recommended_skus") or [])
        if str(sku or "").strip()
    ]
    # “这些产品 / 它们” refers to the product set visibly returned in the
    # preceding answer.  Recommendation contexts may retain only the top
    # recommendation, while candidate context preserves that displayed set.
    # Use the latter only for an explicitly plural explanation; singular
    # follow-ups still explain the recommendation anchor.
    plural_explanation = any(term in text for term in ("这些", "它们", "这几款", "前面推荐的"))
    candidate_ordered = [
        str(sku or "").strip().upper()
        for sku in (candidate_scope.get("ordered_result_skus") or candidate_scope.get("candidate_skus") or [])
        if str(sku or "").strip()
    ]
    if plural_explanation and len(candidate_ordered) >= 2:
        ordered = candidate_ordered
    anchor_sku = str(
        context.get("last_referenced_sku")
        or context.get("top_recommended_sku")
        or (ordered[0] if ordered else "")
    ).strip().upper()
    if not anchor_sku or anchor_sku not in ordered:
        return None
    rows_by_sku = {
        str(item.get("sku") or "").strip().upper(): item
        for item in _phase1_catalog_rows(db, "产品")
        if str(item.get("sku") or "").strip()
    }
    rows = [rows_by_sku[sku] for sku in ordered if isinstance(rows_by_sku.get(sku), dict)]
    if not rows:
        return None
    def explanation_reason(row: dict[str, Any]) -> str:
        reason_parts: list[str] = []
        for key in ("usage_scenarios", "features"):
            value = row.get(key)
            value_text = _compound_display_value(value)
            if value_text and value_text not in reason_parts:
                reason_parts.append(value_text)
        return "；".join(reason_parts[:2]) or "它符合上一轮已核验的推荐条件"
    if plural_explanation and len(rows) >= 2:
        answer = "推荐这些产品的依据：\n" + "\n".join(
            f"- {str(row.get('product_name_cn') or row.get('product_name') or row.get('sku') or '').strip()}（{str(row.get('sku') or '').strip().upper()}）：{explanation_reason(row)}。"
            for row in rows
        )
    else:
        row = next((item for item in rows if str(item.get("sku") or "").strip().upper() == anchor_sku), rows[0])
        product_name = str(row.get("product_name_cn") or row.get("product_name") or anchor_sku).strip()
        answer = f"推荐 {product_name}（{anchor_sku}）的依据是：{explanation_reason(row)}。"
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": rows if plural_explanation and len(rows) >= 2 else [row],
        "candidate_skus": [str(item.get("sku") or "").strip().upper() for item in rows] if plural_explanation and len(rows) >= 2 else [anchor_sku],
        "result_skus": [str(item.get("sku") or "").strip().upper() for item in rows] if plural_explanation and len(rows) >= 2 else [anchor_sku],
        "debug": {"agent_mode": "recommendation_context_explanation_followup"},
        "answer_metadata": {"source": "recommendation_context_explanation_followup"},
        "skip_polish": True,
    }


def _context_skus_for_pair_followup(*contexts: dict[str, Any] | None) -> list[str]:
    for context in contexts:
        if not isinstance(context, dict):
            continue
        for key in ("pair_skus", "ordered_result_skus", "recommended_skus", "candidate_skus"):
            skus = [
                str(sku or "").strip().upper()
                for sku in context.get(key) or []
                if str(sku or "").strip()
            ]
            if len(skus) >= 2:
                return skus[:2]
    return []


def _context_pair_followup_result(db: Session, question: str, skus: list[str]) -> dict | None:
    pair = [str(sku or "").strip().upper() for sku in skus[:2] if str(sku or "").strip()]
    if len(pair) < 2:
        return None
    products = (
        db.query(Product)
        .filter(Product.sku.in_(pair))
        .all()
    )
    by_sku = {str(product.sku or "").strip().upper(): product for product in products}
    rows: list[dict] = []
    for sku in pair:
        product = by_sku.get(sku)
        if not product:
            continue
        specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == product.id).first()
        business = db.query(ProductBusiness).filter(ProductBusiness.product_id == product.id).first()
        content = db.query(ProductContent).filter(ProductContent.product_id == product.id).first()
        rows.append(_product_row_from_model(product, specs, business, content))
    if len(rows) < 2:
        return None
    text = str(question or "")
    if any(term in text for term in ("酒精炉", "酒精")) and any(term in text for term in ("它们", "这两个", "两款", "两个")):
        lines = []
        for row in rows:
            answer, _ = _phase1_alcohol_stove_compatibility_answer(db, row)
            lines.append(f"- {answer}")
        answer = "分别看这两个产品的酒精炉兼容性：\n" + "\n".join(lines)
        answer_type = "product_detail"
        intent = "product_detail"
        agent_mode = "context_pair_product_compatibility"
    else:
        first, second = rows[0], rows[1]
        first_name = first.get("product_name_cn") or first.get("sku")
        second_name = second.get("product_name_cn") or second.get("sku")
        first_evidence = _phase1_product_evidence_text(first)
        second_evidence = _phase1_product_evidence_text(second)
        weight_comparison = any(term in text for term in ("重量", "多重", "重吗", "更重", "更轻", "轻吗"))
        first_weight = first.get("gross_weight_g")
        second_weight = second.get("gross_weight_g")
        missing_weight = [
            name for name, value in ((first_name, first_weight), (second_name, second_weight))
            if value in (None, "", 0)
        ]
        if weight_comparison and missing_weight:
            answer = (
                f"你前面提到的第一个是{first_name}（{first.get('sku')}），第二个是{second_name}（{second.get('sku')}）。"
                f"{ '、'.join(missing_weight) }\u7f3a\u5c11\u660e\u786e\u91cd\u91cf\u8d44\u6599\uff0c\u56e0\u6b64\u65e0\u6cd5\u51c6\u786e\u6bd4\u8f83\uff0c\u4e5f\u65e0\u6cd5\u51c6\u786e\u5224\u65ad\u8c01\u66f4\u91cd\u6216\u66f4\u8f7b\uff1b\u4e0d\u80fd\u6839\u636e\u5bb9\u91cf\u3001\u6750\u8d28\u6216\u573a\u666f\u63a8\u65ad\u91cd\u91cf\u3002"
            )
        elif weight_comparison:
            relation = "更重" if float(second_weight) > float(first_weight) else "更轻" if float(second_weight) < float(first_weight) else "重量相同"
            answer = (
                f"你前面提到的第一个是{first_name}（{first.get('sku')}，重量：{first_weight}g），"
                f"第二个是{second_name}（{second.get('sku')}，重量：{second_weight}g）。"
                f"第二个相对第一个{relation}。"
            )
        else:
            choice = second if _phase1_two_person_score(second) >= _phase1_two_person_score(first) else first
            answer = (
                f"你前面提到的第一个是{first_name}（{first.get('sku')}），第二个是{second_name}（{second.get('sku')}）。"
                f"{first_name}：{first_evidence or '当前资料未提供足够细项'}。"
                f"{second_name}：{second_evidence or '当前资料未提供足够细项'}。"
                f"如果更在意新手使用/一个人背，建议优先看{choice.get('product_name_cn') or choice.get('sku')}（{choice.get('sku')}），并结合实际重量和收纳体积确认。"
            )
        answer_type = "comparison"
        intent = "compare_products"
        agent_mode = "context_pair_comparison_followup"
    skus_out = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
    return {
        "intent": intent,
        "answer_type": answer_type,
        "answer": answer,
        "results": rows,
        "result_skus": skus_out,
        "candidate_skus": skus_out,
        "answer_metadata": {"source": agent_mode},
        "debug": {
            "agent_mode": agent_mode,
            "raw_results": rows,
            "candidate_skus": skus_out,
            "plan": {
                "primary_intent": intent,
                "answer_type": answer_type,
                "product_refs": skus_out,
                "product_ref": " / ".join(skus_out),
                "requested_field": "heat_source" if answer_type == "product_detail" else "",
                "source": "context_pair_followup",
            },
        },
        "skip_polish": True,
    }


def _is_plural_heat_source_followup(question: str) -> bool:
    text = str(question or "")
    return (
        any(term in text for term in ("它们", "这两个", "上面两个", "这几款", "两款", "两个"))
        and any(term in text for term in ("酒精炉", "酒精", "热源"))
        and any(term in text for term in ("能不能", "能用", "可以用", "支持", "是否支持"))
    )


def _phase1_result_skus(agent_result: dict) -> list[str]:
    skus = []
    for key in ("result_skus", "candidate_skus"):
        for sku in agent_result.get(key) or []:
            text = str(sku or "").strip()
            if text and text not in skus:
                skus.append(text)
    for row in agent_result.get("results") or []:
        if isinstance(row, dict):
            sku = str(row.get("sku") or "").strip()
            if sku and sku not in skus:
                skus.append(sku)
    return skus


def _phase1_answer_mentions_product(agent_result: dict) -> bool:
    answer = str(agent_result.get("answer") or "")
    if re.search(r"\b[A-Z]{1,6}-[A-Z0-9][A-Z0-9-]{1,40}\b", answer):
        return True
    return any(term in answer for term in ("单锅", "套锅", "锅具", "烤盘", "水壶", "行山", "激川"))


def _phase1_explicit_recommendation_scope_ref(question: str) -> str:
    text = str(question or "").strip()
    if not text:
        return ""
    # A category mentioned in a comparison is one side of the trade-off, not
    # a hard recommendation scope.  Keep both catalog pools available so the
    # dedicated comparison route can evaluate them.
    if (
        customer_agent_planner_service._is_compare_question(text)
        or customer_agent_planner_service._is_compare_choice_question(text)
        or customer_agent_intent_service._is_compare_question(text)
        or _phase1_is_griddle_vs_cookware_scenario(text)
        or "还是" in text
    ):
        return ""
    ref = _semantic_catalog_product_ref(text)
    if ref in {"炉具", "锅具", "烤盘", "水壶", "水具", "咖啡器具", "茶具", "配件", "餐具", "桌椅"}:
        return ref
    return ""


def _looks_like_product_capability_or_field_question(text: str) -> bool:
    return bool(_explicit_sku_detail_requested_fields(text)) or _looks_like_product_detail_field_question(text)


def _is_generic_field_subject(subject: str) -> bool:
    value = re.sub(r"(?:一般|通常)$", "", str(subject or "").strip())
    return value in {"烤盘", "煎盘", "锅", "锅具", "水壶", "水杯", "杯子", "炉具", "炉子", "配件"}


def _is_generic_company_product_scope(subject: str) -> bool:
    value = re.sub(r"\s+", "", str(subject or "")).strip()
    return bool(re.fullmatch(r"(?:你们|我们|咱们|本店|你家|品牌|公司)(?:的)?(?:产品|商品|货品)", value))


def _entity_scope_pre_route_guard_result(
    db: Session,
    question: str,
    phase1_plan: dict | None,
    semantic_preplan: dict | None,
) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    # Semantic product-QA already has a dedicated sealed path below the
    # shortcut layer.  Its entity contract can use a unique canonical name
    # from the full turn before bounded same-SKU QA/KB retrieval.  This broad
    # scope guard is for catalogue/recommendation ambiguity and must not
    # return a clarification first merely because the semantic subject span
    # includes part of the predicate.
    if _semantic_prefers_sealed_product_qa(phase1_plan or {}):
        return None
    # A formal FieldContract must still reach Phase 2, where the
    # EntityResolutionContract records the unresolved identity.  The semantic
    # scope guard below is only a pre-recommendation safety veto for turns
    # that have no formal field contract at all.
    formal_field_contract = customer_field_contract.resolve_requested_field_contract(
        text,
        {"semantic_preplan": semantic_preplan or {}},
    )
    semantic_entity_scope = _semantic_preplan_entity_scope(semantic_preplan)
    semantic_fields = list(formal_field_contract.get("canonical_fields") or [])
    unsupported_semantic_field = bool(semantic_fields) and not all(
        customer_field_contract.is_supported_detail_field(field) for field in semantic_fields
    )
    if (
        (not semantic_fields or unsupported_semantic_field)
        and _semantic_preplan_route_family(semantic_preplan) == "recommendation"
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and semantic_entity_scope in {"unresolved_product_like", "unresolved_product", "negative_product_like", "negative_product"}
    ):
        semantic_subjects = [
            str(item or "").strip()
            for item in ((semantic_preplan or {}).get("entities") or [])
            if str(item or "").strip()
        ]
        subject = semantic_subjects[0] if semantic_subjects else _product_like_scope_subject(text)
        label = (
            _resolved_entity_realtime_commercial_field_guard_label(text)
            or _detect_unknown_product_fact_label(text)
            or str((semantic_preplan or {}).get("field_hint") or "相关")
        )
        unresolved = _build_unresolved_product_like_unknown_field_clarification_result(
            text,
            label=label,
            subject_override=subject,
        )
        # A semantic unresolved-product scope is itself a sealed safety fact.
        # The optional lexical subject extractor may not isolate a clean span
        # from every natural phrasing (for example a product-like name followed
        # immediately by a commercial question).  Do not let that extraction
        # limitation hand the turn to a catalogue-wide recommendation route.
        # The generic clarification preserves the semantic identity verdict
        # without inventing a subject, SKU, or field value.
        return unresolved or _generic_unresolved_product_like_unknown_field_clarification_result(
            text,
            label=label,
            subject_override=subject,
        )
    # A formal FieldContract owns the field meaning.  This legacy scope guard
    # may still protect genuinely unclassified product-like text, but it must
    # not consume a supported or safely-unsupported field before the central
    # EntityResolutionContract gets the chance to seal an exact identity.
    # Identity ambiguity remains fail-closed downstream; this only removes an
    # obsolete pre-contract shortcut.
    # A lexical alias is not enough to prove that its surrounding text is a
    # real field predicate: a product-like name can itself contain words such
    # as “品牌”.  Keep an unresolved product-like scope in entity arbitration
    # even when a FieldContract candidate exists, so it cannot fall through to
    # catalogue recommendation before the name has been rejected.
    if formal_field_contract.get("canonical_fields") and not _has_unresolved_product_like_scope(db, text):
        return None
    # Interrogative catalogue subjects are not concrete product identities.
    # Let query/recommendation routing own them rather than producing a
    # single-product clarification before the executor runs.
    if re.match(r"^(?:哪种|哪款|哪些|什么|有哪|有没有)", text):
        return None
    if _looks_like_ordinal_product_field_followup(text):
        return None
    category_contract = phase1_plan if isinstance(phase1_plan, dict) else {}
    if (
        str(category_contract.get("primary_intent") or "") == "category_compatibility"
        and bool(category_contract.get("must_stay_within_category"))
        and str(category_contract.get("category_ref") or "").strip()
    ):
        return None
    # A planner-confirmed catalogue aggregation has no single-product
    # identity to arbitrate.  Keep it on the structured count/list contract
    # before the product-scope guard can mistake its category noun for a
    # missing product name.
    if (
        str(category_contract.get("primary_intent") or "") == "catalog_count"
        and _looks_like_semantic_catalog_query(text)
        and not _contains_explicit_negative_product_marker(text)
    ):
        return None
    # A planner-confirmed recommendation contract describes a candidate set,
    # even when it contains negative product constraints such as excluding a
    # two-person option.  It is not a request to resolve that constraint as a
    # single product identity.  Let the recommendation executor filter the
    # catalogue; explicit named-product facts continue through the entity
    # contract below.
    if (
        str(category_contract.get("primary_intent") or "") == "recommendation"
        and not _products_named_in_question(db, text)
        and not _has_unresolved_product_like_scope(db, text)
    ):
        return None
    # A planner-confirmed comparison is a multi-entity operation, not a
    # request to collapse the whole phrase into one product identity.  Let the
    # comparison executor resolve every named participant and make its sealed
    # decision; the single-entity guard below is intentionally inapplicable.
    if (
        str(category_contract.get("primary_intent") or "") in {"comparison", "product_compare_recommendation"}
        or bool(category_contract.get("must_compare_both_products"))
    ):
        return None
    # A formal field does not prove a product reference.  Keep unresolved
    # product-like requests in entity arbitration so price/manual/shipping and
    # other formal fields cannot bypass the sealed-identity requirement.
    if customer_agent_service._extract_skus(text):
        return None
    if customer_agent_intent_service._looks_like_multi_product_relation_question(text):
        return None
    # Commercial/realtime fields are never safe to answer from a fuzzy name
    # recall. Establish the same strong-identity threshold before semantic
    # category hints or generic fallbacks can consume the request.
    early_subject = _product_like_scope_subject(text) or customer_agent_intent_service._detail_subject_from_question(text).strip()
    early_unknown_label = (
        _resolved_entity_realtime_commercial_field_guard_label(text)
        or _detect_unknown_product_fact_label(text)
    )


    if early_unknown_label and early_subject and _looks_like_product_like_scope_subject(early_subject):
        early_candidates = _products_named_in_question(db, text)
        if not any(_subject_strongly_matches_product(early_subject, product) for product in early_candidates):
            unresolved = _build_unresolved_product_like_unknown_field_clarification_result(
                text,
                label=early_unknown_label,
                subject_override=early_subject,
            )
            if unresolved:
                return unresolved
            return _build_unknown_field_product_not_found_result(
                text,
                label=early_unknown_label,
                subject_override=early_subject,
            )
    if _contains_explicit_negative_product_marker(text):
        subject = customer_field_contract.select_entity_subject_for_routing(
            raw_question=text,
            fallback_product_like_subject=_product_like_scope_subject(text),
            fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(text).strip(),
        ).entity_subject
        unknown_label = (
            _resolved_entity_realtime_commercial_field_guard_label(text)
            or _detect_unknown_product_fact_label(text)
        )
        if _looks_like_recommendation_request(text):
            return {
                "intent": "clarify",
                "answer_type": "clarification",
                "answer": f"没有找到“{subject or '该商品'}”对应的产品资料，请确认商品名或提供 SKU。",
                "results": [],
                "result_skus": [],
                "candidate_skus": [],
                "needs_clarification": True,
                "answer_metadata": {"source": "unknown_field_product_not_found", "evidence_status": "product_not_found"},
                "debug": {"agent_mode": "entity_scope_product_not_found"},
                "skip_polish": True,
            }
        if unknown_label:
            unresolved = _build_unresolved_product_like_unknown_field_clarification_result(
                text,
                label=unknown_label,
                subject_override=subject,
            )
            if unresolved:
                return unresolved
            return _build_unknown_field_product_not_found_result(text, label=unknown_label, subject_override=subject)
    route_family_hint = _semantic_preplan_route_family(semantic_preplan)
    entity_scope_hint = _semantic_preplan_entity_scope(semantic_preplan)
    if (
        _semantic_preplan_confident(semantic_preplan)
        and route_family_hint in {"structured_query", "recommendation", "generic_query"}
        and entity_scope_hint in {"category_scope", "generic_scope"}
        and not _has_unresolved_product_like_scope(db, text)
    ):
        return None
    if (
        route_family_hint not in {"unresolved_product_like", "negative_product_like"}
        and entity_scope_hint not in {
            "unresolved_product",
            "negative_product",
            "unresolved_product_like",
            "negative_product_like",
        }
        and _structured_hard_filter_contract(text)
    ):
        return None

    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=text,
        fallback_product_like_subject=_product_like_scope_subject(text),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(text).strip(),
    )
    extracted_subject = subject_selection.entity_subject
    subject = extracted_subject or ("" if subject_selection.source == "field_contract" else text)
    if (
        customer_field_contract.is_field_contract_predicate_signal(subject_selection)
        and _is_generic_field_subject(extracted_subject)
    ):
        generic_subject = re.sub(r"(?:一般|通常)$", "", extracted_subject).strip()
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"“{generic_subject}”是商品类目，还不能对应到具体商品。请提供完整商品名或 SKU。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "needs_clarification": True,
            "answer_metadata": {"source": "entity_scope_generic_clarification", "evidence_status": "generic_product"},
            "debug": {"agent_mode": "entity_scope_generic_clarification"},
            "skip_polish": True,
        }
    unresolved_scope = _has_unresolved_product_like_scope(db, text)
    subject_product_like = (
        (bool(extracted_subject) and _looks_like_product_like_scope_subject(extracted_subject))
        or unresolved_scope
        or _contains_explicit_negative_product_marker(text)
    )
    if not subject_product_like:
        return None
    if _looks_like_generic_constraint_category_query(text):
        return None

    named_products = _products_named_in_question(db, text)
    if extracted_subject and named_products:
        all_products = db.query(Product).order_by(Product.sku.asc()).all()
        entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            text,
            all_products,
            resolver_candidates=named_products,
            entity_text_override=extracted_subject,
        )
        entity_decision = customer_entity_resolution_contract.can_resolve_single_product(
            entity_contract,
            all_products,
        )
        if entity_decision.allowed:
            return None
    if (
        subject
        and named_products
        and _looks_like_unresolved_product_like_question(text)
        and not customer_agent_intent_service._looks_like_contents_grounding_question(text)
    ):
        strong_named_products = [product for product in named_products if _subject_strongly_matches_product(subject, product)]
        if strong_named_products:
            named_products = strong_named_products
        else:
            named_products = []
    unknown_label = (
        _resolved_entity_realtime_commercial_field_guard_label(text)
        or _detect_unknown_product_fact_label(text)
    )
    unresolved_named_product_question = bool(
        unresolved_scope
        and _product_like_scope_subject(text)
    )
    product_bound_question = bool(
        unknown_label
        or unresolved_named_product_question
        or customer_agent_intent_service._looks_like_contents_grounding_question(text)
        or customer_agent_intent_service._looks_like_usage_care_question(text)
        or _looks_like_product_capability_or_field_question(text)
        or _looks_like_recommendation_request(text)
        or _looks_like_structured_field_filter_query(text)
    )
    if not product_bound_question:
        return None

    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        contents_clarification = _unresolved_product_like_contents_clarification_result(db, text)
        if contents_clarification:
            return contents_clarification

    if len(named_products) > 1 or entity_scope_hint in {"ambiguous_product", "ambiguous_product_name"}:
        if unknown_label:
            return _build_generic_ambiguous_unknown_field_clarification_result(
                text,
                label=unknown_label,
                products=named_products,
                subject_override=subject,
            )
        if customer_agent_intent_service._looks_like_contents_grounding_question(text):
            options = "；".join(
                f"{str(product.product_name_cn or product.product_name_en or product.sku).strip()}（{str(product.sku or '').strip().upper()}）"
                for product in named_products[:5]
            )
            answer = (
                f"匹配到多个相关商品：{options}。"
                "请先指定 SKU 或具体款式，我再帮你查包装清单、配件或开箱内容。"
            )
            candidate_skus = [str(product.sku or "").strip().upper() for product in named_products[:5] if getattr(product, "sku", None)]
            return {
                "intent": "clarify",
                "answer_type": "clarification",
                "answer": answer,
                "results": [],
                "result_skus": [],
                "candidate_skus": candidate_skus,
                "needs_clarification": True,
                "answer_metadata": {"source": "unresolved_product_like_contents_clarification", "evidence_status": "ambiguous_product"},
                "debug": {"agent_mode": "unresolved_product_like_contents_clarification"},
                "skip_polish": True,
            }
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"我还不能把“{subject}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [str(product.sku or "").strip().upper() for product in named_products if getattr(product, 'sku', None)],
            "needs_clarification": True,
            "answer_metadata": {"source": "entity_scope_ambiguous_clarification", "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": "entity_scope_ambiguous_clarification"},
            "skip_polish": True,
        }

    if len(named_products) == 1 and not unresolved_scope:
        return None

    if route_family_hint == "product_bound_qa" and entity_scope_hint == "resolved_product":
        return None

    if unknown_label:
        unresolved = _build_unresolved_product_like_unknown_field_clarification_result(
            text,
            label=unknown_label,
            subject_override=subject,
        )
        if unresolved:
            return unresolved
        return _build_unknown_field_product_not_found_result(text, label=unknown_label, subject_override=subject)

    if (
        _looks_like_product_capability_or_field_question(text)
        and not customer_agent_intent_service._looks_like_contents_grounding_question(text)
        and not _looks_like_recommendation_request(text)
        and not _contains_explicit_negative_product_marker(text)
        and not unresolved_scope
    ):
        return None

    if (
        not customer_agent_intent_service._looks_like_contents_grounding_question(text)
        and not _looks_like_recommendation_request(text)
        and not _contains_explicit_negative_product_marker(text)
        and (
            customer_agent_intent_service._looks_like_usage_care_question(text)
            or _looks_like_product_capability_or_field_question(text)
            or route_family_hint == "product_bound_qa"
        )
    ):
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"我还不能把“{subject}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名，我再继续确认这个问题。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "needs_clarification": True,
            "answer_metadata": {"source": "entity_scope_ambiguous_clarification", "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": "entity_scope_ambiguous_clarification"},
            "skip_polish": True,
        }

    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        no_match_answer = (
            f"没有找到“{subject}”对应的产品资料。"
            "请先指定 SKU 或具体款式，我再帮你查包装清单、配件或开箱内容。"
        )
    else:
        no_match_answer = f"没有找到“{subject}”对应的产品资料，请确认商品名或提供 SKU。"
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": no_match_answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {"source": "unknown_field_product_not_found", "evidence_status": "product_not_found"},
        "debug": {"agent_mode": "entity_scope_product_not_found"},
        "skip_polish": True,
    }


def _is_candidate_set_heat_source_filter(question: str) -> bool:
    """Whether a heat-source request filters a prior set, not one product."""
    text = str(question or "")
    return bool(
        any(term in text for term in ("酒精炉", "酒精", "热源"))
        and any(term in text for term in ("哪些", "有哪", "这些", "这几款", "它们", "两款", "两个"))
    )


def _product_like_scope_subject(question: str) -> str:
    text = str(question or "").strip()
    if not text:
        return ""
    if "还是" in text and any(term in text for term in ("更", "优先", "先买", "选", "实用", "合适", "值得")):
        return ""
    patterns = (
        r"^(?P<subject>.+?)\s*(?:包装里有什么|盒子里有什么|包装清单是什么|包装清单是啥|有哪些配件|有什么配件|有啥配件|有没有配件|包含哪些东西|包含哪些内容).*$",
        r"^(?P<subject>.+?)\s*(?:有哪些|有什么|有啥|有没有|包含哪些|包装里有|盒子里有|包装清单是|包装清单是什么).*(?:配件|附件|包装清单|东西|内容|内容物).*$",
        r"^(?P<subject>.+?)(?:能不能|能用|可不可以|可以|多少钱|什么价|有活动吗|有优惠吗|带什么|运费多少|包邮吗|今天能发吗).*$",
        r"^(?P<subject>.+?)是(?:钛的|不锈钢|铝合金|硬氧|什么材质|哪种材质|几个人|几人|多大|多少|什么).*$",
        r"^(?P<subject>.+?)\s*(?:适合|适不适合).*$",
        r"^(?P<subject>.+?)(?:推荐(?:一|几|一下|一个|几个|几款)?).*$",
        r"^(?P<subject>.+?)(?:的)?(?:材质|容量|重量|尺寸|配件|内容物|赠品|运费|包邮|库存|发货|售后|保修).*$",
    )
    for pattern in patterns:
        match = re.match(pattern, text)
        if not match:
            continue
        subject = str(match.group("subject") or "").strip("，。！？；;：: ")
        if subject:
            return subject
    return ""


def _looks_like_product_like_scope_subject(subject: str) -> bool:
    text = customer_agent_service.normalize_search_text(subject).strip()
    if not text:
        return False
    if text.startswith(("哪些", "有哪些", "哪款", "哪几款", "有什么", "推荐", "给我推荐", "适合")):
        return False
    if any(term in text for term in ("什么", "哪个", "哪些", "哪款", "怎么", "如何")):
        return False
    if text in {"卡式炉", "酒精炉", "燃气炉", "气炉"}:
        return False
    if _is_generic_contents_subject(text) or _is_generic_modifier_prefixed_product_scope(text):
        return False
    if customer_agent_intent_service._looks_like_named_product_term(text):
        return True
    category_tokens = ("水壶", "咖啡壶", "套锅", "锅具", "炉具", "烤盘", "水杯", "杯", "壶", "锅", "炉")
    matched_token = next((token for token in category_tokens if token in text), "")
    if not matched_token:
        return False
    if re.search(r"[A-Za-z0-9\-]", text):
        return True
    generic_constraint_terms = (
        "适合", "露营", "徒步", "野餐", "公园", "卡式炉", "酒精炉", "燃气炉", "气炉", "多人", "双人",
        "两人", "两个人", "轻量", "轻便", "预算", "便宜", "推荐", "能配", "能用", "可以用",
    )
    if any(term in text for term in generic_constraint_terms):
        return False
    prefix = text.split(matched_token, 1)[0].strip()
    if len(prefix) < 2:
        return False
    descriptor_terms = (
        "不锈钢", "铝合金", "硬氧", "钛", "轻量", "轻便", "便携", "徒步", "新手", "预算", "便宜",
        "双人", "两人", "两个人", "公园", "野餐", "户外", "露营", "咖啡",
    )
    descriptor_remainder = prefix
    for term in descriptor_terms:
        descriptor_remainder = descriptor_remainder.replace(term, "")
    return bool(descriptor_remainder.strip())


def _contains_explicit_negative_product_marker(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    return any(term in value for term in ("不存在", "完全不存在", "虚构", "假的", "并不存在", "没这个", "没有这个"))


def _is_generic_category_phrase(subject: str) -> bool:
    text = str(subject or "").strip()
    if not text:
        return False
    generic_scopes = {
        "水壶", "水杯", "杯", "杯子", "锅", "锅具", "炉", "炉具", "炉子", "装备", "咖啡器具", "配件", "商品", "产品",
        "咖啡壶", "壶", "水具",
    }
    return text in generic_scopes


def _is_generic_modifier_prefixed_product_scope(subject: str) -> bool:
    text = str(subject or "").strip()
    if not text:
        return True
    generic_prefixes = (
        "轻便", "轻便的", "轻量", "轻量的", "不要太重", "不要太重的", "比较轻", "比较轻的", "适合徒步", "适合徒步的", "适合新手", "适合新手的",
        "预算低一点", "预算低一点的", "预算不高", "预算不高的", "适合卡式炉", "适合卡式炉的", "公园野餐", "夏天徒步", "夏天", "冷水", "补水",
        "热水", "饮水", "有什么", "推荐几个", "推荐一个", "推荐", "两个人", "双人", "新手", "徒步", "露营", "野餐",
        "评价最好", "客户评价最好", "销量最高", "最好", "最高",
    )
    if any(text.startswith(prefix) for prefix in generic_prefixes):
        return True
    if _is_generic_category_phrase(text):
        return True
    product_ref = _semantic_catalog_product_ref(text)
    if product_ref and product_ref != "产品" and text.endswith(product_ref):
        prefix = text[: -len(product_ref)].strip()
        if not prefix:
            return True
        if any(token in prefix for token in ("轻便", "轻量", "不要太重", "比较轻", "预算低", "预算不高", "便宜", "新手", "徒步", "露营", "野餐", "公园", "夏天", "冷水", "补水", "热水", "饮水", "有什么", "双人", "两个人", "两人", "评价最好", "客户评价最好", "销量最高", "最好", "最高")):
            return True
    return False


def _looks_like_generic_constraint_category_query(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    if any(term in value for term in ("能用", "可以", "可不可以", "能不能", "多少钱", "运费", "包邮", "库存", "发货", "保修", "售后", "评价", "包含什么", "里有什么", "带什么")):
        return False
    subject = _product_like_scope_subject(value) or customer_agent_intent_service._detail_subject_from_question(value).strip()
    if not subject:
        subject = value
    if _contains_explicit_negative_product_marker(value):
        return False
    # A purchase request with an explicit party-size/usage constraint is a
    # catalogue recommendation even when the sentence contains a descriptive
    # noun phrase such as "5个人...的锅".  Do this before the unresolved-name
    # guard; an unknown named product without these structured constraints
    # still fails closed below.
    category_terms = ("水杯", "杯子", "杯", "水壶", "壶", "锅具", "套锅", "锅", "炉具", "炉子", "炉", "装备", "咖啡器具", "配件", "水具")
    recommendation_constraints = (
        "大容量", "多人", "单人", "双人", "轻便", "轻量", "预算", "便宜",
        "徒步", "露营", "野餐", "公园", "做饭", "烹饪", "不要",
    )
    has_variant_identity = bool(re.search(
        r"\d+(?:\.\d+)?\s*(?:杯|寸|英寸|毫升|ml|升|l)(?:[-－—_/ ]*(?:黑|白|红|蓝|绿|粉|灰|银|金|橙|黄|紫)(?:色)?)?",
        subject,
        re.IGNORECASE,
    ))
    if (
        _looks_like_recommendation_request(value)
        and any(term in value for term in category_terms)
        and not has_variant_identity
        and (
            bool(re.search(r"\d+\s*(?:个)?人", value))
            or any(term in value for term in recommendation_constraints)
        )
    ):
        return True
    if _looks_like_product_like_scope_subject(subject):
        return False
    if _is_generic_modifier_prefixed_product_scope(subject):
        return True
    modifier_terms = ("轻便", "轻量", "不要太重", "比较轻", "预算低", "预算不高", "便宜", "新手", "徒步", "露营", "野餐", "公园", "卡式炉", "酒精炉", "双人", "两个人", "两人")
    return any(term in subject for term in category_terms) and any(term in value for term in modifier_terms)


def _looks_like_unresolved_product_like_question(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    subject = _product_like_scope_subject(value) or customer_agent_intent_service._detail_subject_from_question(value).strip()
    if not subject:
        return False
    if _looks_like_generic_constraint_category_query(value):
        return False
    if _contains_explicit_negative_product_marker(value):
        return True
    if _is_generic_modifier_prefixed_product_scope(subject):
        return False
    if _looks_like_product_like_scope_subject(subject):
        return True
    return False


def _subject_strongly_matches_product(subject: str, product: Product) -> bool:
    normalized_subject = customer_agent_service.normalize_search_text(subject).lower().strip()
    if not normalized_subject:
        return False
    normalized_subject_compact = re.sub(r"\s+", "", normalized_subject)
    alias_values: list[str] = []
    seen_aliases: set[str] = set()
    for raw_value in (
        getattr(product, "name", ""),
        getattr(product, "product_name_cn", ""),
        getattr(product, "product_name_en", ""),
    ):
        for alias in (
            customer_agent_service.product_name_aliases(raw_value)
            + customer_agent_service.product_name_family_aliases(raw_value)
        ):
            normalized_alias = customer_agent_service.normalize_search_text(alias).lower().strip()
            if not normalized_alias or normalized_alias in seen_aliases:
                continue
            seen_aliases.add(normalized_alias)
            alias_values.append(normalized_alias)
    for raw_value in (
        *alias_values,
        getattr(product, "name", ""),
        getattr(product, "product_name_cn", ""),
        getattr(product, "product_name_en", ""),
        getattr(product, "sku", ""),
        getattr(product, "barcode", ""),
    ):
        normalized_name = customer_agent_service.normalize_search_text(raw_value).lower().strip()
        if not normalized_name:
            continue
        normalized_name_compact = re.sub(r"\s+", "", normalized_name)
        if normalized_subject == normalized_name or normalized_subject_compact == normalized_name_compact:
            return True
        if len(normalized_subject_compact) >= 4 and normalized_subject_compact in normalized_name_compact:
            return True
    return False


def _has_unresolved_product_like_scope(db: Session, question: str) -> bool:
    text = str(question or "").strip()
    if not text or customer_agent_service._extract_skus(text):
        return False
    subject = _product_like_scope_subject(text) or customer_agent_intent_service._detail_subject_from_question(text).strip()
    if not subject:
        return False
    if _looks_like_generic_constraint_category_query(text):
        return False
    if not _looks_like_unresolved_product_like_question(text):
        return False
    # Fuzzy recall is diagnostic only.  A similarly named product must not
    # suppress unresolved handling unless the extracted subject strongly
    # matches that product's own canonical/alias identity.
    return not any(
        _subject_strongly_matches_product(subject, product)
        for product in _products_named_in_question(db, text)
    )


def _has_resolved_named_product_contract(db: Session, question: str) -> bool:
    """Return true only when the current utterance seals one product identity."""
    products = db.query(Product).order_by(Product.sku.asc()).all()
    default_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
    )
    canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
        question,
        products,
    )
    canonical_contract = (
        customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            entity_text_override=canonical_subject,
        )
        if canonical_subject
        else None
    )
    selection = customer_entity_resolution_contract.choose_effective_entity_contract(
        default_contract,
        canonical_contract,
        products,
    )
    return bool(
        customer_entity_resolution_contract.can_resolve_single_product(
            selection.contract,
            products,
        ).allowed
    )


def _reject_unsealed_named_product_phase1_result(
    db: Session,
    question: str,
    agent_result: dict | None,
) -> dict | None:
    """Keep generic Phase-1 retrieval from answering a uniquely named product."""
    if not isinstance(agent_result, dict):
        return agent_result
    if str(agent_result.get("answer_type") or "").strip() not in {
        "knowledge_base_answer",
        "knowledge_answer",
        "product_query",
        "query_products",
    }:
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    if isinstance(debug.get("entity_resolution_contract"), dict):
        return agent_result
    if _has_resolved_named_product_contract(db, question):
        return None
    return agent_result


def _recommendation_question_contract(question: str) -> dict[str, Any]:
    text = str(question or "").strip()
    if not text or not _looks_like_recommendation_request(text):
        return {}
    filters: dict[str, Any] = {}
    negative_filters: dict[str, Any] = {}

    if "水壶" in text:
        filters["product.category"] = "水壶"
    elif any(term in text for term in ("水杯", "杯子", "钛杯", "杯")):
        filters["product.category"] = "水杯"
    elif any(term in text for term in ("锅具", "锅", "套锅", "炊具")):
        filters["product.category"] = "锅具"
    elif any(term in text for term in ("炉具", "炉子", "酒精炉", "卡式炉", "气炉", "燃气炉")):
        filters["product.category"] = "炉具"
    elif "咖啡" in text:
        filters["product.category"] = "咖啡器具"

    if "钛" in text:
        filters["specs.body_material"] = "钛"
    elif "不锈钢" in text:
        filters["specs.body_material"] = "不锈钢"
    elif "铝合金" in text:
        filters["specs.body_material"] = "铝合金"

    if "卡式炉" in text:
        filters["specs.heat_source"] = "卡式炉"
    elif "酒精炉" in text:
        filters["specs.heat_source"] = "酒精炉"
    elif "明火直烧" in text:
        filters["specs.heat_source"] = "明火直烧"
    elif "直接加热" in text or "明火" in text:
        filters["specs.heat_source"] = "明火"

    if "徒步" in text:
        filters["_contract.hiking"] = "true"
    if "轻量" in text or "轻便" in text or "不要太重" in text or "别太重" in text or "比较轻" in text:
        filters["_contract.lightweight"] = "true"
    if "新手" in text:
        filters["_contract.beginner"] = "true"
    if "预算低" in text or "预算不高" in text or "预算低一点" in text or "便宜点" in text or "性价比" in text:
        filters["_contract.budget"] = "true"
    if "两个人" in text or "两人" in text or "2人" in text or "双人" in text:
        filters["_contract.two_person"] = "true"
    if "公园" in text or "野餐" in text:
        filters["_contract.lightweight"] = "true"
    if "不能进洗碗机" in text or "不能放洗碗机" in text or "不可进洗碗机" in text:
        negative_filters["_contract.dishwasher"] = "洗碗机"

    return {"filters": filters, "negative_filters": negative_filters}


def _should_use_central_subject_recommendation(
    *,
    question: str,
    recommendation_contract: customer_recommendation_verification_contract.RecommendationRequestContract,
) -> bool:
    text = str(question or "").strip()
    if not text or not recommendation_contract.subject_category:
        return False
    comparison_signal = bool(
        customer_agent_planner_service._is_compare_question(text)
        or customer_agent_planner_service._is_compare_choice_question(text)
        or customer_agent_intent_service._is_compare_question(text)
        or _phase1_is_griddle_vs_cookware_scenario(text)
        or "还是" in text
    )
    if comparison_signal:
        return False
    return _looks_like_recommendation_request(text)


def _rehydrate_recommendation_rows_from_database(
    db: Session,
    agent_result: dict,
) -> dict:
    """Restore tool-backed recommendation candidates before contract filtering.

    Some runtime responses retain product-search output only in the debug
    raw-results list while their public results list is empty. The
    recommendation contract must not interpret that transport shape as a
    verified empty catalogue. Only SKU identifiers are read from the debug
    payload; every returned row is reloaded from the current database before
    verification, so this path never accepts model-supplied product facts.
    """
    if not isinstance(agent_result, dict) or agent_result.get("results"):
        return agent_result
    if str(agent_result.get("answer_type") or "").strip() != "recommendation":
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    raw_rows = debug.get("raw_results") if isinstance(debug.get("raw_results"), list) else []
    raw_skus = list(dict.fromkeys(
        str(row.get("sku") or "").strip().upper()
        for row in raw_rows
        if isinstance(row, dict) and str(row.get("sku") or "").strip()
    ))
    if not raw_skus:
        return agent_result
    catalog_by_sku = {
        str(row.get("sku") or "").strip().upper(): row
        for row in _phase1_catalog_rows(db, "产品")
        if isinstance(row, dict) and str(row.get("sku") or "").strip()
    }
    rows = [catalog_by_sku[sku] for sku in raw_skus if sku in catalog_by_sku]
    if not rows:
        return agent_result
    result = dict(agent_result)
    result["results"] = rows
    result["result_skus"] = [str(row.get("sku") or "").strip().upper() for row in rows]
    result["candidate_skus"] = list(result["result_skus"])
    result_debug = dict(debug)
    result_debug["recommendation_candidates_rehydrated"] = "database_by_tool_result_sku"
    result["debug"] = result_debug
    return result


def _post_filter_recommendation_result(db: Session, question: str, agent_result: dict) -> dict:
    if not isinstance(agent_result, dict):
        return agent_result
    original_visible_result_skus = [
        str(sku or "").strip().upper()
        for sku in (agent_result.get("result_skus") or [])
        if str(sku or "").strip()
    ]
    agent_result = _rehydrate_recommendation_rows_from_database(db, agent_result)
    recommendation_like_question = _looks_like_recommendation_request(question)
    explicit_recommendation_request = any(
        term in str(question or "")
        for term in ("推荐", "哪款", "选什么", "帮我选", "帮我挑", "推荐一个", "推荐几个")
    )
    allow_recommendation_contract = explicit_recommendation_request or (
        recommendation_like_question and not _looks_like_structured_field_filter_query(question)
    )
    answer_type = str(agent_result.get("answer_type") or "").strip()
    metadata = dict(agent_result.get("answer_metadata") or {})
    metadata_source = str(metadata.get("source") or "").strip()
    sealed_semantic_contract_data = metadata.get("recommendation_contract")
    has_sealed_semantic_contract = bool(
        metadata_source == "validated_semantic_preplan_then_same_sku_verification"
        and isinstance(sealed_semantic_contract_data, dict)
    )
    # A pairwise choice has already sealed its candidate domain and rendered
    # a recommendation from that ordered set.  Re-running global catalogue
    # filtering here can leave the result rows scoped while replacing the
    # answer lead with an unrelated SKU.
    if metadata_source == "planner_compare_choice":
        return agent_result
    # A structured dual-domain recommendation has already sealed one
    # evidence-backed option for each requested domain and rendered the
    # requested trade-off.  The generic filter below is a single-domain
    # ranker; rebuilding here would flatten that answer into a generic
    # "primary + backup" list and lose the category comparison.
    if (
        metadata_source == "product_catalog_structured_recommendation"
        and (
            _phase1_is_stove_griddle_combo_scenario(question)
            or _phase1_is_griddle_vs_cookware_scenario(question)
        )
    ):
        return agent_result
    if answer_type != "recommendation" and metadata_source.startswith("structured_"):
        return agent_result
    if answer_type != "recommendation" and not (
        allow_recommendation_contract and answer_type in {"product_query", "query_products"}
    ):
        return agent_result
    contract = _recommendation_question_contract(question)
    if not contract and isinstance(metadata.get("recommendation_contract"), dict):
        # Semantic planning already supplied a validated recommendation
        # contract; do not let an older lexical contract gate bypass its
        # candidate verification.
        contract = {"filters": {}, "negative_filters": {}}
    if not contract:
        return agent_result
    rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    if not rows:
        if not allow_recommendation_contract:
            return agent_result
        metadata = dict(agent_result.get("answer_metadata") or {})
        debug = dict(agent_result.get("debug") or {})
        agent_result["intent"] = "recommendation"
        agent_result["answer_type"] = "recommendation"
        agent_result["answer"] = "当前未找到符合条件的推荐商品，可以尝试放宽类目、材质或使用条件。"
        agent_result["results"] = []
        agent_result["result_skus"] = []
        agent_result["candidate_skus"] = []
        agent_result["skip_polish"] = True
        metadata["source"] = metadata.get("source") or "product_catalog_structured_recommendation"
        metadata["post_filter_no_match"] = True
        agent_result["answer_metadata"] = metadata
        debug["recommendation_post_filter_applied"] = True
        debug["recommendation_post_filter_matched_count"] = 0
        debug["agent_mode"] = debug.get("agent_mode") or "recommendation_post_filter_no_match"
        agent_result["debug"] = debug
        return agent_result
    verification_contract = (
        customer_recommendation_verification_contract.RecommendationRequestContract.from_dict(
            sealed_semantic_contract_data
        )
        if has_sealed_semantic_contract
        else customer_recommendation_verification_contract.build_recommendation_request_contract(question)
    )
    eligibility_filters = dict(contract.get("filters") or {})
    eligibility_filters.pop("_contract.lightweight", None)
    if verification_contract.subject_kind == "stove" and not verification_contract.heat_sources:
        eligibility_filters.pop("specs.heat_source", None)
    eligibility_contract = {
        "filters": eligibility_filters,
        "negative_filters": dict(contract.get("negative_filters") or {}),
    }
    # A semantic recommendation has already converted the complete request
    # into a formal verification contract. Reapplying the older lexical
    # eligibility filter can silently discard its verified candidates (for
    # example, a DB people-range value that does not contain the exact words
    # from the request). Reuse the sealed contract and let the central
    # verifier evaluate the same rows. Legacy results still receive the
    # deterministic eligibility filter.
    qualified_rows = (
        list(rows)
        if has_sealed_semantic_contract
        else [
            row for row in rows
            if _structured_row_matches_contract(row, eligibility_contract)
        ]
    )
    # Runtime ranking may return only a truncated candidate window. When the
    # formal verification contract has no hard factual constraint, an empty
    # intersection with that window is not evidence that the catalogue has no
    # matching product. Re-evaluate the deterministic eligibility contract
    # against the database catalogue before returning an empty recommendation.
    # A true formal hard constraint remains fail-closed.
    if not qualified_rows and not verification_contract.hard_constraints:
        qualified_rows = [
            row
            for row in _phase1_catalog_rows(db, "产品")
            if _structured_row_matches_contract(row, eligibility_contract)
        ]
    explicit_target_category = _structured_target_category_from_question(question)
    comparison_scope = bool(
        customer_agent_planner_service._is_compare_question(question)
        or customer_agent_planner_service._is_compare_choice_question(question)
        or customer_agent_intent_service._is_compare_question(question)
        or _phase1_is_griddle_vs_cookware_scenario(question)
        or "还是" in str(question or "")
    )
    if not explicit_target_category and _looks_like_recommendation_request(question) and not comparison_scope:
        semantic_target = _semantic_catalog_product_ref(question)
        if semantic_target != "产品":
            explicit_target_category = semantic_target
    if explicit_target_category == "烤盘" and not comparison_scope:
        qualified_rows = [
            row
            for row in qualified_rows
            if any(
                term in " ".join(
                    str(row.get(key) or "")
                    for key in ("product_name_cn", "product_name_en", "category", "capacity", "features")
                ).lower()
                for term in ("烤盘", "煎盘", "griddle")
            )
        ]
    debug = dict(agent_result.get("debug") or {})
    subject_entry_enabled = _should_use_central_subject_recommendation(
        question=question,
        recommendation_contract=verification_contract,
    )
    verification_enabled = bool(
        subject_entry_enabled
        or (
            not verification_contract.subject_category
            and (verification_contract.hard_constraints or verification_contract.soft_preferences)
        )
    )
    debug["central_subject_recommendation_eligible"] = subject_entry_enabled
    debug["initial_candidate_skus"] = [
        str(row.get("sku") or "").strip().upper()
        for row in qualified_rows
        if str(row.get("sku") or "").strip()
    ]
    strict_subject_rejections: list[dict[str, Any]] = []
    if verification_enabled and verification_contract.subject_category == "锅具":
        subject_rows: list[dict[str, Any]] = []
        for row in qualified_rows:
            if _is_service_pot_or_cookware_set_candidate(row):
                subject_rows.append(row)
                continue
            strict_subject_rejections.append(
                {
                    "sku": str(row.get("sku") or "").strip().upper(),
                    "subject_eligible": False,
                    "hard_constraints_passed": False,
                    "evidence_by_constraint": {
                        "subject": {
                            "status": "conflict",
                            "field_source": "catalog_subject_classifier",
                            "raw_value": str(row.get("sub_category") or row.get("category") or "").strip(),
                        }
                    },
                    "verified_preferences": [],
                    "unsupported_preferences": [],
                    "rejection_reasons": ["subject_category_mismatch"],
                }
            )
        qualified_rows = subject_rows
    verifications = (
        customer_recommendation_verification_contract.verify_recommendation_candidates(
            verification_contract,
            qualified_rows,
        )
        if verification_enabled
        else []
    )
    if verification_enabled:
        matched_rows = customer_recommendation_verification_contract.select_recommendation_candidates(
            qualified_rows,
            verifications,
        )
        verified_skus = {
            str(row.get("sku") or "").strip().upper()
            for row in matched_rows
            if str(row.get("sku") or "").strip()
        }
        qualified_rows, return_metadata = customer_recommendation_verification_contract.prepare_recommendation_return_rows(
            matched_rows,
            limit=5,
        )
        metadata["recommendation_contract"] = verification_contract.to_dict()
        metadata.update(return_metadata)
        metadata["verification_level"] = (
            "fully_verified"
            if any(item.verification_level == "fully_verified" and item.sku in verified_skus for item in verifications)
            else "partially_verified" if verified_skus else "rejected"
        )
        metadata["fully_verified_count"] = sum(item.verification_level == "fully_verified" for item in verifications)
        metadata["partially_verified_count"] = sum(item.verification_level == "partially_verified" for item in verifications)
        metadata["rejected_count"] = len(strict_subject_rejections) + sum(item.verification_level == "rejected" for item in verifications)
        debug["all_verified_candidate_skus"] = [
            str(row.get("sku") or "").strip().upper()
            for row in matched_rows
            if str(row.get("sku") or "").strip()
        ]
        debug["verified_candidate_skus"] = [
            str(row.get("sku") or "").strip().upper()
            for row in qualified_rows
            if str(row.get("sku") or "").strip()
        ]
        debug["candidate_verifications"] = [item.to_dict() for item in verifications if item.sku in verified_skus]
        debug["fully_verified_candidates"] = [item.to_dict() for item in verifications if item.verification_level == "fully_verified"]
        debug["partially_verified_candidates"] = [item.to_dict() for item in verifications if item.verification_level == "partially_verified"]
        debug["rejected_candidates"] = strict_subject_rejections + [
            item.to_dict() for item in verifications if item.verification_level == "rejected"
        ]
    if not qualified_rows:
        answer = (
            customer_recommendation_verification_contract.build_verified_recommendation_answer(
                verification_contract,
                [],
                verifications,
            )
            if verification_enabled
            else "当前未找到符合条件的推荐商品，可以尝试放宽类目、材质或使用条件。"
        )
        agent_result["intent"] = "recommendation"
        agent_result["answer_type"] = "recommendation"
        agent_result["answer"] = answer
        agent_result["results"] = []
        agent_result["result_skus"] = []
        agent_result["candidate_skus"] = []
        agent_result["skip_polish"] = True
        metadata["source"] = metadata.get("source") or "product_catalog_structured_recommendation"
        metadata["post_filter_no_match"] = True
        agent_result["answer_metadata"] = metadata
        debug["recommendation_post_filter_applied"] = True
        debug["recommendation_post_filter_matched_count"] = 0
        debug["agent_mode"] = debug.get("agent_mode") or "recommendation_post_filter_no_match"
        agent_result["debug"] = debug
        return agent_result

    filtered_skus = [str(row.get("sku") or "").strip().upper() for row in qualified_rows if str(row.get("sku") or "").strip()]
    original_skus = (
        original_visible_result_skus
        if has_sealed_semantic_contract and original_visible_result_skus
        else [
            str(row.get("sku") or "").strip().upper()
            for row in rows
            if str(row.get("sku") or "").strip()
        ]
    )
    agent_result["intent"] = "recommendation"
    agent_result["answer_type"] = "recommendation"
    agent_result["results"] = qualified_rows
    agent_result["result_skus"] = filtered_skus
    agent_result["candidate_skus"] = filtered_skus
    answer = str(agent_result.get("answer") or "")
    normalized_answer = answer.upper()
    filtered_sku_set = set(filtered_skus)
    row_name_map: dict[str, set[str]] = {}
    for row in qualified_rows:
        sku = str(row.get("sku") or "").strip().upper()
        if not sku:
            continue
        names = {
            sku,
            str(row.get("product_name_cn") or "").strip(),
            str(row.get("product_name_en") or "").strip(),
        }
        row_name_map[sku] = {name for name in names if name}
    matched_skus_in_answer = {
        sku
        for sku, names in row_name_map.items()
        if any(name and name.upper() in normalized_answer for name in names)
    }
    answer_mentions_filtered = bool(matched_skus_in_answer)
    answer_mentions_outside = False
    if normalized_answer:
        for row in rows:
            sku = str(row.get("sku") or "").strip().upper()
            if not sku or sku in filtered_sku_set:
                continue
            candidate_names = {
                sku,
                str(row.get("product_name_cn") or "").strip(),
                str(row.get("product_name_en") or "").strip(),
            }
            if any(name and name.upper() in normalized_answer for name in candidate_names):
                answer_mentions_outside = True
                break
    # Mentioning a candidate is insufficient after the verifier changes the
    # order: the visible lead must follow the sealed top result, not the old
    # ranker's first product.
    ranking_changed = filtered_skus != original_skus[:len(filtered_skus)]
    recommendation_narrative = metadata.get("recommendation_narrative")
    validated_semantic_narrative = bool(
        isinstance(recommendation_narrative, dict)
        and recommendation_narrative.get("source") == "validated_deepseek_grounded_narrative"
    )
    should_rebuild_answer = (
        (verification_enabled and not validated_semantic_narrative)
        or comparison_scope
        or ranking_changed
        or not answer
        or not answer_mentions_filtered
        or answer_mentions_outside
    )
    debug["recommendation_post_filter_rebuild_reasons"] = [
        reason
        for reason, active in (
            ("unvalidated_verification_answer", verification_enabled and not validated_semantic_narrative),
            ("comparison_scope", comparison_scope),
            ("visible_ranking_changed", ranking_changed),
            ("empty_answer", not answer),
            ("selected_identity_missing", not answer_mentions_filtered),
            ("outside_identity_mentioned", answer_mentions_outside),
        )
        if active
    ]
    if should_rebuild_answer:
        if verification_enabled:
            rebuilt_answer = customer_recommendation_verification_contract.build_verified_recommendation_answer(
                verification_contract,
                qualified_rows,
                verifications,
                total_match_count=metadata.get("total_match_count"),
            )
        else:
            top_row = qualified_rows[0]
            top_name = top_row.get("product_name_cn") or top_row.get("sku")
            top_sku = str(top_row.get("sku") or "").strip().upper()
            top_reason = str(
                top_row.get("usage_scenarios")
                or top_row.get("features")
                or top_row.get("positioning")
                or "匹配当前使用场景"
            ).strip("。；; ")
            rebuilt_answer = f"优先推荐 {top_name}（{top_sku}），因为它更贴合你当前场景，{top_reason}。"
            backups: list[str] = []
            for row in qualified_rows[1:3]:
                name = row.get("product_name_cn") or row.get("sku")
                sku = str(row.get("sku") or "").strip().upper()
                reason = str(row.get("usage_scenarios") or row.get("features") or row.get("positioning") or "匹配当前使用场景").strip("。；; ")
                backups.append(f"{name}（{sku}），{reason}")
            if backups:
                rebuilt_answer += " 备选可以看" + "；".join(backups) + "。"
        preserved_scope_statement = str(metadata.get("preserved_scope_statement") or "").strip()
        if preserved_scope_statement and preserved_scope_statement not in rebuilt_answer:
            rebuilt_answer = f"{preserved_scope_statement}{rebuilt_answer}"
        agent_result["answer"] = rebuilt_answer
        agent_result["skip_polish"] = True
    debug["recommendation_post_filter_applied"] = True
    debug["recommendation_post_filter_matched_count"] = len(filtered_skus)
    debug["recommendation_post_filter_answer_rebuilt"] = should_rebuild_answer
    agent_result["debug"] = debug
    agent_result["answer_metadata"] = metadata
    return agent_result


def _attach_formal_field_contract(
    agent_result: dict,
    question: str,
    plan: dict | None,
) -> dict:
    """Expose the FieldContract consumed by an early protected result."""
    if not isinstance(agent_result, dict):
        return agent_result
    field_request = resolve_requested_field_contract(question, plan)
    if not field_request.get("field_type"):
        return agent_result
    if isinstance(plan, dict):
        plan["field_contract"] = dict(field_request)
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug["field_contract"] = dict(field_request)
    agent_result["debug"] = debug
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    metadata["contract_field_type"] = field_request["field_type"]
    agent_result["answer_metadata"] = metadata
    return agent_result


async def _semantic_recommendation_contract_result(
    db: Session,
    question: str,
    plan: dict[str, Any] | None,
    recommendation_context: dict[str, Any] | None = None,
) -> dict | None:
    """Execute a high-confidence semantic recommendation through DB evidence.

    The semantic preplan supplies only allowlisted abstract requirements.  It
    never picks products or facts; every returned row first passes the shared
    recommendation verifier against that row's own structured evidence.
    """
    preplan = (plan or {}).get("semantic_preplan") if isinstance(plan, dict) else None
    # A pairwise request can be semantically described as a recommendation,
    # but it is not a catalogue search.  Its named participants have already
    # been sealed into EntityResolutionContracts and must continue to the
    # comparison executor rather than be replaced by new catalogue candidates.
    if not _should_execute_semantic_catalog_recommendation(preplan):
        return None
    constraints = preplan.get("recommendation_constraints")
    unrepresented_requirements = [
        str(item or "").strip()
        for item in (preplan.get("unrepresented_recommendation_requirements") or [])
        if str(item or "").strip()
    ]
    semantic_soft_preferences = [
        str(item or "").strip()
        for item in (preplan.get("recommendation_soft_preferences") or [])
        if str(item or "").strip()
    ]
    # The semantic layer has identified material customer requirements that
    # the current DB verification ontology cannot represent.  Do not silently
    # discard them and recommend a broader category; request a verifiable
    # priority instead.  This branch never selects a product or invents a
    # lexical interpretation of the requirement.
    if unrepresented_requirements:
        requirement_labels = "、".join(f"“{item}”" for item in unrepresented_requirements[:3])
        return {
            "intent": "recommendation",
            "answer_type": "clarification",
            "answer": (
                f"你提到的{requirement_labels}，当前还不能用同 SKU 的已验证资料作为筛选条件。"
                "我不会省略这个要求后直接推荐；如果愿意，可以补充可接受的替代条件，我再继续帮你筛选。"
            ),
            "results": [], "result_skus": [], "candidate_skus": [], "evidence": [],
            "debug": {
                "agent_mode": "semantic_recommendation_unrepresented_requirement_clarification",
                "semantic_constraints": dict(constraints or {}),
                "unrepresented_recommendation_requirements": unrepresented_requirements,
                "semantic_soft_preferences": semantic_soft_preferences,
            },
            "answer_metadata": {"source": "validated_semantic_preplan_unrepresented_requirement_clarification"},
            "skip_polish": True,
        }
    semantic_subject = str(preplan.get("subject_text") or "").strip()
    subject_rows = customer_agent_service.search_products(db, semantic_subject, limit=50) if semantic_subject else []
    # The semantic model understands the requested thing; the database owns
    # its actual category. If the model's small abstract subject_kind schema
    # conflicts with a non-empty DB subject scope, do not use it to discard
    # those candidates. This never broadens beyond the database scope.
    if subject_rows and constraints.get("subject_kind"):
        expected_category = {"cookware": "锅具", "waterware": "水具", "stove": "炉具", "coffee_gear": "咖啡器具", "accessories": "配件"}.get(
            str(constraints.get("subject_kind") or "")
        )
        actual_categories = {str(row.get("category") or "").strip() for row in subject_rows}
        if expected_category and actual_categories and all(expected_category not in category for category in actual_categories):
            constraints.pop("subject_kind", None)
    contract = customer_recommendation_verification_contract.build_recommendation_request_contract(
        question,
        semantic_constraints=constraints,
    )
    if not contract.field_provenance or not all(
        item.get("provenance") == "validated_semantic_preplan"
        for item in contract.field_provenance.values()
    ):
        return None
    rows = subject_rows or _phase1_catalog_rows(db, "产品")
    # The semantic plan alone decides whether the customer asks for an
    # alternative. Deterministic code only excludes already-returned sealed
    # SKUs; it never infers a replacement from a keyword or rewrites intent.
    if str(preplan.get("recommendation_followup_action") or "") == "alternative":
        previous_result_skus = {
            str(sku or "").strip().upper()
            for sku in ((recommendation_context or {}).get("previous_result_skus") or [])
            if str(sku or "").strip()
        }
        if previous_result_skus:
            rows = [
                row for row in rows
                if str(row.get("sku") or "").strip().upper() not in previous_result_skus
            ]
    verifications = customer_recommendation_verification_contract.verify_recommendation_candidates(contract, rows)
    fully_verified = [item for item in verifications if item.verification_level == "fully_verified"]
    if not fully_verified:
        evidence_spans = preplan.get("recommendation_constraint_evidence_spans")
        evidence_spans = evidence_spans if isinstance(evidence_spans, dict) else {}
        condition_labels = []
        for key, spans in evidence_spans.items():
            if key == "subject_kind" or not isinstance(spans, list):
                continue
            for span in spans:
                text = str(span or "").strip()
                if text and text not in condition_labels:
                    condition_labels.append(text)
        condition_summary = "、".join(f"“{item}”" for item in condition_labels[:3]) or "你提出的条件"
        return {
            "intent": "recommendation",
            "answer_type": "recommendation",
            "answer": (
                f"当前没有商品能同时用同 SKU 资料明确核验{condition_summary}。"
                "我不会把证据不完整的商品当作推荐候选；你可以放宽其中一项条件后，我再继续筛选。"
            ),
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "evidence": [],
            "debug": {
                "agent_mode": "semantic_recommendation_insufficient_verified_evidence",
                "semantic_constraints": dict(constraints),
                "semantic_soft_preferences": semantic_soft_preferences,
                "candidate_verifications": [item.to_dict() for item in verifications],
            },
            "answer_metadata": {
                "source": "validated_semantic_preplan_insufficient_verified_evidence",
                "recommendation_contract": contract.to_dict(),
                "fully_verified_count": 0,
                "partially_verified_count": sum(item.verification_level == "partially_verified" for item in verifications),
                "rejected_count": sum(item.verification_level == "rejected" for item in verifications),
            },
            "skip_polish": True,
        }
    verified_rows = customer_recommendation_verification_contract.select_recommendation_candidates(rows, verifications)
    returned_rows, return_metadata = customer_recommendation_verification_contract.prepare_recommendation_return_rows(
        verified_rows,
        limit=5,
    )
    narrative_diagnostics: list[dict[str, Any]] = []
    narrative = await _semantic_recommendation_narrative(
        db,
        question=question,
        rows=returned_rows,
        verifications=verifications,
        soft_preferences=semantic_soft_preferences,
        diagnostics=narrative_diagnostics,
    )
    # Verification establishes that candidate rows meet the stated constraints,
    # but it cannot replace the semantic explanation of *why* a customer should
    # choose one.  The former deterministic fallback was a legacy category-list
    # formatter: it exposed broad catalogue matches as though they were a
    # personalized recommendation whenever DeepSeek's grounded narrative was
    # unavailable.  Fail closed instead; no product is a recommendation until
    # the semantic narrative has passed its same-SKU evidence review.
    if not narrative:
        return {
            "intent": "recommendation",
            "answer_type": "clarification",
            "answer": "我已找到满足已验证条件的商品范围，但当前无法基于同 SKU 资料生成可核验的推荐理由。请补充最重要的使用场景、人数、炉具或轻便需求后，我再为你筛选。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "evidence": [],
            "debug": {
                "agent_mode": "semantic_recommendation_narrative_unavailable",
                "semantic_constraints": dict(constraints),
                "semantic_soft_preferences": semantic_soft_preferences,
                "verified_candidate_count": len(fully_verified),
                "recommendation_narrative_diagnostics": narrative_diagnostics,
            },
            "answer_metadata": {
                "source": "validated_semantic_preplan_narrative_unavailable_clarification",
                "recommendation_contract": contract.to_dict(),
                "total_verified_match_count": return_metadata["total_match_count"],
                "reason": "no_validated_deepseek_recommendation_narrative",
            },
            "skip_polish": True,
        }
    if narrative:
        ranked_indexes = list(narrative.get("ranked_candidate_indexes") or [])
        ranked_rows = [returned_rows[index] for index in ranked_indexes]
    answer = str(narrative.get("answer") or "")
    # Only the products explicitly selected and cited by the approved semantic
    # narrative are recommendation results.  Other fully verified rows remain
    # diagnostic candidates, but must not become hidden recommendations for
    # the UI, follow-up context, or evidence list.
    candidate_skus = [str(row.get("sku") or "").strip().upper() for row in returned_rows if row.get("sku")]
    result_skus = [str(row.get("sku") or "").strip().upper() for row in ranked_rows if row.get("sku")]
    verification_by_sku = {item.sku: item for item in verifications}
    evidence: list[dict[str, Any]] = []
    for sku in result_skus:
        item = verification_by_sku.get(sku)
        if not item:
            continue
        for field, item_evidence in item.evidence_by_constraint.items():
            if item_evidence.get("status") != "verified":
                continue
            evidence.append({
                "type": "recommendation_constraint",
                "source_type": "product_db",
                "sku": sku,
                "field": field,
                "source": item_evidence.get("field_source"),
                "field_label": f"推荐条件（{field}）",
                "value": item_evidence.get("raw_value"),
            })
    # The DeepSeek narrative is validated against a sealed, same-SKU evidence
    # map.  Surface each content value it explicitly cited in the API evidence
    # as well; otherwise an audit can see a grounded customer claim but not the
    # exact first-party record that licensed it.  This projects an already
    # approved ``evidence_usage`` declaration and never grants the writer new
    # fields or product identities.
    for usage in list(narrative.get("evidence_usage") or []):
        if not isinstance(usage, dict):
            continue
        index = usage.get("candidate_index")
        if type(index) is not int or index < 0 or index >= len(returned_rows):
            continue
        row = returned_rows[index]
        sku = str(row.get("sku") or "").strip().upper()
        if sku not in result_skus:
            continue
        for field in list(usage.get("fields") or []):
            if not isinstance(field, str) or not field.startswith("content."):
                continue
            source = field.removeprefix("content.")
            value = row.get(source)
            if not str(value or "").strip():
                continue
            evidence.append({
                "type": "semantic_recommendation_narrative_evidence",
                "source_type": "product_db",
                "sku": sku,
                "field": field,
                "source": source,
                "field_label": f"推荐依据（{source}）",
                "value": value,
            })
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": ranked_rows,
        "result_skus": result_skus,
        "candidate_skus": candidate_skus,
        "evidence": evidence,
        "debug": {
            "agent_mode": "semantic_recommendation_contract",
            "semantic_constraints": dict(constraints),
            "semantic_soft_preferences": semantic_soft_preferences,
            "candidate_verifications": [
                item.to_dict()
                for item in verifications
                if item.sku in result_skus
            ],
            "recommendation_narrative_diagnostics": narrative_diagnostics,
            "rejected_candidates": [item.to_dict() for item in verifications if item.verification_level == "rejected"],
        },
        "answer_metadata": {
            "source": "validated_semantic_preplan_then_same_sku_verification",
            "recommendation_contract": contract.to_dict(),
            "semantic_soft_preferences": semantic_soft_preferences,
            "recommendation_narrative": {
                "source": "validated_deepseek_grounded_narrative" if narrative else "deterministic_safe_fallback",
                "ranked_candidate_indexes": list((narrative or {}).get("ranked_candidate_indexes") or []),
                "evidence_usage": list((narrative or {}).get("evidence_usage") or []),
            },
            **return_metadata,
        },
        "skip_polish": True,
    }


def _semantic_recommendation_constraint_clarification_result(preplan: dict[str, Any] | None) -> dict | None:
    """Fail closed when a confident semantic recommendation lacks usable constraints."""
    invalid_semantic_recommendation = (
        isinstance(preplan, dict)
        and preplan.get("semantic_route_family_hint") == "recommendation"
        and str(preplan.get("fallback_reason") or "") in {
            "invalid_recommendation_constraints",
            "recommendation_constraints_outside_recommendation",
            "semantic_label_without_contract",
        }
    )
    if not isinstance(preplan, dict):
        return None
    # A request to choose between named products may be classified as a
    # recommendation by semantic planning, but its entities still require the
    # sealed pairwise comparison path below.  Do not discard those contracts
    # merely because catalogue-wide constraints are absent.
    if _semantic_pairwise_contract_candidate(preplan) or preplan.get("error"):
        return None
    if (
        not invalid_semantic_recommendation
        and (
            not _semantic_preplan_confident(preplan, minimum=0.9)
            or _semantic_preplan_route_family(preplan) != "recommendation"
            or preplan.get("fallback_reason")
        )
    ):
        return None
    if invalid_semantic_recommendation:
        return {
            "intent": "recommendation",
            "answer_type": "clarification",
            "answer": "我理解你是在寻求商品推荐，但当前需求条件还无法用已验证的产品资料安全匹配。请补充希望选锅具、水具还是炉具，以及最重要的使用场景、炉具或人数条件。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "answer_metadata": {
                "source": "semantic_recommendation_invalid_contract_clarification",
                "reason": "invalid_semantic_recommendation_constraint_contract",
            },
            "debug": {
                "agent_mode": "semantic_recommendation_invalid_contract_clarification",
                "recommendation_constraints": {},
            },
            "skip_polish": True,
        }
    if preplan.get("recommendation_constraints"):
        # The formal semantic recommendation was deliberately not executable
        # (for example, its entity scope remained ambiguous).  Returning None
        # here used to hand the exact same request to the legacy lexical
        # recommendation guard, which could emit a broad fixed candidate list
        # despite the unresolved semantic contract.  Keep route ownership and
        # fail closed instead.
        return {
            "intent": "recommendation",
            "answer_type": "clarification",
            "answer": "我已理解你的推荐条件，但当前还不能把它们稳定映射为可核验的商品范围。请补充最重要的一项条件（如人数、炉具、重量或使用场景），我会继续按同 SKU 资料筛选。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "evidence": [],
            "answer_metadata": {
                "source": "validated_semantic_preplan_unexecutable_recommendation_clarification",
            },
            "debug": {
                "agent_mode": "semantic_recommendation_unexecutable_clarification",
                "recommendation_constraints": dict(preplan.get("recommendation_constraints") or {}),
                "semantic_ambiguity": bool(preplan.get("ambiguity")),
            },
            "skip_polish": True,
        }
    return {
        "intent": "recommendation",
        "answer_type": "clarification",
        "answer": "为了避免把不相干的商品当作推荐，请补充希望选锅具、水具还是炉具，以及最重要的使用场景、炉具或人数条件。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {
            "source": "semantic_recommendation_constraint_clarification",
            "reason": "high_confidence_recommendation_without_validated_constraints",
        },
        "debug": {
            "agent_mode": "semantic_recommendation_constraint_clarification",
            "recommendation_constraints": {},
        },
        "skip_polish": True,
    }


def _semantic_structured_query_constraint_clarification_result(
    preplan: dict[str, Any] | None,
    *,
    question: str = "",
) -> dict | None:
    """Fail closed when a semantic multi-filter plan cannot form a contract."""
    if not (
        isinstance(preplan, dict)
        and preplan.get("semantic_route_family_hint") == "structured_query"
        and str(preplan.get("fallback_reason") or "") in {
            "invalid_structured_query_constraints",
            "structured_query_constraints_outside_structured_query",
            "structured_query_constraints_field_mismatch",
            "missing_structured_query_constraints",
        }
    ):
        return None
    # Semantic planning has already selected the structured-query family, but
    # one JSON serialization may still fail its predicate schema.  When the
    # existing contract can independently validate every literal subject and
    # condition from this same customer turn, let that contract execute rather
    # than discard the high-confidence semantic route.  This is validation,
    # not a lexical route fallback: unresolved or generic contracts remain
    # fail-closed below.
    if question:
        validated_contract = customer_structured_query_contract.build_structured_query_contract(question)
        if validated_contract.status == "resolved":
            return None
    return {
        "intent": "query_products",
        "answer_type": "clarification",
        "answer": "我理解你同时限定了多个筛选条件，但当前无法把每项条件都稳定映射为可核验的商品范围。请换一种说法或分别说明最重要的筛选条件，我会按每个条件的真实商品资料筛选。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "evidence": [],
        "answer_metadata": {
            "source": "semantic_structured_query_invalid_contract_clarification",
            "reason": "invalid_semantic_structured_query_constraint_contract",
        },
        "debug": {
            "agent_mode": "semantic_structured_query_invalid_contract_clarification",
        },
        "skip_polish": True,
    }


def _invalid_structured_query_named_detail_contract_result(
    db: Session,
    question: str,
    semantic_preplan: dict[str, Any] | None,
) -> dict | None:
    """Recover one semantic product fact only after deterministic identity sealing.

    A malformed structured-filter payload is normally fail-closed.  The narrow
    exception is a preserved semantic candidate with one allowlisted field and
    a subject that the catalogue resolves uniquely.  The candidate never
    supplies a SKU, database value, or answer.
    """
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    candidate = preplan.get("invalid_structured_query_named_detail_candidate")
    if not isinstance(candidate, dict):
        return None
    subject = str(candidate.get("subject_text") or "").strip()
    fields = [
        customer_field_contract.semantic_preplan_field_type(value)
        for value in (candidate.get("canonical_fields") or [])
    ]
    fields = list(dict.fromkeys(
        field for field in fields if field in customer_field_contract.FORMAL_DETAIL_FIELDS
    ))
    if not subject or len(fields) != 1 or float(candidate.get("confidence") or 0) < 0.9:
        return None
    field_type = fields[0]
    products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        entity_text_override=subject,
        field_type_override=field_type,
    )
    decision = customer_entity_resolution_contract.can_resolve_single_product(entity_contract, products)
    field = next(
        (item for item in customer_field_contract.FIELD_CONTRACTS if item.field_type == field_type),
        None,
    )
    field_label = customer_field_contract.product_detail_field_label(field_type)
    if field is None or not field_label:
        return None
    field_contract = {
        "field_type": field_type,
        "requested_field": field_label,
        "requested_fields": [field_label],
        "canonical_fields": [field_type],
        "supported_fields": [field_type],
        "unsupported_fields": [],
        "subject": subject,
        "requested_scope": "subject",
        "source": "recovered_semantic_named_detail_candidate",
        "confidence": float(candidate.get("confidence") or 0),
        "compound": False,
    }
    if entity_contract.status == "ambiguous":
        # A malformed structured-filter payload still cannot select a SKU,
        # but its independent single-field candidate must survive into the
        # normal entity clarification.  This keeps the field, candidate set,
        # and result_skus contract observable instead of replacing it with a
        # generic multi-filter error.
        result = _build_phase2_entity_state_response(
            db,
            question,
            {
                "action": "ambiguous_clarification",
                "contract": entity_contract,
                "products": products,
                "displayable_candidate_skus": _displayable_phase2_clarification_candidate_skus(entity_contract),
            },
        )
        if not isinstance(result, dict):
            return None
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["agent_mode"] = "invalid_structured_query_named_detail_ambiguous_contract"
        debug["field_contract"] = field_contract
        debug["entity_resolution_contract"] = entity_contract.to_dict()
        result["debug"] = debug
        metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
        metadata["contract_field_type"] = field_type
        metadata["source"] = "invalid_structured_query_named_detail_ambiguous_contract"
        result["answer_metadata"] = metadata
        return result
    if not (
        decision.allowed
        and entity_contract.is_unique
        and entity_contract.confidence == "high"
        and entity_contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
    ):
        return None
    result = _build_phase2_entity_state_response(
        db,
        question,
        {
            "action": "resolved_detail",
            "contract": entity_contract,
            "products": products,
            "field": field,
            "requested_field": field_label,
        },
    )
    if not isinstance(result, dict):
        return None
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["agent_mode"] = "invalid_structured_query_named_detail_contract"
    debug["field_contract"] = field_contract
    result["debug"] = debug
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    metadata["contract_field_type"] = field_type
    metadata["source"] = "invalid_structured_query_named_detail_contract"
    result["answer_metadata"] = metadata
    return result


def _semantic_preplan_unavailable_clarification_result(
    preplan: dict[str, Any] | None,
    *,
    db: Session | None = None,
    question: str = "",
    phase1_plan: dict[str, Any] | None = None,
) -> dict | None:
    """Prevent an unavailable semantic planner from reopening legacy routing.

    A deterministic FieldContract adapter remains usable for a canonical,
    allowlisted field that the legacy planner has already recognized.  That is a
    narrow outage fallback, not a second language router: it must still seal an
    entity and consume same-SKU evidence.  Without that formal contract, an LLM
    outage conveys no safe meaning for an ordinary natural language turn, so
    legacy QA/usage/recommendation shortcuts must not guess.
    """
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return None
    if not str(preplan.get("fallback_reason") or "").startswith("llm_error:"):
        return None
    if preplan.get("semantic_adapter_source"):
        return None
    # An outage must not erase a comparison or multi-field detail contract
    # whose participants are already explicit and can be sealed
    # deterministically.  These paths do not infer a recommendation from
    # wording: every named participant still receives an
    # EntityResolutionContract and every field still needs same-SKU evidence.
    named_products = _products_named_in_question(db, question) if db is not None else []
    if len(named_products) >= 2:
        return None
    outage_field_contract = resolve_requested_field_contract(question, phase1_plan)
    if (
        outage_field_contract.get("canonical_fields")
        and named_products
    ):
        return None
    # Recommendation intent is semantic-owned. During an outage, never let a
    # later lexical field match decide that a recommendation is merely a
    # filter; return the same fail-closed clarification before any shortcut.
    if _looks_like_recommendation_request(question):
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": "当前语义理解服务暂时不可用。为避免把你的推荐条件误判为普通商品筛选，请稍后重试，或补充明确的商品名称/SKU和要查询的信息。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "evidence": [],
            "answer_metadata": {"source": "semantic_preplan_unavailable_clarification"},
            "debug": {
                "agent_mode": "semantic_preplan_unavailable_clarification",
                "semantic_fallback_reason": str(preplan.get("fallback_reason") or ""),
            },
            "skip_polish": True,
        }
    if str(preplan.get("field_type") or "").strip() or preplan.get("canonical_fields"):
        # A recommendation remains a semantic decision even if one of its
        # words resembles a formal detail field (for example, a heat source).
        # During a model outage do not let that partial lexical contract reopen
        # a legacy catalogue recommender; it cannot know the requested subject
        # or the customer's preference priority.
        if (
            (isinstance(phase1_plan, dict) and str(phase1_plan.get("primary_intent") or "") == "recommendation")
            or _looks_like_recommendation_request(question)
        ):
            return {
                "intent": "clarify",
                "answer_type": "clarification",
                "answer": "当前语义理解服务暂时不可用。为避免把你的推荐条件误判为普通商品筛选，请稍后重试，或补充明确的商品名称/SKU和要查询的信息。",
                "results": [],
                "result_skus": [],
                "candidate_skus": [],
                "evidence": [],
                "answer_metadata": {"source": "semantic_preplan_unavailable_clarification"},
                "debug": {
                    "agent_mode": "semantic_preplan_unavailable_clarification",
                    "semantic_fallback_reason": str(preplan.get("fallback_reason") or ""),
                },
                "skip_polish": True,
            }
        return None
    field_contract = resolve_requested_field_contract(question, phase1_plan)
    if str(field_contract.get("field_type") or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS:
        return None
    # Do not preempt the later named-product outage guard.  That guard first
    # seals EntityResolutionContract and returns a clarification carrying the
    # resolved identity; the generic branch below is only for genuinely
    # unbound natural-language turns.
    if db is not None and _products_named_in_question(db, question):
        return None
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "当前语义理解服务暂时不可用。为避免把你的问题误判为其他商品字段，请稍后重试，或补充明确的商品名称/SKU和要查询的信息。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "evidence": [],
        "answer_metadata": {"source": "semantic_preplan_unavailable_clarification"},
        "debug": {
            "agent_mode": "semantic_preplan_unavailable_clarification",
            "semantic_fallback_reason": str(preplan.get("fallback_reason") or ""),
        },
        "skip_polish": True,
    }


def _phase1_structured_recommendation_result(db: Session, plan: dict) -> dict | None:
    scenario = str(plan.get("scenario") or plan.get("raw_question") or "").strip()
    if not scenario:
        return None
    semantic_preplan = plan.get("semantic_preplan") if isinstance(plan, dict) else None
    if isinstance(semantic_preplan, dict) and semantic_preplan.get("called"):
        # Once semantic planning has seen a recommendation turn, the legacy
        # scenario recognizers are no longer allowed to decide its product
        # scope or emit a fixed candidate list.  A valid semantic contract is
        # executed by the central recommendation/comparison path; an invalid
        # one is deliberately clarified there.  This boundary is based only
        # on semantic provenance, never on wording or a product identifier.
        return None
    # The planner's recommendation label is not authority to discard an
    # unresolved product-like subject.  Candidate generation is allowed only
    # for a genuine category/constraint request; a named-but-unmatched product
    # must first receive an unresolved EntityResolutionContract response.
    if _has_unresolved_product_like_scope(db, scenario):
        return None
    scope_text = " ".join(
        part for part in (
            str(plan.get("scenario") or "").strip(),
            str(plan.get("raw_question") or "").strip(),
        )
        if part
    )
    rows = _phase1_catalog_rows(db, "产品")
    if (
        any(term in scope_text for term in ("酒精炉", "液体酒精", "固体酒精", "alcohol stove"))
        and any(term in scope_text for term in ("锅", "锅具", "套锅", "单锅", "炊具"))
        and not any(term in scope_text for term in ("水壶", "茶壶", "烧水壶", "壶类"))
    ):
        exact_rows = [
            row for row in rows
            if _is_service_pot_or_cookware_set_candidate(row) and _phase1_row_has_explicit_alcohol_stove_support(db, row)
        ]
        if exact_rows:
            selected = exact_rows[:5]
            lines = ["当前资料里明确标注适合酒精炉的锅具，优先看下面这些："]
            for row in selected[:3]:
                name = row.get("product_name_cn") or row.get("sku")
                sku = str(row.get("sku") or "").strip().upper()
                heat_source = str(row.get("heat_source") or "").strip() or "同SKU资料/问答明确显示支持酒精炉"
                lines.append(f"- {name}（{sku}），明确证据：{heat_source}")
            skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
            return {
                "intent": "recommendation",
                "answer_type": "recommendation",
                "answer": "\n".join(lines),
                "results": selected,
                "result_skus": skus,
                "candidate_skus": skus,
                "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
                "answer_metadata": {"source": "product_catalog_structured_recommendation"},
                "skip_polish": True,
            }
        fallback_rows = [row for row in rows if _is_service_pot_or_cookware_set_candidate(row)][:3]
        if fallback_rows:
            fallback_lines = [
                "当前资料里没有找到明确标注适合酒精炉的锅具。",
                "下面这些只能作为普通锅具替代参考；它们没有酒精炉证据，不能直接当成酒精炉适配推荐：",
            ]
            for row in fallback_rows:
                name = row.get("product_name_cn") or row.get("sku")
                sku = str(row.get("sku") or "").strip().upper()
                reason = str(row.get("usage_scenarios") or row.get("features") or row.get("positioning") or "可作为同类替代").strip("。；; ")
                fallback_lines.append(f"- {name}（{sku}），{reason}")
            skus = [str(row.get("sku") or "").strip().upper() for row in fallback_rows if row.get("sku")]
            return {
                "intent": "recommendation",
                "answer_type": "recommendation",
                "answer": "\n".join(fallback_lines),
                "results": fallback_rows,
                "result_skus": skus,
                "candidate_skus": skus,
                "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
                "answer_metadata": {"source": "product_catalog_structured_recommendation"},
                "skip_polish": True,
            }
    if _phase1_is_water_kettle_selection_scenario(scenario):
        water_kettle_result = _phase1_structured_water_kettle_result(scenario, rows)
        if water_kettle_result:
            return water_kettle_result
    if _phase1_is_light_budget_cookware_set_scenario(scenario):
        light_budget_set_result = _phase1_structured_light_budget_cookware_set_result(scenario, rows)
        if light_budget_set_result:
            return light_budget_set_result
    if _phase1_is_griddle_vs_cookware_scenario(scenario):
        griddle_vs_cookware_result = _phase1_structured_griddle_vs_cookware_result(scenario, rows)
        if griddle_vs_cookware_result:
            return griddle_vs_cookware_result
    if _phase1_is_stove_pairing_scenario(scenario):
        stove_pairing_result = _phase1_structured_stove_pairing_result(scenario, rows)
        if stove_pairing_result:
            return stove_pairing_result
    if _phase1_is_stove_griddle_combo_scenario(scenario):
        combo_result = _phase1_structured_stove_griddle_result(scenario, rows)
        if combo_result:
            return combo_result
    scope_ref = _phase1_explicit_recommendation_scope_ref(scope_text)
    if scope_ref:
        rows = _phase1_catalog_rows(db, scope_ref)
        if scope_ref == "烤盘":
            rows = [
                row
                for row in rows
                if any(
                    term in " ".join(
                        str(row.get(key) or "")
                        for key in ("product_name_cn", "product_name_en", "category", "capacity", "features")
                    ).lower()
                    for term in ("烤盘", "煎盘", "griddle")
                )
            ]
    scored: list[tuple[int, dict]] = []
    for row in rows:
        haystack = " ".join(
            str(row.get(key) or "")
            for key in (
                "sku",
                "product_name_cn",
                "category",
                "capacity",
                "features",
                "usage_scenarios",
                "positioning",
                "long_description_cn",
            )
        )
        category = str(row.get("category") or "")
        score = 0
        if any(term in scenario for term in ("锅", "锅具", "套锅", "单锅", "炊具")):
            if "锅" in category:
                score += 8
            elif not _phase1_is_stove_griddle_combo_scenario(scenario):
                score -= 10
        if any(term in scenario for term in ("套锅", "套装")):
            if any(term in haystack for term in ("套锅", "套装", "锅5件套", "锅7件套", "锅10件套")):
                score += 8
            elif "锅" in category:
                score += 2
            else:
                score -= 8
        if "野餐" in scenario and "野餐" in haystack:
            score += 6
        if any(term in scenario for term in ("两个人", "2人", "两人", "双人")) and any(term in haystack for term in ("2人", "2-3人", "两人", "两个人", "双人")):
            score += 5
        if any(term in scenario for term in ("轻露营", "轻一点", "轻量", "轻便")) and any(term in haystack for term in ("轻量", "轻便", "便携", "收纳", "套娃")):
            score += 4
        if any(term in scenario for term in ("别太单薄", "稳一点", "稳定")) and any(term in haystack for term in ("稳", "稳定", "硬质氧化", "不锈钢", "厚实")):
            score += 4
        if "周末" in scenario and any(term in haystack for term in ("周末", "短途", "公园", "家庭野餐")):
            score += 2
        if "徒步" in scenario and "徒步" in haystack:
            score += 8
        if any(term in scenario for term in ("长途徒步", "只想带一个锅", "一个锅", "单锅")) and any(term in haystack for term in ("单锅", "轻量", "徒步", "套娃")):
            score += 7
        if any(term in scenario for term in ("一个人", "单人", "1人")) and any(term in haystack for term in ("单人", "1人", "1-2人", "1000ML", "轻量")):
            score += 5
        if any(term in scenario for term in ("三口之家", "四五个", "多人", "家庭")) and any(term in haystack for term in ("3L", "3700ML", "多人", "家庭", "2-4人")):
            score += 7
        if any(term in scenario for term in ("容量", "正餐")) and any(term in haystack for term in ("3L", "3700ML", "大容量", "多人做饭")):
            score += 6
        if any(term in scenario for term in ("收纳", "别太差")) and any(term in haystack for term in ("收纳", "套娃", "便携")):
            score += 4
        if any(term in scenario for term in ("烧水", "简单餐食")) and any(term in haystack for term in ("水壶", "烧水", "做饭", "套锅")):
            score += 4
        if "轻量" in haystack or "便携" in haystack:
            score += 2
        if any(term in haystack for term in ("锅", "炉", "水壶", "套装")):
            score += 1
        if any(term in scenario for term in ("套锅", "套装", "锅")) and any(term in haystack for term in ("调料瓶", "三角架", "配件", "餐具")):
            score -= 12
        if any(term in haystack for term in ("烤盘", "煎盘", "griddle")):
            score -= 3
        if score > 0:
            scored.append((score, row))
    scored.sort(key=lambda item: (-item[0], str(item[1].get("sku") or "")))
    selected = [row for _, row in scored[:5]]
    if not selected:
        return None
    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    top_row = selected[0]
    top_name = top_row.get("product_name_cn") or top_row.get("sku")
    top_sku = top_row.get("sku")
    top_reason = top_row.get("usage_scenarios") or top_row.get("features") or top_row.get("positioning") or "匹配当前使用场景"
    answer = f"优先推荐 {top_name}（{top_sku}），因为它更贴合你当前场景，{top_reason}。"
    backups: list[str] = []
    for row in selected[1:3]:
        name = row.get("product_name_cn") or row.get("sku")
        sku = row.get("sku")
        reason = row.get("usage_scenarios") or row.get("features") or row.get("positioning") or "匹配当前使用场景"
        backups.append(f"{name}（{sku}），{reason}")
    if backups:
        answer += " 备选可以看" + "；".join(backups) + "。"
    scenario_label = "、".join(_phase1_scenario_labels(scenario)) or "当前"
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": f"按你“{scenario_label}”的需求，{answer}",
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {"source": "product_catalog_structured_recommendation"},
        "skip_polish": True,
    }


def _phase1_should_use_structured_recommendation(plan: dict) -> bool:
    scenario = str((plan or {}).get("scenario") or (plan or {}).get("raw_question") or "")
    if not scenario:
        return False
    if any(
        checker(scenario)
        for checker in (
            _phase1_is_light_budget_cookware_set_scenario,
            _phase1_is_griddle_vs_cookware_scenario,
            _phase1_is_stove_pairing_scenario,
            _phase1_is_stove_griddle_combo_scenario,
        )
    ):
        return True
    if any(term in scenario for term in ("想买套锅", "想买锅", "买套锅", "买锅", "买哪个", "应该买", "该买", "推荐", "怎么选", "希望", "想选")):
        return True
    return any(term in scenario for term in ("露营", "野餐", "徒步", "公园", "自驾", "家庭", "烧烤", "早餐")) and any(
        term in scenario for term in ("锅", "锅具", "套锅", "单锅", "炊具", "炉具", "炉子", "烤盘", "正餐", "做正餐", "烧水", "做简单餐食", "煎东西")
    )


def _phase1_force_structured_recommendation_rebuild(question: str) -> bool:
    scenario = str(question or "").strip()
    if not scenario:
        return False
    return any(
        checker(scenario)
        for checker in (
            _phase1_is_light_budget_cookware_set_scenario,
            _phase1_is_griddle_vs_cookware_scenario,
            _phase1_is_stove_pairing_scenario,
            _phase1_is_stove_griddle_combo_scenario,
        )
    )


def _phase1_scenario_labels(scenario: str) -> list[str]:
    labels = []
    for term in ("家庭", "周末", "三口之家", "两个人", "三个人", "一个人", "多人", "野餐", "公园", "露营", "徒步", "自驾", "火锅", "烧烤", "早餐", "轻量", "轻便", "容量优先", "收纳", "套锅", "锅具", "炉具", "烤盘"):
        if term in scenario and term not in labels:
            labels.append(term)
    return labels


def _phase1_repair_recommendation_result(db: Session, agent_result: dict, plan: dict) -> dict:
    if not isinstance(agent_result, dict) or not _phase1_should_use_structured_recommendation(plan):
        return agent_result
    scenario = str((plan or {}).get("scenario") or (plan or {}).get("raw_question") or "")
    scope_text = " ".join(
        part for part in (
            str((plan or {}).get("scenario") or "").strip(),
            str((plan or {}).get("raw_question") or "").strip(),
        )
        if part
    )
    if (
        any(term in scope_text for term in ("酒精炉", "液体酒精", "固体酒精", "alcohol stove"))
        and any(term in scope_text for term in ("锅", "锅具", "套锅", "单锅", "炊具"))
        and not any(term in scope_text for term in ("水壶", "茶壶", "烧水壶", "壶类"))
    ):
        return agent_result
    force_rebuild = _phase1_force_structured_recommendation_rebuild(scenario)
    if (
        str(agent_result.get("answer_type") or "").strip() == "recommendation"
        and _phase1_answer_mentions_product(agent_result)
        and _phase1_result_skus(agent_result)
        and not force_rebuild
    ):
        return agent_result
    if (plan or {}).get("primary_intent") not in {"recommendation", "product_query"} and str(agent_result.get("answer_type") or "").strip() not in {"query_products", "product_query", "recommendation"}:
        return agent_result
    rebuilt = _phase1_structured_recommendation_result(db, plan)
    return rebuilt or agent_result


def _phase1_is_stove_griddle_combo_scenario(question: str) -> bool:
    value = str(question or "").strip()
    if not value:
        return False
    if customer_agent_intent_service._is_barbecue_stove_griddle_dual_scope_question(value):
        return True
    if not any(term in value for term in ("烤盘", "煎盘", "煎东西")):
        return False
    return any(term in value for term in ("烧烤", "炉具", "炉子", "怎么搭", "更合适", "先买哪类", "先买哪个"))


def _phase1_is_light_budget_cookware_set_scenario(question: str) -> bool:
    value = str(question or "").strip()
    if not value:
        return False
    has_two_person = any(term in value for term in ("双人", "两人", "两个人", "2人", "情侣"))
    has_camping = any(term in value for term in ("露营", "野营", "户外"))
    has_lightweight = any(term in value for term in ("轻", "轻量", "轻便", "不想太重", "别太重"))
    has_budget = any(term in value for term in ("不想买太贵", "不想太贵", "别太贵", "不太贵", "预算", "入门", "性价比"))
    has_set_selection = any(term in value for term in ("哪套", "推荐哪套", "买哪套", "选哪套", "套锅", "套装"))
    has_cookware_scope = any(term in value for term in ("锅具", "炊具", "套锅", "锅", "买套", "一套"))
    has_cooking_usage = any(term in value for term in ("做饭", "煮饭", "煮面", "正餐", "烹饪"))
    has_purchase_or_selection = any(
        term in value for term in ("想买", "买", "推荐", "怎么选", "该买", "选", "用什么", "推荐几款", "推荐几个", "有什么推荐")
    )
    if not (has_two_person and has_camping):
        return False
    if has_cookware_scope and has_purchase_or_selection:
        return True
    if has_budget and (has_set_selection or has_cookware_scope):
        return True
    return has_lightweight and has_cookware_scope and has_purchase_or_selection


def _phase1_is_water_kettle_selection_scenario(question: str) -> bool:
    value = str(question or "").strip()
    if not value:
        return False
    if _phase1_is_stove_pairing_scenario(value) or _phase1_is_stove_griddle_combo_scenario(value):
        return False
    has_water_scope = any(term in value for term in ("水壶", "烧水壶", "茶壶", "水具", "壶"))
    if not has_water_scope:
        return False
    has_selection = any(term in value for term in ("怎么选", "推荐", "买", "想买", "选", "哪个", "哪款", "更稳"))
    has_water_usage = any(term in value for term in ("喝热水", "热水", "烧水", "煮水", "泡茶", "热饮", "饮水", "补水"))
    has_lightweight = any(term in value for term in ("轻", "轻量", "轻便", "好带", "便携"))
    has_outdoor = any(term in value for term in ("露营", "野营", "户外", "野餐"))
    if has_selection and (has_water_usage or (has_lightweight and has_outdoor)):
        return True
    return has_lightweight and has_outdoor and any(term in value for term in ("水具", "水壶", "壶"))


def _phase1_is_griddle_vs_cookware_scenario(question: str) -> bool:
    value = str(question or "").strip()
    if not value:
        return False
    has_griddle_scope = any(term in value for term in ("烤盘", "煎盘"))
    has_cookware_scope = any(term in value for term in ("锅具", "锅", "套锅", "单锅"))
    has_compare_or_selection = any(
        term in value
        for term in ("还是", "哪个更合适", "更合适", "推荐", "更实用", "更好", "优先选", "更适用", "哪个更值得", "更值得", "先买")
    )
    has_grill_breakfast_signal = any(term in value for term in ("煎烤", "煎东西", "煎烤食物", "早餐"))
    return (
        has_griddle_scope
        and has_cookware_scope
        and has_compare_or_selection
        and has_grill_breakfast_signal
    )


def _phase1_is_water_kettle_candidate(row: dict[str, Any]) -> bool:
    if not isinstance(row, dict):
        return False
    category = str(row.get("category") or "").strip()
    text = " ".join(
        str(row.get(key) or "")
        for key in (
            "sku",
            "product_name_cn",
            "product_name_en",
            "category",
            "sub_category",
            "capacity",
            "features",
            "usage_scenarios",
            "positioning",
            "long_description_cn",
        )
    )
    if any(term in text for term in ("调料瓶", "配件", "三角架", "收纳袋", "收纳包", "点火器", "炉具")):
        return False
    if category in {"水具", "水壶"}:
        return True
    return any(term in text for term in ("水壶", "烧水壶", "保温壶", "冷水壶", "便携水具", "户外杯", "保温杯"))


def _phase1_is_strict_water_kettle_candidate(row: dict[str, Any]) -> bool:
    return customer_structured_query_contract.resolve_structured_subject_scope(
        row=row,
        subject_category="水壶",
    )["matched"]


def _phase1_structured_water_kettle_result(scenario: str, rows: list[dict]) -> dict | None:
    water_rows = [row for row in rows if _phase1_is_water_kettle_candidate(row)]
    if not water_rows:
        return None

    def _rank(row: dict) -> tuple[int, str]:
        category = str(row.get("category") or "").strip()
        text = " ".join(
            str(row.get(key) or "")
            for key in (
                "product_name_cn",
                "category",
                "capacity",
                "features",
                "usage_scenarios",
                "positioning",
                "price_positioning",
                "long_description_cn",
            )
        )
        score = 0
        if category == "水壶":
            score += 9
        elif category == "水具":
            score += 7
        if any(term in text for term in ("烧水", "煮水", "热水", "泡茶", "热饮", "煮茶")):
            score += 6
        if any(term in text for term in ("轻量", "轻便", "便携", "随行", "补水")):
            score += 4
        if any(term in scenario for term in ("双人", "两人", "两个人", "情侣")) and any(term in text for term in ("双人", "两人", "两个人", "情侣")):
            score += 3
        if any(term in scenario for term in ("泡茶", "热饮")) and any(term in text for term in ("泡茶", "煮茶", "热饮")):
            score += 3
        try:
            weight_value = float(row.get("gross_weight_g") or 0)
        except (TypeError, ValueError):
            weight_value = 0
        if 0 < weight_value <= 250:
            score += 3
        elif 250 < weight_value <= 400:
            score += 2
        return (-score, str(row.get("sku") or ""))

    selected = sorted(water_rows, key=_rank)[:5]
    if not selected:
        return None
    top_row = selected[0]
    top_name = top_row.get("product_name_cn") or top_row.get("sku")
    top_sku = str(top_row.get("sku") or "").strip().upper()
    top_reason = str(top_row.get("usage_scenarios") or top_row.get("features") or top_row.get("positioning") or "更适合露营热饮和烧水场景").strip("。；; ")
    answer = f"这类需求我会优先从水壶/水具域里选，不把调料瓶或普通配件放到主推前排。主推 {top_name}（{top_sku}），更贴合喝热水、烧水或泡茶这类场景。"
    if top_reason:
        answer += f" 主要理由是：{top_reason}。"
    backups: list[str] = []
    for row in selected[1:3]:
        name = row.get("product_name_cn") or row.get("sku")
        sku = str(row.get("sku") or "").strip().upper()
        reason = str(row.get("usage_scenarios") or row.get("features") or row.get("positioning") or "可作为同域备选").strip("。；; ")
        backups.append(f"{name}（{sku}），{reason}")
    if backups:
        answer += " 备选可以看" + "；".join(backups) + "。"
    answer += " 如果你更偏向频繁烧水或泡茶，优先看壶型和热饮场景更明确的款；如果更偏向日常补水，再看轻便杯具。"
    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {"source": "product_catalog_structured_recommendation"},
        "skip_polish": True,
    }


def _phase1_is_stove_pairing_scenario(question: str) -> bool:
    value = str(question or "").strip()
    if not value:
        return False
    if _phase1_is_stove_griddle_combo_scenario(value):
        return False
    has_stove_scope = any(term in value for term in ("炉具", "炉子"))
    has_pairing_or_selection = any(
        term in value
        for term in ("怎么搭", "怎么配", "怎么选", "该怎么选", "更稳", "稳一点", "兼顾", "先买", "先补", "先选", "先选什么", "先选哪个", "还是水壶")
    )
    has_bbq_signal = any(term in value for term in ("烧烤", "烤肉", "烤东西"))
    has_water_signal = any(term in value for term in ("烧水", "煮水", "热饮", "加热饮", "泡茶", "热水"))
    has_stove_scene_signal = any(term in value for term in ("营地聚餐", "风大", "防风")) or (has_bbq_signal and has_water_signal)
    return has_stove_scope and has_pairing_or_selection and has_stove_scene_signal


def _phase1_structured_light_budget_cookware_set_result(scenario: str, rows: list[dict]) -> dict | None:
    cookware_rows = [row for row in rows if _is_service_pot_or_cookware_set_candidate(row)]
    if not cookware_rows:
        return None
    scenario_text = str(scenario or "")
    has_lightweight = any(term in scenario_text for term in ("轻", "轻量", "轻便", "不想太重", "别太重"))
    has_budget = any(term in scenario_text for term in ("不想买太贵", "不想太贵", "别太贵", "不太贵", "预算", "入门", "性价比"))
    has_set_selection = any(term in scenario_text for term in ("哪套", "推荐哪套", "买哪套", "选哪套", "套锅", "套装"))
    has_cooking_usage = any(term in scenario_text for term in ("做饭", "煮饭", "煮面", "正餐", "烹饪"))

    def _rank(row: dict) -> tuple[int, str]:
        text = " ".join(
            str(row.get(key) or "")
            for key in (
                "product_name_cn",
                "category",
                "capacity",
                "features",
                "usage_scenarios",
                "positioning",
                "price_positioning",
                "long_description_cn",
            )
        )
        score = 0
        if any(term in text for term in ("套锅", "套装", "锅5件套", "锅7件套", "锅10件套", "野餐锅")):
            score += 10
        if any(term in text for term in ("双人", "两人", "两个人", "2人", "2-3人")):
            score += 8
        if any(term in text for term in ("轻量", "轻便", "便携", "收纳", "套娃")):
            score += 6
        if has_cooking_usage and any(term in text for term in ("做饭", "煮饭", "煮面", "正餐", "烹饪")):
            score += 4
        if any(term in text for term in ("入门", "性价比", "基础", "中端", "周末野餐")):
            score += 4
        if any(term in text for term in ("高端", "礼盒")):
            score -= 3
        weight = row.get("gross_weight_g")
        try:
            weight_value = float(weight or 0)
        except (TypeError, ValueError):
            weight_value = 0
        if 0 < weight_value <= 800:
            score += 5
        elif 800 < weight_value <= 1200:
            score += 3
        elif weight_value >= 1800:
            score -= 3
        return (-score, str(row.get("sku") or ""))

    selected = sorted(cookware_rows, key=_rank)[:5]
    if not selected:
        return None
    top_row = selected[0]
    top_name = top_row.get("product_name_cn") or top_row.get("sku")
    top_sku = str(top_row.get("sku") or "").strip().upper()
    top_reason = str(top_row.get("usage_scenarios") or top_row.get("features") or top_row.get("positioning") or "").strip("。；; ")
    demand_bits = ["双人露营"]
    if has_lightweight:
        demand_bits.append("轻便好带")
    if has_budget:
        demand_bits.append("入门取舍")
    if has_set_selection:
        demand_bits.append("套锅/套装")
    if has_cooking_usage:
        demand_bits.append("做饭用锅")
    demand_label = "、".join(dict.fromkeys(demand_bits))
    answer = (
        f"这类需求我会优先从双人露营的锅具/套锅里选，不先把水壶当主推。"
        f" 优先推荐 {top_name}（{top_sku}），更贴合“{demand_label}”这类需求。"
    )
    if top_reason:
        answer += f" 主要理由是：{top_reason}。"
    backups: list[str] = []
    for row in selected[1:3]:
        name = row.get("product_name_cn") or row.get("sku")
        sku = str(row.get("sku") or "").strip().upper()
        reason = str(row.get("usage_scenarios") or row.get("features") or row.get("positioning") or "更偏向双人露营的套装取舍").strip("。；; ")
        backups.append(f"{name}（{sku}），{reason}")
    if backups:
        answer += " 备选可以看" + "；".join(backups) + "。"
    if has_lightweight:
        answer += " 如果你更在意极致轻量，就优先看更轻便的小套锅；"
    if has_cooking_usage or not has_lightweight:
        answer += " 如果你更在意两个人做饭的完整度，再看容量和组件更全的套装。"
    else:
        answer += " 如果你更在意两个人做饭的完整度，再看容量和组件更全的套装。"
    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {
            "source": "product_catalog_structured_recommendation",
            "preserved_scope_statement": "这类需求我会优先从双人露营的锅具/套锅里选，不先把水壶当主推。",
        },
        "skip_polish": True,
    }


def _phase1_structured_griddle_vs_cookware_result(scenario: str, rows: list[dict]) -> dict | None:
    griddle_rows = [row for row in rows if customer_agent_intent_service._is_barbecue_griddle_candidate_row(row)]
    cookware_rows = [row for row in rows if _is_service_pot_or_cookware_set_candidate(row)]
    if not griddle_rows or not cookware_rows:
        return None

    def _rank_griddle(row: dict) -> tuple[int, str]:
        text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "features", "usage_scenarios", "positioning", "category"))
        score = 0
        if any(term in text for term in ("烤盘", "煎盘", "煎烤", "早餐")):
            score += 8
        if "导热盘" in text:
            score -= 8
        return (-score, str(row.get("sku") or ""))

    def _rank_cookware(row: dict) -> tuple[int, str]:
        text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "features", "usage_scenarios", "positioning", "category"))
        score = 0
        if any(term in text for term in ("锅", "套锅", "烧水", "正餐", "通用", "多场景")):
            score += 6
        if any(term in text for term in ("轻量", "便携", "收纳")):
            score += 2
        return (-score, str(row.get("sku") or ""))

    best_griddle = sorted(griddle_rows, key=_rank_griddle)[0]
    best_cookware = sorted(cookware_rows, key=_rank_cookware)[0]
    selected = [best_griddle]
    if str(best_cookware.get("sku") or "").strip().upper() != str(best_griddle.get("sku") or "").strip().upper():
        selected.append(best_cookware)

    griddle_name = best_griddle.get("product_name_cn") or best_griddle.get("sku")
    griddle_sku = best_griddle.get("sku")
    cookware_name = best_cookware.get("product_name_cn") or best_cookware.get("sku")
    cookware_sku = best_cookware.get("sku")
    answer = (
        f"如果你的重点是早餐煎烤，我会优先推荐烤盘 {griddle_name}（{griddle_sku}），配合炉具使用会更贴合煎、烤这类用法。"
        f"如果你还想兼顾烧水、煮面或正餐，备选可以看锅具 {cookware_name}（{cookware_sku}），会更通用。"
        "简单说：偏煎烤先烤盘，想一套多用再补锅具。"
    )
    skus = [str(row.get('sku') or '').strip().upper() for row in selected if row.get('sku')]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": answer,
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {"source": "product_catalog_structured_recommendation"},
        "skip_polish": True,
    }


def _phase1_structured_stove_pairing_result(scenario: str, rows: list[dict]) -> dict | None:
    stove_rows = [
        row
        for row in rows
        if str(row.get("category") or "").strip() == "炉具"
        and customer_agent_intent_service._is_barbecue_stove_candidate_row(row)
    ]
    if not stove_rows:
        return None

    def _rank_stove(row: dict) -> tuple[int, str]:
        text = " ".join(
            str(row.get(key) or "")
            for key in ("product_name_cn", "features", "usage_scenarios", "positioning", "category")
        )
        score = 0
        if any(term in text for term in ("炉具", "炉子", "桌面炉", "卡式炉", "烧烤炉")):
            score += 8
        if any(term in text for term in ("稳定", "火力", "稳", "防风")):
            score += 6
        if any(term in text for term in ("烧烤", "烤肉", "桌面聚餐", "露营烧烤", "营地聚餐")):
            score += 5
        if any(term in text for term in ("烧水", "煮水", "热饮", "煮茶", "泡茶", "加热饮", "热水")):
            score += 3
        return (-score, str(row.get("sku") or ""))

    stove_rows = sorted(stove_rows, key=_rank_stove)
    selected = stove_rows[:4]
    if not selected:
        return None

    top_row = selected[0]
    top_name = top_row.get("product_name_cn") or top_row.get("sku")
    top_sku = top_row.get("sku")
    top_reason = top_row.get("features") or top_row.get("usage_scenarios") or "更适合烧烤主加热场景"

    answer_parts = [
        f"这类需求我会优先按炉具域来配，先用 {top_name}（{top_sku}）承担烧烤和主加热，{top_reason}。"
    ]
    if any(term in scenario for term in ("烧水", "煮水", "热饮", "加热饮", "泡茶", "热水")):
        answer_parts.append("如果还要兼顾烧水或热饮，建议在同一套炉具体系下搭配壶或锅处理，不要先把水壶本身当主设备。")
    if any(term in scenario for term in ("风大", "海边", "防风")):
        answer_parts.append("风大的场景优先看防风能力、支撑稳定性和低重心结构，先把炉具本体选稳，再考虑其他搭配。")
    if len(selected) > 1:
        backup = selected[1]
        backup_name = backup.get("product_name_cn") or backup.get("sku")
        backup_sku = backup.get("sku")
        backup_reason = backup.get("features") or backup.get("usage_scenarios") or "更适合作为同气源备选"
        answer_parts.append(
            f"备选炉具可以看 {backup_name}（{backup_sku}），{backup_reason}。"
        )
    answer_parts.append("搭配上优先考虑同一气源、稳定支撑和可控火力，这样烧烤和热饮切换会更稳，不建议先把调料瓶、水壶或普通配件放到主推前排。")

    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": " ".join(answer_parts),
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {"source": "product_catalog_structured_recommendation"},
        "skip_polish": True,
    }


def _phase1_structured_stove_griddle_result(scenario: str, rows: list[dict]) -> dict | None:
    stove_rows = [row for row in rows if customer_agent_intent_service._is_barbecue_stove_candidate_row(row)]
    griddle_rows = [row for row in rows if customer_agent_intent_service._is_barbecue_griddle_candidate_row(row)]
    if not stove_rows and not griddle_rows:
        return None

    def _rank_stove(row: dict) -> tuple[int, str]:
        text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "features", "usage_scenarios", "positioning", "category"))
        score = 0
        if any(term in text for term in ("烧烤", "火力", "稳定", "桌面炉", "卡式炉", "炉具")):
            score += 6
        if any(term in text for term in ("桌面聚餐", "露营烧烤", "家庭露营")):
            score += 4
        return (-score, str(row.get("sku") or ""))

    def _rank_griddle(row: dict) -> tuple[int, str]:
        text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "features", "usage_scenarios", "positioning", "category"))
        score = 0
        if any(term in text for term in ("烤盘", "煎盘", "煎烤", "早餐")):
            score += 7
        if "导热盘" in text:
            score -= 10
        return (-score, str(row.get("sku") or ""))

    stove_rows = sorted(stove_rows, key=_rank_stove)
    griddle_rows = sorted(griddle_rows, key=_rank_griddle)
    selected: list[dict] = []
    if stove_rows:
        selected.append(stove_rows[0])
    if len(stove_rows) > 1:
        selected.append(stove_rows[1])
    if griddle_rows:
        selected.append(griddle_rows[0])
    for row in stove_rows[2:] + griddle_rows[1:]:
        sku = str(row.get("sku") or "").strip().upper()
        if sku and sku not in {str(item.get("sku") or "").strip().upper() for item in selected}:
            selected.append(row)
        if len(selected) >= 4:
            break
    if not selected:
        return None

    stove_row = stove_rows[0] if stove_rows else None
    griddle_row = griddle_rows[0] if griddle_rows else None
    parts: list[str] = []
    if stove_row:
        stove_name = stove_row.get("product_name_cn") or stove_row.get("sku")
        stove_sku = stove_row.get("sku")
        stove_reason = stove_row.get("features") or stove_row.get("usage_scenarios") or "更适合露营烧烤场景"
        parts.append(f"炉具方向：优先看 {stove_name}（{stove_sku}），{stove_reason}。")
    if griddle_row:
        griddle_name = griddle_row.get("product_name_cn") or griddle_row.get("sku")
        griddle_sku = griddle_row.get("sku")
        griddle_reason = griddle_row.get("features") or griddle_row.get("usage_scenarios") or "适合煎烤搭配"
        parts.append(f"烤盘方向：备选可以看 {griddle_name}（{griddle_sku}），{griddle_reason}。")
    if "先买哪类" in scenario or "先买哪个" in scenario:
        parts.insert(0, "如果你这次只能先补一类，我更建议先把炉具补齐，再搭配烤盘。")
    elif "煎东西" in scenario or "早餐" in scenario:
        parts.insert(0, "如果你的重点是煎东西，烤盘会比普通锅具更对路；有稳定火力时再搭配炉具更完整。")
    else:
        parts.insert(0, "这类场景更适合按“炉具 + 烤盘”去搭，不建议先回到普通锅具或导热盘。")

    skus = [str(row.get("sku") or "").strip().upper() for row in selected if row.get("sku")]
    return {
        "intent": "recommendation",
        "answer_type": "recommendation",
        "answer": " ".join(parts),
        "results": selected,
        "result_skus": skus,
        "candidate_skus": skus,
        "debug": {"agent_mode": "planner_recommendation_guard_rebuild"},
        "answer_metadata": {"source": "product_catalog_structured_recommendation"},
        "skip_polish": True,
    }


def _phase1_is_alcohol_stove_cookware_question(
    question: str,
    candidate_context: dict[str, Any] | None = None,
    agent_result: dict | None = None,
) -> bool:
    text = str(question or "")
    if "酒精炉" not in text and "alcohol stove" not in text.lower():
        return False
    if SKU_RE.search(text) and any(term in text for term in ("能不能", "能否", "是否", "可不可以", "支持", "适用")):
        return False
    context = candidate_context if isinstance(candidate_context, dict) else {}
    if any(term in text for term in ("水壶", "茶壶", "烧水壶", "壶类")):
        return False
    if _is_service_pot_cookware_scope(
        str(context.get("product_scope") or ""),
        " ".join([text, str(context.get("user_question") or "")]),
    ):
        return True
    result_text = ""
    if isinstance(agent_result, dict):
        result_text = " ".join(
            str(value or "")
            for row in (agent_result.get("results") or [])
            if isinstance(row, dict)
            for value in (
                row.get("category"),
                row.get("product_name_cn"),
                row.get("product_name_en"),
            )
        )
    return _is_service_pot_cookware_scope(
        "",
        " ".join([text, result_text]),
    )


def _phase1_filter_alcohol_stove_cookware_result(
    db: Session,
    agent_result: dict | None,
    *,
    question: str,
    candidate_context: dict[str, Any] | None = None,
) -> dict | None:
    if not isinstance(agent_result, dict) or not _phase1_is_alcohol_stove_cookware_question(question, candidate_context, agent_result):
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    intent_debug = debug.get("intent") if isinstance(debug.get("intent"), dict) else {}
    if (
        str(intent_debug.get("source_context") or "") == "previous_results"
        and not customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(question)
    ):
        # The candidate-domain executor has already evaluated the sealed rows
        # against same-SKU evidence.  A later global catalogue filter has a
        # narrower evidence view and must not erase that validated subset.
        return agent_result
    if str(debug.get("agent_mode") or "").startswith("recommendation_context_product_"):
        return agent_result
    is_list_query = bool(
        customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(question)
        and not customer_agent_service._extract_skus(question)
    )
    rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    if not rows:
        result_skus = {
            str(sku or "").strip().upper()
            for sku in (agent_result.get("result_skus") or [])
            if str(sku or "").strip()
        }
        if result_skus:
            rows = [
                row for row in _phase1_catalog_rows(db, "产品")
                if str(row.get("sku") or "").strip().upper() in result_skus
            ]
    if not rows:
        return agent_result
    products = db.query(Product).filter(Product.sku.in_([
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    ])).all()
    product_by_sku = {str(product.sku or "").strip().upper(): product for product in products}
    cookware_filtered = [
        row for row in rows
        if _is_service_pot_or_cookware_set_candidate(row, product_by_sku.get(str(row.get("sku") or "").strip().upper()))
    ]
    filtered = [
        row for row in cookware_filtered
        if _phase1_row_has_explicit_alcohol_stove_support(db, row)
    ]
    if len(filtered) == len(rows):
        result = dict(agent_result)
        skus = [str(row.get("sku") or "").strip().upper() for row in filtered if str(row.get("sku") or "").strip()]
        if is_list_query and str(result.get("answer_type") or "").strip() == "product_detail":
            result["intent"] = "query_products"
            result["answer_type"] = "product_query"
        return _sync_alcohol_stove_cookware_scope_metadata(result, skus=skus, rows=filtered, question=question)
    skus = [str(row.get("sku") or "").strip().upper() for row in filtered if str(row.get("sku") or "").strip()]
    result = dict(agent_result)
    result["results"] = filtered
    if is_list_query and str(result.get("answer_type") or "").strip() == "product_detail":
        result["intent"] = "query_products"
        result["answer_type"] = "product_query"
    result = _sync_alcohol_stove_cookware_scope_metadata(result, skus=skus, rows=filtered, question=question)
    lines = [
        "筛选条件：类目包含 锅具；必须有明确酒精炉支持证据。",
        "当前资料里只确认以下 SKU 明确支持酒精炉；其他锅具虽然可能支持明火、卡式炉、分体炉或一体炉，但没有明确酒精炉证据，我不建议直接归为酒精炉适用。",
    ]
    for row in filtered[:10]:
        name = row.get("product_name_cn") or row.get("name") or row.get("sku")
        sku = row.get("sku")
        heat_source = row.get("heat_source") or ((row.get("field_values") or {}).get("热源") if isinstance(row.get("field_values"), dict) else "")
        lines.append(f"- {name}（{sku}），明确证据：{heat_source or '同SKU资料/问答明确显示支持酒精炉'}")
    result["answer"] = "\n".join(lines)
    result["skip_polish"] = True
    return result


def _compound_display_value(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith("[") and text.endswith("]"):
        try:
            return _display_value(json.loads(text))
        except (TypeError, ValueError, json.JSONDecodeError):
            items = [item.strip().strip("'\"") for item in text[1:-1].split(",")]
            return "，".join(item for item in items if item)
    return text


def _record_semantic_compound_child(
    *,
    query: str,
    candidate: dict[str, Any] | None,
    compound_answers: list[dict[str, Any]],
    answered_requests: list[tuple[str, str]],
) -> bool:
    """Record one independently verified semantic child and its provenance.

    Related child requests may legitimately share one same-SKU evidence item.
    Deduplicating on a coarse provider label turned that valid support into a
    false missing-data tail. Each candidate has already passed its own
    semantic selection and grounding gates, so this layer records coverage
    without re-deciding relevance.
    """
    if not isinstance(candidate, dict):
        return False
    metadata = (
        candidate.get("answer_metadata")
        if isinstance(candidate.get("answer_metadata"), dict)
        else {}
    )
    evidence_ids = [
        str(item or "").strip()
        for item in (metadata.get("evidence_ids") or [])
        if str(item or "").strip()
    ]
    receipt = "|".join(dict.fromkeys(evidence_ids))
    if not receipt:
        receipt = str(
            metadata.get("evidence_source")
            or metadata.get("source")
            or "same_sku_child_evidence"
        ).strip()
    compound_answers.append(candidate)
    answered_requests.append((str(query or "").strip(), receipt))
    return True


async def _try_semantic_compound_child_answer(
    db: Session,
    child_question: str,
    child_plan: dict[str, Any],
) -> dict[str, Any] | None:
    """Resolve one LLM-issued child against the same sealed entity/evidence.

    A transient conservative reranker or grounding vote must not turn valid
    same-SKU file evidence into a false missing answer. Retry the identical
    sealed RAG request once; no wording, candidate, SKU, or contract is
    changed between attempts.
    """
    candidate = await _try_product_qa_shortcut_with_semantic_selection(
        db,
        child_question,
        phase1_plan=child_plan,
    )
    if _is_sealed_product_qa_safe_missing(candidate):
        candidate = None
    if candidate:
        return candidate
    for _rag_attempt in range(2):
        candidate = await _try_sealed_same_sku_knowledge_answer(
            db,
            child_question,
            child_plan,
        )
        if candidate:
            return candidate
    return None


async def _execute_composite_customer_question(
    db: Session,
    *,
    user_id: str,
    composite_question: dict[str, str],
    sku: str | None,
) -> dict | None:
    """Execute independently resolvable fact and recommendation tasks.

    The separator is semantic structure, not a product or sentence exception:
    each part receives its own identity/evidence route before their readable
    answers are merged.  This prevents the fact part's entity contract from
    treating the recommendation clause as part of its product subject.
    """
    fact_part = str(composite_question.get("fact_part") or "").strip()
    recommendation_part = _normalize_composite_recommendation_part(
        composite_question.get("recommendation_part") or ""
    )
    if not fact_part or not recommendation_part:
        return None
    options = {"allow_search_top1_promotion": True}
    # A compound fact still needs the same formal field/entity/evidence chain
    # as a standalone product question.  Do not hand it to the legacy intent
    # executor merely because a recommendation follows in the same utterance.
    fact_plan = customer_agent_planner_service.plan_customer_question(fact_part)
    fact_field_request = resolve_requested_field_contract(fact_part, fact_plan)
    fact_field = str(fact_field_request.get("field_type") or "").strip()
    fact_sku = _resolve_sku(db, fact_part, None)
    fact_label = customer_field_contract.product_detail_field_label(fact_field) if fact_field else ""
    explicit_multi_product_comparison = bool(
        len(customer_agent_service._extract_skus(fact_part)) >= 2
        and customer_agent_planner_service._is_compare_question(fact_part)
    )
    # A comparison is a multi-entity contract.  Even where it mentions a
    # field, its first SKU must not be treated as the whole fact clause; let
    # the comparison executor bind every named product before merging the
    # independently requested recommendation.
    fact_result = (
        _product_field_followup_result(
            db,
            fact_sku,
            fact_label,
            fact_part,
            # ``fact_sku`` was resolved from an explicit SKU token above.
            # Reuse the existing exact-SKU provenance rather than introducing
            # a parallel composite-only trust class.
            identity_source="explicit_sku_exact",
            field_request_override=fact_field_request,
        )
        if (
            not explicit_multi_product_comparison
            and fact_sku
            and fact_label
            and customer_field_contract.is_supported_detail_field(fact_field)
        )
        else None
    )
    if fact_result is None:
        fact_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=fact_part,
            sku=sku,
            previous_result_skus=[],
            allow_llm_fallback=False,
            **options,
        )
    fact_previous_result_skus = list(dict.fromkeys(
        str(item.get("sku") or "").strip().upper()
        for item in ((fact_result or {}).get("results") or [])
        if isinstance(item, dict) and str(item.get("sku") or "").strip()
    ) or [
        str(item or "").strip().upper()
        for item in ((fact_result or {}).get("result_skus") or [])
        if str(item or "").strip()
    ])
    recommendation_result = await customer_agent_intent_service.process_intent_request(
        db,
        user_id=user_id,
        question=recommendation_part,
        sku=None,
        previous_result_skus=fact_previous_result_skus,
        allow_llm_fallback=False,
        scoped_comparison_candidates=bool(
            len(fact_previous_result_skus) >= 2
            and any(term in fact_part for term in ("比较", "对比"))
            and "更适合" in recommendation_part
            and re.search(r"(?:[1-9]\d?|[一二两三四五六七八九十])\s*(?:个)?人", recommendation_part)
        ),
        **options,
    )
    if not fact_result and not recommendation_result:
        return None
    merged_result = dict(recommendation_result or fact_result or {})
    if fact_result and recommendation_result:
        if composite_question.get("order") == "recommendation_first":
            merged_result["answer"] = _merge_composite_answers(recommendation_result.get("answer", ""), fact_result.get("answer", ""))
        else:
            merged_result["answer"] = _merge_composite_answers(fact_result.get("answer", ""), recommendation_result.get("answer", ""))
        merged_result["intent"] = "recommendation"
        merged_result["answer_type"] = recommendation_result.get("answer_type") or fact_result.get("answer_type")
        merged_result["results"] = recommendation_result.get("results") or fact_result.get("results") or []
        merged_result["result_skus"] = recommendation_result.get("result_skus") or fact_result.get("result_skus") or []
    merged_result.setdefault("debug", {})
    merged_result["debug"]["composite_question"] = {
        "fact_part": fact_part,
        "recommendation_part": recommendation_part,
        "order": composite_question.get("order") or "fact_first",
        "strategy": "fact_contract_plus_recommendation",
    }
    return merged_result


def _heat_source_field_evidence(value: Any) -> str:
    """Normalize a structured heat-source cell into one readable list."""
    display = _compound_display_value(value)
    if not display:
        return ""
    items = [
        item.strip()
        for item in re.split(r"[、,，;；\r\n]+", display)
        if item.strip()
    ]
    return "、".join(dict.fromkeys(items))


def _selling_point_heat_source_evidence(value: Any) -> str:
    """Use a selling-point fallback only when it explicitly names a heat source."""
    text = _compound_display_value(value).strip()
    if not text:
        return ""
    markers = (
        "电陶炉", "电磁炉", "卡式炉", "酒精炉", "柴火炉", "燃气炉",
        "明火", "直火", "炭火", "固体燃料", "气罐",
    )
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and any(marker in clause for marker in markers)
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


_CAPACITY_VALUE_PATTERN = re.compile(
    r"(?<![\d.])\d+(?:\.\d+)?\s*(?:ml|毫升|l|升)(?![A-Za-z])",
    re.IGNORECASE,
)


def _capacity_field_evidence(value: Any) -> str:
    """Return only values that are structurally valid capacity evidence.

    The imported catalogue uses a JSON list for ``specs.capacity`` but also
    contains explicit placeholders and a few values copied from unrelated
    columns.  Same-SKU provenance alone is therefore insufficient: a capacity
    provider must also prove capacity-unit semantics before it can be exposed.
    """
    if value in (None, ""):
        return ""
    parsed: Any = value
    if isinstance(value, str):
        text = value.strip()
        if not text or text in {"[]", "/", "null", "None"}:
            return ""
        if text.startswith(("[", "{")):
            try:
                parsed = json.loads(text)
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = text

    items = parsed if isinstance(parsed, list) else [parsed]
    accepted: list[str] = []
    for item in items:
        display = _display_value(item).strip()
        if not display or not _CAPACITY_VALUE_PATTERN.search(display):
            continue
        accepted.append(display)
    return "，".join(dict.fromkeys(accepted))


def _color_field_evidence(value: Any) -> str:
    """Keep only explicit color tokens from the structured color column."""
    display = _compound_display_value(value)
    if not display:
        return ""
    items = [item.strip() for item in re.split(r"[、,，;；\r\n]+", display) if item.strip()]
    accepted = [
        item
        for item in items
        if "色" in item or any(char in _COLOR_FAMILY_CHARACTERS for char in item)
    ]
    return "、".join(dict.fromkeys(accepted))


def _dishwasher_specific_evidence(value: Any) -> str:
    """Return only clauses that explicitly state dishwasher compatibility."""
    text = str(value or "").strip()
    if not text or text in {"[]", "/"} or "洗碗机" not in text:
        return ""
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and "洗碗机" in clause
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


def _machine_wash_specific_evidence(value: Any) -> str:
    """Return only clauses that explicitly discuss laundry-machine washing."""
    text = str(value or "").strip()
    if not text or text in {"[]", "/"} or not any(term in text for term in ("洗衣机", "机洗")):
        return ""
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and any(term in clause for term in ("洗衣机", "机洗"))
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


_USAGE_INSTRUCTION_FIELD_MARKERS: dict[str, tuple[str, ...]] = {
    "cleaning": (
        "清洁", "清洗", "冲洗", "洗净", "擦洗", "擦拭", "刷洗",
        "去污", "污渍", "油污", "洗涤", "湿布", "温水", "洗洁精",
    ),
    "care": (
        "保养", "养护", "存放", "收纳", "晾干", "烘干", "擦干",
        "干燥", "防锈", "防霉", "通风", "长期不用", "避免潮湿",
        "定期检查",
    ),
}


def _liquid_temperature_capability_evidence(value: Any) -> str:
    """Keep only clauses that explicitly support liquid-temperature capability.

    A generic instruction such as "may contact hot food" does not establish
    whether a product can contain hot water.  This is evidence validation after
    the semantic FieldContract has selected ``usage_instruction``; it does not
    classify the user's wording or infer a capability from a product category.
    """
    text = str(value or "").strip()
    if not text or text in {"[]", "/"}:
        return ""
    markers = (
        "热水", "冷水", "开水", "沸水", "饮水", "补水",
        "保温", "热饮", "冷饮", "装水", "盛水", "液体",
        "装温水", "盛温水", "饮用温水",
    )
    clauses = [
        re.sub(r"\s+", " ", clause).strip()
        for clause in re.split(r"(?<=[。！？!?；;])\s*", text)
        if clause and clause.strip()
    ]
    return " ".join(
        clause for clause in clauses if any(marker in clause for marker in markers)
    ).strip()


def _usage_instruction_field_evidence(value: Any, canonical_field: str | None) -> str:
    """Select only usage-instruction clauses compatible with the requested field.

    ``specs.usage_instruction`` is a shared storage column, not proof that every
    row contains cleaning and care guidance.  The central FieldContract may use
    it as a provider, but the provider must fail closed when no clause carries
    the requested semantics.
    """
    text = str(value or "").strip()
    field_type = str(canonical_field or "").strip()
    if not text or text in {"[]", "/"}:
        return ""

    def clean_segment(segment: str) -> str:
        cleaned = re.sub(r"\s+", " ", str(segment or "")).strip()
        # Imported instruction cells occasionally contain a stray terminal
        # ASCII token glued to Chinese prose.  It is not actionable evidence
        # and should not be repeated to customers.
        cleaned = re.sub(r"(?<=[\u4e00-\u9fff])[A-Za-z]{3,}\s*$", "", cleaned).strip()
        return cleaned

    text = re.sub(
        r"(?<=[\u4e00-\u9fff])[A-Za-z]{3,}(?=\s*(?:$|\r?\n))",
        "",
        text,
        flags=re.MULTILINE,
    ).strip()
    if field_type == "usage_instruction":
        return clean_segment(text)
    markers = _USAGE_INSTRUCTION_FIELD_MARKERS.get(field_type)
    if not markers:
        return text

    def has_field_marker(segment: str, target_field: str, target_markers: tuple[str, ...]) -> bool:
        matched = [marker for marker in target_markers if marker in segment]
        if not matched:
            return False
        if (
            target_field == "care"
            and set(matched) == {"收纳"}
            and re.search(r"(?:从.{0,8}收纳(?:包|袋).{0,8}取出|取出.{0,8}收纳(?:包|袋))", segment)
        ):
            return False
        return True

    selected: list[str] = []
    # Work with complete headings and numbered items. Splitting on commas or
    # line breaks produced fragments such as "1.使用后清洁泥土，" and could
    # join unrelated continuation lines into an unusable answer.
    sections = [
        section.strip()
        for section in re.split(r"(?=[【\[].*?[】\]])", text)
        if section and section.strip()
    ]
    for section in sections:
        heading_match = re.match(r"^([【\[].*?[】\]])", section)
        heading = heading_match.group(1) if heading_match else ""
        body = section[heading_match.end():] if heading_match else section
        heading_matches = bool(heading and any(marker in heading for marker in markers))
        items = [
            clean_segment(item)
            for item in re.split(r"(?m)(?=^\s*\d+\s*[.、)])", body)
            if clean_segment(item)
        ]
        if not items:
            items = [clean_segment(body)] if clean_segment(body) else []
        for item in items:
            own_matches = has_field_marker(item, field_type, markers)
            competing_matches = any(
                has_field_marker(item, other_field, other_markers)
                for other_field, other_markers in _USAGE_INSTRUCTION_FIELD_MARKERS.items()
                if other_field != field_type
            )
            if own_matches and competing_matches:
                # A single imported sentence can join distinct instructions,
                # for example "用清水冲洗，使用后擦干并通风存放".  Keep
                # complete punctuation-delimited clauses for the requested
                # field instead of returning the other field's guidance too.
                clauses = [
                    clean_segment(clause)
                    for clause in re.split(r"(?<=[，,。！？!?；;])\s*", item)
                    if clean_segment(clause)
                ]
                keep_following = False
                for clause in clauses:
                    clause_matches_own = has_field_marker(clause, field_type, markers)
                    clause_matches_other = any(
                        has_field_marker(clause, other_field, other_markers)
                        for other_field, other_markers in _USAGE_INSTRUCTION_FIELD_MARKERS.items()
                        if other_field != field_type
                    )
                    if clause_matches_own:
                        selected.append(clause)
                        keep_following = True
                    elif clause_matches_other:
                        keep_following = False
                    elif keep_following:
                        # Unmarked continuation clauses often complete the
                        # preceding numbered instruction (for example the
                        # second half of an alternative drying method).
                        selected.append(clause)
            elif own_matches or (heading_matches and not competing_matches):
                selected.append(item)
    normalized_selected: list[str] = []
    for item in dict.fromkeys(selected):
        # Once clauses from different source sections are filtered into one
        # field answer, their original per-section numbering is no longer a
        # valid sequence.  Remove only the leading list marker; keep all
        # evidence text and any numbers that are part of the instruction.
        normalized = re.sub(r"^\d+\s*[.、)]\s*", "", item).strip()
        if normalized:
            normalized_selected.append(normalized)
    return " ".join(normalized_selected).strip().rstrip("，,；;：:")


def _usage_instruction_matches_product(product: Product, value: Any) -> bool:
    """Fail closed when an instruction cell clearly describes another domain."""
    instruction = str(value or "")
    identity = " ".join(
        str(part or "")
        for part in (
            product.product_name_cn,
            product.product_name_en,
            product.category,
            product.sub_category,
        )
    )
    domain_rules = (
        (("研磨粗细", "研磨器", "刀盘"), ("磨豆", "研磨机", "研磨器")),
        (("气罐对准炉头", "火力调节阀", "按下点火装置"), ("炉", "灶", "烤炉")),
    )
    for evidence_terms, identity_terms in domain_rules:
        if any(term in instruction for term in evidence_terms) and not any(term in identity for term in identity_terms):
            return False
    cup_only = "杯" in identity and not any(term in identity for term in ("壶", "锅", "炉", "灶"))
    cookware_markers = ("锅身", "水壶置于灶具", "壶身", "壶底", "烹饪前", "小火预热", "严禁干烧")
    if cup_only and sum(marker in instruction for marker in cookware_markers) >= 2:
        return False
    return True


def _capacity_evidence_conflict(product_name: Any, structured_value: Any) -> tuple[str, str] | None:
    """Detect explicit capacity-unit contradictions without guessing a winner."""
    pattern = re.compile(r"(?<![\d.])(\d+(?:\.\d+)?)\s*(ml|毫升|l|升)", re.IGNORECASE)

    def values(text: Any) -> list[tuple[float, str]]:
        found: list[tuple[float, str]] = []
        for match in pattern.finditer(str(text or "")):
            number = float(match.group(1))
            unit = match.group(2).lower()
            milliliters = number if unit in {"ml", "毫升"} else number * 1000
            found.append((round(milliliters, 3), match.group(0).strip()))
        return found

    name_values = values(product_name)
    structured_values = values(structured_value)
    if not name_values or not structured_values:
        return None
    if {item[0] for item in name_values} & {item[0] for item in structured_values}:
        return None
    return name_values[0][1], structured_values[0][1]


_COLOR_FAMILY_CHARACTERS = frozenset("黑白红橙黄绿蓝紫粉灰银金棕褐咖锖")


def _color_evidence_conflict(product_name: Any, structured_value: Any) -> tuple[str, str] | None:
    """Detect an explicit color in a product name that conflicts with specs.

    Product names frequently carry the sellable variant in parentheses or
    after a dash.  Only those explicit variant spans are compared, so ordinary
    brand/name characters are not interpreted as colors.
    """
    name_text = str(product_name or "").strip()
    value_text = str(structured_value or "").strip()
    if not name_text or not value_text:
        return None
    name_spans = re.findall(r"[（(]([^（）()]{1,12})[）)]", name_text)
    name_spans.extend(re.findall(r"[-—]([^\s（）()]{1,12})$", name_text))
    name_colors = {
        char
        for span in name_spans
        for char in span
        if char in _COLOR_FAMILY_CHARACTERS
    }
    structured_colors = {char for char in value_text if char in _COLOR_FAMILY_CHARACTERS}
    if not name_colors or not structured_colors or name_colors & structured_colors:
        return None
    explicit_name_span = next(
        (span for span in name_spans if any(char in _COLOR_FAMILY_CHARACTERS for char in span)),
        "",
    )
    return explicit_name_span, value_text


def _resolve_single_product_field_evidence(
    db: Session,
    *,
    resolved_sku: str,
    requested_field: str,
    question: str,
) -> dict[str, Any]:
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_sku)
    if not product:
        return {
            "requested_field": requested_field,
            "evidence_field": None,
            "evidence_value": "",
            "evidence_source": None,
            "evidence_scope": None,
            "evidence_sku": None,
            "missing": True,
        }

    material_component = customer_field_contract.material_component_from_detail_label(requested_field)
    if material_component == "body":
        raw_material = str(getattr(specs, "body_material", "") or "").strip() if specs else ""
        body_material, _handle_material = customer_agent_intent_service._split_primary_and_handle_material(raw_material)
        value = _compound_display_value(body_material)
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": value,
            "evidence_source": "specs.body_material" if value else None,
            "evidence_scope": "body" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }
    if material_component == "handle":
        raw_material = str(getattr(specs, "body_material", "") or "").strip() if specs else ""
        _body_material, handle_material = customer_agent_intent_service._split_primary_and_handle_material(raw_material)
        value = _compound_display_value(handle_material)
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": value,
            "evidence_source": "specs.body_material" if value else None,
            "evidence_scope": "handle" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }
    if material_component == "lid":
        # General body-material cells do not evidence a lid.  Only a same-SKU
        # QA/knowledge statement that explicitly names both the lid and its
        # material is admissible; otherwise keep the missing-field boundary.
        value = customer_agent_intent_service._best_same_sku_evidence_text(
            db,
            sku=resolved_sku,
            supporting=None,
            term_groups=[("锅盖", "盖子", "杯盖"), ("材质", "材料")],
        )
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": _compound_display_value(value),
            "evidence_source": "product_qa:component_material" if value else None,
            "evidence_scope": "lid" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }

    if requested_field == "适用场景":
        value = _compound_display_value(getattr(business, "usage_scenarios", "") if business else "")
        return {
            "requested_field": requested_field,
            "evidence_field": "usage_scene" if value else None,
            "evidence_value": value,
            "evidence_source": "business.usage_scenarios" if value else None,
            "evidence_scope": "subject" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }

    field_contract = customer_field_contract.detect_field_contract(requested_field)
    canonical_field = (
        customer_field_contract.field_type_from_detail_label(requested_field)
        or (field_contract.field_type if field_contract else None)
    )
    detail_label = customer_field_contract.product_detail_field_label(canonical_field) if canonical_field else None
    if not canonical_field or not customer_field_contract.is_supported_detail_field(canonical_field) or not detail_label:
        return {
            "requested_field": requested_field,
            "evidence_field": canonical_field,
            "evidence_value": "",
            "evidence_source": None,
            "evidence_scope": None,
            "evidence_sku": None,
            "missing": True,
        }

    result = _product_field_followup_result(
        db,
        resolved_sku,
        detail_label,
        question,
        identity_source="phase2_resolved_entity",
        field_request_override={"field_type": canonical_field, "requested_field": detail_label, "source": "compound_field"},
    )
    metadata = result.get("answer_metadata") if isinstance(result, dict) and isinstance(result.get("answer_metadata"), dict) else {}
    evidence_status = str(metadata.get("evidence_status") or "").strip()
    missing = evidence_status in {"", "missing"}
    value = str(metadata.get("evidence_value") or "").strip()
    if not missing and not value:
        answer = str(result.get("answer") or "")
        marker = f"的{detail_label}："
        value = answer.split(marker, 1)[1].rstrip("。") if marker in answer else answer
    return {
        "requested_field": requested_field,
        "evidence_field": metadata.get("evidence_field") or (canonical_field if not missing else None),
        "evidence_value": _compound_display_value(value),
        "evidence_source": metadata.get("evidence_source"),
        "evidence_scope": metadata.get("evidence_scope"),
        "evidence_sku": metadata.get("evidence_sku") or (resolved_sku if not missing else None),
        "missing": missing,
    }


def _build_compound_product_detail_result(
    db: Session,
    *,
    resolved_sku: str,
    requested_fields: list[str],
    question: str,
    entity_contract: dict[str, Any] | None = None,
    compatibility_plan: dict[str, Any] | None = None,
) -> dict | None:
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_sku)
    if not product:
        return None
    # Compatibility extraction may emit product-component nouns (for example
    # "煎盘") alongside an actual field.  A component noun is not a second
    # FieldContract and must not preempt the same-SKU evidence route.  Keep
    # only labels that map to an existing canonical field contract.
    ordered_fields = list(dict.fromkeys(
        label
        for label in (str(field or "").strip() for field in requested_fields)
        if label and (
            customer_field_contract.field_type_from_detail_label(label)
            or (customer_field_contract.detect_field_contract(label) is not None)
        )
    ))
    if len(ordered_fields) < 2:
        return None
    field_results = [
        _resolve_single_product_field_evidence(
            db,
            resolved_sku=resolved_sku,
            requested_field=field,
            question=question,
        )
        for field in ordered_fields
    ]
    name = str(product.product_name_cn or product.product_name_en or resolved_sku).strip()
    lines = [f"{name}（{resolved_sku}）："]
    for field_result in field_results:
        label = field_result["requested_field"]
        value = str(field_result.get("evidence_value") or "").strip()
        if value:
            lines.append(f"- {label}：{value}")
        elif customer_field_contract.material_component_from_detail_label(label) == "lid":
            lines.append(f"- {label}：当前资料未单独提供锅盖材质。")
        else:
            lines.append(f"- {label}：当前资料未标注。")
    row = _product_row_from_model(product, specs, business, content)
    original_plan = compatibility_plan if isinstance(compatibility_plan, dict) else {}
    debug_plan = dict(original_plan)
    debug_plan.update({
        "primary_intent": str(original_plan.get("primary_intent") or "product_field"),
        "product_ref": resolved_sku,
        "sku": resolved_sku,
        "requested_fields": ordered_fields,
        "raw_question": question,
        "compound": True,
        "multi_field": True,
    })
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": "\n".join(lines),
        "sku": resolved_sku,
        "results": [row],
        "result_skus": [resolved_sku],
        "candidate_skus": [resolved_sku],
        "answer_metadata": {
            "source": "resolved_entity_compound_detail",
            "answer_policy": "compound_field_evidence",
            "compound_fields": field_results,
        },
        "debug": {
            "agent_mode": "resolved_entity_compound_detail",
            "entity_resolution_contract": entity_contract or {},
            "requested_fields": ordered_fields,
            "compound": True,
            "multi_field": True,
            "plan": debug_plan,
        },
        "skip_polish": True,
    }


def _is_sealed_product_qa_safe_missing(result: dict | None) -> bool:
    """Whether a sealed QA attempt had identity but no direct evidence.

    This is a route-state check, not intent classification.  A safe-missing
    QA result remains the fallback for a compound supplement, but must not
    prevent the same sealed SKU from trying the RAG evidence provider.
    """
    return bool(
        isinstance(result, dict)
        and str((result.get("debug") or {}).get("agent_mode") or "")
        == "sealed_product_qa_safe_missing"
    )


async def _resolve_sealed_supplemental_product_evidence(
    db: Session,
    *,
    question: str,
    semantic_preplan: dict[str, Any] | None,
    base_plan: dict[str, Any] | None = None,
) -> tuple[dict | None, str]:
    """Use QA first, then sealed same-SKU RAG, for a semantic supplement."""
    effective_preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    supplemental_query = str(effective_preplan.get("supplemental_qa_evidence_query") or "").strip()
    if not supplemental_query:
        return None, ""
    supplemental_preplan = dict(effective_preplan)
    supplemental_preplan.update({
        "canonical_fields": [], "field_type": "", "field_hint": None,
        "evidence_kind": "product_qa", "qa_evidence_query": supplemental_query,
        "compound": False,
    })
    supplemental_plan = dict(base_plan or {})
    supplemental_plan["semantic_preplan"] = supplemental_preplan
    supplemental_question = " ".join(
        item for item in (
            str(supplemental_preplan.get("subject_text") or "").strip(),
            supplemental_query,
        ) if item
    ) or question
    supplemental = await _try_product_qa_shortcut_with_semantic_selection(
        db, supplemental_question, phase1_plan=supplemental_plan,
    )
    qa_safe_missing = supplemental if _is_sealed_product_qa_safe_missing(supplemental) else None
    if qa_safe_missing:
        supplemental = None
    if not supplemental:
        for _supplemental_attempt in range(3):
            supplemental = await _try_sealed_same_sku_knowledge_answer(
                db, supplemental_question, supplemental_plan,
            )
            if supplemental:
                break
    return supplemental or qa_safe_missing, supplemental_query


def _build_resolved_compound_evidence_result(
    db: Session,
    *,
    question: str,
    entity_contract: Any | None,
    field_request: dict[str, Any] | None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict | None:
    """Execute a compound same-SKU evidence answer behind sealed contracts.

    The legacy compound formatter contains product-agnostic secondary evidence
    checks (for example a material question plus a durability question).  It
    is not permitted to resolve identity or choose the primary field here:
    both must already be sealed by Phase 2.  Returning ``None`` leaves normal
    one-field execution unchanged.
    """
    contract = entity_contract
    if not contract or not (
        contract.status == "resolved"
        and contract.resolved_sku
        and contract.is_unique
        and contract.confidence == "high"
        and contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
        and contract.resolver_candidate_skus == [contract.resolved_sku]
    ):
        return None
    request = field_request if isinstance(field_request, dict) else {}
    canonical_fields = list(dict.fromkeys(
        str(field or "").strip()
        for field in (request.get("canonical_fields") or [])
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ))
    if not canonical_fields:
        return None
    product, specs, business, content = _phase1_product_bundle_by_ref(db, contract.resolved_sku)
    if not product:
        return None
    if len(canonical_fields) > 1:
        if str(contract.matched_by or "") == "recommendation_context_anchor":
            # This executor has already verified the anchor's resolved,
            # unique, high-confidence one-SKU contract above.  The context
            # provenance is not a raw-turn exact name, but it is a sealed
            # identity from the immediately preceding conversation state.
            resolution_decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
                allowed=True,
                resolved_sku=str(contract.resolved_sku or "").strip().upper(),
                resolved_product_id=str(product.id),
                reason="resolved_context_anchor",
                match_level="recommendation_context_anchor",
            )
        else:
            resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(contract, [product])
        if not resolution_decision.allowed:
            return None
        answers: list[str] = []
        evidence_items: list[dict[str, Any]] = []
        requested_labels_by_field: dict[str, list[str]] = {}
        for requested_label in request.get("requested_fields") or []:
            requested_type = customer_field_contract.field_type_from_detail_label(requested_label)
            if requested_type:
                requested_labels_by_field.setdefault(requested_type, []).append(str(requested_label))
        for field_type in canonical_fields:
            # A component qualifier refines the already-sealed canonical
            # material field.  Preserve that scope into the same-SKU evidence
            # provider instead of replacing it with the generic material
            # label in a compound answer.
            label = (requested_labels_by_field.get(field_type) or [
                customer_field_contract.product_detail_field_label(field_type)
            ])[0]
            if not label:
                return None
            supported = customer_field_contract.is_supported_detail_field(field_type)
            single_request = {
                "field_type": field_type,
                "requested_field": label,
                "requested_fields": [label],
                "canonical_fields": [field_type],
                "supported_fields": [field_type] if supported else [],
                "unsupported_fields": [] if supported else [field_type],
                "subject": str(request.get("subject") or ""),
                "requested_scope": "subject",
                "source": str(request.get("source") or "validated_semantic_preplan"),
                "confidence": float(request.get("confidence") or 0.0),
                "compound": False,
            }
            material_component = customer_field_contract.material_component_from_detail_label(label)
            if supported and material_component:
                # Component labels are evidence scopes for the already sealed
                # ``material`` contract.  The generic single-field formatter
                # would otherwise reread the whole body-material cell and
                # discard that scope in a compound answer.
                component_evidence = _resolve_single_product_field_evidence(
                    db,
                    resolved_sku=contract.resolved_sku,
                    requested_field=label,
                    question=question,
                )
                component_value = str(component_evidence.get("evidence_value") or "").strip()
                component_missing = bool(component_evidence.get("missing"))
                if component_value:
                    component_answer = f"{product.product_name_cn}（{contract.resolved_sku}）的{label}：{component_value}。"
                elif material_component == "lid":
                    component_answer = f"当前资料未单独提供{product.product_name_cn}（{contract.resolved_sku}）的锅盖材质。"
                else:
                    component_answer = f"当前资料未单独提供{product.product_name_cn}（{contract.resolved_sku}）的{label}。"
                field_result = {
                    "intent": "product_detail",
                    "answer_type": "product_detail",
                    "answer": component_answer,
                    "result_skus": [contract.resolved_sku],
                    "answer_metadata": {
                        "evidence_status": "missing" if component_missing else "structured",
                        "evidence_field": component_evidence.get("evidence_field"),
                        "evidence_source": component_evidence.get("evidence_source"),
                        "evidence_value": component_value,
                        "evidence_sku": component_evidence.get("evidence_sku"),
                    },
                }
            elif supported:
                field_result = _product_field_followup_result(
                    db,
                    contract.resolved_sku,
                    label,
                    question,
                    identity_source="phase2_resolved_entity",
                    field_request_override=single_request,
                )
            else:
                field_result = _build_resolved_product_unknown_field_result(
                    db,
                    product,
                    label=label,
                    source="resolved_entity_unknown_field_fallback",
                    resolution_decision=resolution_decision,
                )
            if not field_result or field_result.get("result_skus") != [contract.resolved_sku]:
                return None
            answer = str(field_result.get("answer") or "").strip()
            if not answer:
                return None
            answers.append(answer)
            field_metadata = field_result.get("answer_metadata") if isinstance(field_result.get("answer_metadata"), dict) else {}
            evidence_items.append({
                "field_type": field_type,
                "requested_field": label,
                "evidence_status": field_metadata.get("evidence_status"),
                "evidence_field": field_metadata.get("evidence_field"),
                "evidence_source": field_metadata.get("evidence_source"),
                "evidence_value": field_metadata.get("evidence_value"),
                "evidence_sku": field_metadata.get("evidence_sku"),
            })
        row = _product_row_from_model(product, specs, business, content)
        plan = dict(phase1_plan or {})
        plan.update({
            "product_ref": contract.resolved_sku,
            "sku": contract.resolved_sku,
            "requested_fields": list(request.get("requested_fields") or []),
            "field_contract": dict(request),
            "compound": True,
            "raw_question": question,
        })
        evidence_skus = list(dict.fromkeys(
            str(item.get("evidence_sku") or "").strip().upper()
            for item in evidence_items
            if str(item.get("evidence_sku") or "").strip()
        ))
        return {
            "intent": "product_detail",
            "answer_type": "product_detail",
            "answer": "\n".join(answers),
            "sku": contract.resolved_sku,
            "results": [row],
            "result_skus": [contract.resolved_sku],
            "candidate_skus": [contract.resolved_sku],
            "answer_metadata": {
                "source": "resolved_entity_multi_field_contract",
                "answer_policy": "sealed_same_sku_multi_field_evidence",
                "contract_field_types": canonical_fields,
                "evidence_items": evidence_items,
                # Retain the established compound audit surface.  It is the
                # same per-field, sealed-SKU evidence list as ``evidence_items``
                # (not a second resolver or formatter path).
                "compound_fields": evidence_items,
                "evidence_skus": evidence_skus,
                "evidence_status": "structured" if any(item.get("evidence_value") for item in evidence_items) else "missing",
            },
            "debug": {
                "agent_mode": "resolved_entity_multi_field_contract",
                "binding_provenance": "resolved_entity_contract",
                "entity_resolution_contract": contract.to_dict(),
                "field_contract": dict(request),
                "plan": plan,
            },
            "skip_polish": True,
        }
    # This adapter is deliberately multi-field only. A single formal field
    # must continue to the ordinary Phase-2 provider, where field-specific
    # validation and same-SKU QA/RAG fallback are available.
    return None


_PHASE2_EXACT_ENTITY_MATCHES = {
    "sku_exact",
    "normalized_sku_exact",
    "canonical_name_exact",
    "normalized_alias_exact",
    # Identity was sealed by the immediately preceding single-product turn;
    # it is eligible for the same compound evidence executor as an exact name.
    "recommendation_context_anchor",
}


def _choose_effective_entity_contract(
    question: str,
    products: list[Product],
    *,
    resolver_candidates: list[Product] | None = None,
    override_subject: str | None = None,
) -> customer_entity_resolution_contract.EntityContractSelection:
    default_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        resolver_candidates=resolver_candidates,
    )
    override_contract = None
    normalized_override = customer_agent_service.normalize_search_text(override_subject or "").strip()
    if normalized_override and normalized_override != default_contract.normalized_entity_text:
        override_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            resolver_candidates=resolver_candidates,
            entity_text_override=override_subject,
        )
    return customer_entity_resolution_contract.choose_effective_entity_contract(
        default_contract,
        override_contract,
        products,
    )


def _phase2_requested_fields(question: str) -> list[str]:
    return resolve_requested_field_contract(question)["requested_fields"]


def _semantic_exact_subject_for_field_contract(
    db: Session,
    question: str,
    semantic_preplan: dict[str, Any] | None,
) -> str:
    """Return a semantic subject only after catalogue identity validates it.

    The semantic model supplies a user-text span, never an SKU or product
    fact.  This adapter merely establishes whether that span is a unique
    exact identity so the formal FieldContract can retain a valid structured
    field plan whose route shape was otherwise catalogue-oriented.
    """
    plan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    subject = str(plan.get("subject_text") or "").strip()
    fields = [
        str(field or "").strip()
        for field in (plan.get("canonical_fields") or [])
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ]
    if not (
        subject
        and len(fields) == 1
        and _semantic_preplan_confident(plan, minimum=0.9)
        and str(plan.get("route_family") or "").strip() == "structured_query"
        and str(plan.get("route_hint") or "").strip() == "query_products"
        and customer_agent_service.normalize_search_text(subject).lower()
        in customer_agent_service.normalize_search_text(question).lower()
    ):
        return ""
    products = db.query(Product).order_by(Product.sku.asc()).all()
    contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        entity_text_override=subject,
    )
    if (
        contract.status == "resolved"
        and contract.resolved_sku
        and contract.is_unique
        and contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
    ):
        return subject
    return ""


def resolve_requested_field_contract(
    question: str,
    phase1_plan: dict | None = None,
    *,
    subject_override: str | None = None,
) -> dict[str, Any]:
    """Central Phase 2 adapter over the stable legacy field extractor."""
    compatibility_fields = customer_agent_intent_service._requested_fields_for_detail_question(question)
    selection = customer_field_contract.select_entity_subject_for_routing(raw_question=question)
    subject = str(subject_override or "").strip()
    if not subject:
        subject = selection.entity_subject if selection.source == "field_contract" else ""
    if not subject:
        subject = customer_agent_intent_service._detail_subject_from_question(question).strip()
    if not subject:
        # The broad SKU extractor intentionally emits a short compatibility
        # suffix as well as the full SKU for some forms (for example CW-C95
        # and C95).  A full token that contains every other extraction is one
        # unambiguous identity, not a multi-product request.
        explicit_skus = list(dict.fromkeys(
            str(item or "").strip().upper()
            for item in customer_agent_service._extract_skus(str(question or ""))
            if str(item or "").strip()
        ))
        longest = max(explicit_skus, key=len, default="")
        if longest and all(item in longest for item in explicit_skus):
            subject = longest
    if subject and compatibility_fields:
        # Legacy recognition may see a field-looking token inside the product
        # name itself (for example a product whose name contains "煎盘"). Only
        # retain compatibility fields that also occur outside the selected
        # subject; the formal FieldContract remains authoritative.
        predicate_text = customer_agent_intent_service._remove_subject_once(question, subject)
        predicate_fields = customer_agent_intent_service._requested_fields_for_detail_question(predicate_text)
        compatibility_fields = [field for field in compatibility_fields if field in predicate_fields]
        # The old extractor treats component nouns such as “手柄” and product
        # title text such as “10件套” as material/accessory hints.  They are not
        # field predicates by themselves.  Keep a legacy mapped field only
        # when the remaining predicate carries the formal field signal (or a
        # concrete material assertion); semantic planning remains the primary
        # route for broader natural-language meaning.
        predicate_types = set(customer_field_contract.detect_field_types(predicate_text))
        material_assertion = bool(re.search(
            r"材质|材料|304|不锈钢|铝合金|硬质氧化铝|钛|木质|白蜡木|胡桃木|榉木",
            predicate_text,
            flags=re.IGNORECASE,
        ))
        compatibility_fields = [
            field
            for field in compatibility_fields
            if not (field_type := customer_field_contract.field_type_from_detail_label(field))
            or field_type in predicate_types
            or (field_type == "material" and material_assertion)
        ]
    # When semantic planning is unavailable, a high-confidence field-only
    # planner task is the controlled fallback for natural wording that has no
    # literal alias (for example a size question phrased without “尺寸”).
    # Adapt that canonical planner label into the one FieldContract instead
    # of allowing an entity or QA shortcut to answer first.
    planned_label = str((phase1_plan or {}).get("requested_field") or "").strip()
    planned_field = customer_field_contract.field_type_from_detail_label(planned_label)
    if (
        not compatibility_fields
        and str((phase1_plan or {}).get("primary_intent") or "") == "product_field"
        and bool((phase1_plan or {}).get("field_only"))
        and customer_field_contract.is_supported_detail_field(planned_field)
    ):
        compatibility_fields = [planned_label]
    return customer_field_contract.resolve_requested_field_contract(
        question,
        phase1_plan,
        compatibility_fields=compatibility_fields,
        subject=subject,
        requested_scope=selection.requested_scope,
        subject_is_catalog_exact=bool(str(subject_override or "").strip()),
    )


def _build_phase2_entity_resolution_context(
    db: Session,
    question: str,
    field_request: dict[str, Any] | None = None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build the deterministic Phase 2 entity snapshot once for this request."""
    try:
        products = db.query(Product).order_by(Product.sku.asc()).all()
        subject_selection = customer_field_contract.select_entity_subject_for_routing(
            raw_question=question,
        )
        canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            products,
        )
        if canonical_subject:
            normalized_subject = customer_agent_service.normalize_search_text(canonical_subject)
            raw_canonical_owners = {
                str(product.sku or "").strip().upper()
                for product in products
                if any(
                    customer_agent_service.normalize_search_text(raw_name) == normalized_subject
                    for raw_name in (
                        str(product.product_name_cn or "").strip(),
                        str(product.product_name_en or "").strip(),
                    )
                    if raw_name
                )
            }
            subject_start = str(question or "").lower().find(str(canonical_subject).lower())
            suffix = (
                str(question or "")[subject_start + len(canonical_subject):]
                if subject_start >= 0
                else ""
            ).lstrip(" 的，,：:；;。.!！?？")
            explicit_variant_suffix = bool(re.match(
                r"^(?:(?:pro|plus)(?![A-Za-z0-9])|基础款|标准版|升级款|旗舰版|"
                r"\d+(?:\.\d+)?\s*(?:杯|寸|英寸|ml|毫升|l|升)|"
                r"(?:黑|白|红|橙|黄|绿|蓝|紫|粉|灰|银|金)(?:色)?)",
                suffix,
                flags=re.IGNORECASE,
            ))
            if len(raw_canonical_owners) != 1 or explicit_variant_suffix:
                canonical_subject = ""
        # A previously formed semantic FieldContract is authoritative here.
        # Re-running the legacy parser solely to obtain a canonical product
        # subject can otherwise replace that field with an incidental word in
        # the question (e.g. ``brand`` in a price-tier request).  The exact
        # catalogue subject remains an input to EntityResolution only; it does
        # not come from semantic classification.
        if (
            isinstance(field_request, dict)
            and field_request.get("source") == "validated_semantic_preplan"
        ):
            resolved_field_request = dict(field_request)
            if canonical_subject:
                resolved_field_request["subject"] = canonical_subject
        else:
            resolved_field_request = dict(
                resolve_requested_field_contract(
                    question,
                    phase1_plan,
                    subject_override=canonical_subject,
                )
                if canonical_subject
                else (field_request or resolve_requested_field_contract(question, phase1_plan))
            )
        entity_subject = str(resolved_field_request.get("subject") or "").strip() or None
        if not entity_subject and resolved_field_request.get("source") == "validated_semantic_preplan":
            # The semantic preplan owns field meaning and may also identify a
            # subject span for natural wording whose predicate has no fixed
            # deterministic alias (for example an included-items question).
            # Accept it only when the exact normalized text occurs in this
            # turn; EntityResolutionContract still decides whether it binds a
            # unique catalogue SKU.
            semantic_subject = str(
                ((phase1_plan or {}).get("semantic_preplan") or {}).get("subject_text") or ""
            ).strip()
            normalized_question = customer_agent_service.normalize_search_text(question)
            normalized_semantic_subject = customer_agent_service.normalize_search_text(semantic_subject)
            if normalized_semantic_subject and normalized_semantic_subject in normalized_question:
                entity_subject = semantic_subject
                resolved_field_request["subject"] = entity_subject
        if not entity_subject and resolved_field_request.get("source") == "validated_semantic_preplan":
            # Reuse only the catalogue subject that already passed the raw
            # canonical-owner and explicit-variant-suffix checks above.  A
            # second unguarded lookup here would promote display aliases or a
            # base name followed by an unavailable variant (for example a
            # version suffix), bypassing the fail-closed entity contract.
            entity_subject = canonical_subject or None
            if entity_subject:
                resolved_field_request["subject"] = entity_subject
        contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            entity_text_override=entity_subject,
            field_type_override=resolved_field_request.get("field_type"),
        )
        return {
            "products_snapshot": products,
            "contract": contract,
            "field_request": resolved_field_request,
            "entity_subject_selection": subject_selection,
            "error": None,
        }
    except Exception as exc:
        return {"products_snapshot": [], "contract": None, "error": f"{type(exc).__name__}: {exc}"}


def _phase2_single_field_arbitration_eligible(
    question: str,
    phase1_plan: dict | None,
    *,
    conversation_id: str | None,
    field_request_override: dict[str, Any] | None = None,
) -> bool:
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    field_request = field_request_override or resolve_requested_field_contract(question, plan)
    current_subject = str(field_request.get("subject") or "").strip().strip("「」『』\"'“”")
    # A field predicate can describe a catalogue request ("哪种适合露营")
    # rather than a fact about one product.  Interrogative subjects never
    # establish single-product identity, so leave them to query/recommendation
    # routing instead of manufacturing an entity clarification.
    if re.match(r"^(?:哪种|哪款|哪些|什么|有哪|有没有)", current_subject):
        return False
    validated_semantic_subject = bool(
        current_subject
        and field_request.get("source") == "validated_semantic_preplan"
    )
    if (
        str(field_request.get("field_type") or "") in {"cleaning", "care", "usage_instruction"}
        and customer_agent_intent_service._looks_like_usage_care_question(question)
        and not _looks_like_product_like_scope_subject(current_subject)
        and not SKU_RE.fullmatch(current_subject)
        and not validated_semantic_subject
    ):
        # Generic care questions have no product identity to seal. Preserve
        # the established usage/care knowledge path; explicit products still
        # form EntityResolutionContract below.
        return False
    if conversation_id:
        # A conversation anchor is only a supplement to identity.  When the
        # current turn carries a formal field predicate and a concrete subject,
        # it must still enter EntityResolutionContract; otherwise an explicit
        # correction such as “我想问「…」的热源” falls through to generic tool
        # calling despite having a sealed current-turn identity.  Pure
        # pronouns retain the established anchor-specific follow-up path.
        if not current_subject or _looks_like_ordinal_product_field_followup(question) or re.match(
            r"^(?:它|它的|这个|这个商品|这款|该商品|该产品|这件商品|本产品|那个|那款)",
            current_subject,
        ):
            return False
    # The legacy compatibility extractor can still label in-box wording as
    # "contents". Let the authoritative FieldContract keep those requests in
    # entity arbitration instead of falling through to a dedicated usage route.
    non_usage_field_request = _has_non_usage_care_field_contract(question)
    # A validated semantic field is the same central contract signal as a
    # deterministic alias.  It must be allowed into Phase 2 before legacy
    # usage/QA shortcuts can interpret the surrounding natural language.
    semantic_field_request = bool(
        field_request.get("source") == "validated_semantic_preplan"
        and field_request.get("canonical_fields")
    )
    primary_intent = str(plan.get("primary_intent") or "").strip()
    if primary_intent not in {"", "product_detail", "product_field"} and not non_usage_field_request and not semantic_field_request:
        return False
    if plan.get("routing_conflict") or plan.get("must_compare_both_products") or plan.get("must_make_choice"):
        return False
    # A planner may expose an exact product reference while still assigning a
    # broad compatibility intent.  That is not a competing product-list
    # request when a validated FieldContract has already identified one
    # supported detail field; Phase 2 must arbitrate identity instead of
    # handing the request back to the legacy executor.
    if (
        (plan.get("must_return_products") or plan.get("product_refs"))
        and not non_usage_field_request
        and not semantic_field_request
    ):
        return False
    tasks = [task for task in (plan.get("tasks") or []) if isinstance(task, dict)]
    if (
        len(tasks) > 1
        or any(str(task.get("type") or "") not in {"", "product_field"} for task in tasks)
    ) and not non_usage_field_request and not semantic_field_request:
        return False
    if len(field_request["requested_fields"]) > 1:
        return False
    return len(field_request["canonical_fields"]) == 1


def _explicit_current_turn_comparison_skus(db: Session, question: str) -> list[str]:
    """Return two or more non-overlapping, catalogue-exact comparison identities."""
    text = customer_agent_service.normalize_search_text(question)
    if not text or not any(
        term in str(question or "")
        for term in ("对比", "比较", "区别", "差异", "不同", "一样", "哪个", "哪款", "谁更", "更大", "更小", "更轻", "更重")
    ):
        return []

    matches: list[tuple[int, int, str]] = []
    for product in db.query(Product).all():
        sku = str(product.sku or "").strip().upper()
        if not sku:
            continue
        candidates = {
            customer_agent_service.normalize_search_text(sku),
            customer_agent_service.normalize_search_text(product.product_name_cn or ""),
            customer_agent_service.normalize_search_text(product.product_name_en or ""),
        }
        for candidate in candidates:
            if not candidate:
                continue
            start = text.find(candidate)
            if start >= 0:
                matches.append((start, start + len(candidate), sku))

    # Prefer the longest identity at an overlapping span (for example a Pro
    # name over its base-family substring). Identical catalogue names remain
    # one unresolved mention rather than being misread as two participants.
    skus_by_span: dict[tuple[int, int], set[str]] = {}
    for start, end, sku in matches:
        skus_by_span.setdefault((start, end), set()).add(sku)
    unique_matches = [
        (start, end, next(iter(skus)))
        for (start, end), skus in skus_by_span.items()
        if len(skus) == 1
    ]
    selected: list[tuple[int, int, str]] = []
    for start, end, sku in sorted(unique_matches, key=lambda item: (-(item[1] - item[0]), item[0], item[2])):
        if any(not (end <= kept_start or start >= kept_end) for kept_start, kept_end, _ in selected):
            continue
        selected.append((start, end, sku))
    selected.sort(key=lambda item: (item[0], item[1], item[2]))
    return list(dict.fromkeys(sku for _, _, sku in selected)) if len(selected) >= 2 else []


def _dedicated_semantic_route(question: str) -> str:
    if customer_agent_intent_service._looks_like_contents_grounding_question(question):
        return "contents_grounding"
    if customer_agent_intent_service._looks_like_usage_care_question(question) or _is_product_usage_care_question(question):
        return "usage_care"
    return str(_classify_customer_faq_intent(question) or "")


def _phase2_entity_arbitration_signals(
    question: str,
    phase1_plan: dict | None,
    semantic_preplan: dict | None,
    *,
    field_request_override: dict[str, Any] | None = None,
) -> dict[str, bool]:
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    primary_intent = str(plan.get("primary_intent") or "").strip()
    tasks = [task for task in (plan.get("tasks") or []) if isinstance(task, dict)]
    field_request = field_request_override or resolve_requested_field_contract(question, plan)
    field_types = field_request["canonical_fields"]
    requested_fields = field_request["requested_fields"]
    semantic_owned_field = bool(
        field_request.get("source") == "validated_semantic_preplan"
        and float(field_request.get("confidence") or 0.0) >= 0.9
        and field_types
        and not str((semantic_preplan or {}).get("semantic_adapter_source") or "").strip()
    )
    # The selected FieldContract is intentionally singular for single-detail
    # execution, but compound customer questions can carry additional formal
    # aliases.  Preserve those independent signals here so a first contract
    # never lets the single-field gate preempt orchestration.
    observed_field_types = (
        set(str(item or "").strip() for item in field_types if str(item or "").strip())
        if semantic_owned_field
        else set(customer_field_contract.detect_field_types(question))
    )
    # Remove a shorter alias when it occurs wholly inside a longer formal
    # alias in the same predicate (e.g. “价格” inside “价格定位”).
    normalized_question = str(question or "").lower()
    contracts = tuple(customer_field_contract.FIELD_CONTRACTS)
    for shorter in tuple(observed_field_types):
        short_aliases = [alias.lower() for item in contracts if item.field_type == shorter for alias in item.aliases]
        if any(
            short_alias in long_alias and len(long_alias) > len(short_alias)
            and long_alias in normalized_question
            for short_alias in short_aliases
            for item in contracts if item.field_type in observed_field_types and item.field_type != shorter
            for long_alias in (alias.lower() for alias in item.aliases)
        ):
            observed_field_types.discard(shorter)
    observed_field_types.update(str(item or "").strip() for item in field_types if str(item or "").strip())
    multi_field = len(requested_fields) > 1 or len(observed_field_types) > 1
    # Once a high-confidence semantic field has passed the allowlist and
    # FieldContract validator, lexical route detectors may no longer reinterpret
    # a word inside the product title as a second intent. True semantic
    # multi-intent requests are already preserved in canonical_fields.
    dedicated_route = "" if semantic_owned_field else _dedicated_semantic_route(question)
    deterministic_field = (
        customer_field_contract.field_contract_for_type(field_types[0])
        if semantic_owned_field and len(field_types) == 1
        else customer_field_contract.detect_field_contract(question)
    )
    # Scenario group-size wording can contain the same "几个人" alias used
    # by the product people field.  It is a constraint only when it appears
    # in a recommendation scenario; other explicit field predicates retain
    # their normal exact-product priority.
    scenario_people_constraint = bool(
        deterministic_field
        and deterministic_field.field_type == "people"
        and re.search(r"(?:[一二三四五六七八九十百千\d]+|几|十几)\s*个人", str(question or ""))
    )
    scenario_route_without_product_field = bool(
        deterministic_field is None or scenario_people_constraint
    )
    # A heat-source predicate plus a category selection phrase is a catalog
    # request, not an incomplete reference to one product.  This deliberately
    # relies on the canonical field and generic product vocabulary rather than
    # any SKU/name or individual audit wording.
    generic_heat_source_selection = bool(
        deterministic_field
        and deterministic_field.field_type == "heat_source"
        and not SKU_RE.search(str(question or ""))
        and any(term in str(question or "") for term in ("锅", "锅具", "套锅", "炊具", "烤盘", "煎盘"))
        and any(term in str(question or "") for term in ("有没有", "有哪些", "推荐", "适合", "能配", "可以用"))
    )
    generic_accessory_catalog = bool(
        deterministic_field
        and deterministic_field.field_type == "accessories"
        and re.match(r"^\s*(?:有|都)?\s*哪些\s*(?:配件|附件)(?:产品|商品)?\s*[？?！!]?$", str(question or ""))
    )
    realtime_guardrail = customer_enterprise_guardrail_service.evaluate_question(question)
    realtime_weather = bool(
        isinstance(realtime_guardrail, dict)
        and str((realtime_guardrail.get("debug") or {}).get("guardrail_category") or "")
        in {"realtime_weather", "casual_weather_chat"}
        # A deterministic non-scenario field is a product fact request even
        # when its wording contains a temporal word such as "现在".  Weather
        # remains eligible for usage-scene questions, where current conditions
        # can genuinely be the user's intent.
        and not (
            deterministic_field is not None
            and deterministic_field.field_type != "usage_scene"
        )
    )
    return {
        "structured_query": bool(
            (
                _semantic_preplan_route_family(semantic_preplan) == "structured_query"
                and _semantic_preplan_confident(semantic_preplan)
            )
            or _looks_like_structured_field_filter_query(question)
        ),
        "multi_condition_recommendation": _looks_like_multi_condition_cookware_recommendation(question),
        # A quantity phrase inside a scenario (for example a group size in
        # "十几个人露营") is not a product's people field.  Preserve the
        # recommendation route before any field alias can turn the prose
        # preceding that phrase into a fictitious product subject.
        "scenario_recommendation": bool(
            scenario_route_without_product_field
            and (
                customer_agent_intent_service._looks_like_scenario_recommendation_question(question)
                or _phase1_is_light_budget_cookware_set_scenario(question)
                or _phase1_is_griddle_vs_cookware_scenario(question)
                or _phase1_is_stove_pairing_scenario(question)
                or _phase1_is_stove_griddle_combo_scenario(question)
                or _phase1_is_water_kettle_selection_scenario(question)
            )
        ),
        "realtime_weather": realtime_weather,
        "generic_heat_source_selection": generic_heat_source_selection,
        "generic_accessory_catalog": generic_accessory_catalog,
        "recommendation": primary_intent == "recommendation",
        "comparison": bool(
            primary_intent in {"comparison", "product_compare_recommendation"}
            or plan.get("must_compare_both_products")
            or plan.get("must_make_choice")
        ),
        "multi_field": multi_field,
        "additional_user_intent": multi_field,
        "compound": bool(plan.get("routing_conflict") or len(tasks) > 1 or len(field_types) > 1 or multi_field),
        "multi_product": bool(len(plan.get("product_refs") or []) > 1),
        "dedicated_route": bool(dedicated_route),
    }


def _semantic_field_ambiguity_clarification_result(
    semantic_preplan: dict | None,
    entity_resolution_context: dict[str, Any] | None,
) -> dict | None:
    """Fail closed when semantic planning reports mutually plausible fields."""
    if not isinstance(semantic_preplan, dict) or not semantic_preplan.get("called"):
        return None
    if not semantic_preplan.get("ambiguity"):
        return None
    if str(semantic_preplan.get("route_hint") or "").strip() != "product_detail":
        return None
    try:
        confidence = float(semantic_preplan.get("confidence") or 0.0)
    except (TypeError, ValueError):
        return None
    if confidence < 0.5:
        return None
    canonical_fields = list(dict.fromkeys(
        str(item or "").strip()
        for item in (semantic_preplan.get("canonical_fields") or [])
        if customer_field_contract.is_supported_detail_field(str(item or "").strip())
    ))
    if len(canonical_fields) < 2:
        return None

    context = entity_resolution_context if isinstance(entity_resolution_context, dict) else {}
    entity_contract = context.get("contract")
    entity_dict = entity_contract.to_dict() if entity_contract is not None else {}
    candidate_skus = [
        str(item or "").strip().upper()
        for item in (entity_dict.get("candidate_skus") or [])
        if str(item or "").strip()
    ]
    labels = [
        customer_field_contract.product_detail_field_label(field) or field
        for field in canonical_fields
    ]
    if len(labels) == 2:
        choices = f"{labels[0]}还是{labels[1]}"
    else:
        choices = "、".join(labels[:-1]) + f"还是{labels[-1]}"
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": f"这个问法可能对应多个字段。请确认你想查{choices}。",
        "results": [],
        "result_skus": [],
        "candidate_skus": candidate_skus,
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_field_ambiguity_clarification",
            "evidence_status": "field_ambiguity",
            "canonical_fields": canonical_fields,
        },
        "debug": {
            "agent_mode": "semantic_field_ambiguity_clarification",
            "field_contract": {
                "field_type": None,
                "canonical_fields": canonical_fields,
                "supported_fields": canonical_fields,
                "unsupported_fields": [],
                "source": "validated_semantic_preplan_ambiguous",
                "confidence": confidence,
                "compound": False,
            },
            "entity_resolution_contract": entity_dict,
        },
        "skip_polish": True,
    }


def _category_general_exclusion_signals(
    *,
    phase1_plan: dict | None,
    entity_contract: Any | None,
    entity_arbitration_signals: dict[str, bool] | None,
) -> dict[str, bool]:
    """Build the broader exclusions used only by category-field aggregation."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    signals = entity_arbitration_signals or {}
    primary_intent = str(plan.get("primary_intent") or "").strip()
    entity_status = str(getattr(entity_contract, "status", "") or "")
    return {
        "entity_resolved": bool(getattr(entity_contract, "resolved_sku", None)),
        "entity_ambiguous": entity_status == "ambiguous" or bool(
            list(getattr(entity_contract, "resolver_candidate_skus", None) or [])
        ),
        "recommendation_explicit": bool(
            primary_intent == "recommendation" or signals.get("recommendation")
        ),
        "scenario_like": bool(
            signals.get("scenario_like") or _phase1_should_use_structured_recommendation(plan)
        ),
        "multi_condition": bool(signals.get("multi_condition_recommendation")),
        "comparison": bool(
            primary_intent in {"comparison", "product_compare_recommendation"}
            or signals.get("comparison")
        ),
        "compound": bool(signals.get("compound")),
        "multi_product": bool(signals.get("multi_product")),
        "dedicated_route": bool(signals.get("dedicated_route")),
    }


def _should_use_category_field_general(
    *,
    structured_contract: customer_structured_query_contract.StructuredQueryContract,
    exclusions: dict[str, bool] | None,
) -> bool:
    if (
        structured_contract.status != "generic"
        or not structured_contract.subject_category
        or not structured_contract.field
        or structured_contract.operator is not None
        or structured_contract.value is not None
        or structured_contract.relation is not None
    ):
        return False
    return not any(bool(value) for value in (exclusions or {}).values())


def _classify_phase2_entity_state_action(
    question: str,
    phase1_plan: dict | None = None,
    *,
    conversation_id: str | None = None,
    signals: dict[str, bool] | None = None,
    entity_resolution_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Classify Phase 2 entity handling without formatting a response."""
    field_request = (
        (entity_resolution_context or {}).get("field_request")
        or resolve_requested_field_contract(question, phase1_plan)
    )
    if not _phase2_single_field_arbitration_eligible(
        question,
        phase1_plan,
        conversation_id=conversation_id,
        field_request_override=field_request,
    ):
        return {"action": "pass_through", "reason": "ineligible"}
    if (signals or {}).get("scenario_recommendation"):
        return {"action": "pass_through", "reason": "scenario_recommendation"}
    if (signals or {}).get("realtime_weather"):
        return {"action": "pass_through", "reason": "realtime_weather"}
    if (signals or {}).get("generic_heat_source_selection"):
        return {"action": "pass_through", "reason": "generic_heat_source_selection"}
    if (signals or {}).get("generic_accessory_catalog"):
        return {"action": "pass_through", "reason": "generic_accessory_catalog"}
    field = customer_field_contract.field_contract_for_type(field_request.get("field_type"))
    requested_field = field_request.get("requested_field")
    if not field or not requested_field:
        return {"action": "pass_through", "reason": "no_detail_field"}
    subject_selection = (entity_resolution_context or {}).get("entity_subject_selection")
    if subject_selection and _is_generic_company_product_scope(
        str(getattr(subject_selection, "entity_subject", "") or "")
    ):
        return {"action": "pass_through", "reason": "generic_company_product_scope"}
    # Every formal customer field, including safely unsupported realtime and
    # service fields, must arbitrate entity identity here.  The distinction
    # between supported evidence execution and safe missing is applied only
    # after the canonical SKU has been sealed.

    context = entity_resolution_context or {}
    products = list(context.get("products_snapshot") or [])
    contract = context.get("contract")
    if contract is None:
        return {"action": "pass_through", "reason": "entity_contract_unavailable"}

    if subject_selection and _is_generic_field_subject(str(getattr(subject_selection, "entity_subject", "") or "")):
        if (signals or {}).get("category_general"):
            # A formally parsed category+field aggregation (for example a
            # category's available capacities) owns this generic subject.
            # It must run before the single-product fail-closed clarification,
            # while exact/ambiguous named products remain protected by the
            # category-general exclusion gate.
            return {"action": "pass_through", "reason": "category_field_general"}
        # A category label plus a product-bound field is not permission to
        # promote search results into a single-product answer.  Keep the
        # FieldContract and return the same explicit clarification used for
        # any other generic entity state.
        return {"action": "generic_clarification", "reason": "generic_field_subject", "contract": contract}

    plan_primary_intent = str((phase1_plan or {}).get("primary_intent") or "").strip()
    planner_confirms_detail = plan_primary_intent in {"product_detail", "product_field"}
    field_contract_confirms_detail = bool(
        contract.entity_text
        and requested_field
        and (
            field_request.get("source") == "validated_semantic_preplan"
            or
            customer_field_contract.is_field_contract_predicate_signal(
                context.get("entity_subject_selection")
            )
            or _has_non_usage_care_field_contract(question)
        )
    )
    rich_field_compatibility = not plan_primary_intent and field.field_type in {
        "model",
        "dimensions",
        "specification",
    }

    high_priority_signal = any(
        bool(value)
        for key, value in (signals or {}).items()
        if key != "dedicated_route"
    ) or bool(
        (signals or {}).get("dedicated_route")
        and not _has_non_usage_care_field_contract(question)
    )

    resolved_exact = bool(
        contract.status == "resolved"
        and contract.resolved_sku
        and contract.is_unique
        and contract.confidence == "high"
        and contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
        and contract.resolver_candidate_skus == [contract.resolved_sku]
    )
    resolved_exact_blocked = bool(
        (signals or {}).get("recommendation")
        or (signals or {}).get("comparison")
        or (signals or {}).get("compound")
        or (signals or {}).get("multi_product")
        or (signals or {}).get("multi_condition_recommendation")
    )

    if not resolved_exact or resolved_exact_blocked:
        if high_priority_signal:
            return {"action": "pass_through", "reason": "higher_priority_route"}

        displayable_candidate_skus = _displayable_phase2_clarification_candidate_skus(contract)
        if (
            contract.status == "ambiguous"
            and displayable_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "ambiguous_clarification",
                "reason": "formal_candidates_ambiguous",
                "contract": contract,
                "products": products,
                "displayable_candidate_skus": displayable_candidate_skus,
            }
        if (
            contract.status == "ambiguous"
            and contract.resolver_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "unresolved_clarification",
                "reason": "weak_single_candidate_not_displayable",
                "contract": contract,
            }
        if (
            contract.status == "ambiguous"
            and contract.diagnostic_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "ambiguous_clarification",
                "reason": "diagnostic_candidates_not_displayable",
                "contract": contract,
                "products": products,
                "displayable_candidate_skus": [],
            }

        generic_scope = contract.status == "generic" or (
            not contract.resolver_candidate_skus
            and _looks_like_generic_constraint_category_query(question)
        )
        if generic_scope and field_contract_confirms_detail:
            return {"action": "generic_clarification", "reason": "generic_field_subject", "contract": contract}
        if generic_scope and planner_confirms_detail and isinstance(phase1_plan, dict):
            product_ref = _semantic_catalog_product_ref(question) or "产品"
            phase1_plan.update(
                {
                    "primary_intent": "catalog_count",
                    "answer_type": "query_products",
                    "product_ref": product_ref,
                    "field_only": False,
                    "allow_search_top1_promotion": False,
                    "entity_resolution_contract": contract.to_dict(),
                }
            )
            return {"action": "pass_through", "reason": "generic_category_constraint", "contract": contract}

        if (
            contract.status == "unresolved"
            and contract.entity_text
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {"action": "unresolved_clarification", "reason": "concrete_entity_unresolved", "contract": contract}
        return {"action": "pass_through", "reason": "no_entity_action", "contract": contract}

    return {
        "action": "resolved_detail",
        "reason": "resolved_exact_supported_field",
        "contract": contract,
        "products": products,
        "field": field,
        "requested_field": requested_field,
    }


def _displayable_phase2_clarification_candidate_skus(contract: Any) -> list[str]:
    if str(getattr(contract, "status", "") or "") != "ambiguous":
        return []
    unique_skus = list(dict.fromkeys(
        str(sku or "").strip().upper()
        for sku in (getattr(contract, "resolver_candidate_skus", None) or [])
        if str(sku or "").strip()
    ))
    return unique_skus if len(unique_skus) >= 2 else []


def _build_phase2_entity_state_response(db: Session, question: str, decision: dict[str, Any]) -> dict | None:
    """Format a previously classified Phase 2 entity-state decision."""
    action = str(decision.get("action") or "pass_through")
    if action == "pass_through":
        return None
    contract = decision.get("contract")
    products = list(decision.get("products") or [])
    if action == "ambiguous_clarification":
        displayable_candidate_skus = list(decision.get("displayable_candidate_skus") or [])
        product_by_sku = {
            str(product.sku or "").strip().upper(): product
            for product in products
        }
        options = [
            product_by_sku[sku]
            for sku in displayable_candidate_skus
            if sku in product_by_sku
        ]
        option_text = "；".join(
            f"{str(product.product_name_cn or product.product_name_en or product.sku).strip()}（{str(product.sku or '').strip().upper()}）"
            for product in options[:5]
        )
        route_source = (
            "named_product_unknown_field_clarification"
            if str(getattr(contract, "field_type", "") or "") in {"gift", "manual"}
            else "entity_state_detail_ambiguous"
        )
        answer = (
            f"“{contract.entity_text}”匹配到多个商品：{option_text}。请指定具体款式或 SKU。"
            if option_text
            else f"“{contract.entity_text}”对应多个相关商品，请先指定具体款式或 SKU。"
        )
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": answer,
            "results": [], "result_skus": [], "candidate_skus": displayable_candidate_skus,
            "needs_clarification": True,
            "answer_metadata": {"source": route_source, "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": route_source, "entity_resolution_contract": contract.to_dict()},
            "skip_polish": True,
        }
    if action == "unresolved_clarification":
        route_source = (
            "unresolved_product_like_contents_clarification"
            if str(getattr(contract, "field_type", "") or "") == "accessories"
            else (
                "unresolved_product_like_unknown_field_clarification"
                if str(getattr(contract, "field_type", "") or "") == "gift"
                else "entity_state_detail_unresolved"
            )
        )
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": f"没有找到“{contract.entity_text}”对应的商品资料，请确认商品名或提供 SKU。",
            "results": [], "result_skus": [], "candidate_skus": [], "needs_clarification": True,
            "answer_metadata": {"source": route_source, "evidence_status": "product_not_found"},
            "debug": {"agent_mode": route_source, "entity_resolution_contract": contract.to_dict()},
            "skip_polish": True,
        }
    if action == "generic_clarification":
        # The subject-selection guard has concluded that the phrase is a
        # generic category-like scope.  An earlier resolver observation may
        # have found a coincidental canonical-name match, but that observation
        # must not leak as an exact identity alongside a fail-closed generic
        # clarification.  This is an output-contract correction only: it
        # neither promotes a SKU nor changes the field's semantic meaning.
        generic_contract = contract.to_dict()
        generic_contract.update({
            "status": "generic",
            "resolved_sku": None,
            "resolver_candidate_skus": [],
            "diagnostic_candidate_skus": [],
            "candidate_skus": [],
            "matched_by": "none",
            "confidence": "low",
            "is_unique": False,
            "matched_span": None,
            "status_reason": "generic_field_subject",
        })
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": f"“{contract.entity_text}”还不是明确的单个商品，请提供完整商品名或 SKU。",
            "results": [], "result_skus": [], "candidate_skus": [], "needs_clarification": True,
            "answer_metadata": {"source": "entity_state_detail_generic", "evidence_status": "generic_product"},
            "debug": {
                "agent_mode": "entity_state_detail_generic",
                # A generic subject is deliberately never promoted to a product.
                # Keep that binding decision observable just like resolved/ambiguous
                # detail contracts, so downstream diagnostics cannot mistake this
                # clarification for a missing contract.
                "binding_provenance": "none",
                "search_top1_promotion_blocked": True,
                "entity_resolution_contract": generic_contract,
            },
            "skip_polish": True,
        }

    field = decision["field"]
    requested_field = decision["requested_field"]
    product = next(
        (item for item in products if str(item.sku or "").strip().upper() == contract.resolved_sku),
        None,
    )
    shipping_qa_evidence_available = bool(
        str(field.field_type or "") == "shipping"
        and product is not None
        and _best_product_qa_match(
            db,
            product,
            question,
            requested_field_type="shipping",
        ) is not None
    )

    if not customer_field_contract.is_supported_detail_field(field.field_type) and not shipping_qa_evidence_available:
        if not product:
            return None
        resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(
            contract,
            products,
        )
        result = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=requested_field,
            source="resolved_entity_detail_contract",
            resolution_decision=resolution_decision,
        )
    else:
        result = _product_field_followup_result(
            db,
            contract.resolved_sku,
            requested_field,
            question,
            identity_source="phase2_resolved_entity",
        )
        if not result:
            return None

    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    if metadata.get("evidence_status") == "missing" and contract.resolved_sku not in str(result.get("answer") or ""):
        product = next(
            (item for item in products if str(item.sku or "").strip().upper() == contract.resolved_sku),
            None,
        )
        name = str(getattr(product, "product_name_cn", "") or getattr(product, "product_name_en", "") or "").strip()
        prefix = f"{name}（{contract.resolved_sku}）" if name else contract.resolved_sku
        result["answer"] = f"{prefix}：{str(result.get('answer') or '').strip()}"
    preserves_unknown_field_route = not customer_field_contract.is_supported_detail_field(field.field_type) and not shipping_qa_evidence_available
    route_source = (
        "resolved_entity_unknown_field_fallback"
        if preserves_unknown_field_route
        else "resolved_entity_detail_contract"
    )
    debug["agent_mode"] = route_source
    debug["binding_provenance"] = "resolved_entity_contract"
    debug["search_top1_promotion_blocked"] = False
    debug["entity_resolution_contract"] = contract.to_dict()
    metadata["source"] = route_source
    metadata["contract_field_type"] = field.field_type
    result["debug"] = debug
    result["answer_metadata"] = metadata
    return result


def _phase2_entity_state_arbitration_result(
    db: Session,
    question: str,
    phase1_plan: dict | None = None,
    *,
    conversation_id: str | None = None,
    signals: dict[str, bool] | None = None,
    entity_resolution_context: dict[str, Any] | None = None,
) -> dict | None:
    """Arbitrate one-field entity states before legacy product-field routing."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    if (
        str(plan.get("primary_intent") or "") == "category_compatibility"
        and bool(plan.get("must_stay_within_category"))
        and str(plan.get("category_ref") or "").strip()
    ):
        return None
    # Every recognised formal field, including safely unsupported and
    # realtime-bound fields, must first seal identity here.  The formatter
    # below selects same-SKU evidence or the field-specific safe-missing
    # response; returning early here previously leaked such requests to
    # generic recommendation/tool routes without an entity contract.
    context = entity_resolution_context
    if context is None:
        predecision = _classify_phase2_entity_state_action(
            question,
            phase1_plan,
            conversation_id=conversation_id,
            signals=signals,
            entity_resolution_context={},
        )
        if predecision.get("reason") != "entity_contract_unavailable":
            return _build_phase2_entity_state_response(db, question, predecision)
        context = _build_phase2_entity_resolution_context(
            db,
            question,
            resolve_requested_field_contract(question, phase1_plan),
            phase1_plan,
        )
    decision = _classify_phase2_entity_state_action(
        question,
        phase1_plan,
        conversation_id=conversation_id,
        signals=signals,
        entity_resolution_context=context,
    )
    result = _build_phase2_entity_state_response(db, question, decision)
    effective_field_request = context.get("field_request") if isinstance(context, dict) else None
    if isinstance(result, dict) and isinstance(effective_field_request, dict):
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["field_contract"] = dict(effective_field_request)
        debug_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
        debug_plan["field_contract"] = dict(effective_field_request)
        debug["plan"] = debug_plan
        result["debug"] = debug
    return result


def _normalize_alcohol_stove_cookware_list_answer_type(question: str, agent_result: dict | None) -> dict | None:
    if not isinstance(agent_result, dict):
        return agent_result
    if str(agent_result.get("answer_type") or "").strip() != "product_detail":
        return agent_result
    if customer_agent_service._extract_skus(question):
        return agent_result
    if not customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(question):
        return agent_result
    rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    if not rows:
        return agent_result
    normalized = dict(agent_result)
    normalized["intent"] = "query_products"
    normalized["answer_type"] = "product_query"
    return normalized


def _phase1_row_has_explicit_alcohol_stove_support(db: Session, row: dict[str, Any]) -> bool:
    if not isinstance(row, dict):
        return False
    heat_source = str(row.get("heat_source") or "").strip()
    if customer_agent_intent_service._alcohol_stove_support_verdict(heat_source) is True:
        return True
    field_values = row.get("field_values")
    if isinstance(field_values, dict):
        field_heat_source = str(field_values.get("热源") or field_values.get("适用热源") or "").strip()
        if customer_agent_intent_service._alcohol_stove_support_verdict(field_heat_source) is True:
            return True
    return False


def _sync_alcohol_stove_cookware_scope_metadata(
    result: dict,
    *,
    skus: list[str],
    rows: list[dict[str, Any]],
    question: str,
) -> dict:
    normalized_skus = [
        str(sku or "").strip().upper()
        for sku in skus
        if str(sku or "").strip()
    ]
    result["result_skus"] = normalized_skus
    result["candidate_skus"] = normalized_skus
    sources = list(result.get("sources") or [])
    scoped_context = {
        "candidate_skus": normalized_skus,
        "ordered_result_skus": normalized_skus,
        "filtered_skus": normalized_skus,
        "recommended_skus": [
            str(sku or "").strip().upper()
            for sku in (result.get("recommended_skus") or [])
            if str(sku or "").strip().upper() in set(normalized_skus)
        ],
        "product_scope": "锅具",
        "user_question": question,
        "applied_filter": {"specs.heat_source": "酒精炉", "product.category": "锅具"},
        "empty_subset": False,
    }
    meta = next((item for item in sources if isinstance(item, dict) and item.get("type") == "agent_meta"), None)
    if isinstance(meta, dict):
        meta["candidate_context"] = dict(scoped_context)
    else:
        sources.append({"type": "agent_meta", "candidate_context": dict(scoped_context)})
    result["sources"] = sources
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    intent_debug = debug.get("intent") if isinstance(debug.get("intent"), dict) else {}
    filters = intent_debug.get("filters") if isinstance(intent_debug.get("filters"), dict) else {}
    filters["product.category"] = "锅具"
    filters["specs.heat_source"] = "酒精炉"
    intent_debug["filters"] = filters
    debug["intent"] = intent_debug
    debug["raw_results"] = list(rows)
    debug["candidate_skus"] = normalized_skus
    debug["alcohol_stove_cookware_scope"] = "pot_or_cookware_set_only"
    result["debug"] = debug
    return result


def _run_phase1_answer_guard(agent_result: dict, plan: dict) -> dict:
    if not isinstance(agent_result, dict) or not isinstance(plan, dict):
        return agent_result
    primary_intent = str(plan.get("primary_intent") or "")
    plan_question = ""
    for key in ("raw_question", "question", "scenario", "semantic_query", "recommendation_query"):
        value = str(plan.get(key) or "").strip()
        if value:
            plan_question = value
            break
    recommendation_like_contract = bool(
        primary_intent == "recommendation"
        or plan.get("must_return_products")
        or _looks_like_recommendation_request(plan_question)
        or customer_agent_intent_service._looks_like_scenario_recommendation_question(plan_question)
    )
    if recommendation_like_contract and agent_result.get("answer_type") == "knowledge_base_answer":
        skus = _phase1_result_skus(agent_result)
        if skus:
            agent_result["answer"] = f"更建议先看 {skus[0]}。它更贴近你的使用场景，建议结合容量、重量、便携性和适用人数确认。"
        else:
            agent_result["answer"] = "当前资料里没有找到足够明确、可推荐的具体产品；建议补充人数、场景、预算或希望的品类后再推荐。"
        agent_result["answer_type"] = "recommendation"
        agent_result["intent"] = "recommendation"
        agent_result["skip_polish"] = True
    if plan.get("must_return_products") and not _phase1_answer_mentions_product(agent_result):
        skus = _phase1_result_skus(agent_result)
        if skus:
            agent_result["answer"] = f"更建议先看 {skus[0]}。它更贴近你的使用场景，建议结合容量、重量、便携性和适用人数确认。"
            agent_result["answer_type"] = "recommendation"
            agent_result["intent"] = "recommendation"
            agent_result["skip_polish"] = True
    if primary_intent == "product_field" and plan.get("field_only"):
        requested_field = str(plan.get("requested_field") or "").strip()
        answer = str(agent_result.get("answer") or "")
        field_answered = requested_field in answer
        if requested_field == "heat_source":
            field_answered = any(term in answer for term in ("酒精炉", "适用热源", "热源"))
        if requested_field and not field_answered:
            product_ref = str(plan.get("product_ref") or "").strip()
            agent_result["answer"] = f"当前资料里没有找到{product_ref}的明确{requested_field}。"
            agent_result["answer_type"] = "product_detail"
            agent_result["intent"] = "product_detail"
            agent_result["skip_polish"] = True
    if plan.get("must_not_recommend_other_categories"):
        rows = [item for item in agent_result.get("results") or [] if isinstance(item, dict)]
        skus = [str(item.get("sku") or "").strip().upper() for item in rows if str(item.get("sku") or "").strip()]
        agent_result["intent"] = "product_detail"
        agent_result["answer_type"] = "product_detail"
        agent_result["results"] = rows
        agent_result["result_skus"] = skus
        agent_result["candidate_skus"] = skus
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["raw_results"] = rows
        debug["candidate_skus"] = skus
        agent_result["debug"] = debug
        agent_result["skip_polish"] = True
    comparison_contract = bool(
        primary_intent == "comparison"
        or plan.get("must_compare_both_products")
        or str(agent_result.get("answer_type") or "").strip() == "comparison"
    )
    explicit_comparison_skus = list(dict.fromkeys(
        str(sku or "").strip().upper()
        for sku in customer_agent_service._extract_skus(plan_question)
        if str(sku or "").strip()
    ))
    if comparison_contract and len(explicit_comparison_skus) >= 2:
        answer = str(agent_result.get("answer") or "")
        if not all(sku in answer.upper() for sku in explicit_comparison_skus):
            first_sku, second_sku = explicit_comparison_skus[:2]
            agent_result["answer"] = (
                f"{first_sku} 和 {second_sku} 是两个不同的 SKU，不能视为同一款商品。"
                "如需继续比较规格或适用场景，请指定要对比的字段。"
            )
            matching_rows = [
                row for row in (agent_result.get("results") or [])
                if isinstance(row, dict)
                and str(row.get("sku") or "").strip().upper() in set(explicit_comparison_skus)
            ]
            agent_result["results"] = matching_rows
            agent_result["result_skus"] = explicit_comparison_skus
            agent_result["candidate_skus"] = explicit_comparison_skus
            agent_result["intent"] = "compare_products"
            agent_result["answer_type"] = "comparison"
            agent_result["skip_polish"] = True
    return agent_result


async def _attach_debug_supporting_knowledge(db: Session, result: dict, question: str) -> dict:
    """Attach QA/KB evidence for dev observability without changing the chosen answer."""
    if not isinstance(result, dict):
        return result
    try:
        return await customer_agent_intent_service.attach_supporting_knowledge_evidence(
            db,
            result,
            question,
            primary_source=(result.get("answer_metadata") or {}).get("final_decision", {}).get("primary_source") or "existing_route",
        )
    except Exception:
        return result


def list_conversations(db: Session, user_id: str, skip: int = 0, limit: int = 30) -> dict:
    user_id = str(user_id)
    query = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.user_id == user_id
    ).order_by(CustomerServiceConversation.updated_at.desc())
    total = query.count()
    items = query.offset(skip).limit(limit).all()
    previews = _conversation_previews(db, [item.id for item in items])
    return {
        "items": [_conversation_list_item(item, previews.get(item.id, {})) for item in items],
        "total": total,
    }


def _conversation_previews(db: Session, conversation_ids: list[str]) -> dict[str, dict]:
    if not conversation_ids:
        return {}
    previews: dict[str, dict] = {conversation_id: {} for conversation_id in conversation_ids}
    rows = (
        db.query(CustomerServiceMessage)
        .filter(CustomerServiceMessage.conversation_id.in_(conversation_ids))
        .order_by(CustomerServiceMessage.conversation_id.asc(), CustomerServiceMessage.created_at.desc())
        .all()
    )
    for message in rows:
        preview = previews.setdefault(message.conversation_id, {})
        preview.setdefault("last_any", message)
        if message.role == "assistant":
            preview.setdefault("last_assistant", message)
    return previews


def _conversation_list_item(item: CustomerServiceConversation, preview: dict) -> dict:
    preview_message = preview.get("last_assistant") or preview.get("last_any")
    preview = str(preview_message.content or "") if preview_message else ""
    return {
        "id": item.id,
        "title": item.title,
        "sku": item.sku,
        "last_message": preview[:120],
        "last_message_role": preview_message.role if preview_message else None,
        "last_message_at": str(preview_message.created_at) if preview_message and preview_message.created_at else None,
        "created_at": str(item.created_at),
        "updated_at": str(item.updated_at),
    }


def get_conversation(db: Session, conversation_id: str, user_id: str) -> dict:
    user_id = str(user_id)
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == user_id,
    ).first()
    if not conversation:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服会话不存在")

    messages = db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id
    ).order_by(CustomerServiceMessage.created_at.asc()).all()
    payload = []
    for item in messages:
        meta = _message_meta(item.sources_json)
        payload.append(
            {
                "id": item.id,
                "role": item.role,
                "content": item.content,
                "sku": item.sku,
                "sources": _safe_json(item.sources_json, []),
                "steps": _steps_from_sources(item.sources_json),
                "intent": meta.get("intent"),
                "answer_type": meta.get("answer_type"),
                "confidence": meta.get("confidence"),
                "uncertainty": meta.get("uncertainty"),
                "needs_clarification": meta.get("needs_clarification", False),
                "anomalies": meta.get("anomalies", []),
                "suggested_followups": meta.get("suggested_followups", meta.get("followups", [])),
                "followups": meta.get("followups", meta.get("suggested_followups", [])),
                "warnings": meta.get("warnings", []),
                "evidence": meta.get("evidence", []),
                "agent_quality": meta.get("agent_quality", {}),
                "debug": meta.get("debug", {}),
                "feedback": meta.get("feedback"),
                "created_at": str(item.created_at),
            }
        )
    return {
        "id": conversation.id,
        "title": conversation.title,
        "sku": conversation.sku,
        "created_at": str(conversation.created_at),
        "updated_at": str(conversation.updated_at),
        "messages": payload,
    }


def delete_conversation(db: Session, conversation_id: str, user_id: str) -> dict:
    user_id = str(user_id)
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == user_id,
    ).first()
    if not conversation:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服会话不存在")

    # Do not rely solely on the database FK's ON DELETE CASCADE here.  Some
    # development/test SQLite connections do not enforce foreign keys, which
    # leaves orphaned turns behind and can make a deleted chat appear again in
    # later previews.  The ownership check above scopes both deletes to this
    # exact conversation.
    db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id
    ).delete(synchronize_session=False)
    db.delete(conversation)
    db.commit()
    return {"deleted": True, "id": conversation_id}


def save_message_feedback(
    db: Session,
    *,
    user_id: str,
    message_id: str,
    rating: str,
    reason: str | None = None,
    comment: str | None = None,
) -> dict:
    allowed = {"helpful", "incorrect", "missing_data"}
    if rating not in allowed:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="反馈类型不支持")
    message = (
        db.query(CustomerServiceMessage)
        .join(CustomerServiceConversation, CustomerServiceConversation.id == CustomerServiceMessage.conversation_id)
        .filter(
            CustomerServiceMessage.id == message_id,
            CustomerServiceMessage.role == "assistant",
            CustomerServiceConversation.user_id == str(user_id),
        )
        .first()
    )
    if not message:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服消息不存在")

    sources = _safe_json(message.sources_json, [])
    meta = None
    for source in sources:
        if isinstance(source, dict) and source.get("type") == "agent_meta":
            meta = source
            break
    if meta is None:
        meta = {"type": "agent_meta", "label": "客服回复元数据"}
        sources.append(meta)
    feedback = {
        "rating": rating,
        "reason": reason or "",
        "comment": comment or "",
    }
    meta["feedback"] = feedback
    message.sources_json = json.dumps(sources, ensure_ascii=False, default=str)
    db.commit()
    return {"message_id": message.id, "feedback": feedback}


async def ask_customer_service(
    db: Session,
    *,
    user_id: str,
    question: str,
    sku: str | None = None,
    conversation_id: str | None = None,
    answer_delta_callback: Callable[[str], Awaitable[None]] | None = None,
) -> dict:
    user_id = str(user_id)
    question = question.strip()
    if not question:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="问题不能为空")
    if not customer_perf_service.get_trace_id():
        customer_perf_service.start_trace()
    request_start = perf_counter()
    planner_start = perf_counter()
    phase1_plan = customer_agent_planner_service.plan_customer_question(question)
    planner_duration_ms = round((perf_counter() - planner_start) * 1000, 2)
    # A catalogue-looking deterministic label is only a weak diagnostic.  It
    # must not execute an exact QA before semantic preplanning: natural named
    # product questions often contain words such as "what" or "which" while
    # asking a formal field (for example prohibited actions or colour).  The
    # post-preplan same-SKU QA branch remains available when the semantic plan
    # intentionally has no formal field; QA is then evidence, not the route.
    semantic_preplan = await _maybe_run_semantic_preplan(
        db,
        question,
        phase1_plan,
        conversation_id=conversation_id,
    )
    if isinstance(phase1_plan, dict):
        phase1_plan["_db"] = db
    if isinstance(semantic_preplan, dict) and semantic_preplan.get("called"):
        _apply_pairwise_recommendation_field_adapter(semantic_preplan)
        _apply_structured_named_field_entity_adapter(db, question, semantic_preplan)
        catalog_value_fields = {"series", "brand", "category", "product_level"}
        semantic_catalog_fields = {
            customer_field_contract.semantic_preplan_field_type(item)
            for item in [
                semantic_preplan.get("field_type"),
                semantic_preplan.get("field_hint"),
                semantic_preplan.get("catalogue_field_candidate"),
                *(semantic_preplan.get("canonical_fields") or []),
            ]
        }
        semantic_catalog_fields.discard("")
        semantic_catalog_failure = bool(
            str(semantic_preplan.get("semantic_route_family_hint") or "") == "structured_query"
            and str(semantic_preplan.get("fallback_reason") or "") in {
                "incomplete_structured_query_scope",
                "catalogue_value_requires_structured_query",
                "unbound_catalogue_browse_requires_structured_query",
            }
            and str(semantic_preplan.get("catalogue_field_candidate") or "") in catalog_value_fields
        )
        # A collection filter has no product identity in this turn.  The
        # semantic provider may omit a literal SKU/name from `entities` while
        # correctly recognizing its field, so independently verify the
        # customer-visible span before letting the collection preflight run.
        # This only protects ownership boundaries; it does not resolve a SKU
        # or create evidence. The ordinary FieldContract/EntityResolution
        # path still performs that work for a named product.
        current_turn_unique_product = bool(
            customer_entity_resolution_contract.unique_canonical_subject_in_question(
                question,
                _products_named_in_question(db, question),
            )
            or customer_agent_service._extract_skus(question)
        )
        is_unbound_catalogue_value_query = bool(
            # A high-confidence semantic structured query owns the set scope.
            # Incidental product-shaped substrings must not override it; an
            # explicit semantic entity remains the only product-fact signal.
            not (semantic_preplan.get("entities") or [])
            and (
                not current_turn_unique_product
                or (
                    str(semantic_preplan.get("route_family") or "") == "structured_query"
                    and not str(semantic_preplan.get("fallback_reason") or "")
                )
            )
            and (
                bool(semantic_catalog_fields)
                and semantic_catalog_fields.issubset(catalog_value_fields)
                and not str(semantic_preplan.get("fallback_reason") or "")
                or semantic_catalog_failure
            )
        )
        if is_unbound_catalogue_value_query:
            early_catalog_result = _semantic_catalog_value_query_result(db, question, semantic_preplan)
            if early_catalog_result is None:
                adapted_catalog_plan = await _semantic_catalog_value_exact_adapter(
                    db,
                    question=question,
                    semantic_preplan=semantic_preplan,
                )
                if adapted_catalog_plan is not None:
                    early_catalog_result = _semantic_catalog_value_query_result(
                        db, question, adapted_catalog_plan
                    )
                if early_catalog_result:
                    metadata = early_catalog_result.setdefault("answer_metadata", {})
                    if isinstance(metadata, dict):
                        metadata["catalog_value_adapter"] = "semantic_exact_live_value"
            if early_catalog_result:
                early_catalog_result = _attach_phase1_plan_and_timing(
                    early_catalog_result,
                    phase1_plan,
                    _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
                )
                early_catalog_result = _attach_semantic_preplan_debug(
                    early_catalog_result, semantic_preplan, final_route="product_query"
                )
                return await _save_agent_result_and_return(
                    db, user_id=user_id, question=question, conversation_id=conversation_id,
                    agent_result=early_catalog_result, request_start=request_start,
                    branch="semantic_catalog_value_preflight", semantic_preplan=semantic_preplan,
                )
            early_catalog_clarification = {
                "intent": "query_products",
                "answer_type": "clarification",
                "answer": "当前无法将该系列、品牌、类目或商品分级稳定对应到可核验的商品范围。请提供更完整的名称、商品名或 SKU 后再查询。",
                "results": [], "result_skus": [], "candidate_skus": [], "evidence": [],
                "debug": {"agent_mode": "semantic_catalog_value_preflight_clarification"},
                "answer_metadata": {"source": "semantic_catalog_value_preflight_clarification"},
                "skip_polish": True,
            }
            early_catalog_clarification = _attach_phase1_plan_and_timing(
                early_catalog_clarification,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            early_catalog_clarification = _attach_semantic_preplan_debug(
                early_catalog_clarification, semantic_preplan, final_route="clarification"
            )
            return await _save_agent_result_and_return(
                db, user_id=user_id, question=question, conversation_id=conversation_id,
                agent_result=early_catalog_clarification, request_start=request_start,
                branch="semantic_catalog_value_preflight_clarification", semantic_preplan=semantic_preplan,
            )
        if (
            str(semantic_preplan.get("route_family") or "") == "generic_query"
            and str(semantic_preplan.get("route_hint") or "") == "query_products"
            and str(semantic_preplan.get("question_type") or "") in {"filter", "list", "count"}
            and not semantic_preplan.get("entities")
            and not current_turn_unique_product
        ):
            generic_catalog_clarification = {
                "intent": "query_products",
                "answer_type": "clarification",
                "answer": "我识别到你想查询产品集合，但当前没有找到可核验的系列、品牌、类目或分级值。请补充中文名称、SKU，或确认筛选条件。",
                "results": [], "result_skus": [], "candidate_skus": [], "evidence": [],
                "debug": {"agent_mode": "semantic_catalog_unresolved_value_clarification"},
                "answer_metadata": {"source": "semantic_catalog_unresolved_value_clarification"},
                "skip_polish": True,
            }
            return await _save_agent_result_and_return(
                db, user_id=user_id, question=question, conversation_id=conversation_id,
                agent_result=generic_catalog_clarification, request_start=request_start,
                branch="semantic_catalog_unresolved_value_clarification", semantic_preplan=semantic_preplan,
            )
        if (
            _semantic_preplan_route_family(semantic_preplan) == "recommendation"
            and not bool(semantic_preplan.get("evidence_required"))
            and not (semantic_preplan.get("recommendation_constraints") or {})
            and _semantic_preplan_entity_scope(semantic_preplan) not in {
                "unresolved_product_like", "unresolved_product",
                "negative_product_like", "negative_product",
            }
        ):
            # After semantic constraint reconciliation, a recommendation with
            # no evidence requirement and no executable catalogue constraint
            # is category-level decision guidance. Keep the model's explicit
            # non-evidentiary decision, but route it to the ordinary DeepSeek
            # advisor rather than asking the customer to name a product type.
            semantic_preplan["route_family"] = "general_chat"
            semantic_preplan["route_hint"] = "clarification"
            semantic_preplan["entities"] = []
            semantic_preplan["canonical_fields"] = []
        phase1_plan["semantic_preplan"] = semantic_preplan
        if _semantic_prefers_sealed_product_qa(phase1_plan):
            formal_field_request = customer_field_contract.resolve_requested_field_contract(
                question,
                phase1_plan,
            )
            formal_field_type = str(formal_field_request.get("field_type") or "").strip()
            if formal_field_type in customer_field_contract.FORMAL_DETAIL_FIELDS:
                # A provider may label a natural formal-field paraphrase as
                # product QA. Normalize that plan once at the central
                # arbitration boundary so no later shortcut can consume it.
                semantic_preplan.update({
                    "route_family": "product_bound_qa",
                    "evidence_kind": "structured_field",
                    "field_type": formal_field_type,
                    "field_hint": formal_field_type,
                    "canonical_fields": [formal_field_type],
                    "qa_evidence_query": "",
                    "qa_evidence_queries": [],
                    "accepted_or_overridden": "formal_field_contract",
                })
                phase1_plan["semantic_preplan"] = semantic_preplan
            else:
            # The semantic plan has explicitly classified this as a
            # non-formal product QA turn. Legacy planner hints may still have
            # extracted a noun such as “规格” from the sentence, but cannot
            # turn that noun into the answer field after semantic arbitration.
            # Keep only the product-bound QA route; identity and evidence are
            # still sealed by their ordinary central contracts below.
                phase1_plan["requested_field"] = ""
                phase1_plan["requested_fields"] = []
                phase1_plan["field_only"] = False
                phase1_plan["tasks"] = [
                    task
                    for task in phase1_plan.get("tasks") or []
                    if not (isinstance(task, dict) and task.get("type") == "product_field")
                ]
        # A sealed exact QA outside the formal field ontology has stronger
        # evidence than a semantic attempt to force it into an unrelated
        # formal field.  Formal FieldContracts do not enter this branch.
        # Do not probe the QA shortcut before Phase 2 unless semantic planning
        # has explicitly classified the turn as product-bound QA. Otherwise a
        # failed/absent semantic call still rebuilds entity identity before the
        # formal FieldContract gets its one authoritative resolution pass.
        exact_generic_qa = (
            await _try_product_qa_shortcut_with_semantic_selection(
                db,
                question,
                phase1_plan=phase1_plan,
            )
            if (
                _semantic_allows_exact_sealed_product_qa(phase1_plan)
                and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
            )
            else None
        )
        if (
            exact_generic_qa
            and not _is_sealed_product_qa_safe_missing(exact_generic_qa)
            and (
                ((exact_generic_qa.get("debug") or {}).get("field_contract") or {}).get("field_type") == "product_qa"
                or _semantic_preplan_route_family(semantic_preplan) == "structured_query"
            )
            and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
        ):
            exact_generic_qa = _attach_phase1_plan_and_timing(
                exact_generic_qa,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=exact_generic_qa,
                request_start=request_start,
                branch="sealed_exact_product_qa_before_semantic_field",
                semantic_preplan=semantic_preplan,
            )
        if _semantic_pairwise_contract_candidate(semantic_preplan) and _semantic_preplan_confident(
            semantic_preplan,
            minimum=0.9,
        ):
            # Semantic planning owns comparison meaning and the participant
            # spans.  The catalogue is consulted only to validate each span
            # into its own EntityResolutionContract; it never receives an LLM
            # SKU choice or a lexical comparison rule.
            comparison_context_skus = (
                _latest_active_product_skus(db, conversation_id, user_id)
                if conversation_id
                else []
            )
            comparison_context_anchor_sku = (
                comparison_context_skus[0]
                if len(comparison_context_skus) == 1
                else None
            )
            comparison_contracts = _apply_semantic_comparison_plan(
                question,
                phase1_plan,
                semantic_preplan,
                db.query(Product).order_by(Product.sku.asc()).all(),
                context_anchor_sku=comparison_context_anchor_sku,
            )
            if not comparison_contracts:
                semantic_comparison_clarification = _semantic_comparison_fail_closed_result(semantic_preplan)
                if semantic_comparison_clarification:
                    semantic_comparison_clarification = _attach_phase1_plan_and_timing(
                        semantic_comparison_clarification,
                        phase1_plan,
                        _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
                    )
                    semantic_comparison_clarification = _attach_semantic_preplan_debug(
                        semantic_comparison_clarification,
                        semantic_preplan,
                        final_route="clarification",
                    )
                    return await _save_agent_result_and_return(
                        db,
                        user_id=user_id,
                        question=question,
                        conversation_id=conversation_id,
                        agent_result=semantic_comparison_clarification,
                        request_start=request_start,
                        branch="semantic_comparison_unsealed_pre_phase2",
                        semantic_preplan=semantic_preplan,
                    )
        semantic_field = str(semantic_preplan.get("field_type") or "").strip()
        semantic_catalog_aggregate = _semantic_catalog_aggregate_contract(semantic_preplan, phase1_plan)
        semantic_catalog_value_result = _semantic_catalog_value_query_result(
            db,
            question,
            semantic_preplan,
        )
        if semantic_catalog_value_result is None:
            adapted_catalog_plan = await _semantic_catalog_value_exact_adapter(
                db,
                question=question,
                semantic_preplan=semantic_preplan,
            )
            if adapted_catalog_plan is not None:
                semantic_catalog_value_result = _semantic_catalog_value_query_result(
                    db,
                    question,
                    adapted_catalog_plan,
                )
                if semantic_catalog_value_result:
                    metadata = semantic_catalog_value_result.setdefault("answer_metadata", {})
                    if isinstance(metadata, dict):
                        metadata["catalog_value_adapter"] = "semantic_exact_live_value"
        if semantic_catalog_value_result:
            semantic_catalog_value_result = _attach_phase1_plan_and_timing(
                semantic_catalog_value_result,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            semantic_catalog_value_result = _attach_semantic_preplan_debug(
                semantic_catalog_value_result,
                semantic_preplan,
                final_route="product_query",
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=semantic_catalog_value_result,
                request_start=request_start,
                branch="semantic_database_value_catalog_filter",
                semantic_preplan=semantic_preplan,
            )
        if (
            semantic_field in {"series", "brand", "category", "product_level"}
            and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
            and _semantic_preplan_route_family(semantic_preplan) == "structured_query"
            and str(semantic_preplan.get("route_hint") or "") == "query_products"
            and not (semantic_preplan.get("entities") or [])
            and not any(token in question for token in ("多少", "几款", "几种", "几个"))
            and not semantic_catalog_aggregate
        ):
            label = customer_field_contract.product_detail_field_label(semantic_field) or "筛选条件"
            safe_catalog_miss = {
                "intent": "query_products",
                "answer_type": "clarification",
                "answer": f"当前资料中未能将该{label}条件稳定对应到可核验的商品范围，请提供更完整的系列、品牌或类目名称后再查询。",
                "results": [], "result_skus": [], "candidate_skus": [], "evidence": [],
                "debug": {"agent_mode": "semantic_catalog_value_unverified_clarification"},
                "answer_metadata": {"source": "semantic_catalog_value_unverified_clarification"},
                "skip_polish": True,
            }
            return await _save_agent_result_and_return(
                db, user_id=user_id, question=question, conversation_id=conversation_id,
                agent_result=safe_catalog_miss, request_start=request_start,
                branch="semantic_catalog_value_unverified_clarification", semantic_preplan=semantic_preplan,
            )
        if (
            semantic_field in customer_field_contract.FORMAL_DETAIL_FIELDS
            and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
            and str(semantic_preplan.get("route_family") or "").strip() != "comparison"
            and not semantic_catalog_aggregate
        ):
            # The semantic preplan has only classified the requested field; it
            # has not supplied an entity or an answer.  Normalize the legacy
            # planner label before any Phase-1 executor can use its weaker
            # keyword interpretation, leaving Phase 2 to seal identity and
            # obtain structured same-SKU evidence.
            _apply_semantic_single_field_route_precedence(
                phase1_plan,
                semantic_preplan,
            )
            phase1_plan["requested_field"] = customer_field_contract.product_detail_field_label(semantic_field)
        if _should_execute_semantic_catalog_recommendation(semantic_preplan):
            # Route ownership comes from the full-sentence semantic plan.
            # A legacy catalogue/count label may remain as diagnostics, but it
            # cannot suppress an allowlisted recommendation contract.
            phase1_plan["primary_intent"] = "recommendation"
            phase1_plan["answer_type"] = "recommendation"
            phase1_plan["scenario"] = question

    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) == "general_chat"
        and not (semantic_preplan.get("entities") or [])
        and not (semantic_preplan.get("canonical_fields") or [])
        and not bool(semantic_preplan.get("evidence_required"))
        and not _products_named_in_question(db, question)
    ):
        answer = ""
        try:
            semantic_runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
            messages = [
                {
                    "role": "system",
                    "content": "You are a concise Chinese outdoor-product customer assistant. Respond naturally to ordinary conversation and general decision guidance. You may explain preparation checklists, beginner considerations, category-level tradeoffs, and general outdoor safety in practical terms. Do not state or infer any catalogue product fact, SKU, price, stock, shipping, warranty, promotion, or after-sales policy. Do not pretend to have searched the product catalogue and do not recommend a specific product. Ask one focused follow-up only when it is genuinely needed to make the general guidance useful.",
                },
                {"role": "user", "content": question},
            ]
            # A provider can occasionally return a blank successful response.
            # Retry the same non-evidentiary request once; this preserves the
            # semantic route without inventing a product-specific fallback.
            for _attempt in range(2):
                answer = str(await customer_llm_service.chat_completion(
                    db,
                    messages,
                    temperature=0.4,
                    # General guidance can legitimately need a short
                    # comparison plus a practical next step.  Keep one
                    # shared completion budget so the response is complete
                    # instead of being cut off mid-sentence.
                    max_tokens=320,
                    purpose="general_customer_chat",
                    # The default chat model can return an empty successful
                    # completion for ordinary advice. Use the same configured
                    # DeepSeek runtime that has already produced the semantic
                    # plan for this turn; it remains non-evidentiary and does
                    # not gain access to product facts or catalogue results.
                    api_model_override=semantic_runtime["model"],
                    thinking=semantic_runtime["thinking"],
                ) or "").strip()
                if answer:
                    break
        except Exception:
            answer = ""
        # Providers can return an empty successful completion.  A general
        # conversation turn has no product evidence to wait for, so preserve a
        # useful, non-product-specific response instead of emitting an empty
        # customer message.
        answer = str(answer or "").strip() or (
            "可以先从人数、行程、天气、是否需要做热食和收纳空间来梳理。"
            "你告诉我最在意的一项，我可以帮你把准备重点排个顺序。"
        )
        general_chat_result = {
            "answer": answer,
            "intent": "general_chat",
            "answer_type": "chat",
            "confidence": "high",
            "uncertainty": "resolved",
            "needs_clarification": False,
            "anomalies": [], "suggested_followups": [], "followups": [], "warnings": [],
            "evidence": [], "sources": [{"type": "semantic_chat", "label": "DeepSeek ordinary conversation"}],
            "actions": [], "results": [], "result_skus": [], "candidate_skus": [],
            "answer_metadata": {"source": "semantic_general_chat", "evidence_status": "not_applicable"},
            "debug": {"agent_mode": "semantic_general_chat"},
            "skip_polish": True,
        }
        general_chat_result = _attach_phase1_plan_and_timing(
            general_chat_result, phase1_plan, _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms)
        )
        return await _save_agent_result_and_return(
            db, user_id=user_id, question=question, conversation_id=conversation_id,
            agent_result=general_chat_result, request_start=request_start,
            branch="semantic_general_chat", semantic_preplan=semantic_preplan,
        )

    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and (
            _semantic_preplan_route_family(semantic_preplan) == "knowledge_base_meta"
            or str(semantic_preplan.get("information_scope") or "").strip() == "knowledge_base_meta"
        )
        and not (semantic_preplan.get("entities") or [])
        and not (semantic_preplan.get("canonical_fields") or [])
    ):
        knowledge_meta_result = {
            "answer": "当前问题需要先定位具体知识库文件或商品资料；在没有可核验来源绑定时，不能据此生成商品推荐。请提供文件名称、商品名或 SKU 后再继续。",
            "intent": "clarification",
            "answer_type": "clarification",
            "confidence": "high",
            "uncertainty": "needs_source_scope",
            "needs_clarification": True,
            "anomalies": [],
            "suggested_followups": [],
            "followups": [],
            "warnings": ["unbound_knowledge_source"],
            "evidence": [],
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "answer_metadata": {
                "answer_policy": "source_scope_clarification",
                "evidence_status": "unbound",
                "final_decision": {"primary_source": "semantic_preplan", "priority": 1, "single_source_of_truth": True, "llm_allowed": False},
            },
            "debug": {"agent_mode": "semantic_unbound_knowledge_meta_clarification"},
        }
        knowledge_meta_result = _attach_phase1_plan_and_timing(
            knowledge_meta_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        knowledge_meta_result = _attach_semantic_preplan_debug(
            knowledge_meta_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=knowledge_meta_result,
            request_start=request_start,
            branch="semantic_unbound_knowledge_meta_clarification",
            semantic_preplan=semantic_preplan,
        )

    semantic_preplan_unavailable_result = _semantic_preplan_unavailable_clarification_result(
        semantic_preplan,
        db=db,
        question=question,
        phase1_plan=phase1_plan,
    )
    if semantic_preplan_unavailable_result:
        semantic_preplan_unavailable_result = _attach_phase1_plan_and_timing(
            semantic_preplan_unavailable_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_preplan_unavailable_result,
            request_start=request_start,
            branch="semantic_preplan_unavailable_clarification",
            semantic_preplan=semantic_preplan,
        )

    # A validated semantic plan can explicitly classify a catalogue-level
    # realtime/commercial question (for example sales or reviews) as safely
    # unsupported.  Preserve that field meaning before generic field
    # clarification or recommendation routing sees category words in the same
    # sentence.  This does not infer a field from wording: the semantic subtype
    # authorizes only the existing safe-missing formatter.
    if (
        _semantic_preplan_unknown_realtime_subtype(semantic_preplan, question)
        and _semantic_preplan_entity_scope(semantic_preplan) in {"category_scope", "generic_scope"}
        and str((semantic_preplan or {}).get("subtype") or "").strip() != "no_match"
        and not [item for item in ((semantic_preplan or {}).get("entities") or []) if str(item or "").strip()]
        and not _products_named_in_question(db, question)
    ):
        semantic_unknown_catalog_result = _unknown_product_fact_result(
            question,
            semantic_authorized=True,
        )
        if semantic_unknown_catalog_result:
            semantic_unknown_catalog_result = _attach_phase1_plan_and_timing(
                semantic_unknown_catalog_result,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            semantic_unknown_catalog_result = _attach_semantic_preplan_debug(
                semantic_unknown_catalog_result,
                semantic_preplan,
                final_route="product_detail",
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=semantic_unknown_catalog_result,
                request_start=request_start,
                branch="semantic_unknown_realtime_catalog_safe_missing",
                semantic_preplan=semantic_preplan,
            )

    invalid_semantic_pairwise_result = _invalid_semantic_pairwise_preplan_clarification_result(
        question,
        phase1_plan,
        semantic_preplan,
        _products_named_in_question(db, question),
    )
    if invalid_semantic_pairwise_result:
        invalid_semantic_pairwise_result = _attach_phase1_plan_and_timing(
            invalid_semantic_pairwise_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=invalid_semantic_pairwise_result,
            request_start=request_start,
            branch="semantic_pairwise_invalid_preplan_clarification",
            semantic_preplan=semantic_preplan,
        )

    # Recommendation constraints may be semantically valid, yet their stated
    # subject can still be an unresolved product-like name.  Bind or clarify
    # that identity before any recommendation contract or its empty-constraint
    # clarification can consume the turn as a generic catalogue request.
    semantic_entity_scope = _semantic_preplan_entity_scope(semantic_preplan)
    unresolved_entity_scope_result = None
    if (
        _semantic_preplan_route_family(semantic_preplan) == "recommendation"
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and semantic_entity_scope in {
            "unresolved_product_like",
            "unresolved_product",
            "negative_product_like",
            "negative_product",
        }
    ):
        unresolved_entity_scope_result = _entity_scope_pre_route_guard_result(
            db,
            question,
            phase1_plan,
            semantic_preplan,
        )
    if unresolved_entity_scope_result:
        unresolved_entity_scope_result = _attach_phase1_plan_and_timing(
            unresolved_entity_scope_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        unresolved_entity_scope_result = _attach_semantic_preplan_debug(
            unresolved_entity_scope_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=unresolved_entity_scope_result,
            request_start=request_start,
            branch="unresolved_entity_scope_before_semantic_recommendation",
            semantic_preplan=semantic_preplan,
        )

    # A named product field request cannot be consumed as a catalogue
    # recommendation merely because its canonical name contains numbers or
    # product-type words.  This path forms the normal FieldContract first;
    # same-SKU QA remains its fallback evidence rather than a route override.
    named_detail_before_recommendation = None
    if (
        _semantic_preplan_route_family(semantic_preplan) == "recommendation"
        and (
            bool(semantic_preplan.get("entities") or [])
            or bool(str(semantic_preplan.get("subject_text") or "").strip())
        )
    ):
        named_detail_before_recommendation = _try_product_qa_shortcut(db, question)
        if not named_detail_before_recommendation:
            named_detail_before_recommendation = await _try_named_product_shortcut(
                db,
                user_id=user_id,
                question=question,
            )
    if named_detail_before_recommendation:
        named_detail_before_recommendation = _attach_phase1_plan_and_timing(
            named_detail_before_recommendation,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=named_detail_before_recommendation,
            request_start=request_start,
            branch="named_product_contract_before_semantic_recommendation",
            semantic_preplan=semantic_preplan,
        )

    # A validated semantic recommendation constraint is already the complete
    # meaning of the request.  Consume it before every legacy recommendation
    # grammar/scoring path; the executor below only verifies actual same-SKU
    # catalogue evidence and never asks lexical rules to reinterpret intent.
    semantic_recommendation_result = await _semantic_recommendation_contract_result(
        db,
        question,
        phase1_plan,
        _latest_recommendation_context_for_sources(db, conversation_id) if conversation_id else None,
    )
    if semantic_recommendation_result:
        semantic_recommendation_result = _post_filter_recommendation_result(
            db,
            question,
            semantic_recommendation_result,
        )
        semantic_recommendation_result = _attach_phase1_plan_and_timing(
            semantic_recommendation_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        semantic_recommendation_result = _attach_semantic_preplan_debug(
            semantic_recommendation_result,
            semantic_preplan,
            final_route="recommendation",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_recommendation_result,
            request_start=request_start,
            branch="semantic_recommendation_contract",
            semantic_preplan=semantic_preplan,
        )

    semantic_recommendation_clarification = _semantic_recommendation_constraint_clarification_result(
        semantic_preplan,
    )
    # A failed recommendation JSON must not hide an independently validated
    # formal catalogue filter from the same turn.  This preserves the
    # semantic decision (the dishwasher field) while letting the deterministic
    # layer execute only the category/evidence contract it can prove.
    semantic_structured_fields = [
        str(item or "").strip()
        for item in [
            *((semantic_preplan or {}).get("canonical_fields") or []),
            (semantic_preplan or {}).get("field_type"),
            (semantic_preplan or {}).get("field_hint"),
        ]
        if str(item or "").strip()
    ]
    if (
        semantic_recommendation_clarification
        and semantic_structured_fields
        and not _products_named_in_question(db, question)
    ):
        structured_catalog_result = _structured_field_filter_result(db, question)
        if structured_catalog_result:
            structured_catalog_result = _attach_phase1_plan_and_timing(
                structured_catalog_result,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            structured_catalog_result = _attach_semantic_preplan_debug(
                structured_catalog_result,
                semantic_preplan,
                final_route="query_products",
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=structured_catalog_result,
                request_start=request_start,
                branch="semantic_failed_recommendation_structured_filter",
                semantic_preplan=semantic_preplan,
            )
    if semantic_recommendation_clarification:
        semantic_recommendation_clarification = _attach_phase1_plan_and_timing(
            semantic_recommendation_clarification,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        semantic_recommendation_clarification = _attach_semantic_preplan_debug(
            semantic_recommendation_clarification,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_recommendation_clarification,
            request_start=request_start,
            branch="semantic_recommendation_constraint_clarification",
            semantic_preplan=semantic_preplan,
        )

    recovered_invalid_structured_named_detail = _invalid_structured_query_named_detail_contract_result(
        db,
        question,
        semantic_preplan,
    )
    if recovered_invalid_structured_named_detail:
        recovered_invalid_structured_named_detail = _attach_phase1_plan_and_timing(
            recovered_invalid_structured_named_detail,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=recovered_invalid_structured_named_detail,
            request_start=request_start,
            branch="invalid_structured_query_named_detail_contract",
            semantic_preplan=semantic_preplan,
        )

    semantic_structured_query_clarification = _semantic_structured_query_constraint_clarification_result(
        semantic_preplan,
        question=question,
    )
    if semantic_structured_query_clarification:
        semantic_structured_query_clarification = _attach_phase1_plan_and_timing(
            semantic_structured_query_clarification,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        semantic_structured_query_clarification = _attach_semantic_preplan_debug(
            semantic_structured_query_clarification,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_structured_query_clarification,
            request_start=request_start,
            branch="semantic_structured_query_constraint_clarification",
            semantic_preplan=semantic_preplan,
        )

    # Once semantic planning has sealed a named pair, execute that comparison
    # before any later product-query fallback can reinterpret the same names.
    if phase1_plan.get("semantic_comparison_entity_contracts"):
        pairwise_result = await _phase1_compare_choice_result(db, phase1_plan)
        if pairwise_result:
            pairwise_result = _attach_phase1_plan_and_timing(
                pairwise_result, phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            return await _save_agent_result_and_return(
                db, user_id=user_id, question=question, conversation_id=conversation_id,
                agent_result=pairwise_result, request_start=request_start,
                branch="semantic_pairwise_contract", semantic_preplan=semantic_preplan,
            )

    semantic_navigation_result = _semantic_product_navigation_contract_result(
        db,
        question,
        semantic_preplan,
    )
    if semantic_navigation_result:
        semantic_navigation_result = _attach_phase1_plan_and_timing(
            semantic_navigation_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_navigation_result,
            request_start=request_start,
            branch="semantic_product_navigation_contract",
            semantic_preplan=semantic_preplan,
        )

    # Resolve a compound utterance before whole-question entity arbitration.
    # Otherwise a valid fact field can seal the first SKU and discard the
    # separately requested recommendation task.
    composite_question = _split_composite_customer_question(question)
    if composite_question:
        composite_result = await _execute_composite_customer_question(
            db,
            user_id=user_id,
            composite_question=composite_question,
            sku=sku,
        )
        if composite_result:
            composite_result = _attach_phase1_plan_and_timing(
                composite_result,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            composite_result = _attach_semantic_preplan_debug(
                composite_result,
                semantic_preplan,
                final_route=str(composite_result.get("answer_type") or "recommendation"),
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=composite_result,
                request_start=request_start,
                branch="composite_multi_intent_pre_entity_arbitration",
                semantic_preplan=semantic_preplan,
            )

    active_anchor_context = _latest_recommendation_context_for_sources(db, conversation_id)
    active_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    if (
        isinstance(active_anchor_context, dict)
        and isinstance(active_candidate_context, dict)
        and not str(active_anchor_context.get("active_single_product_anchor") or "").strip()
    ):
        visible_recommendations = list(dict.fromkeys(
            str(value or "").strip().upper()
            for value in (active_candidate_context.get("recommended_skus") or [])
            if str(value or "").strip()
        ))
        last_referenced_sku = str(active_candidate_context.get("last_referenced_sku") or "").strip().upper()
        if len(visible_recommendations) == 1:
            active_anchor_context = dict(active_anchor_context)
            active_anchor_context["active_single_product_anchor"] = visible_recommendations[0]
            active_anchor_context["anchor_update_reason"] = "unique_visible_recommendation"
        elif last_referenced_sku:
            active_anchor_context = dict(active_anchor_context)
            active_anchor_context["active_single_product_anchor"] = last_referenced_sku
            active_anchor_context["anchor_update_reason"] = "latest_candidate_reference"
        else:
            # A normal product-detail/QA turn is not a recommendation, so it
            # need not populate recommendation_context.  A later pronoun may
            # still safely refer to its one sealed result: recover only the
            # most recent single current SKU already persisted in this same
            # conversation.  The current semantic contract still decides the
            # field or product-QA meaning; this supplies identity only.
            latest_active_skus = _latest_active_product_skus(db, conversation_id, user_id)
            if len(latest_active_skus) == 1:
                active_anchor_context = dict(active_anchor_context)
                active_anchor_context["active_single_product_anchor"] = latest_active_skus[0]
                active_anchor_context["anchor_update_reason"] = "latest_single_product_result"
    if _should_force_runtime_empty_subset_followup(
        question,
        explicit_sku=sku,
        named_products=_products_named_in_question(db, question),
        candidate_context=active_candidate_context,
    ):
        empty_subset_result = _empty_candidate_subset_followup_result(
            question,
            active_candidate_context,
        )
        empty_subset_result = _attach_phase1_plan_and_timing(
            empty_subset_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=empty_subset_result,
            request_start=request_start,
            branch="empty_candidate_subset_followup",
            semantic_preplan=semantic_preplan,
        )
    recommendation_explanation_result = _recommendation_explanation_followup_result(
        db,
        question,
        active_anchor_context,
        active_candidate_context,
    )
    if recommendation_explanation_result:
        recommendation_explanation_result = _attach_phase1_plan_and_timing(
            recommendation_explanation_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=recommendation_explanation_result,
            request_start=request_start,
            branch="recommendation_context_explanation_followup",
            semantic_preplan=semantic_preplan,
        )
    explicit_compatibility_result = await _explicit_multi_product_compatibility_contract_result(db, question)
    if explicit_compatibility_result:
        explicit_compatibility_result = _attach_phase1_plan_and_timing(
            explicit_compatibility_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=explicit_compatibility_result,
            request_start=request_start,
            branch="explicit_multi_entity_compatibility_contract",
            semantic_preplan=semantic_preplan,
        )
    active_anchor_result = await _active_product_anchor_field_followup_result(
        db,
        question,
        active_anchor_context,
        phase1_plan,
    )
    if active_anchor_result:
        active_anchor_result = _attach_phase1_plan_and_timing(
            active_anchor_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=active_anchor_result,
            request_start=request_start,
            branch="active_product_anchor_field",
            semantic_preplan=semantic_preplan,
        )

    # A deictic singular subject is an entity reference, not a catalogue
    # category.  If the anchor resolver did not bind it above, fail closed
    # before semantic structured-query execution can turn “this pot” into a
    # search across every pot.  This deliberately contains no category or
    # field-specific routing: a later turn may supply any SKU/name and resume
    # the field request through the normal contract path.
    # A preserved pair is a sealed plural entity scope.  Let the dedicated
    # pair-followup contract consume it later; the singular deictic guard must
    # not intercept "它们" merely because it begins with "它".  Without a
    # preserved pair the same wording still fails closed below.
    preserved_pair_skus = (
        _context_skus_for_pair_followup(active_anchor_context, active_candidate_context)
        if _is_plural_heat_source_followup(question)
        else []
    )
    # A recommendation refinement is not a request for facts about the
    # deictic product.  Its prior recommendation set is the context contract
    # and is consumed by the recommendation path below; treating “这个太重，
    # 换个轻点的” as an unbound product fact loses that safe candidate scope.
    has_recommendation_followup_context = _has_followup_result_context(active_anchor_context)
    semantic_anchor_pending = bool(
        str((semantic_preplan or {}).get("context_usage") or "").strip() == "entity_anchor"
        and str((active_anchor_context or {}).get("active_single_product_anchor") or "").strip()
    )
    unbound_deictic_result = None if (
        preserved_pair_skus
        or (has_recommendation_followup_context and _is_recommendation_followup_question(question))
        # Semantic planning already identified the current turn as a
        # context-bound product QA request and the conversation has one sealed
        # active SKU. Let only the ordinary same-SKU QA/RAG path consume it;
        # without both signals, retain the fail-closed pronoun clarification.
        or semantic_anchor_pending
    ) else _unbound_deictic_product_reference_result(
        db,
        question,
        field_type=(phase1_plan.get("field_contract") or {}).get("field_type"),
    )
    if unbound_deictic_result:
        unbound_deictic_result = _attach_phase1_plan_and_timing(
            unbound_deictic_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        unbound_deictic_result = _attach_semantic_preplan_debug(
            unbound_deictic_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=unbound_deictic_result,
            request_start=request_start,
            branch="unbound_deictic_entity_contract_guard",
            semantic_preplan=semantic_preplan,
        )

    ambiguity_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    ambiguity_refinement_result = _ambiguity_candidate_attribute_followup_result(
        db,
        question,
        ambiguity_candidate_context,
    )
    if ambiguity_refinement_result:
        ambiguity_refinement_result = _attach_phase1_plan_and_timing(
            ambiguity_refinement_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=ambiguity_refinement_result,
            request_start=request_start,
            branch="candidate_context_variant_refinement",
            semantic_preplan=semantic_preplan,
        )

    # Before the realtime/commercial guard produces a safe-missing answer,
    # give an explicit same-SKU shipping QA one chance to satisfy the formal
    # field contract. The helper still requires unique entity resolution and
    # field-compatible QA evidence; absence of either falls through to the
    # guard unchanged.
    pre_guard_shipping_qa = None
    semantic_shipping_field = bool(
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and str((semantic_preplan or {}).get("field_type") or "").strip() == "shipping"
    )
    if customer_field_contract.detect_shipping_intent_signal(question) or semantic_shipping_field:
        pre_guard_shipping_qa = _try_product_qa_shortcut(
            db,
            question,
            phase1_plan=phase1_plan,
        )
    if pre_guard_shipping_qa:
        pre_guard_shipping_qa = _attach_phase1_plan_and_timing(
            pre_guard_shipping_qa,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=pre_guard_shipping_qa,
            request_start=request_start,
            branch="sealed_shipping_qa_before_high_risk_guard",
            semantic_preplan=semantic_preplan,
        )

    high_risk_contract_result = _pre_route_high_risk_contract_result(
        db,
        question,
        semantic_preplan,
    )
    if high_risk_contract_result:
        high_risk_contract_result = _attach_formal_field_contract(
            high_risk_contract_result,
            question,
            phase1_plan,
        )
        high_risk_contract_result = _attach_phase1_plan_and_timing(
            high_risk_contract_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        high_risk_contract_result = _attach_semantic_preplan_debug(
            high_risk_contract_result,
            semantic_preplan,
            final_route=str(high_risk_contract_result.get("answer_type") or high_risk_contract_result.get("intent") or ""),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=high_risk_contract_result,
            request_start=request_start,
            branch="pre_route_high_risk_contract",
            semantic_preplan=semantic_preplan,
        )

    # A product-only reply to an explicit earlier clarification is already a
    # formal conversational field contract: the current turn seals identity
    # and the saved clarification supplies the requested field.  It must be
    # applied before the semantic-outage guard, otherwise a transient planner
    # transport error turns a valid contract continuation into a new generic
    # clarification.
    clarification_followup_start = perf_counter()
    clarification_followup_result = await _try_pending_clarification_followup(
        db,
        user_id=user_id,
        conversation_id=conversation_id,
        question=question,
    )
    customer_perf_service.log_stage(
        "clarification_followup_guard",
        clarification_followup_start,
        hit=bool(clarification_followup_result),
        agent_mode=(clarification_followup_result.get("debug") or {}).get("agent_mode") if clarification_followup_result else None,
    )
    if clarification_followup_result:
        clarification_followup_result = _attach_phase1_plan_and_timing(
            clarification_followup_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        clarification_followup_result = _attach_semantic_preplan_debug(
            clarification_followup_result,
            semantic_preplan,
            final_route="product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=clarification_followup_result,
            request_start=request_start,
            branch="clarification_followup_guard",
            semantic_preplan=semantic_preplan,
        )

    semantic_outage_result = _semantic_outage_named_product_field_clarification_result(
        db,
        question,
        semantic_preplan,
    )
    if semantic_outage_result:
        semantic_outage_result = _attach_phase1_plan_and_timing(
            semantic_outage_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        semantic_outage_result = _attach_semantic_preplan_debug(
            semantic_outage_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_outage_result,
            request_start=request_start,
            branch="semantic_outage_named_product_field_guard",
            semantic_preplan=semantic_preplan,
        )

    explicit_comparison_skus = _explicit_current_turn_comparison_skus(db, question)
    if explicit_comparison_skus and isinstance(phase1_plan, dict):
        # The semantic field remains untouched; this only restores the
        # catalogue-validated multi-entity orchestration contract when a
        # planner summary retained just one participant.
        phase1_plan.update(
            {
                "product_refs": explicit_comparison_skus,
                "must_compare_both_products": True,
                "raw_question": question,
            }
        )
        if str(phase1_plan.get("primary_intent") or "") not in {
            "comparison",
            "product_compare_recommendation",
        }:
            phase1_plan["primary_intent"] = "comparison"
            phase1_plan["answer_type"] = "comparison"
    phase2_arbitration_signals = _phase2_entity_arbitration_signals(
        question,
        phase1_plan,
        semantic_preplan,
    )
    structured_query_contract = customer_structured_query_contract.build_structured_query_contract(question)
    # Semantic planning decides which independent customer constraints are
    # present in the whole sentence.  The adapter accepts only a validated,
    # literal predicate schema and keeps the deterministic catalogue subject
    # from the existing contract; it never accepts an LLM-provided product or
    # database fact.  This prevents a legacy single-filter parser from
    # silently broadening a high-confidence multi-condition request.
    semantic_structured_query_contract = (
        customer_structured_query_contract.adapt_semantic_structured_query_contract(
            question=question,
            base_contract=structured_query_contract,
            semantic_preplan=semantic_preplan,
        )
    )
    if semantic_structured_query_contract is not None:
        structured_query_contract = semantic_structured_query_contract
    semantic_structured_query_contract_active = semantic_structured_query_contract is not None
    if structured_query_contract.status == "resolved":
        phase2_arbitration_signals["structured_query"] = True
    # Keep the validated semantic field signal explicit at the one formal
    # FieldContract boundary.  Planner compatibility output may contain a
    # broad lexical label (for example ``brand`` inside a question about a
    # brand's price tier); it is not permitted to replace this schema-checked
    # field classification.  The semantic payload supplies neither entity nor
    # evidence: Phase 2 still seals both from the catalogue and same-SKU
    # structured provider.
    phase2_field_plan = dict(phase1_plan) if isinstance(phase1_plan, dict) else {}
    if isinstance(semantic_preplan, dict) and semantic_preplan.get("called"):
        phase2_field_plan["semantic_preplan"] = semantic_preplan
    semantic_subject = _semantic_exact_subject_for_field_contract(
        db,
        question,
        semantic_preplan,
    )
    phase2_field_request = resolve_requested_field_contract(
        question,
        phase2_field_plan,
        subject_override=semantic_subject or None,
    )
    if isinstance(phase1_plan, dict):
        phase1_plan["field_contract"] = dict(phase2_field_request)
        phase1_plan["requested_fields"] = phase2_field_request["requested_fields"]
        phase1_plan["multi_field"] = bool(phase2_arbitration_signals.get("multi_field"))
        phase1_plan["additional_user_intent"] = bool(phase2_arbitration_signals.get("additional_user_intent"))
        phase1_plan["compound"] = bool(phase2_arbitration_signals.get("compound"))
        phase1_plan["dedicated_route_signal"] = _dedicated_semantic_route(question)
    phase2_context_needed = bool(
        (
            phase2_field_request.get("source") == "validated_semantic_preplan"
            and len(phase2_field_request.get("supported_fields") or []) == 1
        )
        or (
            _phase2_single_field_arbitration_eligible(
                question,
                phase1_plan,
                conversation_id=conversation_id,
            )
            and (
                len(phase2_field_request["supported_fields"]) == 1
                or _has_non_usage_care_field_contract(question)
            )
        )
        or (
            phase2_arbitration_signals.get("compound")
            and phase2_arbitration_signals.get("multi_field")
            and not phase2_arbitration_signals.get("recommendation")
            and not phase2_arbitration_signals.get("comparison")
            and not phase2_arbitration_signals.get("structured_query")
            and not phase2_arbitration_signals.get("multi_product")
            and not phase2_arbitration_signals.get("dedicated_route")
        )
    )
    # Build one catalogue-aware context even when the preliminary field parser
    # saw multiple tokens.  An exact product name may itself contain a field
    # word (for example a stove name containing "酒精炉"); only the catalogue-
    # aware subject span can distinguish that identity text from the predicate.
    phase2_entity_context = _build_phase2_entity_resolution_context(
        db,
        question,
        phase2_field_request,
        phase1_plan,
    )
    effective_field_request = (phase2_entity_context or {}).get("field_request")
    if isinstance(effective_field_request, dict):
        phase2_field_request = effective_field_request
        phase2_arbitration_signals = _phase2_entity_arbitration_signals(
            question,
            phase1_plan,
            semantic_preplan,
            field_request_override=effective_field_request,
        )
        if structured_query_contract.status == "resolved":
            phase2_arbitration_signals["structured_query"] = True
        if isinstance(phase1_plan, dict):
            phase1_plan["field_contract"] = dict(effective_field_request)
            phase1_plan["requested_fields"] = effective_field_request["requested_fields"]
            phase1_plan["multi_field"] = bool(phase2_arbitration_signals.get("multi_field"))
            phase1_plan["additional_user_intent"] = bool(phase2_arbitration_signals.get("additional_user_intent"))
            phase1_plan["compound"] = bool(phase2_arbitration_signals.get("compound"))
    candidate_field_filter_result = _candidate_context_formal_field_filter_result(
        db,
        question=question,
        field_request=phase2_field_request,
        candidate_context=active_candidate_context,
    )
    if candidate_field_filter_result:
        candidate_field_filter_result = _attach_phase1_plan_and_timing(
            candidate_field_filter_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        candidate_field_filter_result = _attach_semantic_preplan_debug(
            candidate_field_filter_result,
            semantic_preplan,
            final_route="product_query",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=candidate_field_filter_result,
            request_start=request_start,
            branch="candidate_context_formal_field_filter",
            semantic_preplan=semantic_preplan,
        )
    semantic_field_ambiguity_result = _semantic_field_ambiguity_clarification_result(
        semantic_preplan,
        phase2_entity_context,
    )
    if semantic_field_ambiguity_result:
        semantic_field_ambiguity_result = _attach_phase1_plan_and_timing(
            semantic_field_ambiguity_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        semantic_field_ambiguity_result = _attach_semantic_preplan_debug(
            semantic_field_ambiguity_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_field_ambiguity_result,
            request_start=request_start,
            branch="semantic_field_ambiguity_clarification",
            semantic_preplan=semantic_preplan,
        )
    category_general_exclusions = _category_general_exclusion_signals(
        phase1_plan=phase1_plan,
        entity_contract=(phase2_entity_context or {}).get("contract"),
        entity_arbitration_signals=phase2_arbitration_signals,
    )
    category_general_eligible = _should_use_category_field_general(
        structured_contract=structured_query_contract,
        exclusions=category_general_exclusions,
    )
    if isinstance(phase1_plan, dict):
        phase1_plan["entity_arbitration_signals"] = dict(phase2_arbitration_signals)
        phase1_plan["category_general_exclusions"] = category_general_exclusions
        phase1_plan["category_general_eligible"] = category_general_eligible
    phase2_arbitration_signals["category_general"] = category_general_eligible
    semantic_field_is_validated = bool(
        isinstance(semantic_preplan, dict)
        and semantic_preplan.get("called")
        and not semantic_preplan.get("error")
        and not semantic_preplan.get("fallback_reason")
        and _semantic_formal_field_preempts_legacy_shortcuts(semantic_preplan)
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
    )
    sealed_compound_evidence_result = None
    if not phase1_plan.get("semantic_comparison_entity_contracts"):
        sealed_compound_evidence_result = _build_resolved_compound_evidence_result(
            db,
            question=question,
            entity_contract=(phase2_entity_context or {}).get("contract"),
            field_request=phase2_field_request,
            phase1_plan=phase1_plan,
        )
    if sealed_compound_evidence_result:
        supplemental_query = str((semantic_preplan or {}).get("supplemental_qa_evidence_query") or "").strip()
        # Semantic planning may correctly mark a mixed turn as compound while
        # omitting the optional retrieval paraphrase. In that case the whole
        # customer sentence is the only safe second-pass query: it preserves
        # the model's intent decision without letting deterministic code name
        # or infer the missing capability.
        if (
            not supplemental_query
            and bool((semantic_preplan or {}).get("compound"))
            and str((semantic_preplan or {}).get("evidence_kind") or "").strip() == "structured_field"
        ):
            supplemental_query = question
        if supplemental_query:
            supplemental, supplemental_query = await _resolve_sealed_supplemental_product_evidence(
                db,
                question=question,
                semantic_preplan=semantic_preplan,
                base_plan=phase1_plan,
            )
            if supplemental and supplemental.get("result_skus") == sealed_compound_evidence_result.get("result_skus"):
                structured_answer = str(sealed_compound_evidence_result.get("answer") or "").strip()
                supplemental_answer = str(supplemental.get("answer") or "").strip()
                if structured_answer and supplemental_answer:
                    sealed_compound_evidence_result["answer"] = structured_answer + "\n" + supplemental_answer
                    metadata = sealed_compound_evidence_result.setdefault("answer_metadata", {})
                    metadata["supplemental_product_qa"] = supplemental.get("answer_metadata") or {}
                    metadata["evidence_skus"] = sealed_compound_evidence_result.get("result_skus") or []
                    debug = sealed_compound_evidence_result.setdefault("debug", {})
                    debug["supplemental_product_qa_contract"] = (supplemental.get("debug") or {}).get("field_contract") or {}
        sealed_compound_evidence_result = _attach_phase1_plan_and_timing(
            sealed_compound_evidence_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        sealed_compound_evidence_result = _attach_semantic_preplan_debug(
            sealed_compound_evidence_result,
            semantic_preplan,
            final_route="product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=sealed_compound_evidence_result,
            request_start=request_start,
            branch="resolved_entity_compound_evidence_contract",
            semantic_preplan=semantic_preplan,
        )
    explicit_alcohol_exclusion_result = _phase1_except_alcohol_stove_cookware_result(db, question)
    if explicit_alcohol_exclusion_result:
        explicit_alcohol_exclusion_result = _attach_phase1_plan_and_timing(
            explicit_alcohol_exclusion_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=explicit_alcohol_exclusion_result,
            request_start=request_start,
            branch="structured_alcohol_stove_cookware_exclusion",
            semantic_preplan=semantic_preplan,
        )
    # A failed or low-confidence semantic attempt must not let a lossy legacy
    # alias reclassify an otherwise explicit cleaning/usage/care request.  In
    # that fallback state, defer to the existing same-SKU usage/care provider;
    # a validated formal semantic field still retains the normal Phase-2
    # FieldContract -> EntityResolutionContract route.
    phase2_contract = (phase2_entity_context or {}).get("contract")
    sealed_usage_care_contract = bool(
        len(phase2_field_request.get("supported_fields") or []) == 1
        and str(phase2_field_request.get("field_type") or "") in {"usage_instruction", "cleaning", "care"}
        and phase2_contract
        and str(getattr(phase2_contract, "status", "") or "") == "resolved"
        and str(getattr(phase2_contract, "resolved_sku", "") or "").strip()
    )
    fallback_usage_care = bool(
        _is_product_usage_care_question(question)
        and not _has_non_usage_care_field_contract(question)
        and not semantic_field_is_validated
        and not _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan)
        and not sealed_usage_care_contract
    )
    # Ordinal follow-ups seal identity from the ordered conversation result
    # set below.  The phrase "第二个" is not an entity name for Phase 2 to
    # fuzzy-resolve against the whole catalogue.
    defer_ordinal_entity_arbitration = bool(
        conversation_id and _looks_like_ordinal_product_field_followup(question)
    )
    defer_generic_structured_arbitration = _should_prioritize_semantic_structured_route(question, phase1_plan)
    phase2_entity_detail_result = None if (
        fallback_usage_care
        or defer_ordinal_entity_arbitration
        or defer_generic_structured_arbitration
    ) else _phase2_entity_state_arbitration_result(
        db,
        question,
        phase1_plan,
        conversation_id=conversation_id,
        signals=phase2_arbitration_signals,
        entity_resolution_context=phase2_entity_context,
    )
    if phase2_entity_detail_result:
        phase2_metadata = (
            phase2_entity_detail_result.get("answer_metadata")
            if isinstance(phase2_entity_detail_result.get("answer_metadata"), dict)
            else {}
        )
        # Some formally supported, non-realtime customer fields are imported
        # only as same-SKU QA or customer content rather than a dedicated
        # structured column. Reuse sealed RAG only after the formal contract,
        # exact entity contract, and ordinary provider all completed. A failed
        # selection deliberately leaves the field-specific missing result
        # untouched; live availability, price, promotion, and inventory never
        # enter this static-evidence adapter.
        phase2_missing_rag_fields = {"accessories", "warranty"}
        phase2_missing_field_type = str(phase2_field_request.get("field_type") or "")
        if (
            phase2_missing_field_type in phase2_missing_rag_fields
            and phase2_metadata.get("field_evidence_missing") is True
            and phase2_contract
            and str(getattr(phase2_contract, "status", "") or "") == "resolved"
            and str(getattr(phase2_contract, "resolved_sku", "") or "").strip()
        ):
            missing_field_preplan = dict(semantic_preplan or {})
            missing_field_preplan.update({
                "route_family": "product_bound_qa",
                "route_hint": "product_detail",
                "question_type": "field",
                "subject_text": str(phase2_contract.resolved_sku),
                "canonical_fields": [],
                "field_type": "",
                "field_hint": None,
                "evidence_required": True,
                "evidence_kind": "product_qa",
                "qa_evidence_query": question,
                "fallback_reason": "",
            })
            # Imported QA can be the only authoritative static record for a
            # sealed warranty or package-accessory field. The helper still
            # resolves the same product and binds the selected QA row; it
            # does not infer a duration, policy term, or package component.
            missing_field_evidence = None
            if phase2_missing_field_type in {"warranty", "accessories"}:
                sealed_product = db.query(Product).filter(
                    Product.sku == phase2_contract.resolved_sku
                ).first()
                sealed_qa = (
                    _best_product_qa_match(db, sealed_product, question)
                    if sealed_product is not None
                    else None
                )
                if sealed_qa is not None:
                    missing_field_evidence = _try_product_qa_shortcut(
                        db,
                        question,
                        phase1_plan={"semantic_preplan": missing_field_preplan},
                        selected_qa=sealed_qa,
                    )
            # Product QA has a purpose-built semantic Q/A selector. Prefer it
            # before free-form RAG so a concise stored answer (for example a
            # warranty statement without a duration) is not discarded merely
            # because it cannot be expanded into a broader prose answer.
            if not missing_field_evidence:
                missing_field_evidence = await _try_product_qa_shortcut_with_semantic_selection(
                    db,
                    question,
                    phase1_plan={"semantic_preplan": missing_field_preplan},
                )
            if _is_sealed_product_qa_safe_missing(missing_field_evidence):
                missing_field_evidence = None
            if not missing_field_evidence:
                for _missing_field_attempt in range(3):
                    missing_field_evidence = await _try_sealed_same_sku_knowledge_answer(
                        db,
                        question,
                        {"semantic_preplan": missing_field_preplan},
                    )
                    if missing_field_evidence:
                        break
            # Conservative last-mile fallback for package contents: when the
            # sealed same-SKU customer content itself contains an explicit
            # composition sentence, return that source sentence verbatim. This
            # never derives contents from title/specs and remains fail-closed
            # when no explicit composition evidence exists.
            if not missing_field_evidence and phase2_missing_field_type == "accessories":
                try:
                    content_rows = knowledge_service.same_sku_customer_context(
                        db, phase2_contract.resolved_sku, limit=3,
                    )
                except Exception:
                    content_rows = []
                explicit_composition = ""
                for row in content_rows:
                    source_text = str((row or {}).get("content") or "")
                    for sentence in re.split(r"(?<=[。！？!?])\s*", source_text):
                        sentence = sentence.strip()
                        if sentence and _is_complete_package_contents_evidence(sentence):
                            explicit_composition = sentence
                            break
                    if explicit_composition:
                        break
                if explicit_composition:
                    missing_field_evidence = dict(phase2_entity_detail_result)
                    missing_field_evidence["answer"] = explicit_composition
                    missing_field_evidence["skip_polish"] = True
                    missing_field_evidence["evidence"] = [{
                        "sku": phase2_contract.resolved_sku,
                        "field_label": "套装组成",
                        "value": explicit_composition,
                        "source_type": "knowledge_base",
                        "source_layer": "RAG",
                        "matched_by": "explicit_same_sku_composition_sentence",
                    }]
                    missing_field_evidence["sources"] = [{
                        "type": "knowledge_base",
                        "label": "同 SKU 文件知识库",
                        "sku": phase2_contract.resolved_sku,
                    }]
                    fallback_debug = missing_field_evidence.get("debug") if isinstance(missing_field_evidence.get("debug"), dict) else {}
                    fallback_debug["agent_mode"] = "resolved_entity_accessories_same_sku_explicit_evidence"
                    missing_field_evidence["debug"] = fallback_debug
                    fallback_metadata = missing_field_evidence.get("answer_metadata") if isinstance(missing_field_evidence.get("answer_metadata"), dict) else {}
                    fallback_metadata.update({
                        "source": "resolved_entity_accessories_same_sku_explicit_evidence",
                        "contract_field_type": "accessories",
                        "evidence_field": "accessories",
                        "field_evidence_match": True,
                        "field_evidence_missing": False,
                        "evidence_status": "matched",
                        "evidence_sku": phase2_contract.resolved_sku,
                        "evidence_skus": [phase2_contract.resolved_sku],
                    })
                    missing_field_evidence["answer_metadata"] = fallback_metadata
            if missing_field_evidence and missing_field_evidence.get("result_skus") == [phase2_contract.resolved_sku]:
                rag_debug = missing_field_evidence.get("debug") if isinstance(missing_field_evidence.get("debug"), dict) else {}
                rag_debug["agent_mode"] = f"resolved_entity_{phase2_missing_field_type}_same_sku_rag"
                rag_debug["field_contract"] = dict(phase2_field_request)
                rag_debug["entity_resolution_contract"] = phase2_contract.to_dict()
                missing_field_evidence["debug"] = rag_debug
                rag_metadata = missing_field_evidence.get("answer_metadata") if isinstance(missing_field_evidence.get("answer_metadata"), dict) else {}
                rag_metadata.update({
                    "source": f"resolved_entity_{phase2_missing_field_type}_same_sku_rag",
                    "contract_field_type": phase2_missing_field_type,
                    "evidence_field": phase2_missing_field_type,
                    "field_evidence_match": True,
                    "field_evidence_missing": False,
                    "entity_resolution_contract": phase2_contract.to_dict(),
                })
                missing_field_evidence["answer_metadata"] = rag_metadata
                # This is now a formal field response, not free-form QA.
                # Its sealed evidence answer has already passed grounding and
                # coverage; a later style pass must not remove its concrete
                # package-composition facts.
                missing_field_evidence["skip_polish"] = True
                phase2_entity_detail_result = missing_field_evidence
        phase2_entity_detail_result = _attach_phase1_plan_and_timing(
            phase2_entity_detail_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        phase2_entity_detail_result = _attach_semantic_preplan_debug(
            phase2_entity_detail_result,
            semantic_preplan,
            final_route="product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=phase2_entity_detail_result,
            request_start=request_start,
            branch="resolved_entity_detail_contract",
            semantic_preplan=semantic_preplan,
        )

    compound_detail_result = None
    if (
        phase2_arbitration_signals.get("compound")
        and phase2_arbitration_signals.get("multi_field")
        and not phase2_arbitration_signals.get("recommendation")
        and not phase2_arbitration_signals.get("comparison")
        and not phase2_arbitration_signals.get("structured_query")
        and not phase2_arbitration_signals.get("multi_product")
        and not phase2_arbitration_signals.get("dedicated_route")
    ):
        try:
            compound_contract = (phase2_entity_context or {}).get("contract")
            if (
                compound_contract
                and compound_contract.status == "resolved"
                and compound_contract.resolved_sku
                and compound_contract.is_unique
                and compound_contract.confidence == "high"
                and compound_contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
                and compound_contract.resolver_candidate_skus == [compound_contract.resolved_sku]
            ):
                compound_detail_result = _build_compound_product_detail_result(
                    db,
                    resolved_sku=compound_contract.resolved_sku,
                    requested_fields=phase2_field_request["requested_fields"],
                    question=question,
                    entity_contract=compound_contract.to_dict(),
                    compatibility_plan=phase1_plan,
                )
        except Exception:
            compound_detail_result = None
    if compound_detail_result:
        compound_detail_result = _attach_phase1_plan_and_timing(
            compound_detail_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        compound_detail_result = _attach_semantic_preplan_debug(
            compound_detail_result,
            semantic_preplan,
            final_route="product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=compound_detail_result,
            request_start=request_start,
            branch="resolved_entity_compound_detail",
            semantic_preplan=semantic_preplan,
        )

    structured_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    scoped_heat_source_structured_followup = _should_keep_preruntime_for_scoped_heat_source_followup(
        question,
        candidate_context=structured_candidate_context,
    )
    semantic_catalog_subject = str((semantic_preplan or {}).get("subject_text") or "").strip()
    semantic_catalog_unresolved = bool(
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) == "structured_query"
        and list((semantic_preplan or {}).get("canonical_fields") or []) == ["category"]
        and semantic_catalog_subject
        and not customer_agent_service.search_products(db, semantic_catalog_subject, limit=1)
    )
    if semantic_catalog_unresolved:
        clarification = {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"没有找到“{semantic_catalog_subject}”对应的商品范围。请确认商品名、SKU 或希望查询的实际品类后，我再按数据库资料查询。",
            "results": [], "result_skus": [], "candidate_skus": [], "evidence": [],
            "answer_metadata": {"source": "semantic_catalog_subject_unresolved", "evidence_status": "subject_not_found"},
            "debug": {"agent_mode": "semantic_catalog_subject_unresolved"},
            "skip_polish": True,
        }
        clarification = _attach_phase1_plan_and_timing(
            clarification,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=clarification,
            request_start=request_start,
            branch="semantic_catalog_subject_unresolved",
            semantic_preplan=semantic_preplan,
        )
    if (
        structured_query_contract.status == "resolved" or category_general_eligible
    ) and not scoped_heat_source_structured_followup and not (
        isinstance(semantic_preplan, dict)
        and semantic_preplan.get("called")
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and str(semantic_preplan.get("field_type") or "") in customer_field_contract.FORMAL_DETAIL_FIELDS
        and not semantic_structured_query_contract_active
        and _semantic_preplan_route_family(semantic_preplan) != "structured_query"
    ):
        structured_contract_result = (
            _build_structured_query_contract_result(db, structured_query_contract)
            if structured_query_contract.status == "resolved"
            else _build_category_field_general_result(db, structured_query_contract)
        )
        structured_contract_result = _attach_phase1_plan_and_timing(
            structured_contract_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=structured_contract_result,
            request_start=request_start,
            branch="structured_query_contract",
            semantic_preplan=semantic_preplan,
        )

    intent_execution_options = {
        "allow_search_top1_promotion": bool(phase1_plan.get("allow_search_top1_promotion", True)),
    }

    # A plural heat-source filter can be an explicit continuation of the
    # immediately preceding candidate set even without a pronoun.  Preserve
    # that sealed domain before any global structured-query route is allowed
    # to infer a category from the field value itself (for example 酒精炉 -> 炉具).
    pre_arbiter_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    scoped_heat_source_candidate_followup = _should_keep_preruntime_for_scoped_heat_source_followup(
        question,
        candidate_context=pre_arbiter_candidate_context,
    )
    # Do not let a loose token overlap in a product name suppress a genuine
    # category filter. This gate is intentionally based on the same sealed
    # entity contract used by product-detail execution.
    # Phase 2 already built the authoritative entity contract for this
    # request. Reuse that snapshot for the structured-query guard rather than
    # parsing the same utterance a second time: a single request must have one
    # EntityResolutionContract decision.
    has_resolved_product_before_structured_arbiter = bool(
        phase2_contract
        and str(getattr(phase2_contract, "status", "") or "") == "resolved"
        and str(getattr(phase2_contract, "resolved_sku", "") or "").strip()
    )
    # An entity-less category request constrained by a formally supported
    # field is a catalogue operation, even if the semantic field is otherwise
    # eligible for product-detail arbitration.  Do not let that formal-field
    # safeguard route this request into a legacy usage/QA executor.
    generic_structured_filter_pending = bool(
        not _products_named_in_question(db, question)
        and _looks_like_structured_field_filter_query(question)
    )
    semantic_schema_failed_hard_filter_repair = _semantic_schema_failed_hard_filter_repair(
        semantic_preplan,
        question=question,
    )

    if (
        not has_resolved_product_before_structured_arbiter
        and (
            generic_structured_filter_pending
            or not (
                isinstance(semantic_preplan, dict)
                and semantic_preplan.get("called")
                and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
                and _semantic_formal_field_preempts_legacy_shortcuts(semantic_preplan)
            )
        )
        and (
            (
                _semantic_preplan_route_family(semantic_preplan) == "structured_query"
                and _semantic_preplan_confident(semantic_preplan)
            )
            or (
                _looks_like_structured_field_filter_query(question)
                and not _looks_like_recommendation_request(question)
            )
            or semantic_schema_failed_hard_filter_repair
        )
        and not scoped_heat_source_candidate_followup
    ):
        arbiter_structured_result = _structured_field_filter_result(db, question)
        if arbiter_structured_result:
            structured_phase1_plan = dict(phase1_plan) if isinstance(phase1_plan, dict) else {}
            structured_metadata = arbiter_structured_result.get("answer_metadata") if isinstance(arbiter_structured_result.get("answer_metadata"), dict) else {}
            if str(structured_metadata.get("product_ref") or "").strip():
                structured_phase1_plan["product_ref"] = str(structured_metadata.get("product_ref") or "").strip()
            arbiter_structured_result = _attach_phase1_plan_and_timing(
                arbiter_structured_result,
                structured_phase1_plan,
                _phase1_timing(
                    request_start=request_start,
                    planner_duration_ms=planner_duration_ms,
                ),
            )
            arbiter_structured_result = _attach_semantic_preplan_debug(
                arbiter_structured_result,
                semantic_preplan,
                final_route=str(arbiter_structured_result.get("answer_type") or "query_products"),
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=arbiter_structured_result,
                request_start=request_start,
                branch="semantic_preplan_structured_query",
                semantic_preplan=semantic_preplan,
            )

    # “除了 SKU” is a catalogue exclusion constraint, not an entity detail
    # request for the SKU being excluded. Resolve it before exact-identity
    # arbitration can bind the exclusion token as the answer subject.
    explicit_alcohol_exclusion_result = _phase1_except_alcohol_stove_cookware_result(db, question)
    if explicit_alcohol_exclusion_result:
        explicit_alcohol_exclusion_result = _attach_phase1_plan_and_timing(
            explicit_alcohol_exclusion_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=explicit_alcohol_exclusion_result,
            request_start=request_start,
            branch="structured_alcohol_stove_cookware_exclusion",
            semantic_preplan=semantic_preplan,
        )

    # Resolve an exact same-SKU QA before an entity-scope clarification can
    # reinterpret a canonical variant name plus its predicate as ambiguous.
    # The QA helper returns None for real multi-product candidates.
    # Phase 1 already owns the semantic decision at this point.  Passing that
    # decision through is essential: an unplanned fuzzy QA lookup must not
    # choose an arbitrary same-SKU answer before the sealed QA intent has a
    # chance to constrain its evidence retrieval.
    exact_qa_before_scope_guard = None
    if not _formal_field_contract_preempts_product_qa(question, phase1_plan):
        exact_qa_before_scope_guard = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan=phase1_plan,
        )
    if (
        exact_qa_before_scope_guard
        and not _is_sealed_product_qa_safe_missing(exact_qa_before_scope_guard)
        and not ((semantic_preplan or {}).get("qa_evidence_queries") or [])
        and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
        and (
            (exact_qa_before_scope_guard.get("answer_metadata") or {}).get("qa_match_type") == "exact"
            or (
                ((exact_qa_before_scope_guard.get("debug") or {}).get("field_contract") or {}).get("field_type")
                == str((semantic_preplan or {}).get("field_type") or "").strip()
                and str((exact_qa_before_scope_guard.get("answer_metadata") or {}).get("evidence_sku") or "").strip()
            )
            or (
                ((exact_qa_before_scope_guard.get("debug") or {}).get("field_contract") or {}).get("field_type") == "product_qa"
                and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
            )
        )
    ):
        exact_qa_before_scope_guard = _attach_phase1_plan_and_timing(
            exact_qa_before_scope_guard,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=exact_qa_before_scope_guard,
            request_start=request_start,
            branch="sealed_exact_product_qa_before_entity_scope_guard",
            semantic_preplan=semantic_preplan,
        )

    current_turn_field_contract = customer_field_contract.detect_field_contract(question)
    current_turn_field_type = str(
        getattr(current_turn_field_contract, "field_type", "") or ""
    ).strip()
    # Warranty is a formal static field whose sealed QA/RAG fallback is owned
    # by Phase 2. Do not let an early unknown-field scope guard decide it is
    # absent before the formal entity/evidence chain can run.
    entity_scope_contract_result = None if (
        (conversation_id and _looks_like_ordinal_product_field_followup(question))
        or current_turn_field_type == "warranty"
    ) else _entity_scope_pre_route_guard_result(
        db,
        question,
        phase1_plan,
        semantic_preplan,
    )
    if entity_scope_contract_result:
        entity_scope_contract_result = _attach_phase1_plan_and_timing(
            entity_scope_contract_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        entity_scope_contract_result = _attach_semantic_preplan_debug(
            entity_scope_contract_result,
            semantic_preplan,
            final_route=str(entity_scope_contract_result.get("answer_type") or "clarification"),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=entity_scope_contract_result,
            request_start=request_start,
            branch="entity_scope_contract_guard",
            semantic_preplan=semantic_preplan,
        )

    # A compound explicit-SKU request must retain every formal field and the
    # sealed entity/evidence contracts.  The legacy single-detail shortcut
    # only renders its first field, so leave compound requests for the
    # contract-aware multi-field branch below.
    explicit_sku_direct_result = (
        None
        if (
            len(_explicit_sku_detail_requested_fields(question)) > 1
            or _semantic_prefers_sealed_product_qa(phase1_plan)
            or current_turn_field_type == "warranty"
        )
        else await _try_explicit_sku_detail_shortcut(db, question)
    )
    if explicit_sku_direct_result:
        explicit_sku_direct_result = _attach_semantic_preplan_debug(
            explicit_sku_direct_result,
            semantic_preplan,
            final_route="product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=explicit_sku_direct_result,
            request_start=request_start,
            branch="phase1_explicit_sku_detail",
            semantic_preplan=semantic_preplan,
        )

    semantic_formal_field = str((semantic_preplan or {}).get("field_type") or "").strip()
    resolved_unknown_field_result = None
    if not (
        _semantic_allows_exact_sealed_product_qa(phase1_plan)
        and semantic_formal_field in customer_field_contract.FORMAL_DETAIL_FIELDS
    ) and current_turn_field_type != "warranty":
        resolved_unknown_field_result = _try_resolved_product_unknown_field_shortcut(db, question)
    if resolved_unknown_field_result:
        resolved_unknown_field_result = _attach_semantic_preplan_debug(
            resolved_unknown_field_result,
            semantic_preplan,
            final_route=resolved_unknown_field_result.get("answer_type") or "product_detail",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=resolved_unknown_field_result,
            request_start=request_start,
            branch="resolved_entity_unknown_field_fallback",
            semantic_preplan=semantic_preplan,
        )

    unresolved_product_like_contents_result = _unresolved_product_like_contents_clarification_result(db, question)
    if unresolved_product_like_contents_result:
        unresolved_product_like_contents_result = _attach_phase1_plan_and_timing(
            unresolved_product_like_contents_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        unresolved_product_like_contents_result = _attach_semantic_preplan_debug(
            unresolved_product_like_contents_result,
            semantic_preplan,
            final_route=str(unresolved_product_like_contents_result.get("answer_type") or "clarification"),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=unresolved_product_like_contents_result,
            request_start=request_start,
            branch="unresolved_product_like_contents_clarification",
            semantic_preplan=semantic_preplan,
        )

    if (
        not conversation_id
        and _is_product_usage_care_question(question)
        and not _has_non_usage_care_field_contract(question)
        and not _semantic_formal_field_preempts_legacy_shortcuts(semantic_preplan)
        and not _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan)
        and not (len(_products_named_in_question(db, question)) > 1)
        and not _semantic_prefers_sealed_product_qa(phase1_plan)
        and not _should_prioritize_semantic_structured_route(question, phase1_plan)
    ):
        early_usage_care_result = await customer_agent_intent_service.answer_product_usage_care_request(
            db,
            question=question,
            named_products=_products_named_in_question(db, question),
        )
        if len((early_usage_care_result or {}).get("result_skus") or []) > 1:
            early_usage_care_result = None
        if early_usage_care_result:
            early_usage_care_result = _attach_phase1_plan_and_timing(
                early_usage_care_result,
                phase1_plan,
                _phase1_timing(
                    request_start=request_start,
                    planner_duration_ms=planner_duration_ms,
                ),
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=early_usage_care_result,
                request_start=request_start,
                branch="product_usage_care_fast_path",
                semantic_preplan=semantic_preplan,
            )

    if (
        _should_prioritize_semantic_structured_route(question, phase1_plan)
        and not _semantic_preplan_unknown_realtime_subtype(semantic_preplan, question)
    ):
        semantic_structured_result = _semantic_structured_query_result(
            db,
            question,
            candidate_context=_latest_candidate_context_for_sources(db, conversation_id),
            semantic_preplan=semantic_preplan,
        )
        if semantic_structured_result:
            semantic_structured_result = _post_filter_recommendation_result(db, question, semantic_structured_result)
            structured_phase1_plan = _semantic_structured_override_plan(question, phase1_plan, semantic_structured_result)
            semantic_structured_result = _attach_phase1_plan_and_timing(
                semantic_structured_result,
                structured_phase1_plan,
                _phase1_timing(
                    request_start=request_start,
                    planner_duration_ms=planner_duration_ms,
                ),
            )
            semantic_structured_result = _attach_semantic_preplan_debug(
                semantic_structured_result,
                semantic_preplan,
                final_route=str(semantic_structured_result.get("answer_type") or "query_products"),
            )
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=semantic_structured_result,
                request_start=request_start,
                branch="phase1_semantic_structured_priority_guard",
                semantic_preplan=semantic_preplan,
            )

    phase1_direct_result = None
    executor_start = perf_counter()
    # Exact same-SKU QA for a fact outside the formal field taxonomy must not
    # be reinterpreted as an unrelated formal field by a later planner.  Do
    # not preempt formal fields here: those continue into FieldContract.
    # This is after semantic preplanning, so never re-enter the legacy QA
    # matcher without the plan.  In particular, a high-confidence
    # ``product_qa`` intent must use its sealed same-SKU retrieval query; an
    # unrelated stored QA is not an acceptable answer merely because it has
    # the right product identity.
    generic_qa_contract = None
    if not _formal_field_contract_preempts_product_qa(question, phase1_plan):
        generic_qa_contract = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan=phase1_plan,
        )
    if (
        generic_qa_contract
        and not _is_sealed_product_qa_safe_missing(generic_qa_contract)
        and not ((semantic_preplan or {}).get("qa_evidence_queries") or [])
        and ((generic_qa_contract.get("debug") or {}).get("field_contract") or {}).get("field_type") == "product_qa"
        and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
    ):
        phase1_direct_result = generic_qa_contract
    if conversation_id and _looks_like_ordinal_product_field_followup(question):
        ordinal_recommendation_context = _latest_recommendation_context_for_sources(db, conversation_id)
        ordinal_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
        ordinal_followup_sku = _ordinal_followup_target_sku(
            question,
            ordinal_recommendation_context,
            ordinal_candidate_context,
        )
        latest_ordered_result_skus = _latest_ordered_result_skus_for_followup(
            db,
            conversation_id,
            user_id,
        )
        if not ordinal_followup_sku and len(latest_ordered_result_skus) >= 2:
            ordinal_followup_sku = _ordinal_followup_target_sku_from_ordered(
                question,
                latest_ordered_result_skus,
            )
        if not ordinal_followup_sku:
            ordinal_followup_sku = _ordinal_followup_target_sku_from_ordered(
                question,
                _conversation_explicit_skus_in_mention_order(db, conversation_id, user_id),
            )
        ordinal_requested_field = _followup_requested_field(question)
        if ordinal_followup_sku and ordinal_requested_field:
            phase1_direct_result = _product_field_followup_result(
                db,
                ordinal_followup_sku,
                ordinal_requested_field,
                question,
                identity_source="recommendation_context_ordinal",
            )
            if phase1_direct_result:
                phase1_direct_result = _attach_phase1_plan_and_timing(
                    phase1_direct_result,
                    phase1_plan,
                    _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
                )
                return await _save_agent_result_and_return(
                    db,
                    user_id=user_id,
                    question=question,
                    conversation_id=conversation_id,
                    agent_result=phase1_direct_result,
                    request_start=request_start,
                    branch="recommendation_context_ordinal_field",
                    semantic_preplan=semantic_preplan,
                )
    plural_heat_source_followup = bool(
        phase1_plan.get("primary_intent") == "product_field"
        and _is_plural_heat_source_followup(question)
    )
    alcohol_stove_cookware_list_query = bool(
        phase1_plan.get("primary_intent") == "product_field"
        and customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(question)
        and not customer_agent_service._extract_skus(question)
    )
    if (
        not phase1_direct_result
        and phase1_plan.get("primary_intent") == "product_field"
        and not plural_heat_source_followup
        and not alcohol_stove_cookware_list_query
        and not _candidate_context_formal_field_filter_eligible(
            question,
            field_request=phase2_field_request,
            candidate_context=active_candidate_context,
        )
        # A high-confidence semantic product-QA contract owns the requested
        # capability.  The legacy phase-one planner may still see an adjacent
        # field token in the product name or question (for example a fuel
        # word) but must not turn that into a structured-field answer before
        # the sealed same-SKU QA path can answer or fail closed.
        and not _semantic_prefers_sealed_product_qa(phase1_plan)
        # A validated semantic FieldContract is authoritative over the
        # planner's compatibility label.  Do not let the phase-1 executor
        # return before central Phase 2 can seal entity identity and select
        # same-SKU structured evidence.
        and not (
            isinstance(semantic_preplan, dict)
            and semantic_preplan.get("called")
            and str(semantic_preplan.get("field_type") or "") in customer_field_contract.FORMAL_DETAIL_FIELDS
            and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
            and not _semantic_catalog_aggregate_contract(semantic_preplan, phase1_plan)
        )
    ):
        phase1_direct_result = _phase1_product_field_result(db, phase1_plan)
    elif phase1_plan.get("primary_intent") == "category_compatibility":
        phase1_direct_result = _phase1_category_compatibility_result(db, phase1_plan)
    elif (
        phase1_plan.get("primary_intent") == "catalog_count"
        and _looks_like_semantic_catalog_query(question)
        # A constrained, allowlisted product-field preplan must reach the
        # central FieldContract/EntityResolution path before a legacy count
        # heuristic can reinterpret a named-product fact as a category query.
        and not (
            isinstance(semantic_preplan, dict)
            and semantic_preplan.get("called")
            and str(semantic_preplan.get("field_type") or "") in customer_field_contract.FORMAL_DETAIL_FIELDS
            and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
            and not _semantic_catalog_aggregate_contract(semantic_preplan, phase1_plan)
        )
        and not _has_resolved_entity_contents_accessories_question(db, question)
        # Count vocabulary embedded inside a named product question (for
        # example a shipping-price "多少") is not a category count.  Preserve
        # the product scope for the central field/entity contracts.
        and not _products_named_in_question(db, question)
        and not _has_unresolved_product_like_scope(db, question)
    ):
        phase1_direct_result = _phase1_catalog_count_result(db, phase1_plan)
    elif phase1_plan.get("primary_intent") in {"product_compare_recommendation", "comparison"}:
        phase1_direct_result = await _phase1_compare_choice_result(db, phase1_plan)
    elif phase1_plan.get("primary_intent") == "recommendation" and _phase1_should_use_structured_recommendation(phase1_plan):
        phase1_direct_result = _phase1_structured_recommendation_result(db, phase1_plan)
    phase1_executor_duration_ms = round((perf_counter() - executor_start) * 1000, 2) if phase1_direct_result else 0
    if phase1_direct_result:
        guard_start = perf_counter()
        phase1_direct_result = _run_phase1_answer_guard(phase1_direct_result, phase1_plan)
        phase1_direct_result = _post_filter_recommendation_result(db, question, phase1_direct_result)
        guard_duration_ms = round((perf_counter() - guard_start) * 1000, 2)
        phase1_direct_result = _attach_phase1_plan_and_timing(
            phase1_direct_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
                executor_duration_ms=phase1_executor_duration_ms,
                guard_duration_ms=guard_duration_ms,
            ),
        )
        phase1_direct_result = _attach_semantic_preplan_debug(
            phase1_direct_result,
            semantic_preplan,
            final_route=str(phase1_direct_result.get("answer_type") or phase1_plan.get("answer_type") or ""),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=phase1_direct_result,
            request_start=request_start,
            branch=f"phase1_{phase1_plan.get('primary_intent') or 'planner'}",
            semantic_preplan=semantic_preplan,
        )

    semantic_comparison_clarification = None if phase1_plan.get("semantic_comparison_entity_contracts") else _semantic_comparison_fail_closed_result(semantic_preplan)
    if semantic_comparison_clarification:
        semantic_comparison_clarification = _attach_phase1_plan_and_timing(
            semantic_comparison_clarification,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
                executor_duration_ms=phase1_executor_duration_ms,
            ),
        )
        semantic_comparison_clarification = _attach_semantic_preplan_debug(
            semantic_comparison_clarification,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_comparison_clarification,
            request_start=request_start,
            branch="semantic_comparison_unsealed_clarification",
            semantic_preplan=semantic_preplan,
        )

    semantic_structured_result = None
    if (
        not _semantic_preplan_unknown_realtime_subtype(semantic_preplan, question)
        and not _looks_like_recommendation_request(question)
        and not (
        isinstance(semantic_preplan, dict)
        and semantic_preplan.get("called")
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and str(semantic_preplan.get("field_type") or "") in customer_field_contract.FORMAL_DETAIL_FIELDS
        )
    ):
        semantic_structured_result = _semantic_structured_query_result(
            db,
            question,
            candidate_context=_latest_candidate_context_for_sources(db, conversation_id),
            semantic_preplan=semantic_preplan,
        )
    if semantic_structured_result:
        semantic_structured_result = _post_filter_recommendation_result(db, question, semantic_structured_result)
        structured_phase1_plan = _semantic_structured_override_plan(question, phase1_plan, semantic_structured_result)
        semantic_structured_result = _attach_phase1_plan_and_timing(
            semantic_structured_result,
            structured_phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        semantic_structured_result = _attach_semantic_preplan_debug(
            semantic_structured_result,
            semantic_preplan,
            final_route=str(semantic_structured_result.get("answer_type") or "query_products"),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_structured_result,
            request_start=request_start,
            branch="phase1_semantic_structured_guard",
            semantic_preplan=semantic_preplan,
        )

    composite_question = _split_composite_customer_question(question)
    if composite_question:
        fact_part = composite_question["fact_part"]
        recommendation_part = _normalize_composite_recommendation_part(composite_question["recommendation_part"])
        fact_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=fact_part,
            sku=sku,
            previous_result_skus=[],
            allow_llm_fallback=False,
            **intent_execution_options,
        )
        fact_previous_result_skus = []
        if fact_result:
            fact_previous_result_skus = list(dict.fromkeys([
                str(item.get("sku") or "").strip().upper()
                for item in (fact_result.get("results") or [])
                if isinstance(item, dict) and str(item.get("sku") or "").strip()
            ] or [
                str(sku or "").strip().upper()
                for sku in (fact_result.get("result_skus") or [])
                if str(sku or "").strip()
            ]))
        recommendation_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=recommendation_part,
            sku=None,
            previous_result_skus=fact_previous_result_skus,
            allow_llm_fallback=False,
            scoped_comparison_candidates=bool(
                len(fact_previous_result_skus) >= 2
                and any(term in fact_part for term in ("比较", "对比"))
                and "更适合" in recommendation_part
                and re.search(r"(?:[1-9]\d?|[一二两三四五六七八九十])\s*(?:个)?人", recommendation_part)
            ),
            **intent_execution_options,
        )
        if fact_result or recommendation_result:
            merged_result = dict(recommendation_result or fact_result or {})
            if fact_result and recommendation_result:
                if composite_question.get("order") == "recommendation_first":
                    merged_result["answer"] = _merge_composite_answers(recommendation_result.get("answer", ""), fact_result.get("answer", ""))
                else:
                    merged_result["answer"] = _merge_composite_answers(fact_result.get("answer", ""), recommendation_result.get("answer", ""))
                merged_result["intent"] = "recommendation"
                merged_result["answer_type"] = recommendation_result.get("answer_type") or fact_result.get("answer_type")
                merged_result["results"] = recommendation_result.get("results") or fact_result.get("results") or []
                merged_result["result_skus"] = recommendation_result.get("result_skus") or fact_result.get("result_skus") or []
                merged_result.setdefault("debug", {})
                merged_result["debug"]["composite_question"] = {
                    "fact_part": fact_part,
                    "recommendation_part": recommendation_part,
                    "original_recommendation_part": composite_question["recommendation_part"],
                    "order": composite_question.get("order") or "fact_first",
                    "strategy": "detail_usage_compare_plus_recommendation",
                }
            elif fact_result:
                merged_result = fact_result
            elif recommendation_result:
                merged_result = recommendation_result
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=merged_result,
                request_start=request_start,
                branch="composite_multi_intent",
            )

    named_products = _products_named_in_question(db, question)
    recommendation_followup_context = _latest_recommendation_context_for_sources(db, conversation_id)
    candidate_followup_context = _latest_candidate_context_for_sources(db, conversation_id)
    active_product_context_skus = _latest_active_product_skus(db, conversation_id, user_id)
    context_pair_result = None
    if (
        _is_ordinal_compare_followup_question(question)
        or "哪个更适合" in question
        or _is_plural_heat_source_followup(question)
    ):
        pair_skus = _context_skus_for_pair_followup(recommendation_followup_context, candidate_followup_context)
        if not pair_skus and _is_plural_heat_source_followup(question):
            pair_skus = _previous_result_skus_for_pre_runtime(
                db,
                user_id=user_id,
                conversation_id=conversation_id,
                question=question,
            )[:2]
        if pair_skus:
            context_pair_result = _context_pair_followup_result(db, question, pair_skus)
    followup_runtime_bypass = _should_bypass_usage_care_and_faq_for_followup(
        db,
        conversation_id=conversation_id,
        question=question,
        conversation_history=_build_conversation_history(db, conversation_id, user_id) if conversation_id else [],
    )
    customer_perf_service.log_stage(
        "followup_runtime_guard",
        perf_counter(),
        bypass=bool(followup_runtime_bypass),
        has_followup=bool(_is_recommendation_followup_question(question)),
        conversation_id=conversation_id,
    )
    usage_care_start = perf_counter()
    usage_care_result = None
    if (
        not context_pair_result
        and _is_product_usage_care_question(question)
        and not _has_non_usage_care_field_contract(question)
        and not _semantic_formal_field_preempts_legacy_shortcuts(semantic_preplan)
        and not _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan)
        and not followup_runtime_bypass
        and not (len(named_products) > 1)
        and not _semantic_prefers_sealed_product_qa(phase1_plan)
        and not _should_prioritize_semantic_structured_route(question, phase1_plan)
    ):
        usage_care_result = await customer_agent_intent_service.answer_product_usage_care_request(
            db,
            question=question,
            named_products=named_products,
        )
        if len((usage_care_result or {}).get("result_skus") or []) > 1:
            usage_care_result = None
    customer_perf_service.log_stage(
        "product_usage_care_fast_path",
        usage_care_start,
        hit=bool(usage_care_result),
        intent=usage_care_result.get("intent") if usage_care_result else None,
        agent_mode=(usage_care_result.get("debug") or {}).get("agent_mode") if usage_care_result else None,
    )
    if usage_care_result:
        usage_care_result = _attach_phase1_plan_and_timing(
            usage_care_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        usage_care_result = _finalize_answer(usage_care_result)
        usage_care_result = _shape_answer_for_output(usage_care_result)
        usage_care_result = customer_final_answer_arbiter.arbitrate_final_answer(
            usage_care_result
        )
        stage_start = perf_counter()
        conversation = _get_or_create_conversation(db, user_id, question, usage_care_result.get("sku"), conversation_id)
        db.add(CustomerServiceMessage(
            conversation_id=conversation.id,
            role="user",
            content=question,
            sku=usage_care_result.get("sku"),
        ))
        assistant_turn_index = _assistant_turn_index(db, conversation.id)
        sources_with_context = _sources_with_result_context(
            usage_care_result,
            turn_index=assistant_turn_index,
            user_question=question,
        )
        assistant_message = CustomerServiceMessage(
            conversation_id=conversation.id,
            role="assistant",
            content=usage_care_result["answer"],
            sku=usage_care_result.get("sku"),
            sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
        )
        db.add(assistant_message)
        _touch_conversation(conversation, usage_care_result.get("sku"))
        conversation_id_value = conversation.id
        message_id_value = assistant_message.id
        db.commit()
        customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch="product_usage_care_fast_path", intent=usage_care_result.get("intent"))
        customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="product_usage_care_fast_path", intent=usage_care_result.get("intent"), agent_mode=(usage_care_result.get("debug") or {}).get("agent_mode"))
        customer_perf_service.summarize_request(
            final_answer=usage_care_result.get("answer"),
            intent=usage_care_result.get("intent"),
            agent_mode=(usage_care_result.get("debug") or {}).get("agent_mode"),
        )
        release_session_connection(db)
        public_intent = _public_intent_name(usage_care_result.get("intent"), usage_care_result.get("answer_type"))
        return {
            "conversation_id": conversation_id_value,
            "message_id": message_id_value,
            "intent": public_intent,
            "answer_type": usage_care_result.get("answer_type"),
            "confidence": usage_care_result.get("confidence"),
            "uncertainty": usage_care_result.get("uncertainty"),
            "needs_clarification": usage_care_result.get("needs_clarification", False),
            "anomalies": usage_care_result.get("anomalies") or [],
            "suggested_followups": usage_care_result.get("suggested_followups") or [],
            "followups": usage_care_result.get("followups") or usage_care_result.get("suggested_followups") or [],
            "warnings": usage_care_result.get("warnings") or [],
            "evidence": usage_care_result.get("evidence") or [],
            "agent_quality": usage_care_result.get("agent_quality") or {},
            "answer_metadata": usage_care_result.get("answer_metadata") or {},
            "debug": usage_care_result.get("debug") or {},
            "sku": usage_care_result.get("sku"),
            "answer": usage_care_result["answer"],
            "sources": sources_with_context,
            "actions": usage_care_result.get("actions") or [],
            "results": usage_care_result.get("results") or [],
            "steps": usage_care_result.get("steps") or [],
            "result_skus": usage_care_result.get("result_skus") or [],
            "agent_mode": (usage_care_result.get("debug") or {}).get("agent_mode"),
        }
    faq_start = perf_counter()
    semantic_route = _semantic_preplan_route_family(semantic_preplan)
    semantic_contract_preempts_faq = bool(
        isinstance(semantic_preplan, dict)
        and semantic_preplan.get("called")
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and semantic_route in {
            "structured_query",
            "recommendation",
            "comparison",
            "product_bound_qa",
            "contents_accessories",
        }
    )
    faq_intent = None if (
        context_pair_result
        or named_products
        or followup_runtime_bypass
        or semantic_contract_preempts_faq
    ) else _classify_customer_faq_intent(question)
    faq_result = None
    if faq_intent:
        faq_result = await _answer_customer_faq_fast_path(db, question, faq_intent)
    customer_perf_service.log_stage(
        "customer_faq_fast_path",
        faq_start,
        hit=bool(faq_result),
        intent=faq_intent,
        agent_mode=(faq_result.get("debug") or {}).get("agent_mode") if faq_result else None,
    )
    if faq_result:
        faq_result = _attach_phase1_plan_and_timing(
            faq_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        faq_result = _finalize_answer(faq_result)
        faq_result = _shape_answer_for_output(faq_result)
        faq_result = await _attach_debug_supporting_knowledge(db, faq_result, question)
        faq_result = _shape_answer_for_output(faq_result)
        faq_result = customer_final_answer_arbiter.arbitrate_final_answer(faq_result)
        stage_start = perf_counter()
        conversation = _get_or_create_conversation(db, user_id, question, faq_result.get("sku"), conversation_id)
        db.add(CustomerServiceMessage(
            conversation_id=conversation.id,
            role="user",
            content=question,
            sku=faq_result.get("sku"),
        ))
        assistant_turn_index = _assistant_turn_index(db, conversation.id)
        sources_with_context = _sources_with_result_context(
            faq_result,
            turn_index=assistant_turn_index,
            user_question=question,
        )
        assistant_message = CustomerServiceMessage(
            conversation_id=conversation.id,
            role="assistant",
            content=faq_result["answer"],
            sku=faq_result.get("sku"),
            sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
        )
        db.add(assistant_message)
        _touch_conversation(conversation, faq_result.get("sku"))
        conversation_id_value = conversation.id
        message_id_value = assistant_message.id
        db.commit()
        customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch="faq_fast_path", intent=faq_result.get("intent"))
        customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="faq_fast_path", intent=faq_result.get("intent"), agent_mode=(faq_result.get("debug") or {}).get("agent_mode"))
        customer_perf_service.summarize_request(
            final_answer=faq_result.get("answer"),
            intent=faq_result.get("intent"),
            agent_mode=(faq_result.get("debug") or {}).get("agent_mode"),
        )
        release_session_connection(db)
        public_intent = _public_intent_name(faq_result.get("intent"), faq_result.get("answer_type"))
        return {
            "conversation_id": conversation_id_value,
            "message_id": message_id_value,
            "intent": public_intent,
            "answer_type": faq_result.get("answer_type"),
            "confidence": faq_result.get("confidence"),
            "uncertainty": faq_result.get("uncertainty"),
            "needs_clarification": faq_result.get("needs_clarification", False),
            "anomalies": faq_result.get("anomalies") or [],
            "suggested_followups": faq_result.get("suggested_followups") or [],
            "followups": faq_result.get("followups") or faq_result.get("suggested_followups") or [],
            "warnings": faq_result.get("warnings") or [],
            "evidence": faq_result.get("evidence") or [],
            "agent_quality": faq_result.get("agent_quality") or {},
            "answer_metadata": faq_result.get("answer_metadata") or {},
            "debug": faq_result.get("debug") or {},
            "sku": faq_result.get("sku"),
            "answer": faq_result["answer"],
            "sources": sources_with_context,
            "actions": faq_result.get("actions") or [],
            "results": faq_result.get("results") or [],
            "steps": faq_result.get("steps") or [],
            "result_skus": faq_result.get("result_skus") or [],
            "agent_mode": (faq_result.get("debug") or {}).get("agent_mode"),
        }

    stage_start = perf_counter()
    shipping_intent_signal = customer_field_contract.detect_shipping_intent_signal(question)
    guardrail_field_contract = customer_field_contract.detect_field_contract(question)
    formal_non_weather_field_signal = bool(
        guardrail_field_contract is not None
        and guardrail_field_contract.field_type != "usage_scene"
    )
    agent_result = customer_enterprise_guardrail_service.evaluate_question(question)
    semantic_catalog_request = bool(
        isinstance(semantic_preplan, dict)
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and str(semantic_preplan.get("route_family") or "").strip() == "structured_query"
        and str(semantic_preplan.get("route_hint") or "").strip() == "query_products"
    )
    if shipping_intent_signal or formal_non_weather_field_signal or semantic_catalog_request:
        agent_result = None
    customer_perf_service.log_stage("guardrail.evaluate_question", stage_start, matched=bool(agent_result))
    if not agent_result and context_pair_result:
        agent_result = context_pair_result
    if agent_result:
        stage_start = perf_counter()
        guard_start = perf_counter()
        agent_result = _run_phase1_answer_guard(agent_result, phase1_plan)
        guard_duration_ms = round((perf_counter() - guard_start) * 1000, 2)
        agent_result = _attach_phase1_plan_and_timing(
            agent_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
                guard_duration_ms=guard_duration_ms,
            ),
        )
        agent_result = _attach_semantic_preplan_debug(
            agent_result,
            semantic_preplan,
            final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
        )
        agent_result = _finalize_answer(agent_result)
        agent_result = _shape_answer_for_output(agent_result)
        agent_result = await _attach_debug_supporting_knowledge(db, agent_result, question)
        agent_result = _attach_semantic_preplan_debug(
            agent_result,
            semantic_preplan,
            final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
        )
        agent_result = _shape_answer_for_output(agent_result)
        agent_result = customer_final_answer_arbiter.arbitrate_final_answer(agent_result)
        agent_result = _attach_agent_quality(agent_result, question)
        conversation = _get_or_create_conversation(db, user_id, question, agent_result.get("sku"), conversation_id)
        db.add(CustomerServiceMessage(
            conversation_id=conversation.id,
            role="user",
            content=question,
            sku=agent_result.get("sku"),
        ))
        assistant_turn_index = _assistant_turn_index(db, conversation.id)
        sources_with_context = _sources_with_result_context(
            agent_result,
            turn_index=assistant_turn_index,
            user_question=question,
        )
        assistant_message = CustomerServiceMessage(
            conversation_id=conversation.id,
            role="assistant",
            content=agent_result["answer"],
            sku=agent_result.get("sku"),
            sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
        )
        db.add(assistant_message)
        _touch_conversation(conversation, agent_result.get("sku"))
        conversation_id_value = conversation.id
        message_id_value = assistant_message.id
        db.commit()
        customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch="guardrail")
        customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="guardrail", intent=agent_result.get("intent"))
        customer_perf_service.summarize_request(final_answer=agent_result.get("answer"), intent=agent_result.get("intent"), agent_mode=(agent_result.get("debug") or {}).get("agent_mode"))
        release_session_connection(db)
        agent_result = _attach_semantic_preplan_debug(
            agent_result,
            semantic_preplan,
            final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
        )
        public_intent = _public_intent_name(agent_result.get("intent"), agent_result.get("answer_type"))
        return {
            "conversation_id": conversation_id_value,
            "message_id": message_id_value,
            "intent": public_intent,
            "answer_type": agent_result.get("answer_type"),
            "confidence": agent_result.get("confidence"),
            "uncertainty": agent_result.get("uncertainty"),
            "needs_clarification": agent_result.get("needs_clarification", False),
            "anomalies": agent_result.get("anomalies") or [],
            "suggested_followups": agent_result.get("suggested_followups") or [],
            "followups": agent_result.get("followups") or agent_result.get("suggested_followups") or [],
            "warnings": agent_result.get("warnings") or [],
            "evidence": agent_result.get("evidence") or [],
            "agent_quality": agent_result.get("agent_quality") or {},
            "answer_metadata": agent_result.get("answer_metadata") or {},
            "debug": agent_result.get("debug") or {},
            "sku": agent_result.get("sku"),
            "answer": agent_result["answer"],
            "sources": sources_with_context,
            "actions": agent_result.get("actions") or [],
            "results": agent_result.get("results") or [],
            "steps": agent_result.get("steps") or [],
            "result_skus": agent_result.get("result_skus") or [
                str(item.get("sku") or "").strip().upper()
                for item in (agent_result.get("results") or [])
                if isinstance(item, dict) and str(item.get("sku") or "").strip()
            ],
            "candidate_skus": agent_result.get("candidate_skus") or agent_result.get("result_skus") or [
                str(item.get("sku") or "").strip().upper()
                for item in (agent_result.get("results") or [])
                if isinstance(item, dict) and str(item.get("sku") or "").strip()
            ],
            "agent_mode": (agent_result.get("debug") or {}).get("agent_mode"),
        }

    preloaded_entity_stack: list[dict] | None = None
    preloaded_conversation_history: list[dict] | None = None

    sku_identity_start = perf_counter()
    agent_result = _try_product_sku_identity_shortcut(db, question)
    customer_perf_service.log_stage(
        "product_sku_identity_shortcut",
        sku_identity_start,
        hit=bool(agent_result),
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode") if agent_result else None,
    )

    explicit_multi_field_start = perf_counter()
    explicit_multi_field_result = None
    if not agent_result:
        explicit_multi_field_result = _phase1_explicit_sku_alcohol_people_result(db, question)
        agent_result = explicit_multi_field_result
    customer_perf_service.log_stage(
        "explicit_sku_compatibility_people",
        explicit_multi_field_start,
        hit=bool(explicit_multi_field_result),
        agent_mode=(explicit_multi_field_result.get("debug") or {}).get("agent_mode") if explicit_multi_field_result else None,
    )

    explicit_detail_start = perf_counter()
    explicit_detail_result = None
    if not agent_result and not _semantic_prefers_sealed_product_qa(phase1_plan):
        explicit_detail_result = await _try_explicit_sku_detail_shortcut(db, question)
        agent_result = explicit_detail_result
    customer_perf_service.log_stage(
        "explicit_sku_detail_shortcut",
        explicit_detail_start,
        hit=bool(explicit_detail_result),
        agent_mode=(explicit_detail_result.get("debug") or {}).get("agent_mode") if explicit_detail_result else None,
    )

    alcohol_exclusion_start = perf_counter()
    alcohol_exclusion_result = None
    if not agent_result:
        alcohol_exclusion_result = _phase1_except_alcohol_stove_cookware_result(db, question)
        agent_result = alcohol_exclusion_result
    customer_perf_service.log_stage(
        "structured_alcohol_stove_cookware_exclusion",
        alcohol_exclusion_start,
        hit=bool(alcohol_exclusion_result),
        agent_mode=(alcohol_exclusion_result.get("debug") or {}).get("agent_mode") if alcohol_exclusion_result else None,
    )

    qa_start = perf_counter()
    qa_result = None
    if not agent_result and shipping_intent_signal:
        # Shipping remains a safety-sensitive formal field.  A response is
        # allowed here only when the normal helper seals the product and finds
        # field-compatible QA evidence on that same SKU; otherwise it returns
        # None and the existing safe-missing path remains authoritative.
        qa_result = _try_product_qa_shortcut(db, question, phase1_plan=phase1_plan)
        agent_result = qa_result
    elif (
        not agent_result
        and customer_field_contract.detect_field_contract(question) is None
        and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
    ):
        qa_result = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan=phase1_plan,
        )
        agent_result = qa_result
    customer_perf_service.log_stage(
        "product_qa_shortcut",
        qa_start,
        hit=bool(qa_result),
        agent_mode=(qa_result.get("debug") or {}).get("agent_mode") if qa_result else None,
    )

    # A high-confidence semantic QA turn without a sealed same-SKU record is
    # not eligible for generic KB or legacy-agent fallback.  Preserve its
    # EntityResolutionContract and either clarify an unknown subject or give
    # the product-specific safe-missing response instead of fabricating a
    # product fact from a top retrieval hit.
    # DeepSeek's evidence selector and entailment auditor are independent
    # semantic calls. A transient conservative verdict must not erase a valid
    # same-SKU answer. Each bounded retry remains fully sealed by the same
    # entity, quote, and strict-entailment contracts; failure after all tries
    # still returns the product-specific safe-missing response.
    qa_safe_missing = agent_result if _is_sealed_product_qa_safe_missing(agent_result) else None
    if qa_safe_missing:
        # A QA miss is not proof that the sealed product has no relevant
        # knowledge-base evidence. Preserve this result solely as the final
        # fail-closed fallback while the same-SKU RAG provider evaluates the
        # semantic question (including a supported part of a compound turn).
        agent_result = None
    compound_preplan = (
        (phase1_plan.get("semantic_preplan") or {})
        if isinstance(phase1_plan, dict)
        else {}
    )
    # Some Phase-2 adapters replace the executable plan with a narrowed copy
    # while the accepted semantic preplan is retained separately for audit.
    # Compound sub-intents belong to that accepted semantic decision, so do
    # not lose them merely because the execution copy omitted the list.
    if not (compound_preplan.get("qa_evidence_queries") or []) and isinstance(semantic_preplan, dict):
        compound_preplan = semantic_preplan
    compound_queries = [
        str(item or "").strip()
        for item in (compound_preplan.get("qa_evidence_queries") or [])
        if str(item or "").strip()
    ]
    if agent_result is not None and compound_queries:
        # A single exact QA may cover one child, but it cannot terminate a
        # semantic multi-question contract before the remaining children have
        # been independently evaluated.
        qa_safe_missing = agent_result
        agent_result = None
    if compound_queries and (agent_result is not None or qa_safe_missing is not None):
        compound_answers: list[dict] = []
        compound_missing_queries: list[str] = []
        compound_answered_requests: list[tuple[str, str]] = []
        parent_preplan = compound_preplan
        for query in compound_queries:
            child_preplan = dict(parent_preplan)
            child_preplan.update({"qa_evidence_query": query, "qa_evidence_queries": [], "compound": False, "strict_compound_child_qa": True})
            child_plan = dict(phase1_plan)
            child_plan["semantic_preplan"] = child_preplan
            child_question = " ".join(item for item in (str(child_preplan.get("subject_text") or "").strip(), query) if item) or question
            candidate = await _try_semantic_compound_child_answer(
                db,
                child_question,
                child_plan,
            )
            if not _record_semantic_compound_child(
                query=query,
                candidate=candidate,
                compound_answers=compound_answers,
                answered_requests=compound_answered_requests,
            ):
                compound_missing_queries.append(query)
        if compound_answers:
            base_result = agent_result or compound_answers[0]
            agent_result = base_result
            base_text = str(agent_result.get("answer") or "").strip()
            extras = [str(item.get("answer") or "").strip() for item in compound_answers if str(item.get("answer") or "").strip() and str(item.get("answer") or "").strip() not in base_text]
            if extras:
                agent_result["answer"] = "\n".join([base_text, *extras])
            if compound_missing_queries:
                agent_result["answer"] = "\n".join([
                    str(agent_result.get("answer") or "").strip(),
                    *(f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in compound_missing_queries),
                ])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_missing_queries
            missing_query_set = set(compound_missing_queries)
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=[
                        item for item in compound_answered_requests
                        if item[0] not in missing_query_set
                    ],
                    unsupported_requests=compound_missing_queries,
                ).to_dict()
            )
        elif qa_safe_missing is not None:
            # No child yielded distinct evidence. Preserve the already sealed
            # parent QA and explicitly fail closed for every remaining child
            # instead of falling back to a single-question shortcut later.
            agent_result = qa_safe_missing
            agent_result["answer"] = "\n".join([
                str(agent_result.get("answer") or "").strip(),
                *(f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in compound_queries[1:]),
            ])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_queries[1:]
            parent_evidence_id = str(
                compound_metadata.get("evidence_source")
                or compound_metadata.get("source")
                or "same_sku_parent_evidence"
            )
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=[(compound_queries[0], parent_evidence_id)],
                    unsupported_requests=compound_queries[1:],
                ).to_dict()
            )
        elif agent_result is not None and len(compound_queries) > 1:
            # The parent QA may be valid while every narrowed child misses.
            # Keep the parent answer, but never silently drop the remaining
            # semantically independent questions.
            agent_result["answer"] = "\n".join([
                str(agent_result.get("answer") or "").strip(),
                *(f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in compound_queries[1:]),
            ])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_queries[1:]
            parent_evidence_id = str(
                compound_metadata.get("evidence_source")
                or compound_metadata.get("source")
                or "same_sku_parent_evidence"
            )
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=[(compound_queries[0], parent_evidence_id)],
                    unsupported_requests=compound_queries[1:],
                ).to_dict()
            )
    for _sealed_attempt in range(3):
        if agent_result or not _semantic_prefers_sealed_product_qa(phase1_plan):
            break
        agent_result = await _try_sealed_same_sku_knowledge_answer(
            db,
            question,
            phase1_plan,
        )
    if not agent_result:
        agent_result = qa_safe_missing
    if not agent_result:
        agent_result = _sealed_semantic_product_qa_entity_guard(
            db,
            question,
            phase1_plan,
        )

    # The entity guard may be the first place that constructs a sealed
    # safe-missing response.  Run the already-planned compound children here
    # as well, before that fallback reaches any legacy shortcut or the final
    # save boundary.  No new intent is inferred: every child is an LLM-issued
    # semantic sub-query and remains bound to the same resolved SKU.
    if _is_sealed_product_qa_safe_missing(agent_result) and compound_queries:
        compound_answers: list[dict] = []
        compound_answered_requests: list[tuple[str, str]] = []
        compound_missing_queries: list[str] = []
        for query in compound_queries:
            child_preplan = dict(compound_preplan)
            child_preplan.update({"qa_evidence_query": query, "qa_evidence_queries": [], "compound": False})
            child_plan = dict(phase1_plan)
            child_plan["semantic_preplan"] = child_preplan
            child_question = " ".join(
                item for item in (str(child_preplan.get("subject_text") or "").strip(), query) if item
            ) or question
            candidate = await _try_semantic_compound_child_answer(
                db,
                child_question,
                child_plan,
            )
            if not _record_semantic_compound_child(
                query=query,
                candidate=candidate,
                compound_answers=compound_answers,
                answered_requests=compound_answered_requests,
            ):
                compound_missing_queries.append(query)
        if compound_answers:
            agent_result = compound_answers[0]
            extras = [str(item.get("answer") or "").strip() for item in compound_answers[1:] if str(item.get("answer") or "").strip()]
            if extras:
                agent_result["answer"] = "\n".join([str(agent_result.get("answer") or "").strip(), *extras])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_missing_queries
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=compound_answered_requests,
                    unsupported_requests=compound_missing_queries,
                ).to_dict()
            )

    shortcut_start = perf_counter()
    if (
        not agent_result
        and not _semantic_prefers_sealed_product_qa(phase1_plan)
        and not _formal_field_contract_preempts_product_qa(question, phase1_plan)
    ):
        agent_result = await _try_named_product_shortcut(db, user_id=user_id, question=question)
    customer_perf_service.log_stage("named_product_shortcut", shortcut_start, hit=bool(agent_result), agent_mode=(agent_result.get("debug") or {}).get("agent_mode") if agent_result else None)
    recommendation_followup_context = _latest_recommendation_context_for_sources(db, conversation_id)
    candidate_followup_context = _latest_candidate_context_for_sources(db, conversation_id)
    active_product_context_skus = _latest_active_product_skus(db, conversation_id, user_id)
    if (
        not agent_result
        and _looks_like_context_required_ordinal_compare(question)
        and not _has_followup_result_context(recommendation_followup_context)
        and not _has_followup_result_context(candidate_followup_context)
    ):
        agent_result = _context_required_ordinal_compare_result(question)
    if not agent_result and (
        _is_ordinal_compare_followup_question(question)
        or "哪个更适合" in question
        or _is_plural_heat_source_followup(question)
    ):
        pair_skus = _context_skus_for_pair_followup(recommendation_followup_context, candidate_followup_context)
        if not pair_skus and _is_plural_heat_source_followup(question):
            pair_skus = _previous_result_skus_for_pre_runtime(
                db,
                user_id=user_id,
                conversation_id=conversation_id,
                question=question,
            )[:2]
        if pair_skus:
            agent_result = _context_pair_followup_result(db, question, pair_skus)
    if not agent_result:
        # The current turn's validated FieldContract owns field meaning. The
        # follow-up helper below is legacy compatibility only; it must not
        # reinterpret a word in the subject matter (for example “酒精” in a
        # storage question) as a different field such as heat_source.
        followup_field_request = resolve_requested_field_contract(question, phase1_plan)
        followup_canonical_field = str(followup_field_request.get("field_type") or "").strip()
        requested_followup_field = (
            customer_field_contract.product_detail_field_label(followup_canonical_field)
            if followup_canonical_field
            else _followup_requested_field(question)
        )
        ordinal_followup_sku = _ordinal_followup_target_sku(
            question,
            recommendation_followup_context,
            candidate_followup_context,
        )
        if not ordinal_followup_sku and any(term in question for term in ("第一个", "第一款", "最前面那个", "第二个", "第二款", "第三个", "第三款", "最后一个", "最后一款", "最后那个")):
            ordinal_followup_sku = _ordinal_followup_target_sku_from_ordered(
                question,
                _latest_ordered_result_skus_for_followup(
                    db,
                    conversation_id=conversation_id,
                    user_id=user_id,
                ),
            )
        if ordinal_followup_sku and requested_followup_field:
            agent_result = _product_field_followup_result(
                db,
                ordinal_followup_sku,
                requested_followup_field,
                question,
                identity_source="recommendation_context_ordinal",
                field_request_override=followup_field_request,
            )
            agent_result = _attach_recommendation_followup_contract(
                agent_result,
                question,
                recommendation_followup_context,
            )
    # A sealed follow-up anchor only supplies identity when the current turn
    # does not name a product. Explicit product references are current-turn
    # authority; otherwise a heat-source term can collapse a two-product
    # compatibility request onto the previous anchor.
    if not agent_result and not named_products:
        heat_source_followup_sku = ""
        latest_ordered_followup_skus: list[str] = []
        if conversation_id:
            latest_ordered_followup_skus = _latest_ordered_result_skus_for_followup(
                db,
                conversation_id,
                user_id,
            )
            previous_user_question = _latest_user_question_for_followup(
                db,
                conversation_id,
                user_id,
                question,
            )
            heat_source_followup_sku = _ordinal_followup_target_sku_from_ordered(
                previous_user_question,
                latest_ordered_followup_skus,
            )
        if isinstance(candidate_followup_context, dict):
            candidate_ordered_skus = _ordered_context_skus(candidate_followup_context)
            if not heat_source_followup_sku:
                heat_source_followup_sku = _ordinal_followup_target_sku_from_ordered(
                    str(candidate_followup_context.get("user_question") or ""),
                    candidate_ordered_skus,
                )
            if not heat_source_followup_sku:
                heat_source_followup_sku = str(candidate_followup_context.get("last_referenced_sku") or "").strip().upper()
        if not heat_source_followup_sku:
            heat_source_followup_sku = _pronoun_heat_source_followup_target_sku(question, recommendation_followup_context)
        if not heat_source_followup_sku and isinstance(candidate_followup_context, dict):
            heat_source_followup_sku = str(candidate_followup_context.get("last_referenced_sku") or "").strip().upper()
        if not heat_source_followup_sku and isinstance(candidate_followup_context, dict):
            ordered_candidate_skus = _ordered_context_skus(candidate_followup_context)
            if ordered_candidate_skus:
                heat_source_followup_sku = ordered_candidate_skus[0]
        if not heat_source_followup_sku and latest_ordered_followup_skus:
            heat_source_followup_sku = latest_ordered_followup_skus[0]
        # A plural field filter addresses the sealed candidate set, never its
        # first member.  Selecting index zero here silently converted a
        # candidate-domain query into a single-product fact answer.
        if (
            heat_source_followup_sku
            and requested_followup_field
            and not _is_candidate_set_heat_source_filter(question)
        ):
            agent_result = _product_field_followup_result(
                db,
                heat_source_followup_sku,
                requested_followup_field,
                question,
                identity_source="recommendation_context_pronoun",
                field_request_override=followup_field_request,
            )
            agent_result = _attach_recommendation_followup_contract(
                agent_result,
                question,
                recommendation_followup_context,
            )
    if not agent_result and _asks_for_alternative_recommendation(question):
        agent_result = _alternative_recommendation_followup_result(
            db,
            question,
            recommendation_followup_context,
            candidate_followup_context,
        )
    vague_price_start = perf_counter()
    vague_price_clarification = bool(
        not agent_result
        and _should_clarify_vague_single_product_price(
            question,
            explicit_sku=sku,
            named_products=named_products,
            recommendation_context=recommendation_followup_context,
            candidate_context=candidate_followup_context,
            active_product_skus=active_product_context_skus,
        )
    )
    if vague_price_clarification:
        agent_result = _vague_single_product_price_clarification_result()
    customer_perf_service.log_stage(
        "vague_single_product_price_guard",
        vague_price_start,
        hit=vague_price_clarification,
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode") if vague_price_clarification else None,
    )
    force_runtime_ordinal_compare_followup = bool(
        not agent_result
        and _is_ordinal_compare_followup_question(question)
        and (
            _has_followup_result_context(recommendation_followup_context)
            or _has_followup_result_context(candidate_followup_context)
        )
    )
    force_runtime_empty_subset_followup = bool(
        not agent_result
        and _should_force_runtime_empty_subset_followup(
            question,
            explicit_sku=sku,
            named_products=named_products,
            candidate_context=candidate_followup_context,
        )
    )
    force_runtime_followup = bool(
        not agent_result
        and (
            force_runtime_empty_subset_followup
            or (
                _is_recommendation_followup_question(question)
                and (recommendation_followup_context or candidate_followup_context)
            )
        )
    )
    keep_preruntime_for_scoped_heat_source = bool(
        not agent_result
        and candidate_followup_context
        and _should_keep_preruntime_for_scoped_heat_source_followup(
            question,
            candidate_context=candidate_followup_context,
        )
    )
    category_reference_detail = _is_category_reference_detail_question(question)
    if not agent_result and keep_preruntime_for_scoped_heat_source and not category_reference_detail:
        scoped_previous_result_skus = _refine_scoped_followup_previous_result_skus(
            db,
            question=question,
            candidate_context=candidate_followup_context,
            previous_result_skus=_previous_result_skus_for_pre_runtime(
                db,
                user_id=user_id,
                conversation_id=conversation_id,
                question=question,
            ),
        )
        stage_start = perf_counter()
        scoped_agent_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=question,
            sku=None,
            previous_result_skus=scoped_previous_result_skus,
            allow_llm_fallback=False,
            scoped_comparison_candidates=True,
            **intent_execution_options,
        )
        scoped_agent_result = _normalize_candidate_context_followup_result(
            scoped_agent_result,
            db,
            question=question,
            candidate_context=candidate_followup_context,
        )
        customer_perf_service.log_stage(
            "process_intent_request_scoped_heat_source_pre_runtime",
            stage_start,
            hit=bool(scoped_agent_result),
            intent=scoped_agent_result.get("intent") if scoped_agent_result else None,
            previous_result_skus_count=len(scoped_previous_result_skus or []),
        )
        if scoped_agent_result:
            agent_result = scoped_agent_result
    bypass_stateless_pre_runtime = bool(
        (recommendation_followup_context or candidate_followup_context)
        and not force_runtime_followup
        and not keep_preruntime_for_scoped_heat_source
    )
    bypass_pre_runtime_for_detail_context = False
    if not agent_result and not bypass_stateless_pre_runtime and not category_reference_detail:
        preloaded_entity_stack = _latest_entity_stack(db, conversation_id, user_id)
        preloaded_conversation_history = _build_conversation_history(db, conversation_id, user_id)
        bypass_pre_runtime_for_detail_context = _should_bypass_preruntime_for_runtime_direct_detail(
            db,
            question=question,
            entity_stack=preloaded_entity_stack,
            conversation_history=preloaded_conversation_history,
        )
    if (
        not agent_result
        and not followup_runtime_bypass
        and not bypass_stateless_pre_runtime
        and not force_runtime_followup
        and not force_runtime_empty_subset_followup
        and not force_runtime_ordinal_compare_followup
        and not category_reference_detail
        and not bypass_pre_runtime_for_detail_context
    ):
        deterministic_previous_result_skus = _previous_result_skus_for_pre_runtime(
            db,
            user_id=user_id,
            conversation_id=conversation_id,
            question=question,
        )
        stage_start = perf_counter()
        try:
            agent_result = await customer_agent_intent_service.process_intent_request(
                db,
                user_id=user_id,
                question=question,
                sku=None,
                previous_result_skus=deterministic_previous_result_skus,
                allow_llm_fallback=False,
                **intent_execution_options,
            )
        except HTTPException as exc:
            if exc.status_code == status.HTTP_404_NOT_FOUND and SKU_RE.fullmatch(question.strip()):
                agent_result = {
                    "intent": "clarify",
                    "answer_type": "clarification",
                    "answer": f"当前没有找到 SKU {question.strip().upper()} 对应的产品资料，请确认 SKU 是否正确。",
                    "results": [],
                    "result_skus": [],
                    "needs_clarification": True,
                    "debug": {"agent_mode": "missing_sku_clarification"},
                    "skip_polish": True,
                }
            else:
                raise
        customer_perf_service.log_stage("process_intent_request_pre_runtime", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None)
        scenario_recommendation_like = (
            customer_agent_intent_service._looks_like_scenario_recommendation_question(question)
            or _phase1_is_water_kettle_selection_scenario(question)
            or _phase1_is_stove_griddle_combo_scenario(question)
            or customer_agent_planner_service._looks_like_scenario_statement_recommendation(question)
        )
        if (
            (not agent_result or str(agent_result.get("answer_type") or "").strip() in {"", "unknown"})
            and scenario_recommendation_like
        ):
            rescue_intent = customer_agent_intent_service.CustomerIntent(
                intent="recommend_products",
                semantic_query=question,
                recommendation_query=question,
                is_single_field_sufficient=False,
            )
            agent_result = await customer_agent_intent_service._recommend_result(
                db,
                user_id,
                rescue_intent,
                scoped_comparison_candidates=False,
            )
        planner_requires_recommendation = bool(
            phase1_plan.get("primary_intent") == "recommendation"
            and phase1_plan.get("must_return_products")
        )
        if (
            agent_result
            and str(agent_result.get("answer_type") or "").strip() in {"query_products", "product_query", "product_detail", "knowledge_base_answer"}
            and (scenario_recommendation_like or planner_requires_recommendation)
            and not customer_agent_intent_service._extract_skus(question)
        ):
            rebuilt = _phase1_structured_recommendation_result(
                db,
                {"primary_intent": "recommendation", "scenario": question},
            )
            if rebuilt and _phase1_result_skus(rebuilt):
                agent_result = rebuilt
        # A low-confidence planner may leave primary_intent empty even when the
        # current question is one of the structured, multi-domain recommendation
        # scenarios.  Do not let the generic recommendation formatter collapse
        # that scenario to its first retrieval hit: rebuild from the current
        # scenario before any result is persisted or shaped for display.
        if (
            agent_result
            and str(agent_result.get("answer_type") or "").strip() == "recommendation"
            and _phase1_force_structured_recommendation_rebuild(question)
            and not customer_agent_intent_service._extract_skus(question)
        ):
            rebuilt = _phase1_structured_recommendation_result(
                db,
                {"primary_intent": "recommendation", "scenario": question},
            )
            if rebuilt and _phase1_result_skus(rebuilt):
                agent_result = rebuilt
        if (
            agent_result
            and str(agent_result.get("answer_type") or "").strip() == "product_detail"
            and scenario_recommendation_like
            and not customer_agent_intent_service._looks_like_product_detail_question(question)
            and not customer_agent_intent_service._extract_skus(question)
        ):
            result_rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
            if not result_rows:
                result_rows = [
                    row for row in customer_agent_intent_service._all_product_rows(db)
                    if "锅" in str(row.get("category") or "")
                ][:3]
            if result_rows:
                top_row = result_rows[0]
                top_sku = str(top_row.get("sku") or "").strip().upper()
                top_name = str(top_row.get("product_name_cn") or top_row.get("product_name_en") or top_sku).strip()
                top_reason = "；".join(
                    str(top_row.get(key) or "").strip("。；; ")
                    for key in ("features", "usage_scenarios", "positioning")
                    if str(top_row.get(key) or "").strip()
                )
                answer = f"更推荐{top_name}（{top_sku}）。"
                if top_reason:
                    answer += f"它更贴合你当前这类场景，{top_reason[:80].rstrip('；;,，')}。"
                if len(result_rows) > 1:
                    backups: list[str] = []
                    for row in result_rows[1:3]:
                        sku = str(row.get('sku') or '').strip().upper()
                        name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
                        backups.append(f"{name}（{sku}）")
                    if backups:
                        answer += " 备选可以看" + "、".join(backups) + "。"
                agent_result["intent"] = "recommend_products"
                agent_result["answer_type"] = "recommendation"
                agent_result["answer"] = answer
                agent_result["skip_polish"] = True
    if not agent_result and conversation_id:
        active_anchor_result = await _active_product_anchor_field_followup_result(
            db,
            question,
            _latest_recommendation_context_for_sources(db, conversation_id),
            phase1_plan,
        )
        if active_anchor_result:
            agent_result = active_anchor_result
    if not agent_result and not followup_runtime_bypass and not bypass_stateless_pre_runtime and not force_runtime_followup and not force_runtime_empty_subset_followup and not force_runtime_ordinal_compare_followup and not bypass_pre_runtime_for_detail_context and not category_reference_detail:
        stage_start = perf_counter()
        agent_result = customer_agent_service.try_numeric_english_name_query(db, question)
        customer_perf_service.log_stage("legacy_rule_agent_fallback", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None)
    if not agent_result and not followup_runtime_bypass and not bypass_stateless_pre_runtime and not force_runtime_followup and not force_runtime_empty_subset_followup and not force_runtime_ordinal_compare_followup and not bypass_pre_runtime_for_detail_context and not category_reference_detail:
        stage_start = perf_counter()
        agent_result = customer_agent_service.process_agent_request(
            db,
            user_id=user_id,
            question=question,
            sku=None,
        )
        customer_perf_service.log_stage("legacy_rule_agent_total", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None)
        if _should_defer_legacy_rule_result_to_runtime(question, agent_result):
            agent_result = None
    if not agent_result:
        context_start = perf_counter()
        entity_stack = preloaded_entity_stack if preloaded_entity_stack is not None else _latest_entity_stack(db, conversation_id, user_id)
        conversation_history = (
            preloaded_conversation_history
            if preloaded_conversation_history is not None
            else _build_conversation_history(db, conversation_id, user_id)
        )
        recommendation_context = _latest_recommendation_context_for_sources(db, conversation_id)
        candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
        previous_result_skus = _previous_result_skus_for_pre_runtime(
            db,
            user_id=user_id,
            conversation_id=conversation_id,
            question=question,
        )
        customer_perf_service.log_stage(
            "context_read",
            context_start,
            entity_stack_count=len(entity_stack or []),
            conversation_history_count=len(conversation_history or []),
            previous_result_skus_count=len(previous_result_skus or []),
            recommendation_context_present=bool(recommendation_context),
            candidate_context_present=bool(candidate_context),
        )
        contextual_conversation_history = conversation_history
        stage_start = perf_counter()
        recognized_intent = _recognized_intent_for_agent_fast_path(db, question, conversation_id)
        feedback_lessons = _build_feedback_lessons(db, user_id)
        release_session_connection(db)
        agent_result = await customer_agent_runtime_service.process_agent_request(
            db,
            user_id=user_id,
            conversation_id=conversation_id,
            question=question,
            sku=None,
            previous_result_skus=previous_result_skus,
            entity_stack=entity_stack,
            conversation_history=contextual_conversation_history,
            feedback_lessons=feedback_lessons,
            recognized_intent=recognized_intent,
            answer_delta_callback=answer_delta_callback,
        )
        agent_result = _synchronize_context_read_trace(
            agent_result,
            previous_result_skus=previous_result_skus,
            recommendation_context=recommendation_context,
            candidate_context=candidate_context,
        )
        agent_result = _normalize_candidate_context_followup_result(
            agent_result,
            db,
            question=question,
            candidate_context=candidate_context,
        )
        customer_perf_service.log_stage("process_agent_request", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None, agent_mode=(agent_result.get("debug") or {}).get("agent_mode") if agent_result else None)
    if _should_retry_with_deterministic_agent(agent_result):
        stage_start = perf_counter()
        retry_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=question,
            sku=None,
            previous_result_skus=[],
            allow_llm_fallback=False,
            **intent_execution_options,
        )
        customer_perf_service.log_stage("process_intent_request_retry", stage_start, hit=bool(retry_result), intent=retry_result.get("intent") if retry_result else None)
        if retry_result and retry_result.get("results"):
            agent_result = _prepare_deterministic_retry_result(retry_result)
    if not agent_result:
        stage_start = perf_counter()
        agent_result = await customer_agent_intent_service.process_intent_request(
            db,
            user_id=user_id,
            question=question,
            sku=None,
            previous_result_skus=[],
            **intent_execution_options,
        )
        customer_perf_service.log_stage("process_intent_request_fallback", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None)
    if force_runtime_followup and not agent_result:
        stage_start = perf_counter()
        context_start = perf_counter()
        entity_stack = preloaded_entity_stack if preloaded_entity_stack is not None else _latest_entity_stack(db, conversation_id, user_id)
        conversation_history = (
            preloaded_conversation_history
            if preloaded_conversation_history is not None
            else _build_conversation_history(db, conversation_id, user_id)
        )
        recommendation_context = _latest_recommendation_context_for_sources(db, conversation_id)
        candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
        previous_result_skus = _previous_result_skus_for_pre_runtime(
            db,
            user_id=user_id,
            conversation_id=conversation_id,
            question=question,
        )
        customer_perf_service.log_stage(
            "context_read",
            context_start,
            entity_stack_count=len(entity_stack or []),
            conversation_history_count=len(conversation_history or []),
            previous_result_skus_count=len(previous_result_skus or []),
            recommendation_context_present=bool(recommendation_context),
            candidate_context_present=bool(candidate_context),
        )
        recognized_intent = _recognized_intent_for_agent_fast_path(db, question, conversation_id)
        feedback_lessons = _build_feedback_lessons(db, user_id)
        release_session_connection(db)
        agent_result = await customer_agent_runtime_service.process_agent_request(
            db,
            user_id=user_id,
            conversation_id=conversation_id,
            question=question,
            sku=None,
            previous_result_skus=previous_result_skus,
            entity_stack=entity_stack,
            conversation_history=conversation_history,
            feedback_lessons=feedback_lessons,
            recognized_intent=recognized_intent,
            answer_delta_callback=answer_delta_callback,
        )
        agent_result = _synchronize_context_read_trace(
            agent_result,
            previous_result_skus=previous_result_skus,
            recommendation_context=recommendation_context,
            candidate_context=candidate_context,
        )
        agent_result = _normalize_candidate_context_followup_result(
            agent_result,
            db,
            question=question,
            candidate_context=candidate_context,
        )
        customer_perf_service.log_stage("process_agent_request_followup", stage_start, hit=bool(agent_result), intent=agent_result.get("intent") if agent_result else None, agent_mode=(agent_result.get("debug") or {}).get("agent_mode") if agent_result else None)
    if (
        agent_result
        and str(agent_result.get("answer_type") or "").strip() == "product_detail"
        and not (agent_result.get("result_skus") or [])
        and _looks_like_ordinal_product_field_followup(question)
    ):
        ordered_followup_sku = _ordinal_followup_target_sku(
            question,
            recommendation_followup_context,
            candidate_followup_context,
        )
        if not ordered_followup_sku:
            ordered_followup_sku = _ordinal_followup_target_sku_from_ordered(
                question,
                _latest_ordered_result_skus_for_followup(db, conversation_id, user_id),
            )
        requested_followup_field = _followup_requested_field(question)
        if ordered_followup_sku and requested_followup_field:
            repaired_followup_result = _product_field_followup_result(
                db,
                ordered_followup_sku,
                requested_followup_field,
                question,
                identity_source="recommendation_context_anchor",
            )
            if repaired_followup_result:
                agent_result = repaired_followup_result
    agent_result = _phase1_filter_alcohol_stove_cookware_result(
        db,
        agent_result,
        question=question,
        candidate_context=candidate_followup_context or _latest_candidate_context_for_sources(db, conversation_id),
    )
    agent_result = _reject_unsealed_named_product_phase1_result(
        db,
        question,
        agent_result,
    )
    if isinstance(agent_result, dict):
        agent_result = _phase1_repair_recommendation_result(db, agent_result, phase1_plan)
        agent_result = _post_filter_recommendation_result(db, question, agent_result)
    if agent_result:
        stage_start = perf_counter()
        guard_start = perf_counter()
        agent_result = _run_phase1_answer_guard(agent_result, phase1_plan)
        agent_result = _normalize_alcohol_stove_cookware_list_answer_type(question, agent_result)
        guard_duration_ms = round((perf_counter() - guard_start) * 1000, 2)
        agent_result = _attach_phase1_plan_and_timing(
            agent_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
                guard_duration_ms=guard_duration_ms,
            ),
        )
        agent_result = _finalize_answer(agent_result)
        agent_result = _enforce_field_evidence_policy(db, question, agent_result)
        agent_result = _ensure_debug_plan_raw_question(agent_result, question)
        answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
        skip_polish = bool(agent_result.get("skip_polish"))
        if _should_skip_polish_for_agent_result(agent_result):
            skip_polish = True
        if answer_metadata.get("evidence_insufficient") is True or answer_metadata.get("answer_policy") == "insufficient_evidence":
            skip_polish = True
        if not skip_polish:
            agent_result["answer"] = await _polish_customer_answer(db, question, agent_result)
        final_compound_queries = [
            str(item or "").strip()
            for item in ((phase1_plan.get("semantic_preplan") or {}).get("qa_evidence_queries") or [])
            if str(item or "").strip()
        ]
        coverage_contract = customer_answer_coverage_contract.AnswerCoverageContract.from_dict(
            answer_metadata.get("answer_coverage_contract")
        )
        if coverage_contract is not None:
            agent_result = _apply_answer_coverage_contract(agent_result)
        elif len(final_compound_queries) > 1:
            answer_text = str(agent_result.get("answer") or "").strip()
            uncovered_queries = _uncovered_compound_queries_for_output(
                answer_text,
                final_compound_queries,
                answer_metadata,
            )
            if uncovered_queries:
                agent_result["answer"] = "\n".join([
                    answer_text,
                    *(f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in uncovered_queries),
                ])
        agent_result = _shape_answer_for_output(agent_result)
        agent_result["skip_polish"] = skip_polish
        agent_result = customer_final_answer_arbiter.arbitrate_final_answer(agent_result)
        agent_result = _attach_agent_quality(agent_result, question)
        conversation = _get_or_create_conversation(db, user_id, question, agent_result.get("sku"), conversation_id)
        db.add(CustomerServiceMessage(
            conversation_id=conversation.id,
            role="user",
            content=question,
            sku=agent_result.get("sku"),
        ))
        assistant_turn_index = _assistant_turn_index(db, conversation.id)
        inherited_recommendation_context = _latest_recommendation_context_for_sources(
            db,
            conversation.id,
        )
        inherited_candidate_context = _latest_candidate_context_for_sources(
            db,
            conversation.id,
        )
        sources_with_context = _sources_with_result_context(
            agent_result,
            turn_index=assistant_turn_index,
            user_question=question,
            inherited_recommendation_context=inherited_recommendation_context,
            inherited_candidate_context=inherited_candidate_context,
        )
        assistant_message = CustomerServiceMessage(
            conversation_id=conversation.id,
            role="assistant",
            content=agent_result["answer"],
            sku=agent_result.get("sku"),
            sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
        )
        db.add(assistant_message)
        _touch_conversation(conversation, agent_result.get("sku"))
        conversation_id_value = conversation.id
        message_id_value = assistant_message.id
        db.commit()
        customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch="agent", skip_polish=bool(agent_result.get("skip_polish")))
        customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="agent", intent=agent_result.get("intent"), agent_mode=(agent_result.get("debug") or {}).get("agent_mode"))
        customer_perf_service.summarize_request(final_answer=agent_result.get("answer"), intent=agent_result.get("intent"), agent_mode=(agent_result.get("debug") or {}).get("agent_mode"))
        release_session_connection(db)
        public_intent = _public_intent_name(agent_result.get("intent"), agent_result.get("answer_type"))
        return {
            "conversation_id": conversation_id_value,
            "message_id": message_id_value,
            "intent": public_intent,
            "answer_type": agent_result.get("answer_type"),
            "confidence": agent_result.get("confidence"),
            "uncertainty": agent_result.get("uncertainty"),
            "needs_clarification": agent_result.get("needs_clarification", False),
            "anomalies": agent_result.get("anomalies") or [],
            "suggested_followups": agent_result.get("suggested_followups") or [],
            "followups": agent_result.get("followups") or agent_result.get("suggested_followups") or [],
            "warnings": agent_result.get("warnings") or [],
            "evidence": agent_result.get("evidence") or [],
            "agent_quality": agent_result.get("agent_quality") or {},
            "answer_metadata": agent_result.get("answer_metadata") or {},
            "debug": agent_result.get("debug") or {},
            "sku": agent_result.get("sku"),
            "answer": agent_result["answer"],
            "sources": sources_with_context,
            "actions": agent_result.get("actions") or [],
            "results": agent_result.get("results") or [],
            "steps": agent_result.get("steps") or [],
            "result_skus": agent_result.get("result_skus") if "result_skus" in agent_result else [
                str(item.get("sku") or "").strip().upper()
                for item in (agent_result.get("results") or [])
                if isinstance(item, dict) and str(item.get("sku") or "").strip()
            ],
            "candidate_skus": agent_result.get("candidate_skus") if "candidate_skus" in agent_result else (
                agent_result.get("result_skus") if "result_skus" in agent_result else [
                str(item.get("sku") or "").strip().upper()
                for item in (agent_result.get("results") or [])
                if isinstance(item, dict) and str(item.get("sku") or "").strip()
                ]
            ),
            "agent_mode": (agent_result.get("debug") or {}).get("agent_mode"),
        }

    resolved_sku = _resolve_sku(db, question, sku)
    if not resolved_sku:
        customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="guidance")
        customer_perf_service.summarize_request(final_answer="guidance", intent="clarify", agent_mode="guidance")
        return _save_and_return_guidance(db, user_id, question, conversation_id)

    knowledge_start = perf_counter()
    product = db.query(Product).filter(Product.sku == resolved_sku).first()
    if not product:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="产品不存在")

    context, sources = build_product_context(db, resolved_sku, question)
    release_session_connection(db)
    messages = [
        {
            "role": "system",
            "content": (
                "你是内部产品客服助手。只能依据提供的产品上下文回答。"
                "如果上下文没有答案，必须明确说需要人工确认。"
                "不要编造参数、认证、价格、库存或售后政策。"
                "回答请先给结论，再给依据，保持中文、简洁、客服口吻。"
            ),
        },
        {
            "role": "user",
            "content": f"产品上下文：\n{context}\n\n客服问题：{question}",
        },
    ]

    try:
        answer = await customer_llm_service.chat_completion(db, messages, purpose="knowledge_answer")
    except Exception as exc:
        answer = f"聊天模型暂时不可用：{exc}"
    customer_perf_service.log_stage("single_sku_knowledge_llm", knowledge_start, sku=resolved_sku)

    conversation = _get_or_create_conversation(db, user_id, question, resolved_sku, conversation_id)
    db.add(CustomerServiceMessage(
        conversation_id=conversation.id,
        role="user",
        content=question,
        sku=resolved_sku,
    ))
    sources_with_meta = list(sources)
    sources_with_meta.append({
        "type": "agent_meta",
        "label": "客服回复元数据",
        "intent": "knowledge_base_answer",
        "answer_type": "knowledge_answer",
        "confidence": "medium",
        "uncertainty": _uncertainty_from_answer(answer, [], [], False),
        "needs_clarification": False,
        "anomalies": [],
        "suggested_followups": [],
        "followups": [],
        "warnings": [],
        "evidence": [],
        "debug": {"intent": "knowledge_base_answer", "steps": [], "warnings": [], "anomalies": [], "raw_results": []},
        "feedback": None,
    })
    assistant_message = CustomerServiceMessage(
        conversation_id=conversation.id,
        role="assistant",
        content=answer,
        sku=resolved_sku,
        sources_json=json.dumps(sources_with_meta, ensure_ascii=False, default=str),
    )
    db.add(assistant_message)
    _touch_conversation(conversation, resolved_sku)
    conversation_id_value = conversation.id
    message_id_value = assistant_message.id
    db.commit()
    customer_perf_service.log_stage("save_messages_and_commit", knowledge_start, branch="knowledge")
    customer_perf_service.log_stage("ask_customer_service.total", request_start, branch="knowledge", sku=resolved_sku)
    customer_perf_service.summarize_request(final_answer=answer, intent="knowledge_base_answer", agent_mode="single_sku_knowledge")
    release_session_connection(db)

    return {
        "conversation_id": conversation_id_value,
        "message_id": message_id_value,
        "intent": "knowledge_base_answer",
        "answer_type": "knowledge_answer",
        "confidence": "medium",
        "uncertainty": _uncertainty_from_answer(answer, [], [], False),
        "needs_clarification": False,
        "anomalies": [],
        "suggested_followups": [],
        "followups": [],
        "warnings": [],
        "evidence": [],
        "debug": {"intent": "knowledge_base_answer", "steps": [], "warnings": [], "anomalies": [], "raw_results": []},
        "sku": resolved_sku,
        "answer": answer,
        "sources": sources,
        "actions": [],
        "results": [],
        "steps": [],
    }


def _finalize_answer(agent_result: dict) -> dict:
    result = _normalize_agent_result(agent_result)
    primary = _pick_primary_answer_source(result)
    sources = _tag_and_order_sources(result.get("sources") or [], primary)
    result["sources"] = sources
    result["answer"] = _sanitize_final_answer_text(str(result.get("answer") or ""), primary)
    answer_metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    answer_metadata["final_decision"] = {
        "primary_source": primary.get("type"),
        "priority": primary.get("priority"),
        "single_source_of_truth": True,
        "llm_allowed": _llm_allowed_for_final_answer(result, primary),
    }
    result["answer_metadata"] = answer_metadata
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["final_answer"] = answer_metadata["final_decision"]
    result["debug"] = debug
    if not answer_metadata["final_decision"]["llm_allowed"]:
        result["skip_polish"] = True
    return result


def build_product_context(db: Session, sku: str, question: str) -> tuple[str, list[dict]]:
    try:
        detail = product_service.get_product_detail(db, sku)
    except HTTPException as exc:
        # A generated/legacy context reference is not customer-supplied
        # product identity.  Do not turn an otherwise ordinary conversation
        # into a transport-level 404; the calling route can continue without
        # this optional product context.
        if exc.status_code == status.HTTP_404_NOT_FOUND:
            return "", []
        raise
    sources: list[dict] = []
    lines = [
        f"SKU: {detail.get('sku')}",
        f"中文名: {detail.get('product_name_cn') or ''}",
        f"英文名: {detail.get('product_name_en') or ''}",
        f"品牌: {detail.get('brand') or ''}",
        f"系列: {detail.get('series') or ''}",
        f"类目: {detail.get('category') or ''} / {detail.get('sub_category') or ''}",
        f"等级: {detail.get('product_level') or ''}",
        f"生命周期: {detail.get('lifecycle_status') or ''}",
    ]
    sources.append({"type": "product", "label": "产品基础信息", "sku": sku})

    specs = detail.get("specs") or {}
    if specs:
        lines.append("规格信息:")
        for key, label in [
            ("capacity", "容量"),
            ("gross_weight_g", "毛重g"),
            ("body_material", "材质"),
            ("color", "颜色"),
            ("surface_finish", "表面工艺"),
            ("heat_source", "适用热源"),
            ("power", "功率"),
            ("technical_advantages", "技术优势"),
            ("usage_instruction", "使用说明"),
        ]:
            value = specs.get(key)
            if value not in (None, "", []):
                lines.append(f"- {label}: {_stringify(value)}")
        sources.append({"type": "product_specs", "label": "产品规格", "sku": sku})

    business = detail.get("business") or {}
    if business:
        lines.append("业务信息:")
        for key, label in [
            ("top_selling_points", "核心卖点"),
            ("target_audience", "目标人群"),
            ("positioning", "定位"),
            ("price_positioning", "价格定位"),
            ("emotional_value", "情绪价值"),
            ("usage_scenarios", "使用场景"),
            ("competitor_benchmark", "竞品信息"),
        ]:
            value = business.get(key)
            if value not in (None, "", []):
                lines.append(f"- {label}: {_stringify(value)}")
        sources.append({"type": "product_business", "label": "产品业务信息", "sku": sku})

    qa_items = product_service.customer_visible_product_qas(db, detail["id"])
    if qa_items:
        lines.append("产品 QA:")
        for item in qa_items[:20]:
            lines.append(f"- Q: {item.question}\n  A: {item.answer}")
        sources.append({"type": "product_qa", "label": "产品 QA", "sku": sku, "count": len(qa_items)})

    negative = db.query(ProductQaNegative).filter(ProductQaNegative.product_id == detail["id"]).first()
    if negative:
        lines.append("差评/负面问题应答:")
        if negative.high_freq_negative_words:
            lines.append(f"- 高频负面词: {negative.high_freq_negative_words}")
        if negative.response_tone:
            lines.append(f"- 应答口径: {negative.response_tone}")
        sources.append({"type": "product_qa_negative", "label": "差评应答", "sku": sku})

    knowledge = knowledge_service.keyword_retrieve(db, question, sku=sku, limit=5)
    if knowledge:
        lines.append("知识库补充:")
        for item in knowledge:
            lines.append(f"- {item['content']}")
        sources.append({"type": "knowledge_base", "label": "向量/知识库补充", "sku": sku, "count": len(knowledge)})

    return "\n".join(lines), sources


def review_samples(db: Session, user_id: str, limit: int = 100) -> dict:
    user_id = str(user_id)
    messages = (
        db.query(CustomerServiceMessage, CustomerServiceConversation)
        .join(CustomerServiceConversation, CustomerServiceConversation.id == CustomerServiceMessage.conversation_id)
        .filter(
            CustomerServiceConversation.user_id == user_id,
            CustomerServiceMessage.role == "assistant",
        )
        .order_by(CustomerServiceMessage.created_at.desc())
        .limit(limit)
        .all()
    )
    items = []
    frequent_questions: dict[str, int] = {}
    clarification_samples = 0
    anomaly_samples = 0
    for assistant_message, conversation in messages:
        meta = _message_meta(assistant_message.sources_json)
        user_message = (
            db.query(CustomerServiceMessage)
            .filter(
                CustomerServiceMessage.conversation_id == conversation.id,
                CustomerServiceMessage.role == "user",
                CustomerServiceMessage.created_at <= assistant_message.created_at,
            )
            .order_by(CustomerServiceMessage.created_at.desc())
            .first()
        )
        question = (user_message.content if user_message else "").strip()
        if question:
            frequent_questions[question] = frequent_questions.get(question, 0) + 1
        if meta.get("needs_clarification"):
            clarification_samples += 1
        if meta.get("anomalies"):
            anomaly_samples += 1
        items.append({
            "conversation_id": conversation.id,
            "message_id": assistant_message.id,
            "question": question,
            "answer": assistant_message.content,
            "intent": meta.get("intent"),
            "confidence": meta.get("confidence"),
            "agent_quality": meta.get("agent_quality", {}),
            "needs_clarification": meta.get("needs_clarification", False),
            "anomalies": meta.get("anomalies", []),
            "warnings": meta.get("warnings", []),
            "suggested_followups": meta.get("suggested_followups", []),
            "created_at": str(assistant_message.created_at),
        })

    top_questions = sorted(frequent_questions.items(), key=lambda item: item[1], reverse=True)[:20]
    quality_summary = _review_quality_summary(items)
    return {
        "items": items,
        "summary": {
            "total_samples": len(items),
            "clarification_samples": clarification_samples,
            "anomaly_samples": anomaly_samples,
            "quality": quality_summary,
            "top_questions": [{"question": question, "count": count} for question, count in top_questions],
        },
    }


def _resolve_sku(db: Session, question: str, sku: str | None) -> str | None:
    if sku:
        resolved = _resolve_exact_sku_variant(db, sku)
        return resolved or sku.strip()
    candidates = customer_agent_service._extract_skus(question)
    for candidate in candidates:
        resolved = _resolve_exact_sku_variant(db, candidate)
        if resolved:
            return resolved
    return None


def _sku_lookup_variants(value: str | None) -> list[str]:
    raw = str(value or "").strip()
    if not raw:
        return []
    variants: list[str] = []
    compact_raw = raw.upper().replace("_", "-")
    parenthetical_variants: list[str] = []
    paren_match = re.match(r"^(?P<prefix>[A-Z0-9]+(?:-[A-Z0-9]+)+)[-](?P<suffix>[A-Z0-9]{2,8})$", compact_raw)
    if paren_match:
        parenthetical_variants.extend(
            [
                f"{paren_match.group('prefix')}({paren_match.group('suffix')})",
                f"{paren_match.group('prefix')}（{paren_match.group('suffix')}）",
            ]
        )
    suffix_match = re.match(r"^(?P<prefix>[A-Z0-9]+(?:-[A-Z0-9]+)+)[(（](?P<suffix>[A-Z0-9]{2,8})[)）]$", compact_raw)
    if suffix_match:
        parenthetical_variants.append(f"{suffix_match.group('prefix')}-{suffix_match.group('suffix')}")
    candidates = [
        raw,
        compact_raw,
        raw.replace("(", "（").replace(")", "）"),
        raw.replace("（", "(").replace("）", ")"),
        customer_agent_service.normalize_search_text(raw).upper().replace("_", "-"),
        *parenthetical_variants,
    ]
    for candidate in candidates:
        normalized = str(candidate or "").strip()
        if normalized and normalized not in variants:
            variants.append(normalized)
    return variants


def _resolve_exact_sku_variant(db: Session, sku: str | None) -> str | None:
    variants = _sku_lookup_variants(sku)
    if not variants:
        return None
    for candidate in variants:
        product = db.query(Product).filter(Product.sku == candidate).first()
        if product:
            return product.sku
    normalized_targets = {
        customer_agent_service.normalize_search_text(candidate).upper().replace("_", "-")
        for candidate in variants
    }
    for product in db.query(Product).all():
        product_sku = str(getattr(product, "sku", "") or "").strip()
        if not product_sku:
            continue
        normalized_product = customer_agent_service.normalize_search_text(product_sku).upper().replace("_", "-")
        if normalized_product in normalized_targets:
            return product_sku
    for candidate in variants:
        product = db.query(Product).filter(Product.sku.ilike(candidate)).first()
        if product:
            return product.sku
    return None


def _try_product_sku_identity_shortcut(db: Session, question: str) -> dict | None:
    subject = _sku_identity_subject(question)
    if not subject:
        return None

    normalized_subject = customer_agent_service.normalize_search_text(subject).lower()
    if not normalized_subject:
        return None

    exact_matches: list[Product] = []
    family_matches: list[Product] = []
    for product in db.query(Product).all():
        names = (product.product_name_cn, product.product_name_en)
        normalized_names = [
            customer_agent_service.normalize_search_text(name or "").lower()
            for name in names
            if str(name or "").strip()
        ]
        if normalized_subject in normalized_names:
            exact_matches.append(product)
        elif any(normalized_subject in name for name in normalized_names):
            family_matches.append(product)

    candidates = exact_matches or family_matches
    if not candidates:
        return None
    candidates.sort(key=lambda item: (len(str(item.product_name_cn or item.product_name_en or "")), item.sku))

    rows = [{
        "sku": str(product.sku or "").strip().upper(),
        "product_name_cn": product.product_name_cn,
        "product_name_en": product.product_name_en,
        "category": product.category,
    } for product in candidates]
    if len(rows) == 1:
        row = rows[0]
        product_name = row.get("product_name_cn") or row.get("product_name_en") or subject
        answer = f"{product_name}对应的 SKU 是 {row['sku']}。"
        sku = row["sku"]
    else:
        options = "\n".join(
            f"- {row.get('product_name_cn') or row.get('product_name_en') or '未命名产品'}：{row['sku']}"
            for row in rows
        )
        answer = f"“{subject}”可能对应以下产品：\n{options}\n请确认你指的是哪一款。"
        sku = None

    result_skus = [row["sku"] for row in rows]
    steps = [{
        "type": "product_sku_identity_shortcut",
        "label": "产品 SKU 身份查询",
        "detail": "、".join(result_skus),
        "ok": True,
    }]
    return {
        "answer": answer,
        "intent": "product_detail",
        "answer_type": "product_detail",
        "confidence": "high" if len(rows) == 1 else "medium",
        "uncertainty": "resolved" if len(rows) == 1 else "ambiguous_product",
        "needs_clarification": len(rows) > 1,
        "anomalies": [],
        "suggested_followups": [] if len(rows) == 1 else ["请提供完整产品名或直接选择上面的 SKU。"],
        "followups": [],
        "evidence": [],
        "sources": [{"type": "product", "label": "产品 SKU", "sku": row["sku"]} for row in rows],
        "actions": [],
        "results": rows,
        "steps": steps,
        "warnings": [],
        "sku": sku,
        "result_skus": result_skus,
        "debug": {
            "agent_mode": "product_sku_identity_shortcut",
            "intent": "product_detail",
            "steps": steps,
            "warnings": [],
            "anomalies": [],
            "raw_results": rows,
        },
        "skip_polish": True,
    }


def _should_clarify_vague_single_product_price(
    question: str,
    *,
    explicit_sku: str | None,
    named_products: list[Product],
    recommendation_context: dict | None,
    candidate_context: dict | None,
    active_product_skus: list[str],
) -> bool:
    text = str(question or "").strip()
    if (
        not text
        or explicit_sku
        or named_products
        or recommendation_context
        or candidate_context
        or active_product_skus
    ):
        return False
    vague_references = ("刚才那个", "上面那个", "那个", "这个", "它")
    price_terms = ("多少钱", "价格", "售价", "什么价", "几块", "几元")
    return any(term in text for term in vague_references) and any(term in text for term in price_terms)


def _unbound_deictic_product_reference_result(
    db: Session,
    question: str,
    *,
    field_type: str | None = None,
) -> dict | None:
    """Require identity context for a leading singular product reference."""
    text = str(question or "").strip()
    if not re.match(
        r"^(?:那|这)?(?:它|这个|这款|该商品|该产品|这个商品|这件商品|本产品)",
        text,
    ):
        return None
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        text,
        db.query(Product).order_by(Product.sku.asc()).all(),
        field_type_override=str(field_type or "").strip() or None,
    )
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "请先说明你指的是哪款商品，或提供 SKU；确认商品后我再查询对应信息。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "unbound_deictic_entity_contract_guard",
            "evidence_status": "missing_entity_context",
        },
        "debug": {
            "agent_mode": "unbound_deictic_entity_contract_guard",
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "skip_polish": True,
    }


